var e=JSON.parse(`[{"id":"basic-mayuan-daolun-1","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 1 题"},"stem":"马克思主义理论体系是一个庞大、复杂的有机整体。在整个理论体系中，居于基础地位的部分是","choices":[{"id":"A","text":"科学社会主义"},{"id":"B","text":"马克思主义哲学"},{"id":"C","text":"马克思主义政治经济学"},{"id":"D","text":"马克思主义社会学"}],"answer":["B"],"analysis":{"point":"","options":{"A":"科学社会主义——是马克思主义的目的和归宿。","B":"马克思主义哲学——是马克思主义的基础和方法，是本题正确答案。","C":"马克思主义政治经济学——是马克思主义的主要内容。","D":"马克思主义社会学——非考点。"}}},{"id":"basic-mayuan-daolun-2","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 2 题"},"stem":"马克思和恩格斯都出生于有教养的资产阶级知识分子家庭，但他们很早就树立了为全人类幸福而奋斗的信念，并在参加国际工人运动的斗争中逐步确立了无产阶级立场，成为无产阶级革命家和思想家。在他们的帮助下，国际性工人组织“正义者同盟”召开代表大会，改名为“共产主义者同盟”，马克思和恩格斯还为其起草了世界上第一个无产阶级政党的党纲。这个党纲是","choices":[{"id":"A","text":"《资本论》"},{"id":"B","text":"《反杜林论》"},{"id":"C","text":"《共产党宣言》"},{"id":"D","text":"《关于费尔巴哈的提纲》"}],"answer":["C"],"analysis":{"point":"","options":{"A":"《资本论》——是系统阐释剩余价值学说、创立马克思主义政治经济学的著作。","B":"《反杜林论》——是全面阐述马克思主义理论体系的著作。","C":"《共产党宣言》——是马克思主义公开问世的标志、科学社会主义诞生的标志，也是世界上第一个无产阶级政党——共产主义者同盟的党纲，是本题正确答案。","D":"《关于费尔巴哈的提纲》——是首次确立科学实践观的著作。"}}},{"id":"basic-mayuan-daolun-3","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 3 题"},"stem":"在党的二十大报告中，习近平总书记进一步提出“不断谱写马克思主义中国化时代化新篇章”的要求，并指明了在新时代新征程上为此而努力的前进方向和思想遵循。马克思主义创新发展的基本路径是","choices":[{"id":"A","text":"坚持人民至上的政治立场"},{"id":"B","text":"马克思主义本土化和时代化"},{"id":"C","text":"马克思主义是科学的世界观和方法论"},{"id":"D","text":"马克思主义具有鲜明的实践品格"}],"answer":["B"],"analysis":{"point":"","options":{"A":"坚持人民至上的政治立场——是马克思主义人民性的含义。","B":"马克思主义本土化和时代化——是马克思主义创新发展的基本路径，是本题正确答案。","C":"马克思主义是科学的世界观和方法论——是马克思主义科学性的含义。","D":"马克思主义具有鲜明的实践品格——是马克思主义实践性的含义。"}}},{"id":"basic-mayuan-daolun-4","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 4 题"},"stem":"习近平总书记鲜明指出马克思主义理论的科学性和革命性源于辩证唯物主义和历史唯物主义的科学世界观和方法论，反复强调全党都要加强对马克思主义哲学的学习和运用，提高运用马克思主义立场、观点、方法分析和解决问题的能力。我们研究问题、解决问题的“总钥匙”是","choices":[{"id":"A","text":"科学社会主义基本原则"},{"id":"B","text":"本土化和时代化"},{"id":"C","text":"科学的世界观和方法论"},{"id":"D","text":"人民至上"}],"answer":["C"],"analysis":{"point":"","options":{"A":"科学社会主义基本原则——是马克思主义的核心内容。","B":"本土化和时代化——是马克思主义创新发展的基本路径。","C":"科学的世界观和方法论——是我们研究问题、解决问题的“总钥匙”，是本题正确答案。","D":"人民至上是马克思主义的政治立场。"}}},{"id":"basic-mayuan-daolun-5","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 5 题"},"stem":"在省部级主要领导干部“学习习近平总书记重要讲话精神，迎接党的二十大”专题研讨班上，习近平指出，“拥有马克思主义科学理论指导是我们党鲜明的政治品格和强大的政治优势”。马克思主义的基本特征，用一句话概括就是","choices":[{"id":"A","text":"科学性与先进性的统一"},{"id":"B","text":"科学性与革命性的统一"},{"id":"C","text":"人民性与阶级性的统一"},{"id":"D","text":"人民性与先进性的统一"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是马克思主义不同特征的组合，不是对马克思主义基本特征的总概括。","B":"科学性与革命性的统一——是对马克思主义基本特征的总概括，是本题正确答案。","C":"是马克思主义不同特征的组合，不是对马克思主义基本特征的总概括。","D":"是马克思主义不同特征的组合，不是对马克思主义基本特征的总概括。"}}},{"id":"basic-mayuan-daolun-6","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 6 题"},"stem":"在中学的时候，列宁第一次看到了在彼得堡上大学的哥哥亚历山大带回家的《资本论》，开始接触马克思主义。列宁深刻地论述资本主义发展到帝国主义阶段的本质和特征，揭示帝国主义时代经济和政治发展不平衡的规律，指出帝国主义是无产阶级社会革命的前夜的著作是","choices":[{"id":"A","text":"《国家与革命》"},{"id":"B","text":"《唯物主义和经验批判主义》"},{"id":"C","text":"《帝国主义是资本主义的最高阶段》"},{"id":"D","text":"《路德维希·费尔巴哈和德国古典哲学的终结》"}],"answer":["C"],"analysis":{"point":"","options":{"A":"《国家与革命》——是马克思主义国家学说的代表作之一。","B":"《唯物主义和经验批判主义》是批判马赫主义的著作。","C":"《帝国主义是资本主义的最高阶段》——是《资本论》的继续和发展，它指出帝国主义是无产阶级社会革命的前夜，是本题正确答案。","D":"《路德维希·费尔巴哈和德国古典哲学的终结》——第一次对哲学基本问题作了明确阐述。"}}},{"id":"basic-mayuan-daolun-7","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 7 题"},"stem":"恩格斯曾经指出：“一个民族要想站在科学的最高峰，就一刻也不能没有理论思维。”而实践发展没有止境，党的理论创新也没有止境。党的创新理论是“改造主观世界的‘营养’”。新时代我们继续推进理论创新必须始终坚持的基本点是","choices":[{"id":"A","text":"中华优秀传统文化"},{"id":"B","text":"习近平新时代中国特色社会主义思想的世界观和方法论"},{"id":"C","text":"历史唯物主义"},{"id":"D","text":"剩余价值理论"}],"answer":["B"],"analysis":{"point":"","options":{"A":"（原书未单独给出此项解析）","B":"习近平新时代中国特色社会主义思想的世界观和方法论——是新时代继续推进理论创新必须始终坚持的基本点，是本题正确答案。","C":"是马克思主义在理论上的两大贡献。","D":"是马克思主义在理论上的两大贡献。"}}},{"id":"basic-mayuan-daolun-8","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 8 题"},"stem":"马克思主义是由马克思和恩格斯创立并为后继者所不断发展的科学理论体系。马克思主义首要的和基本的观点是","choices":[{"id":"A","text":"物质决定意识的观点"},{"id":"B","text":"阶级斗争的观点"},{"id":"C","text":"对立统一的观点"},{"id":"D","text":"实践观点"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是马克思主义的具体观点。","B":"是马克思主义的具体观点。","C":"是马克思主义的具体观点。","D":"实践观点——是马克思主义首要的和基本的观点，是本题正确答案。"}}},{"id":"basic-mayuan-daolun-9","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 9 题"},"stem":"列宁深刻分析了19世纪末20世纪初世界历史条件的变化，提出了社会主义革命可能在一国或数国首先发生并取得胜利的论断。列宁提出这一论断的依据是","choices":[{"id":"A","text":"经济政治发展的不平衡已成为资本主义发展的绝对规律"},{"id":"B","text":"资本主义生产方式在西欧已经有了相当的发展"},{"id":"C","text":"无产阶级在反抗资产阶级剥削和压迫的斗争中，逐步走向自觉"},{"id":"D","text":"共产主义分为两个阶段"}],"answer":["A"],"analysis":{"point":"","options":{"A":"经济政治发展的不平衡已成为资本主义发展的绝对规律——是提出社会主义革命可能在一国或数国首先发生并取得胜利的论断的依据，是本题正确答案。","B":"（原书未单独给出此项解析）","C":"无产阶级在反抗资产阶级剥削和压迫的斗争中，逐步走向自觉——是马克思主义产生的阶级基础。","D":"共产主义分为两个阶段是《哥达纲领批判》的内容之一。"}}},{"id":"basic-mayuan-daolun-10","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 10 题"},"stem":"马克思和恩格斯并不是先知先觉的圣人，他们从小面对的也是一个充满矛盾的现实世界，在家庭、学校和社会的影响下，也曾接受过那个时代的唯心主义和资产阶级民主主义思想。但是资本主义制度的弊端和劳动群众渴求解放的呼声，促使他们立志进行社会变革，并走上求索科学真理的道路。1844年2月，马克思和恩格斯在《德法年鉴》上发表的文章，标志着马克思和恩格斯完成了","choices":[{"id":"A","text":"从唯心主义向唯物主义的转变"},{"id":"B","text":"从革命民主主义向共产主义的转变"},{"id":"C","text":"从空想社会主义向科学社会主义的转变"},{"id":"D","text":"从唯心史观向唯物史观的转变"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是马克思和恩格斯创立马克思主义的思想前提，是他们发表在《德法年鉴》上的文章所体现的“两个转变”，是本题正确答案。","B":"是马克思和恩格斯创立马克思主义的思想前提，是他们发表在《德法年鉴》上的文章所体现的“两个转变”，是本题正确答案。","C":"从空想社会主义向科学社会主义的转变——是以唯物史观和剩余价值学说的创立为基础的。","D":"从唯心史观向唯物史观的转变——是以《德意志意识形态》中唯物史观的创立为标志的。"}}},{"id":"basic-mayuan-daolun-11","moduleId":"basic","subjectId":"mayuan","chapter":"导论 马克思主义是关于无产阶级和人类解放的科学","chapterKey":"导论","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 导论 第 11 题"},"stem":"马克思主义是一个博大精深的理论体系，为马克思主义的创立提供直接理论来源的是","choices":[{"id":"A","text":"德国古典哲学"},{"id":"B","text":"英国古典政治经济学"},{"id":"C","text":"英法空想社会主义"},{"id":"D","text":"资本主义生产方式在西欧已经有了相当的发展"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是资本主义发展初期的思想家求索时代课题的尝试，是马克思主义直接的理论来源，是本题正确答案。","B":"是资本主义发展初期的思想家求索时代课题的尝试，是马克思主义直接的理论来源，是本题正确答案。","C":"是资本主义发展初期的思想家求索时代课题的尝试，是马克思主义直接的理论来源，是本题正确答案。","D":"资本主义生产方式在西欧已经有了相当的发展——是马克思主义产生的社会根源。"}}},{"id":"basic-mayuan-ch01-1","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 1 题"},"stem":"从哲学上看，世界上的万事万物归结起来无非是两大类现象，即物质现象和精神现象；人类的活动归纳起来无非也是两大类，即认识世界和改造世界。哲学的基本问题是","choices":[{"id":"A","text":"世界是怎样存在的问题"},{"id":"B","text":"社会存在与社会意识的关系问题"},{"id":"C","text":"存在和思维的关系问题"},{"id":"D","text":"历史创造者问题"}],"answer":["C"],"analysis":{"point":"","options":{"A":"世界是怎样存在的问题——是哲学的重要问题，是区分辩证法和形而上学的标准。","B":"社会存在与社会意识的关系问题——是社会历史观的基本问题。","C":"存在和思维的关系问题——是哲学的基本问题，是本题正确答案。","D":"历史创造者问题——是唯物史观和唯心史观的分水岭。"}}},{"id":"basic-mayuan-ch01-2","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 2 题"},"stem":"哲学基本问题的第一个方面，即物质和意识何者为第一性、何者为第二性的问题是","choices":[{"id":"A","text":"区分唯物主义与唯心主义的标准"},{"id":"B","text":"区分可知论与不可知论的标准"},{"id":"C","text":"区分辩证法与形而上学的标准"},{"id":"D","text":"区分唯物史观与唯心史观的标准"}],"answer":["A"],"analysis":{"point":"","options":{"A":"区分唯物主义与唯心主义的标准——是物质和意识何者为第一性、何者为第二性的问题，是本题正确答案。","B":"区分可知论与不可知论的标准——是思维和存在有无同一性的问题，即“思维能否正确认识存在”。","C":"区分辩证法与形而上学的标准——是世界是怎样存在的问题，即“世界上的事物是联系的还是孤立的，是发展的还是静止的”。","D":"区分唯物史观与唯心史观的标准——是社会存在决定社会意识，还是社会意识决定社会存在的问题。"}}},{"id":"basic-mayuan-ch01-3","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 3 题"},"stem":"现代辩证唯物主义从无限多样的物质现象中抽象出共同的特性，从哲学上作了最高概括，指出了物质的本质规定是","choices":[{"id":"A","text":"运动"},{"id":"B","text":"主观能动性"},{"id":"C","text":"社会历史性"},{"id":"D","text":"客观实在性"}],"answer":["D"],"analysis":{"point":"","options":{"A":"运动是物质的存在方式和根本属性。","B":"主观能动性是意识对物质的反作用。","C":"社会历史性——是意识、实践、价值等范畴的特性。","D":"客观实在性——是物质的本质规定，是从自然存在和社会存在中抽象出的共同特性，是本题正确答案。"}}},{"id":"basic-mayuan-ch01-4","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 4 题"},"stem":"物质世界是运动变化着的，并从中分化出多样化的特别是更高级的事物和运动形式。其中，最高级的物质存在形态是","choices":[{"id":"A","text":"暗物质"},{"id":"B","text":"人类社会"},{"id":"C","text":"自然界"},{"id":"D","text":"时空"}],"answer":["B"],"analysis":{"point":"","options":{"A":"暗物质——非考点。","B":"人类社会——是最高级的物质存在形态，是本题正确答案。","C":"自然界——是客观世界的一部分，其发展过程是自发的。","D":"时空——是运动着的物质的基本存在形式。"}}},{"id":"basic-mayuan-ch01-5","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 5 题"},"stem":"自然界与人类社会、客观世界与主观世界相分化和统一的关键是","choices":[{"id":"A","text":"物质"},{"id":"B","text":"意识"},{"id":"C","text":"实践"},{"id":"D","text":"静止"}],"answer":["C"],"analysis":{"point":"","options":{"A":"物质——是不依赖于人类的意识而存在，并能为人类的意识所反映的客观实在。","B":"意识——是人脑的机能和属性，是客观世界的主观映象。","C":"实践——是自然界与人类社会、客观世界与主观世界相分化的关键，也是它们相统一的关键，是本题正确答案。","D":"静止——是物质运动在一定条件下的稳定状态，具体包括空间的相对位置暂时不变和事物的根本性质暂时不变两种状态。"}}},{"id":"basic-mayuan-ch01-6","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 6 题"},"stem":"意识是社会历史发展的产物。在意识的产生和发展中起决定性作用的是","choices":[{"id":"A","text":"能动性"},{"id":"B","text":"劳动"},{"id":"C","text":"语言"},{"id":"D","text":"运动"}],"answer":["B"],"analysis":{"point":"","options":{"A":"能动性——是人的实践活动和认识活动所具有的特性。","B":"劳动——在意识的产生和发展中起着决定性的作用，是本题正确答案。","C":"语言——是思维的物质外壳和意识的现实形式，意识正是通过语言表达出来的。","D":"运动——是物质的存在方式和根本属性。"}}},{"id":"basic-mayuan-ch01-7","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 7 题"},"stem":"承认规律的客观性，并不是说人在规律面前无能为力、无所作为。人能够通过自觉活动认识规律和利用规律。正确发挥人的主观能动性的根本途径是","choices":[{"id":"A","text":"意识"},{"id":"B","text":"实践"},{"id":"C","text":"时空"},{"id":"D","text":"观念"}],"answer":["B"],"analysis":{"point":"","options":{"A":"意识——是人脑的机能和属性，是客观世界的主观映象。","B":"实践是正确发挥人的主观能动性的根本途径，是本题正确答案。","C":"时空——是运动着的物质的基本存在方式。","D":"观念是意识的别称。"}}},{"id":"basic-mayuan-ch01-8","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 8 题"},"stem":"社会中虽然也包含精神现象，但从根本上讲，人类社会是一种物质性的存在，具有不以人的意志为转移的客观规律性。构成人类社会存在和发展的基础，集中体现着人类社会的物质性的是","choices":[{"id":"A","text":"自然地理环境"},{"id":"B","text":"物质资料的生产方式"},{"id":"C","text":"自然科学"},{"id":"D","text":"社会观念"}],"answer":["B"],"analysis":{"point":"","options":{"A":"自然地理环境——是人类社会生存和发展的必要条件，对社会发展起着加速或延缓的作用。","B":"物质资料的生产方式——构成了人类社会存在和发展的基础，集中体现着人类社会的物质性，是本题正确答案。","C":"属于意识范畴。","D":"属于意识范畴。"}}},{"id":"basic-mayuan-ch01-9","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 9 题"},"stem":"毛泽东同志在革命战争年代写下的《实践论》《矛盾论》等著作，灵活运用了辩证唯物主义世界观和方法论，形成了具有鲜明中国特色的马克思主义哲学思想，为我们党掌握和运用辩证唯物主义树立了光辉典范。辩证唯物主义最基本、最核心的观点是","choices":[{"id":"A","text":"矛盾的同一性和斗争性辩证关系原理"},{"id":"B","text":"世界的物质统一性原理"},{"id":"C","text":"实践观点"},{"id":"D","text":"生产关系一定要适应生产力的原理"}],"answer":["B"],"analysis":{"point":"","options":{"A":"矛盾的同一性和斗争性辩证关系原理——矛盾的同一性和斗争性是矛盾的两种基本属性。","B":"世界的物质统一性原理——是辩证唯物主义最基本、最核心的观点，是马克思主义的基石，是本题正确答案。","C":"实践观点——是马克思主义首要的和基本的观点。","D":"生产关系一定要适应生产力的原理——是社会历史发展的第一规律。"}}},{"id":"basic-mayuan-ch01-10","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 10 题"},"stem":"在坚持和发展中国特色社会主义伟大实践中，想问题、办事情的根本立足点是","choices":[{"id":"A","text":"充分发挥主观能动性"},{"id":"B","text":"一切从实际出发"},{"id":"C","text":"科学社会主义的基本原则"},{"id":"D","text":"马克思主义经典文本"}],"answer":["B"],"analysis":{"point":"","options":{"A":"充分发挥主观能动性——是意识能动性的方法论体现。","B":"一切从实际出发——是在坚持和发展中国特色社会主义伟大实践中想问题、办事情的根本立足点，是本题正确答案。","C":"科学社会主义的基本原则——是马克思主义的核心内容。","D":"马克思主义经典文本——非考点。"}}},{"id":"basic-mayuan-ch01-11","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 11 题"},"stem":"物质决定意识，意识对物质具有反作用，这种反作用就是意识的能动作用。意识的能动作用主要表现在","choices":[{"id":"A","text":"意识具有目的性和计划性"},{"id":"B","text":"意识具有创造性"},{"id":"C","text":"意识具有指导实践改造客观世界的作用"},{"id":"D","text":"意识具有调控人的行为和生理活动的作用"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是意识能动作用的四种主要表现，是本题正确答案。","B":"是意识能动作用的四种主要表现，是本题正确答案。","C":"是意识能动作用的四种主要表现，是本题正确答案。","D":"是意识能动作用的四种主要表现，是本题正确答案。"}}},{"id":"basic-mayuan-ch01-12","moduleId":"basic","subjectId":"mayuan","chapter":"第一章 辩证唯物论","chapterKey":"第一章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第一章 第 12 题"},"stem":"即使是计算能力最强大、最先进的智能机器，也达不到人类智能的层级，无法真正具有人的意识，不能取代或超越人类智能。人工智能不可能取代或超越人类智能的原因有","choices":[{"id":"A","text":"人工智能不具备情感、信念、意志等人类意识形式"},{"id":"B","text":"人工智能不可能真正具备人类的社会属性"},{"id":"C","text":"人工智能难以完全具备理解自然语言真实意义的能力"},{"id":"D","text":"人脑中总有许多东西是无法被化约的"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是人工智能不可能取代或超越人类智能的原因，是本题正确答案。","B":"是人工智能不可能取代或超越人类智能的原因，是本题正确答案。","C":"是人工智能不可能取代或超越人类智能的原因，是本题正确答案。","D":"是人工智能不可能取代或超越人类智能的原因，是本题正确答案。"}}},{"id":"basic-mayuan-ch02-1","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 1 题"},"stem":"马克思主义唯物辩证法并不是先验地强加到任何特定内容之上的抽象原则，它揭示的是世界的真实存在，是世界观和方法论的内在一致和高度统一。概括唯物辩证法的总观点、集中体现唯物辩证法的总特征的是","choices":[{"id":"A","text":"矛盾分析方法"},{"id":"B","text":"联系和发展的观点"},{"id":"C","text":"辩证否定观"},{"id":"D","text":"适度原则"}],"answer":["B"],"analysis":{"point":"","options":{"A":"矛盾分析方法——是人们认识世界和改造世界的根本方法。","B":"联系和发展的观点——是唯物辩证法的总观点，集中体现了唯物辩证法的总特征，是本题正确答案。","C":"辩证否定观——是包含肯定的否定，其实质是“扬弃”。","D":"适度原则是量变质变规律的方法论体现。"}}},{"id":"basic-mayuan-ch02-2","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 2 题"},"stem":"一切形式的变化就是运动，发展则是事物变化中前进的、上升的运动。发展的实质是","choices":[{"id":"A","text":"人类智能的物化"},{"id":"B","text":"新事物的产生和旧事物的灭亡"},{"id":"C","text":"系统观念"},{"id":"D","text":"对立统一规律"}],"answer":["B"],"analysis":{"point":"","options":{"A":"人类智能的物化——是人工智能的实质所在。","B":"新事物的产生和旧事物的灭亡——是发展的实质，是本题正确答案。","C":"系统观念是联系原理的方法论。","D":"对立统一规律——是唯物辩证法的实质和核心。"}}},{"id":"basic-mayuan-ch02-3","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 3 题"},"stem":"持续不断地深入揭示中国化时代化的马克思主义对唯物辩证法的贡献，是马克思主义理论工作者一项极为重要的任务。唯物辩证法的实质和核心是","choices":[{"id":"A","text":"对立统一规律"},{"id":"B","text":"量变质变规律"},{"id":"C","text":"否定之否定规律"},{"id":"D","text":"过程观点"}],"answer":["A"],"analysis":{"point":"","options":{"A":"对立统一规律——是唯物辩证法的实质和核心，是本题正确答案。","B":"与对立统一规律一起，是唯物辩证法的三大规律。","C":"与对立统一规律一起，是唯物辩证法的三大规律。","D":"过程观点是发展原理的方法论。"}}},{"id":"basic-mayuan-ch02-4","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 4 题"},"stem":"对立统一规律从根本上回答了事物为什么会发展的问题，它揭示了","choices":[{"id":"A","text":"事物发展的形式和状态"},{"id":"B","text":"事物发展的方向和道路"},{"id":"C","text":"事物发展的内在动力"},{"id":"D","text":"事物的内在要素及结构形式"}],"answer":["C"],"analysis":{"point":"","options":{"A":"事物发展的形式和状态——是量变质变规律所揭示的内容。","B":"事物发展的方向和道路——是否定之否定规律所揭示的内容。","C":"事物发展的内在动力——是对立统一规律所揭示的内容，是本题正确答案。","D":"事物的内在要素及结构形式——是内容与形式的辩证关系原理所揭示的问题。"}}},{"id":"basic-mayuan-ch02-5","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 5 题"},"stem":"在调查研究中坚持马克思主义的立场观点方法，就是要坚持唯物辩证法，反对形而上学。唯物辩证法和形而上学对立的实质是","choices":[{"id":"A","text":"是否承认世界的联系和发展"},{"id":"B","text":"是否承认对立统一规律"},{"id":"C","text":"是否承认物质的第一性"},{"id":"D","text":"是否承认世界的可知性"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是否承认世界的联系和发展——是唯物辩证法和形而上学对立的表现之一。","B":"是否承认对立统一规律——是唯物辩证法和形而上学对立的实质，是本题正确答案。","C":"是否承认物质的第一性——是唯物主义和唯心主义对立的实质。","D":"是否承认世界的可知性——是可知论和不可知论对立的实质。"}}},{"id":"basic-mayuan-ch02-6","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 6 题"},"stem":"对立统一规律提供了人们认识世界和改造世界的根本方法——矛盾分析方法，它是对事物辩证认识的实质。关于事物矛盾问题的精髓是","choices":[{"id":"A","text":"矛盾的共性和个性、绝对和相对的道理"},{"id":"B","text":"矛盾的同一性和斗争性"},{"id":"C","text":"由认识个别上升到认识一般，再由认识一般到认识个别"},{"id":"D","text":"“两点论”和“重点论”的统一"}],"answer":["A"],"analysis":{"point":"","options":{"A":"矛盾的共性和个性、绝对和相对的道理——是关于事物矛盾问题的精髓，是本题正确答案。","B":"矛盾的同一性和斗争性是矛盾的两种基本属性。","C":"由认识个别上升到认识一般，再由认识一般到认识个别——是人的认识的一般规律。","D":"“两点论”和“重点论”的统一——是矛盾不平衡性原理的方法论。"}}},{"id":"basic-mayuan-ch02-7","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 7 题"},"stem":"从构成要素和表现方式上反映事物的范畴是","choices":[{"id":"A","text":"内容与形式"},{"id":"B","text":"原因与结果"},{"id":"C","text":"必然与偶然"},{"id":"D","text":"现象与本质"}],"answer":["A"],"analysis":{"point":"","options":{"A":"内容与形式——是从构成要素和表现方式上反映事物的一对范畴，是本题正确答案。","B":"原因与结果——是揭示事物引起和被引起关系的一对范畴。","C":"必然与偶然——是揭示事物产生、发展和衰亡过程中的不同趋势的一对范畴。","D":"现象与本质——是揭示事物外在表现和内在联系的一对范畴。"}}},{"id":"basic-mayuan-ch02-8","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 8 题"},"stem":"反映事物的过去、现在和将来关系的范畴是","choices":[{"id":"A","text":"原因与结果"},{"id":"B","text":"必然与偶然"},{"id":"C","text":"现象与本质"},{"id":"D","text":"可能与现实"}],"answer":["D"],"analysis":{"point":"","options":{"A":"原因与结果——是揭示事物引起和被引起关系的一对范畴。","B":"必然与偶然——是揭示事物产生、发展和衰亡过程中的不同趋势的一对范畴。","C":"现象与本质——是揭示事物外在表现和内在联系的一对范畴。","D":"可能与现实——是反映事物的过去、现在和将来关系的一对范畴，是本题正确答案。"}}},{"id":"basic-mayuan-ch02-9","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 9 题"},"stem":"联系是指事物内部各要素之间和事物之间相互影响、相互制约和相互作用的关系。联系的特点包括","choices":[{"id":"A","text":"客观性"},{"id":"B","text":"普遍性"},{"id":"C","text":"多样性"},{"id":"D","text":"条件性"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是联系的四种特点，是本题正确答案。","B":"是联系的四种特点，是本题正确答案。","C":"是联系的四种特点，是本题正确答案。","D":"是联系的四种特点，是本题正确答案。"}}},{"id":"basic-mayuan-ch02-10","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 10 题"},"stem":"矛盾的同一性和斗争性在事物发展过程中有着不同的作用。矛盾的同一性在事物发展中的作用主要表现在","choices":[{"id":"A","text":"矛盾双方可以利用对方的发展使自己得到发展"},{"id":"B","text":"矛盾双方可以相互吸取有利于自身的因素而得到发展"},{"id":"C","text":"矛盾双方可以向着彼此的对立面转化而得到发展，并规定着事物发展的方向"},{"id":"D","text":"矛盾存在于一切事物中，存在于一切事物发展过程的始终"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是矛盾的同一性在事物发展中的作用的主要表现，是本题正确答案。","B":"是矛盾的同一性在事物发展中的作用的主要表现，是本题正确答案。","C":"是矛盾的同一性在事物发展中的作用的主要表现，是本题正确答案。","D":"矛盾存在于一切事物中，存在于一切事物发展过程的始终——是矛盾普遍性的表现。"}}},{"id":"basic-mayuan-ch02-11","moduleId":"basic","subjectId":"mayuan","chapter":"第二章 唯物辩证法","chapterKey":"第二章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第二章 第 11 题"},"stem":"辩证否定观是马克思主义哲学的重要组成部分，它建立在对肯定和否定对立统一的辩证理解的基础上。辩证否定观的基本内容包括","choices":[{"id":"A","text":"否定是事物的自我否定、自我发展，是事物内部矛盾运动的结果"},{"id":"B","text":"否定是事物发展的环节"},{"id":"C","text":"否定是新旧事物联系的环节"},{"id":"D","text":"辩证否定的实质是“扬弃”"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是辩证否定观的基本内容，是本题正确答案。","B":"是辩证否定观的基本内容，是本题正确答案。","C":"是辩证否定观的基本内容，是本题正确答案。","D":"是辩证否定观的基本内容，是本题正确答案。"}}},{"id":"basic-mayuan-ch03-1","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 1 题"},"stem":"马克思在《关于费尔巴哈的提纲》这个集中阐述科学实践观的重要文献中，阐明了实践是","choices":[{"id":"A","text":"主体自我实现的精神活动"},{"id":"B","text":"感性的、对象性的物质活动"},{"id":"C","text":"理性先天的道德活动"},{"id":"D","text":"生物适应环境的活动"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是唯心主义的观点。","B":"感性的、对象性的物质活动——是马克思阐述的科学实践观，是本题正确答案。","C":"是唯心主义的观点。","D":"生物适应环境的活动是旧唯物主义的观点。"}}},{"id":"basic-mayuan-ch03-2","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 2 题"},"stem":"人的实践活动是以改造客观世界为目的的客观过程，是实践的主体与客体之间的相互作用，这种相互作用必须借助于一定的手段和工具，即实践的中介。实践活动中具有自主性和能动性的因素是","choices":[{"id":"A","text":"实践主体"},{"id":"B","text":"实践中介"},{"id":"C","text":"实践客体"},{"id":"D","text":"实践对象"}],"answer":["A"],"analysis":{"point":"","options":{"A":"实践主体——是实践的基本结构的要素之一，是实践活动中具有自主性和能动性的因素，是本题正确答案。","B":"均属于实践的基本结构，其中实践对象是实践客体的别称。","C":"均属于实践的基本结构，其中实践对象是实践客体的别称。","D":"均属于实践的基本结构，其中实践对象是实践客体的别称。"}}},{"id":"basic-mayuan-ch03-3","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 3 题"},"stem":"实践主体的能力包括自然能力和精神能力，精神能力又包括知识性因素和非知识性因素。其中，首要的能力是","choices":[{"id":"A","text":"情感和意志因素"},{"id":"B","text":"知识性因素"},{"id":"C","text":"非知识性因素"},{"id":"D","text":"自然能力"}],"answer":["B"],"analysis":{"point":"","options":{"A":"情感和意志因素——是实践主体精神能力中的非知识性因素。","B":"知识性因素——是实践主体精神能力中的首要的能力，是本题正确答案。","C":"非知识性因素——是实践主体精神能力的组成部分。","D":"自然能力是实践主体能力的组成部分。"}}},{"id":"basic-mayuan-ch03-4","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 4 题"},"stem":"在实践的主体和客体相互作用的关系中，最根本的关系是","choices":[{"id":"A","text":"实践关系"},{"id":"B","text":"认识关系"},{"id":"C","text":"价值关系"},{"id":"D","text":"自然关系"}],"answer":["A"],"analysis":{"point":"","options":{"A":"实践关系——是实践的主体和客体相互作用的关系中最根本的关系，是本题正确答案。","B":"属于实践的主体和客体相互作用的关系，但不是最根本的关系。","C":"属于实践的主体和客体相互作用的关系，但不是最根本的关系。","D":"自然关系非考点。"}}},{"id":"basic-mayuan-ch03-5","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 5 题"},"stem":"随着人与世界关系的发展，特别是随着社会分工的进步，人类实践的具体形式日益多样化。其中，最基本的实践活动是","choices":[{"id":"A","text":"物质生产实践"},{"id":"B","text":"社会政治实践"},{"id":"C","text":"科学文化实践"},{"id":"D","text":"虚拟实践"}],"answer":["A"],"analysis":{"point":"","options":{"A":"物质生产实践——属于实践的基本类型，是人类最基本的实践活动，是本题正确答案。","B":"也属于实践的基本类型，但不是最基本的实践活动。","C":"也属于实践的基本类型，但不是最基本的实践活动。","D":"虚拟实践——是实践活动的派生形式，具有相对独立性。"}}},{"id":"basic-mayuan-ch03-6","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 6 题"},"stem":"人与世界的关系主要包括两个方面：一是认识世界；二是改造世界。人类认识世界和改造世界的根本目标是","choices":[{"id":"A","text":"追求真理"},{"id":"B","text":"认识必然和争取自由"},{"id":"C","text":"实现意志自由"},{"id":"D","text":"消除事物自身固有的矛盾"}],"answer":["B"],"analysis":{"point":"","options":{"A":"追求真理是认识世界和改造世界的目标之一。","B":"认识必然和争取自由——是人类认识世界和改造世界的根本目标，是本题正确答案。","C":"实现意志自由——是唯心主义的观点。","D":"消除事物自身固有的矛盾——是形而上学的观点。"}}},{"id":"basic-mayuan-ch03-7","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 7 题"},"stem":"关于事物的本质、全体、内部联系和事物自身规律性的认识是","choices":[{"id":"A","text":"感性认识"},{"id":"B","text":"理性认识"},{"id":"C","text":"理性因素"},{"id":"D","text":"非理性因素"}],"answer":["B"],"analysis":{"point":"","options":{"A":"感性认识——是人们在实践基础上，由感觉器官直接感受到的关于事物的现象、事物的外部联系、事物的各个方面的认识。","B":"理性认识——是关于事物的本质、全体、内部联系和事物自身规律性的认识，是本题正确答案。","C":"理性因素——是指人的理性直观、理性思维等能力。","D":"非理性因素——是指认识主体的情感和意志。"}}},{"id":"basic-mayuan-ch03-8","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 8 题"},"stem":"以下既是思维的细胞，也是最基本的思维形式的是","choices":[{"id":"A","text":"感觉"},{"id":"B","text":"判断"},{"id":"C","text":"推理"},{"id":"D","text":"概念"}],"answer":["D"],"analysis":{"point":"","options":{"A":"感觉是感性认识的基本形式之一。","B":"与概念一起，均属于理性认识的基本形式。","C":"与概念一起，均属于理性认识的基本形式。","D":"概念——是理性认识的基本形式之一，既是思维的细胞，也是最基本的思维形式，是本题正确答案。"}}},{"id":"basic-mayuan-ch03-9","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 9 题"},"stem":"实践是人类能动地改造世界的社会性的物质活动，实践的基本特征包括","choices":[{"id":"A","text":"客观实在性"},{"id":"B","text":"自觉能动性"},{"id":"C","text":"被动适应性"},{"id":"D","text":"社会历史性"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是实践的基本特征，是本题正确答案。","B":"是实践的基本特征，是本题正确答案。","C":"被动适应性是动物具有的特性。","D":"是实践的基本特征，是本题正确答案。"}}},{"id":"basic-mayuan-ch03-10","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 10 题"},"stem":"人类的社会生活色彩斑斓，实践活动在形式上是丰富多彩的。毛泽东指出，“人的社会实践，不限于生产活动一种形式，还有多种其他的形式，阶级斗争，政治生活，科学和艺术的活动”。从内容上看，实践的基本类型包括","choices":[{"id":"A","text":"物质生产实践"},{"id":"B","text":"社会政治实践"},{"id":"C","text":"科学文化实践"},{"id":"D","text":"虚拟实践"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是实践形式的三种基本类型，是本题正确答案。","B":"是实践形式的三种基本类型，是本题正确答案。","C":"是实践形式的三种基本类型，是本题正确答案。","D":"虚拟实践——是实践活动的派生形式，具有相对独立性。"}}},{"id":"basic-mayuan-ch03-11","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 11 题"},"stem":"辩证唯物主义认为，在实践和认识之间，实践是认识的基础，实践在认识活动中起着决定性的作用。“实践的观点是辩证唯物论的认识论之第一的和基本的观点。”实践对认识的决定作用表现在","choices":[{"id":"A","text":"实践是认识的来源"},{"id":"B","text":"实践是认识发展的动力"},{"id":"C","text":"实践是认识的目的"},{"id":"D","text":"实践是检验认识真理性的唯一标准"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是实践对认识的决定作用的具体表现，是本题正确答案。","B":"是实践对认识的决定作用的具体表现，是本题正确答案。","C":"是实践对认识的决定作用的具体表现，是本题正确答案。","D":"是实践对认识的决定作用的具体表现，是本题正确答案。"}}},{"id":"basic-mayuan-ch03-12","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 12 题"},"stem":"感性认识是人们在实践基础上，由感觉器官直接感受到的关于事物的现象、事物的外部联系、事物的各个方面的认识。感性认识的表现形式包括","choices":[{"id":"A","text":"感觉"},{"id":"B","text":"推理"},{"id":"C","text":"知觉"},{"id":"D","text":"表象"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是感性认识的表现形式，是本题正确答案。","B":"推理——是理性认识的基本形式之一。","C":"是感性认识的表现形式，是本题正确答案。","D":"是感性认识的表现形式，是本题正确答案。"}}},{"id":"basic-mayuan-ch03-13","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 13 题"},"stem":"认识的过程首先是从实践到认识的过程。这个过程主要表现为在实践基础上认识活动由感性认识能动地飞跃到理性认识。感性认识的特点包括","choices":[{"id":"A","text":"直接性"},{"id":"B","text":"抽象性"},{"id":"C","text":"具体性"},{"id":"D","text":"间接性"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是感性认识的特点，是本题正确答案。","B":"是理性认识的特点。","C":"是感性认识的特点，是本题正确答案。","D":"是理性认识的特点。"}}},{"id":"basic-mayuan-ch03-14","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 14 题"},"stem":"在认识的辩证运动中，我们既要注重理性因素的作用，同时也不可忽视非理性因素的重要作用。其中，理性因素的作用主要有","choices":[{"id":"A","text":"指导作用"},{"id":"B","text":"解释作用"},{"id":"C","text":"预见作用"},{"id":"D","text":"激活、驱动作用"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是理性因素所起的作用，是本题正确答案。","B":"是理性因素所起的作用，是本题正确答案。","C":"是理性因素所起的作用，是本题正确答案。","D":"激活、驱动作用是非理性因素所起的作用。"}}},{"id":"basic-mayuan-ch03-15","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 15 题"},"stem":"从真理的二重性上看，真理的绝对性与相对性相互依存，任何真理都既是绝对的，又是相对的。真理的绝对性与相对性根源于人的认识能力、思维能力的矛盾本性，即","choices":[{"id":"A","text":"人的思维的至上性和非至上性的矛盾"},{"id":"B","text":"人的认识能力的无限性和有限性的矛盾"},{"id":"C","text":"真理的主观内容与客观形式的矛盾"},{"id":"D","text":"真理的客观内容与单一形式的矛盾"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是人的认识能力、思维能力的矛盾本性，是本题正确答案。","B":"是人的认识能力、思维能力的矛盾本性，是本题正确答案。","C":"真理的主观内容与客观形式的矛盾——是错误说法，真理是客观内容和主观形式的统一。","D":"真理的客观内容与单一形式的矛盾——是错误说法，真理的内容是客观的，形式是多样的。"}}},{"id":"basic-mayuan-ch03-16","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 16 题"},"stem":"真理具有客观性，凡真理都是客观真理。真理的客观性或客观真理的含义是","choices":[{"id":"A","text":"真理的内容是客观的"},{"id":"B","text":"真理是“思想形式”"},{"id":"C","text":"有用即真理"},{"id":"D","text":"真理的标准是客观的"}],"answer":["A","D"],"analysis":{"point":"","options":{"A":"是真理的客观性的体现，是本题正确答案。","B":"是唯心主义的观点。","C":"是唯心主义的观点。","D":"是真理的客观性的体现，是本题正确答案。"}}},{"id":"basic-mayuan-ch03-17","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 17 题"},"stem":"价值是反映主体和客体之间意义关系的哲学范畴，是客体对个人、群体乃至整个社会的生活和活动所具有的意义。价值的基本特性包括","choices":[{"id":"A","text":"主体性"},{"id":"B","text":"客观性"},{"id":"C","text":"多维性"},{"id":"D","text":"社会历史性"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是价值的基本特性，是本题正确答案。","B":"是价值的基本特性，是本题正确答案。","C":"是价值的基本特性，是本题正确答案。","D":"是价值的基本特性，是本题正确答案。"}}},{"id":"basic-mayuan-ch03-18","moduleId":"basic","subjectId":"mayuan","chapter":"第三章 认识论","chapterKey":"第三章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第三章 第 18 题"},"stem":"价值评价是一种关于价值现象的认识活动，是主体对客体的价值以及价值大小所作的评判或判断，因而也被称作价值判断。价值评价的基本特点主要有","choices":[{"id":"A","text":"评价以主客体之间的价值关系为认识对象"},{"id":"B","text":"评价结果与评价主体直接相关"},{"id":"C","text":"评价结果的正确与否依赖于对客体状况和主体需要的认识"},{"id":"D","text":"价值评价有科学与非科学之别"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是价值评价的基本特点，是本题正确答案。","B":"是价值评价的基本特点，是本题正确答案。","C":"是价值评价的基本特点，是本题正确答案。","D":"是价值评价的基本特点，是本题正确答案。"}}},{"id":"basic-mayuan-ch04-1","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 1 题"},"stem":"唯物史观是唯一科学的历史观，它把人们对社会历史的认识，从唯心史观的统治下彻底解放出来。社会历史观的基本问题是","choices":[{"id":"A","text":"思维与存在是否具有同一性问题"},{"id":"B","text":"生产力与生产关系的矛盾"},{"id":"C","text":"社会存在和社会意识的关系问题"},{"id":"D","text":"经济基础与上层建筑的矛盾"}],"answer":["C"],"analysis":{"point":"","options":{"A":"思维与存在是否具有同一性问题——是划分可知论与不可知论的标准。","B":"是社会基本矛盾。","C":"社会存在和社会意识的关系问题——是社会历史观的基本问题，是本题正确答案。","D":"是社会基本矛盾。"}}},{"id":"basic-mayuan-ch04-2","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 2 题"},"stem":"在历史观上，划分唯物史观与唯心史观的分水岭是","choices":[{"id":"A","text":"主张社会存在决定社会意识，还是社会意识决定社会存在"},{"id":"B","text":"是否承认世界的可知性"},{"id":"C","text":"历史创造者问题"},{"id":"D","text":"是否承认对立统一规律"}],"answer":["C"],"analysis":{"point":"","options":{"A":"主张社会存在决定社会意识，还是社会意识决定社会存在——是唯物史观与唯心史观的根本分野。","B":"是否承认世界的可知性——是划分可知论和不可知论的标准。","C":"历史创造者问题——是划分唯物史观与唯心史观的分水岭，是本题正确答案。","D":"是否承认对立统一规律——是唯物辩证法和形而上学对立的实质。"}}},{"id":"basic-mayuan-ch04-3","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 3 题"},"stem":"社会意识具有相对独立性，它在反映社会存在的同时具有自身特有的发展形式和发展规律。社会意识相对独立性的突出表现是","choices":[{"id":"A","text":"社会意识与社会存在发展不完全同步"},{"id":"B","text":"社会意识内部各种形式之间相互影响"},{"id":"C","text":"社会意识具有历史继承性"},{"id":"D","text":"社会意识对社会存在具有能动的反作用"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是社会意识相对独立性的具体表现，但不是突出表现。","B":"是社会意识相对独立性的具体表现，但不是突出表现。","C":"是社会意识相对独立性的具体表现，但不是突出表现。","D":"社会意识对社会存在具有能动的反作用——是社会意识相对独立性的突出表现，是本题正确答案。"}}},{"id":"basic-mayuan-ch04-4","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 4 题"},"stem":"区分社会经济时代的客观依据是","choices":[{"id":"A","text":"生产资料所有制关系"},{"id":"B","text":"生产工具"},{"id":"C","text":"劳动者"},{"id":"D","text":"劳动对象"}],"answer":["B"],"analysis":{"point":"","options":{"A":"生产资料所有制关系——是生产关系中最基本的、决定性的要素，构成全部生产关系的基础，是区分不同生产方式、判定社会经济结构性质的客观依据。","B":"生产工具——是区分社会经济时代的客观依据，是本题正确答案。","C":"劳动者——是生产力的基本要素之一，是生产力中最活跃的因素。","D":"劳动对象是生产力的基本要素之一。"}}},{"id":"basic-mayuan-ch04-5","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 5 题"},"stem":"劳动资料是人们在劳动过程中所运用的物质资料或物质条件。劳动对象是指人们通过自身劳动对之进行加工，使之变为使用价值用以满足社会需要的那一部分物质资料。劳动资料和劳动对象合称为","choices":[{"id":"A","text":"生产力"},{"id":"B","text":"生产资料"},{"id":"C","text":"劳动手段"},{"id":"D","text":"生产关系"}],"answer":["B"],"analysis":{"point":"","options":{"A":"生产力——是标志人类改造自然的实际程度和实际能力的范畴。","B":"生产资料——是劳动资料和劳动对象的合称，是本题正确答案。","C":"劳动手段——也称劳动资料，是生产力的基本要素之一。","D":"生产关系——是人们在物质生产过程中形成的不以人的意志为转移的经济关系，是社会关系中最基本的关系。"}}},{"id":"basic-mayuan-ch04-6","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 6 题"},"stem":"新质生产力是以创新为主导，强调高科技、高效能和高质量特征的先进生产力。先进生产力的集中体现和主要标志是","choices":[{"id":"A","text":"生产工具"},{"id":"B","text":"劳动者"},{"id":"C","text":"科学技术"},{"id":"D","text":"管理制度"}],"answer":["C"],"analysis":{"point":"","options":{"A":"生产工具——是生产力的基本要素之一，是区分社会经济时代的客观依据。","B":"劳动者——是生产力的基本要素之一，是生产力中最活跃的因素。","C":"科学技术——是生产力中的重要因素，是先进生产力的集中体现和主要标志，是本题正确答案。","D":"管理制度非考点。"}}},{"id":"basic-mayuan-ch04-7","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 7 题"},"stem":"唯物史观认为，社会进步的最高标准是","choices":[{"id":"A","text":"社会和谐程度"},{"id":"B","text":"社会道德水平"},{"id":"C","text":"生产力发展水平"},{"id":"D","text":"人民生活水平"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是社会进步的具体表现，但不是最高标准。","B":"是社会进步的具体表现，但不是最高标准。","C":"生产力发展水平——是社会进步的最高标准，是本题正确答案。","D":"是社会进步的具体表现，但不是最高标准。"}}},{"id":"basic-mayuan-ch04-8","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 8 题"},"stem":"上层建筑是指建立在一定经济基础之上的意识形态以及与之相适应的制度、组织和设施。自原始社会解体以来，上层建筑由意识形态以及政治法律制度及设施和政治组织两部分构成。在整个上层建筑中，居于主导地位的是","choices":[{"id":"A","text":"观念上层建筑"},{"id":"B","text":"政治上层建筑"},{"id":"C","text":"生产资料所有制关系"},{"id":"D","text":"产品分配关系"}],"answer":["B"],"analysis":{"point":"","options":{"A":"观念上层建筑——又称意识形态，是上层建筑的组成部分。","B":"政治上层建筑是政治法律制度及设施和政治组织，在上层建筑中居于主导地位，是本题正确答案。","C":"是生产关系的构成要素，不属于上层建筑。","D":"是生产关系的构成要素，不属于上层建筑。"}}},{"id":"basic-mayuan-ch04-9","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 9 题"},"stem":"政治上层建筑一旦形成，就成为一种现实的力量，影响并制约着人们的思想理论观点。政治上层建筑的核心是","choices":[{"id":"A","text":"政党制度"},{"id":"B","text":"法律制度"},{"id":"C","text":"国家政权"},{"id":"D","text":"政治法律思想"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是政治上层建筑的构成部分，但不是核心。","B":"是政治上层建筑的构成部分，但不是核心。","C":"国家政权——是政治上层建筑的核心，是本题正确答案。","D":"政治法律思想——是观念上层建筑的核心。"}}},{"id":"basic-mayuan-ch04-10","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 10 题"},"stem":"唯物史观视域中的“世界历史”是指各民族、国家通过普遍交往，打破孤立隔绝的状态，进入相互依存、相互联系的世界整体化的历史。世界历史的基本特征是","choices":[{"id":"A","text":"生产方式的发展变革"},{"id":"B","text":"普遍交往"},{"id":"C","text":"资本主义生产方式的出现"},{"id":"D","text":"促进文化的发展与传播"}],"answer":["B"],"analysis":{"point":"","options":{"A":"生产方式的发展变革——是世界历史形成和发展的基础。","B":"普遍交往——是世界历史的基本特征，是本题正确答案。","C":"资本主义生产方式的出现——是世界历史产生的原因之一。","D":"促进文化的发展与传播——是交往对社会生活的重要影响之一。"}}},{"id":"basic-mayuan-ch04-11","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 11 题"},"stem":"人的发展是指人的体力、智力、个性和交往能力等的发展，其中最根本的是","choices":[{"id":"A","text":"人的体力的增强"},{"id":"B","text":"人的智力的提高"},{"id":"C","text":"人的自由程度的提高"},{"id":"D","text":"人的交往范围的扩大"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是人的发展的具体表现。","B":"是人的发展的具体表现。","C":"人的自由程度的提高——是人的发展最根本的表现，是本题正确答案。","D":"是人的发展的具体表现。"}}},{"id":"basic-mayuan-ch04-12","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 12 题"},"stem":"唯物史观全面揭示了人类社会历史发展的动力系统。历史发展的根本动力是","choices":[{"id":"A","text":"阶级斗争"},{"id":"B","text":"社会基本矛盾"},{"id":"C","text":"科学技术"},{"id":"D","text":"改革"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是社会历史发展的重要动力。","B":"社会基本矛盾——是社会历史发展的根本动力，是本题正确答案。","C":"是社会历史发展的重要动力。","D":"是社会历史发展的重要动力。"}}},{"id":"basic-mayuan-ch04-13","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 13 题"},"stem":"以下既是社会基本矛盾运动中最基本的动力因素，也是人类社会发展和进步的最终决定力量的是","choices":[{"id":"A","text":"生产力"},{"id":"B","text":"生产关系"},{"id":"C","text":"经济基础"},{"id":"D","text":"上层建筑"}],"answer":["A"],"analysis":{"point":"","options":{"A":"生产力——是社会基本矛盾运动中最基本的动力因素，也是人类社会发展和进步的最终决定力量，是本题正确答案。","B":"生产关系——是人们在物质生产过程中形成的不以人的意志为转移的经济关系，是社会关系中最基本的关系。","C":"经济基础——是指由社会一定发展阶段的生产力所决定的生产关系的总和。","D":"上层建筑——是建立在一定经济基础之上的意识形态以及与之相适应的制度、组织和设施。"}}},{"id":"basic-mayuan-ch04-14","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 14 题"},"stem":"以下被称为“一切历史冲突的根源”，并决定着其他社会矛盾的是","choices":[{"id":"A","text":"经济基础和上层建筑的矛盾"},{"id":"B","text":"人民群众和历史人物的矛盾"},{"id":"C","text":"道德与艺术的矛盾"},{"id":"D","text":"生产力和生产关系的矛盾"}],"answer":["D"],"analysis":{"point":"","options":{"A":"经济基础和上层建筑的矛盾——是社会基本矛盾之一。","B":"人民群众和历史人物的矛盾——是人类社会的具体矛盾之一。","C":"道德与艺术的矛盾非考点。","D":"生产力和生产关系的矛盾——是社会基本矛盾之一，被称为“一切历史冲突的根源”，并决定着其他社会矛盾，是本题正确答案。"}}},{"id":"basic-mayuan-ch04-15","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 15 题"},"stem":"人类社会是不断发展的，社会的根本性变革和进步就是通过社会形态的更替实现的。实现社会形态更替的重要手段和决定性环节是","choices":[{"id":"A","text":"阶级斗争"},{"id":"B","text":"改革"},{"id":"C","text":"文化发展"},{"id":"D","text":"革命"}],"answer":["D"],"analysis":{"point":"","options":{"A":"阶级斗争——是社会基本矛盾在阶级社会中的表现，是阶级社会发展的直接动力。","B":"是推动社会发展的重要动力。","C":"是推动社会发展的重要动力。","D":"革命——是阶级斗争的最高形式，是实现社会形态更替的重要手段和决定性环节，是本题正确答案。"}}},{"id":"basic-mayuan-ch04-16","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 16 题"},"stem":"唯物史观立足于现实的人及其本质来把握历史的创造者。人的本质属性是","choices":[{"id":"A","text":"自然属性"},{"id":"B","text":"社会属性"},{"id":"C","text":"政治属性"},{"id":"D","text":"文化属性"}],"answer":["B"],"analysis":{"point":"","options":{"A":"自然属性——是人的属性之一，但不是本质属性。","B":"社会属性——是人的本质属性，是本题正确答案。","C":"是人的属性，属于人的社会属性。","D":"是人的属性，属于人的社会属性。"}}},{"id":"basic-mayuan-ch04-17","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 17 题"},"stem":"人民群众是一个历史范畴，在不同的历史时期，人民群众有着不同的内容，包含着不同的阶级、阶层和集团。人民群众中最稳定的主体部分始终是","choices":[{"id":"A","text":"奴隶主阶级"},{"id":"B","text":"资产阶级"},{"id":"C","text":"从事物质资料生产的劳动群众"},{"id":"D","text":"地主阶级"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是特定历史阶段中人民群众的构成部分。","B":"是特定历史阶段中人民群众的构成部分。","C":"从事物质资料生产的劳动群众——始终是人民群众中最稳定的主体部分，是本题正确答案。","D":"是特定历史阶段中人民群众的构成部分。"}}},{"id":"basic-mayuan-ch04-18","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":18,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 18 题"},"stem":"以下既是社会历史实践的主体，也是历史的创造者的是","choices":[{"id":"A","text":"杰出人物"},{"id":"B","text":"人民群众"},{"id":"C","text":"历史人物"},{"id":"D","text":"英雄人物"}],"answer":["B"],"analysis":{"point":"","options":{"A":"杰出人物——是历史人物中对推动历史社会发展作出重要贡献或起重要作用的人。","B":"人民群众——既是社会历史实践的主体，也是历史的创造者，是本题正确答案。","C":"历史人物——是一定历史事件的主要倡导者、组织领导者或思想理论、科学文化的重要代表人物。","D":"英雄人物是杰出人物的别称。"}}},{"id":"basic-mayuan-ch04-19","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":19,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 19 题"},"stem":"无产阶级政党的群众观点和群众路线的理论基础是","choices":[{"id":"A","text":"社会存在决定社会意识的原理"},{"id":"B","text":"人民群众是历史创造者的原理"},{"id":"C","text":"社会形态更替的原理"},{"id":"D","text":"阶级斗争理论"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是唯物史观的具体原理。","B":"人民群众是历史创造者的原理——是无产阶级政党的群众观点和群众路线的理论基础，是本题正确答案。","C":"是唯物史观的具体原理。","D":"是唯物史观的具体原理。"}}},{"id":"basic-mayuan-ch04-20","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 20 题"},"stem":"社会存在是社会生活的物质方面，是社会实践和物质生活各种条件的总和，主要包括","choices":[{"id":"A","text":"物质生产方式"},{"id":"B","text":"自然地理环境"},{"id":"C","text":"人口因素"},{"id":"D","text":"哲学"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是社会存在的构成要素，是本题正确答案。","B":"是社会存在的构成要素，是本题正确答案。","C":"是社会存在的构成要素，是本题正确答案。","D":"哲学——是社会意识的构成要素，不属于社会存在。"}}},{"id":"basic-mayuan-ch04-21","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 21 题"},"stem":"生产力是人类在生产实践中形成的改造和影响自然以使其适合社会需要的物质力量。生产力的基本要素包括","choices":[{"id":"A","text":"劳动资料"},{"id":"B","text":"生产资料所有制关系"},{"id":"C","text":"劳动者"},{"id":"D","text":"劳动对象"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是生产力的基本要素，是本题正确答案。","B":"生产资料所有制关系——是生产关系中最基本的、决定性的要素，构成全部生产关系的基础，是区分不同生产方式、判定社会经济结构性质的客观依据。","C":"是生产力的基本要素，是本题正确答案。","D":"是生产力的基本要素，是本题正确答案。"}}},{"id":"basic-mayuan-ch04-22","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 22 题"},"stem":"狭义的生产关系是指在直接生产过程中结成的相互关系，主要包括","choices":[{"id":"A","text":"生产资料所有制关系"},{"id":"B","text":"生产中人与人的关系"},{"id":"C","text":"产品分配关系"},{"id":"D","text":"消费关系"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是狭义的生产关系的构成要素，是本题正确答案。","B":"是狭义的生产关系的构成要素，是本题正确答案。","C":"是狭义的生产关系的构成要素，是本题正确答案。","D":"消费关系——是广义的生产关系的构成要素。广义的生产关系是指人们在再生产的过程中结成的相互关系，是包括生产、分配、交换和消费等诸多关系在内的生产关系体系。"}}},{"id":"basic-mayuan-ch04-23","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 23 题"},"stem":"唯物史观从社会进步和人的发展的内在联系出发，把人的发展从低级到高级依次概括为不同阶段，包括","choices":[{"id":"A","text":"人的依赖关系占统治地位的阶段"},{"id":"B","text":"意志自由的阶段"},{"id":"C","text":"以物的依赖关系为基础的人的独立性的阶段"},{"id":"D","text":"自由个性的阶段"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是人的发展从低级到高级的三个阶段，是本题正确答案。","B":"意志自由的阶段是唯意志论的观点。","C":"是人的发展从低级到高级的三个阶段，是本题正确答案。","D":"是人的发展从低级到高级的三个阶段，是本题正确答案。"}}},{"id":"basic-mayuan-ch04-24","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 24 题"},"stem":"社会形态是关于社会运动的具体形式、发展阶段和不同质态的范畴，是同生产力发展一定阶段相适应的经济基础与上层建筑的统一体。社会形态包括社会的","choices":[{"id":"A","text":"经济形态"},{"id":"B","text":"政治形态"},{"id":"C","text":"意识形态"},{"id":"D","text":"科技形态"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是社会形态的构成要素，是本题正确答案。","B":"是社会形态的构成要素，是本题正确答案。","C":"是社会形态的构成要素，是本题正确答案。","D":"科技形态非考点。"}}},{"id":"basic-mayuan-ch04-25","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 25 题"},"stem":"在新的历史时期，坚持和贯彻党的群众观点和群众路线，就要把“人民拥护不拥护”“人民赞成不赞成”“人民高兴不高兴”“人民答应不答应”作为制定各项方针、政策的出发点和归宿。群众观点的主要内容有","choices":[{"id":"A","text":"坚信人民群众自己解放自己"},{"id":"B","text":"全心全意为人民服务"},{"id":"C","text":"一切向人民群众负责"},{"id":"D","text":"虚心向人民群众学习"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是群众观点的主要内容，是本题正确答案。","B":"是群众观点的主要内容，是本题正确答案。","C":"是群众观点的主要内容，是本题正确答案。","D":"是群众观点的主要内容，是本题正确答案。"}}},{"id":"basic-mayuan-ch04-26","moduleId":"basic","subjectId":"mayuan","chapter":"第四章 唯物史观","chapterKey":"第四章","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第四章 第 26 题"},"stem":"群众路线是群众观点在实际工作中的贯彻运用，其基本内容包括","choices":[{"id":"A","text":"一切为了群众"},{"id":"B","text":"一切依靠群众"},{"id":"C","text":"从群众中来"},{"id":"D","text":"到群众中去"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是群众路线的基本内容，是本题正确答案。","B":"是群众路线的基本内容，是本题正确答案。","C":"是群众路线的基本内容，是本题正确答案。","D":"是群众路线的基本内容，是本题正确答案。"}}},{"id":"basic-mayuan-ch05-1","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 1 题"},"stem":"商品是用来交换、能满足人的某种需要的劳动产品。在商品的二因素中，构成社会财富的物质内容的是","choices":[{"id":"A","text":"交换价值"},{"id":"B","text":"价值"},{"id":"C","text":"使用价值"},{"id":"D","text":"价格"}],"answer":["C"],"analysis":{"point":"","options":{"A":"交换价值——是一种使用价值同另一种使用价值相交换的量的关系或比例。","B":"价值——是凝结在商品中的无差别的一般人类劳动，即人的脑力和体力的耗费。","C":"使用价值——是商品能满足人的某种需要的属性，即商品的有用性，是商品的自然属性，是一切劳动产品所共有的属性，构成社会财富的物质内容，是本题正确答案。","D":"价格——是商品价值的货币表现。"}}},{"id":"basic-mayuan-ch05-2","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 2 题"},"stem":"商品交换总是按照一定比例进行的，决定商品交换比例的是","choices":[{"id":"A","text":"使用价值"},{"id":"B","text":"价值"},{"id":"C","text":"供求关系"},{"id":"D","text":"货币"}],"answer":["B"],"analysis":{"point":"","options":{"A":"使用价值——是商品能满足人的某种需要的属性，即商品的有用性，是商品的自然属性，是一切劳动产品所共有的属性，构成社会财富的物质内容。","B":"价值——是凝结在商品中的无差别的一般人类劳动，即人的脑力和体力的耗费，决定商品交换的比例，是本题正确答案。","C":"供求关系——是影响商品价格的因素，即影响商品交换比例的因素，但不能决定商品交换比例。","D":"货币——是在长期交换过程中形成的固定充当一般等价物的商品。"}}},{"id":"basic-mayuan-ch05-3","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 3 题"},"stem":"资本主义生产方式占统治地位的社会的财富，表现为“庞大的商品堆积”。商品不同于一般劳动产品的特有的社会属性是","choices":[{"id":"A","text":"使用价值"},{"id":"B","text":"具体劳动"},{"id":"C","text":"价值"},{"id":"D","text":"有用性"}],"answer":["C"],"analysis":{"point":"","options":{"A":"使用价值——是商品能满足人的某种需要的属性，即商品的有用性，是商品的自然属性，是一切劳动产品所共有的属性，构成社会财富的物质内容。","B":"具体劳动——是生产一定使用价值的具体形式的劳动。","C":"价值——是凝结在商品中的无差别的一般人类劳动，即人的脑力和体力的耗费，是商品不同于一般劳动产品的特有的社会属性，是本题正确答案。","D":"有用性——即商品的使用价值，是商品的自然属性。"}}},{"id":"basic-mayuan-ch05-4","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 4 题"},"stem":"商品的价值不仅有质的规定，而且还有量的规定。决定商品价值量大小的是","choices":[{"id":"A","text":"个别劳动时间"},{"id":"B","text":"社会必要劳动时间"},{"id":"C","text":"生产过程的社会结合"},{"id":"D","text":"劳动者的平均劳动熟练程度"}],"answer":["B"],"analysis":{"point":"","options":{"A":"个别劳动时间——是个别劳动者生产单位商品的劳动时间，不决定商品价值量大小。","B":"社会必要劳动时间——是在现有的社会正常的生产条件下，在社会平均的劳动熟练程度和劳动强度下制造某种使用价值所需要的劳动时间，决定商品价值量大小，是本题正确答案。","C":"是影响劳动生产率的因素。","D":"是影响劳动生产率的因素。"}}},{"id":"basic-mayuan-ch05-5","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 5 题"},"stem":"在商品经济中，价值规律的表现形式是","choices":[{"id":"A","text":"商品的价值量由生产商品的社会必要劳动时间决定"},{"id":"B","text":"商品的价格围绕商品的价值自发波动"},{"id":"C","text":"商品交换以价值量为基础"},{"id":"D","text":"商品交换按照等价交换的原则进行"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是价值规律的基本内容和客观要求。","B":"商品的价格围绕商品的价值自发波动——是价值规律的表现形式，是本题正确答案。","C":"是价值规律的基本内容和客观要求。","D":"是价值规律的基本内容和客观要求。"}}},{"id":"basic-mayuan-ch05-6","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 6 题"},"stem":"私有制基础上商品经济的基本矛盾是","choices":[{"id":"A","text":"具体劳动和抽象劳动的矛盾"},{"id":"B","text":"私人劳动和社会劳动的矛盾"},{"id":"C","text":"使用价值和价值的矛盾"},{"id":"D","text":"商品和货币的矛盾"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是商品经济中的重要矛盾，但不是基本矛盾。","B":"私人劳动和社会劳动的矛盾——是私有制基础上商品经济的基本矛盾，是商品经济其他一切矛盾的基础，是本题正确答案。","C":"是商品经济中的重要矛盾，但不是基本矛盾。","D":"是商品经济中的重要矛盾，但不是基本矛盾。"}}},{"id":"basic-mayuan-ch05-7","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 7 题"},"stem":"马克思主义政治经济学中，被称为“理解政治经济学的枢纽”的理论是","choices":[{"id":"A","text":"资本有机构成理论"},{"id":"B","text":"剩余价值理论"},{"id":"C","text":"劳动二重性理论"},{"id":"D","text":"资本积累理论"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是剩余价值理论的重要组成部分。","B":"剩余价值理论——是马克思主义经济学说的核心内容和基石。","C":"劳动二重性理论——是“理解政治经济学的枢纽”，是本题正确答案。","D":"是剩余价值理论的重要组成部分。"}}},{"id":"basic-mayuan-ch05-8","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 8 题"},"stem":"资本主义生产过程具有二重性，其主要方面是","choices":[{"id":"A","text":"生产物质资料的劳动过程"},{"id":"B","text":"工人在资本家的监督下劳动，他们的劳动隶属于资本家"},{"id":"C","text":"价值增殖过程"},{"id":"D","text":"劳动的成果或产品全部归资本家所有"}],"answer":["C"],"analysis":{"point":"","options":{"A":"生产物质资料的劳动过程——是生产使用价值的过程，但不是资本主义生产过程的主要方面。","B":"是资本主义劳动过程的两个特点。","C":"价值增殖过程——是生产剩余价值的过程，是资本主义生产过程的主要方面，是本题正确答案。","D":"是资本主义劳动过程的两个特点。"}}},{"id":"basic-mayuan-ch05-9","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 9 题"},"stem":"在资本主义社会，资本总是通过各种物品表现出来，但资本的本质不是物，而是","choices":[{"id":"A","text":"用于增殖的货币"},{"id":"B","text":"机器、厂房等生产资料"},{"id":"C","text":"一定的历史社会形态下的生产关系"},{"id":"D","text":"商品资本"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是资本的具体表现形式。","B":"是资本的具体表现形式。","C":"一定的历史社会形态下的生产关系——是资本的本质，是本题正确答案。","D":"是资本的具体表现形式。"}}},{"id":"basic-mayuan-ch05-10","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 10 题"},"stem":"剩余价值不是由全部资本创造的。剩余价值的唯一源泉是","choices":[{"id":"A","text":"不变资本"},{"id":"B","text":"雇佣劳动者的具体劳动"},{"id":"C","text":"雇佣劳动者的剩余劳动"},{"id":"D","text":"雇佣劳动者的必要劳动"}],"answer":["C"],"analysis":{"point":"","options":{"A":"不变资本——是以生产资料形态存在的资本，它通过工人的具体劳动被转移到新产品中去，其转移的价值量不会大于它原有价值量。","B":"雇佣劳动者的具体劳动——是生产商品使用价值、转移生产资料价值的劳动，不生产剩余价值。","C":"雇佣劳动者的剩余劳动——是剩余价值的唯一源泉，是本题正确答案。","D":"雇佣劳动者的必要劳动——是用于再生产劳动力的价值的劳动，不生产剩余价值。"}}},{"id":"basic-mayuan-ch05-11","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 11 题"},"stem":"资本主义再生产的特点是扩大再生产。资本家将获得剩余价值的一部分转化为资本，使生产在扩大的规模上重复进行，这就是资本主义扩大再生产。资本主义扩大再生产的源泉是","choices":[{"id":"A","text":"资本集中"},{"id":"B","text":"资本积累"},{"id":"C","text":"剩余价值"},{"id":"D","text":"资本循环"}],"answer":["B"],"analysis":{"point":"","options":{"A":"资本集中——是指大资本吞并小资本，或由许多小资本合并而成大资本的过程。","B":"资本积累——是资本主义扩大再生产的源泉，是本题正确答案。","C":"剩余价值——是雇佣工人所创造并被资本家无偿占有的超过劳动力价值的那部分价值，是资本积累的源泉。","D":"资本循环——是资本从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。"}}},{"id":"basic-mayuan-ch05-12","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 12 题"},"stem":"在资本主义社会，失业现象产生的根源在于","choices":[{"id":"A","text":"社会财富占有两极分化"},{"id":"B","text":"资本积累"},{"id":"C","text":"劳动者技能不足"},{"id":"D","text":"所用资本和所费资本之间的差额"}],"answer":["B"],"analysis":{"point":"","options":{"A":"社会财富占有两极分化——是资本积累的后果之一。","B":"资本积累——是资本主义社会失业现象产生的根源，是本题正确答案。","C":"劳动者技能不足——是资本主义社会失业现象产生的原因之一。","D":"所用资本和所费资本之间的差额——是影响资本积累规模大小的因素之一。"}}},{"id":"basic-mayuan-ch05-13","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 13 题"},"stem":"在对个别资本的再生产和流通的规律性进行分析的基础上，马克思对社会总资本的再生产和流通也进行了深入分析，进一步揭露了资本主义经济所包含的对抗性矛盾。社会再生产的核心问题是","choices":[{"id":"A","text":"价值补偿问题"},{"id":"B","text":"社会总产品的实现问题"},{"id":"C","text":"实物补偿问题"},{"id":"D","text":"机会成本问题"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是社会总产品的实现问题的具体内容。","B":"社会总产品的实现问题——是社会再生产的核心问题，即社会总产品的价值补偿和实物补偿问题，是本题正确答案。","C":"是社会总产品的实现问题的具体内容。","D":"机会成本问题非考点。"}}},{"id":"basic-mayuan-ch05-14","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 14 题"},"stem":"资本主义工资的形式主要有两种：计时工资和计件工资。此外还有各种形式的血汗工资制度，和","choices":[{"id":"A","text":"劳动的价值或价格"},{"id":"B","text":"工人全部劳动的报酬"},{"id":"C","text":"劳动力的价值或价格"},{"id":"D","text":"剩余价值"}],"answer":["C"],"analysis":{"point":"","options":{"A":"劳动的价值或价格——是资本主义工资的歪曲表现，掩盖了工资的本质。","B":"工人全部劳动的报酬是资本主义工资的表现。","C":"劳动力的价值或价格——是资本主义工资的本质，是本题正确答案。","D":"剩余价值——是雇佣工人所创造并被资本家无偿占有的超过劳动力价值的那部分价值。"}}},{"id":"basic-mayuan-ch05-15","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 15 题"},"stem":"企业通过提供产品或服务，创造经济价值，从而获得利润。在资本主义经济中，利润的本质是","choices":[{"id":"A","text":"不变资本"},{"id":"B","text":"可变资本"},{"id":"C","text":"全部预付资本"},{"id":"D","text":"剩余价值"}],"answer":["D"],"analysis":{"point":"","options":{"A":"不变资本——是以生产资料形态存在的资本，它通过工人的具体劳动被转移到新产品中去，其转移的价值量不会大于它原有的价值量。","B":"可变资本——是用来购买劳动力的那部分资本，在生产过程中不是被转移到新产品中去，而是由工人的劳动再生产出来。","C":"全部预付资本——是资本家眼中利润的来源，而资本家这样做，是为了掩盖剥削。","D":"剩余价值——是雇佣工人所创造并被资本家无偿占有的超过劳动力价值的那部分价值，是利润的本质，是本题正确答案。"}}},{"id":"basic-mayuan-ch05-16","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 16 题"},"stem":"马克思主义政治经济学是马克思主义的重要组成部分。马克思主义经济学说的核心内容和基石是","choices":[{"id":"A","text":"劳动价值论"},{"id":"B","text":"剩余价值理论"},{"id":"C","text":"资本积累理论"},{"id":"D","text":"经济危机理论"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是马克思主义经济学说的重要内容，但不是基石。","B":"剩余价值理论——是马克思主义经济学说的核心内容和基石，是本题正确答案。","C":"是马克思主义经济学说的重要内容，但不是基石。","D":"是马克思主义经济学说的重要内容，但不是基石。"}}},{"id":"basic-mayuan-ch05-17","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 17 题"},"stem":"资本主义的基本矛盾是生产力和生产关系之间的矛盾在资本主义社会的具体体现，即","choices":[{"id":"A","text":"私人劳动和社会劳动的矛盾"},{"id":"B","text":"使用价值和价值的矛盾"},{"id":"C","text":"生产资料资本主义私人占有和生产社会化之间的矛盾"},{"id":"D","text":"商品和货币的矛盾"}],"answer":["C"],"analysis":{"point":"","options":{"A":"私人劳动和社会劳动的矛盾——是私有制基础上商品经济的基本矛盾，在资本主义社会转化为资本主义的基本矛盾，即生产资料资本主义私人占有和生产社会化之间的矛盾。","B":"是私有制条件下商品经济的重要矛盾。","C":"生产资料资本主义私人占有和生产社会化之间的矛盾——是资本主义的基本矛盾，是本题正确答案。","D":"是私有制条件下商品经济的重要矛盾。"}}},{"id":"basic-mayuan-ch05-18","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":18,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 18 题"},"stem":"资本主义经济危机周期性爆发的特点，使社会资本再生产也呈现周期性的特点，一般包括四个阶段：危机、萧条、复苏和高涨。资本主义经济危机的本质特征是","choices":[{"id":"A","text":"资本积累"},{"id":"B","text":"生产相对过剩"},{"id":"C","text":"社会资源浪费"},{"id":"D","text":"资本主义条件下以强制的方式解决社会再生产的实现问题的途径"}],"answer":["B"],"analysis":{"point":"","options":{"A":"资本积累——是剩余价值的资本化，是经济危机爆发的原因之一。","B":"生产相对过剩——是资本主义经济危机的本质特征，是本题正确答案。","C":"社会资源浪费——是价值规律的消极作用之一，也是经济危机的具体表现之一。","D":"资本主义条件下以强制的方式解决社会再生产的实现问题的途径——是资本主义经济危机的实质。"}}},{"id":"basic-mayuan-ch05-19","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":19,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 19 题"},"stem":"资本主义经济危机是以社会经济生活的严重混乱甚至瘫痪以及社会资源和财富的极大浪费为代价的。资本主义经济危机爆发的根本原因是","choices":[{"id":"A","text":"货币作为支付手段"},{"id":"B","text":"资本主义的基本矛盾"},{"id":"C","text":"货币作为流通手段"},{"id":"D","text":"两大部类的生产具有严重的盲目性"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是经济危机的抽象的一般的可能性，是危机在形式上的可能性。","B":"资本主义的基本矛盾——是资本主义经济危机爆发的根本原因，是本题正确答案。","C":"是经济危机的抽象的一般的可能性，是危机在形式上的可能性。","D":"两大部类的生产具有严重的盲目性——是经济危机爆发的原因之一。"}}},{"id":"basic-mayuan-ch05-20","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 20 题"},"stem":"商品经济作为一定历史条件下的经济形式，其产生的社会历史条件包括","choices":[{"id":"A","text":"存在社会分工"},{"id":"B","text":"生产资料和劳动产品属于不同的所有者"},{"id":"C","text":"劳动者在法律上是自由人"},{"id":"D","text":"劳动者没有任何生产资料，没有别的商品可以出卖，“自由”得一无所有"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是商品经济产生的社会历史条件，是本题正确答案。","B":"是商品经济产生的社会历史条件，是本题正确答案。","C":"是劳动力成为商品需要具备的两个基本条件。","D":"是劳动力成为商品需要具备的两个基本条件。"}}},{"id":"basic-mayuan-ch05-21","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 21 题"},"stem":"商品的价值形式在历史上经历了若干发展阶段，主要包括","choices":[{"id":"A","text":"简单的或偶然的价值形式"},{"id":"B","text":"总和的或扩大的价值形式"},{"id":"C","text":"一般的价值形式"},{"id":"D","text":"货币形式"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是商品的价值形式在历史上经历的四个发展阶段，是本题正确答案。","B":"是商品的价值形式在历史上经历的四个发展阶段，是本题正确答案。","C":"是商品的价值形式在历史上经历的四个发展阶段，是本题正确答案。","D":"是商品的价值形式在历史上经历的四个发展阶段，是本题正确答案。"}}},{"id":"basic-mayuan-ch05-22","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 22 题"},"stem":"货币在商品经济中具有多种职能，其中最基本的两个职能是","choices":[{"id":"A","text":"支付手段"},{"id":"B","text":"流通手段"},{"id":"C","text":"价值尺度"},{"id":"D","text":"贮藏手段"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"是货币的职能，但不是最基本的职能。","B":"是货币的两个最基本的职能，是本题正确答案。","C":"是货币的两个最基本的职能，是本题正确答案。","D":"是货币的职能，但不是最基本的职能。"}}},{"id":"basic-mayuan-ch05-23","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 23 题"},"stem":"价值规律是商品经济的基本经济规律，其基本内容和客观要求是","choices":[{"id":"A","text":"商品的价值量由生产商品的社会必要劳动时间决定"},{"id":"B","text":"商品交换以价值量为基础，按照等价交换的原则进行"},{"id":"C","text":"价格围绕价值自发波动"},{"id":"D","text":"调节生产资料和劳动力在社会各生产部门之间的分配比例"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是价值规律的基本内容和客观要求，是本题正确答案。","B":"是价值规律的基本内容和客观要求，是本题正确答案。","C":"价格围绕价值自发波动——是价值规律的表现形式。","D":"调节生产资料和劳动力在社会各生产部门之间的分配比例——是价值规律在市场配置资源过程中的作用。"}}},{"id":"basic-mayuan-ch05-24","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 24 题"},"stem":"17世纪中期到18世纪后半期，英、法等国先后进行了资产阶级革命，建立了资产阶级的政治统治，实现了产业革命，机器大工业代替了工场手工业，促进了社会生产力和资本主义生产关系的空前大发展，最终建立起资本主义生产方式。资本主义产生的途径主要有","choices":[{"id":"A","text":"从奴隶主经济直接转化而来"},{"id":"B","text":"生产集中和资本集中"},{"id":"C","text":"从小商品经济中分化出来"},{"id":"D","text":"从商人和高利贷者转化而来"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"从奴隶主经济直接转化而来——非考点。","B":"生产集中和资本集中——是资本家追求剩余价值和自由竞争的结果，也是生产社会化和资本社会化的重要表现。","C":"是资本主义产生的途径，是本题正确答案。","D":"是资本主义产生的途径，是本题正确答案。"}}},{"id":"basic-mayuan-ch05-25","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 25 题"},"stem":"马克思指出，所谓资本原始积累“只不过是生产者和生产资料分离的历史过程。这个过程所以表现为原始的’，因为它形成资本及与之相适应的生产方式的前史”。资本原始积累的主要途径包括","choices":[{"id":"A","text":"用暴力手段剥夺农民的土地"},{"id":"B","text":"用暴力手段掠夺货币财富"},{"id":"C","text":"资本有机构成不断提高"},{"id":"D","text":"造成大量失业人口"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是资本原始积累的两个主要途径，是本题正确答案。","B":"是资本原始积累的两个主要途径，是本题正确答案。","C":"是资本积累的结果。","D":"是资本积累的结果。"}}},{"id":"basic-mayuan-ch05-26","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 26 题"},"stem":"劳动力的价值，是由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定的。具体包括","choices":[{"id":"A","text":"维持劳动者本人生存所必需的生活资料的价值"},{"id":"B","text":"维持劳动者家属生存所必需的生活资料的价值"},{"id":"C","text":"劳动者接受教育和训练所支出的费用"},{"id":"D","text":"劳动者创造的全部剩余价值"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是劳动力价值的具体构成部分，是本题正确答案。","B":"是劳动力价值的具体构成部分，是本题正确答案。","C":"是劳动力价值的具体构成部分，是本题正确答案。","D":"劳动者创造的全部剩余价值——是被资本家无偿占有的价值。"}}},{"id":"basic-mayuan-ch05-27","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 27 题"},"stem":"资本主义生产过程是商品生产的资本主义形式。资本主义生产过程具有二重性，是指","choices":[{"id":"A","text":"生产剩余价值的价值增殖过程"},{"id":"B","text":"工人在资本家监督下劳动，他们的劳动隶属于资本家"},{"id":"C","text":"物质资料生产过程"},{"id":"D","text":"劳动的成果或产品全部归资本家所有"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是资本主义生产过程二重性的两个方面，是本题正确答案。","B":"是资本主义劳动过程区别于其他社会劳动过程的特点。","C":"是资本主义生产过程二重性的两个方面，是本题正确答案。","D":"是资本主义劳动过程区别于其他社会劳动过程的特点。"}}},{"id":"basic-mayuan-ch05-28","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 28 题"},"stem":"根据资本在剩余价值生产过程中所起的不同作用，资本可以区分为","choices":[{"id":"A","text":"固定资本"},{"id":"B","text":"流动资本"},{"id":"C","text":"不变资本"},{"id":"D","text":"可变资本"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"是根据资本周转方式的不同所区分的两种资本，固定资本的价值在生产中分多次转移到商品中，流动资本的价值在生产中一次性转移到商品中。","B":"是根据资本周转方式的不同所区分的两种资本，固定资本的价值在生产中分多次转移到商品中，流动资本的价值在生产中一次性转移到商品中。","C":"是根据资本在剩余价值生产过程中所起的作用不同而区分的两种资本，是本题正确答案。","D":"是根据资本在剩余价值生产过程中所起的作用不同而区分的两种资本，是本题正确答案。"}}},{"id":"basic-mayuan-ch05-29","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 29 题"},"stem":"资本家提高对工人的剥削程度的方法是多种多样的，最基本的方法有","choices":[{"id":"A","text":"绝对剩余价值的生产"},{"id":"B","text":"相对剩余价值的生产"},{"id":"C","text":"超额剩余价值的生产"},{"id":"D","text":"提高自身企业的劳动生产率"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是资本家提高对工人的剥削程度的最基本的方法，是本题正确答案。","B":"是资本家提高对工人的剥削程度的最基本的方法，是本题正确答案。","C":"超额剩余价值的生产——是资本家提高对工人的剥削程度的方法之一，但不是最基本的方法。","D":"提高自身企业的劳动生产率——是个别企业获取超额剩余价值的方法。"}}},{"id":"basic-mayuan-ch05-30","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 30 题"},"stem":"在资本主义发展初期，生产技术以手工劳动为基础，资本家增加生产主要靠生产绝对剩余价值来实现。绝对剩余价值的生产方法包括","choices":[{"id":"A","text":"改进生产技术"},{"id":"B","text":"延长工作日长度"},{"id":"C","text":"提高劳动强度"},{"id":"D","text":"提高全社会的劳动生产率"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"是相对剩余价值的生产方法。","B":"是绝对剩余价值的生产方法，是本题正确答案。","C":"是绝对剩余价值的生产方法，是本题正确答案。","D":"是相对剩余价值的生产方法。"}}},{"id":"basic-mayuan-ch05-31","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":31,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 31 题"},"stem":"资本积累的本质，就是资本家不断地利用无偿占有的工人创造的剩余价值来扩大自己的资本规模，从而进一步扩大和加强对工人的剥削和统治。资本积累规模的大小取决于","choices":[{"id":"A","text":"资本家对工人的剥削程度"},{"id":"B","text":"劳动生产率的高低"},{"id":"C","text":"所用资本与所费资本之间的差额"},{"id":"D","text":"资本家预付资本的大小"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是影响资本积累规模大小的因素，是本题正确答案。","B":"是影响资本积累规模大小的因素，是本题正确答案。","C":"是影响资本积累规模大小的因素，是本题正确答案。","D":"是影响资本积累规模大小的因素，是本题正确答案。"}}},{"id":"basic-mayuan-ch05-32","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":32,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 32 题"},"stem":"经常性的庞大失业人口即相对过剩人口的存在，是资本主义的痼疾。相对过剩人口的具体形式包括","choices":[{"id":"A","text":"流动的过剩人口"},{"id":"B","text":"潜在的过剩人口"},{"id":"C","text":"停滞的过剩人口"},{"id":"D","text":"绝对的过剩人口"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是相对过剩人口的具体形式，是本题正确答案。","B":"是相对过剩人口的具体形式，是本题正确答案。","C":"是相对过剩人口的具体形式，是本题正确答案。","D":"绝对的过剩人口非考点。"}}},{"id":"basic-mayuan-ch05-33","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":33,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 33 题"},"stem":"产业资本在循环过程中要经历三个不同阶段，与此相联系的是资本依次执行三种不同的职能，包括","choices":[{"id":"A","text":"货币资本"},{"id":"B","text":"生产资本"},{"id":"C","text":"商品资本"},{"id":"D","text":"借贷资本"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是产业资本在循环过程中执行的三种职能，是本题正确答案。","B":"是产业资本在循环过程中执行的三种职能，是本题正确答案。","C":"是产业资本在循环过程中执行的三种职能，是本题正确答案。","D":"借贷资本——是垄断资本向世界范围扩展的基本形式之一。"}}},{"id":"basic-mayuan-ch05-34","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":34,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 34 题"},"stem":"要使产业资本实现连续循环，需要具备的基本条件有","choices":[{"id":"A","text":"两大部类内部各个产业部门之间和两大部类之间保持一定的比例关系"},{"id":"B","text":"三种职能形式在空间上并存"},{"id":"C","text":"三种职能形式在时间上继起"},{"id":"D","text":"资本主义制度的必然灭亡和社会主义制度的必然胜利"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"两大部类内部各个产业部门之间和两大部类之间保持一定的比例关系——是社会再生产顺利进行的要求。","B":"是产业资本实现连续循环需要具备的两个基本条件，是本题正确答案。","C":"是产业资本实现连续循环需要具备的两个基本条件，是本题正确答案。","D":"资本主义制度的必然灭亡和社会主义制度的必然胜利——是资本积累的历史趋势。"}}},{"id":"basic-mayuan-ch05-35","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":35,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 35 题"},"stem":"影响资本周转快慢的因素有许多，其中，关键的因素为","choices":[{"id":"A","text":"资本周转的时间"},{"id":"B","text":"生产资本的固定资本和流动资本的构成"},{"id":"C","text":"资本家预付资本的大小"},{"id":"D","text":"资本家对工人的剥削程度"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是影响资本周转快慢的关键因素，是本题正确答案。","B":"是影响资本周转快慢的关键因素，是本题正确答案。","C":"是影响资本积累规模大小的因素。","D":"是影响资本积累规模大小的因素。"}}},{"id":"basic-mayuan-ch05-36","moduleId":"basic","subjectId":"mayuan","chapter":"第五章 资本主义的本质及规律","chapterKey":"第五章","n":36,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第五章 第 36 题"},"stem":"资本主义基本矛盾的具体表现主要包括","choices":[{"id":"A","text":"生产无限扩大的趋势与劳动人民有支付能力的需求相对缩小的矛盾"},{"id":"B","text":"单个企业内部生产的有组织性和整个社会生产的无政府状态之间的矛盾"},{"id":"C","text":"经济增长与资源环境之间的矛盾"},{"id":"D","text":"国内生产与国际市场之间的矛盾"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是资本主义基本矛盾的具体表现，是本题正确答案。","B":"是资本主义基本矛盾的具体表现，是本题正确答案。","C":"是资本主义生产过程中的重要矛盾，但不是资本主义基本矛盾的具体表现。","D":"是资本主义生产过程中的重要矛盾，但不是资本主义基本矛盾的具体表现。"}}},{"id":"basic-mayuan-ch06-1","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 1 题"},"stem":"垄断组织有多种形式，其中最简单的、初级的垄断组织形式是","choices":[{"id":"A","text":"卡特尔"},{"id":"B","text":"辛迪加"},{"id":"C","text":"托拉斯"},{"id":"D","text":"短期价格协定"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是常见的垄断组织。","B":"是常见的垄断组织。","C":"是常见的垄断组织。","D":"短期价格协定——是垄断组织中最简单的、初级的垄断组织形式，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-2","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 2 题"},"stem":"垄断是通过一定的垄断组织形式实现的。垄断组织是指在一个或几个经济部门中占据垄断地位的大企业联合。早期的国际垄断同盟主要是","choices":[{"id":"A","text":"国际卡特尔"},{"id":"B","text":"国际货币基金组织"},{"id":"C","text":"国家垄断资本主义的国际联盟"},{"id":"D","text":"世界贸易组织"}],"answer":["A"],"analysis":{"point":"","options":{"A":"国际卡特尔——是早期的国际垄断同盟的主要形式，是本题正确答案。","B":"是第二次世界大战后，从事国际经济协调、维护国际经济秩序的国际经济组织。","C":"国家垄断资本主义的国际联盟——是当代国际垄断同盟的形式。","D":"是第二次世界大战后，从事国际经济协调、维护国际经济秩序的国际经济组织。"}}},{"id":"basic-mayuan-ch06-3","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 3 题"},"stem":"第二次世界大战后崛起并成为居主导地位的资本所有制形式是","choices":[{"id":"A","text":"私人资本所有制"},{"id":"B","text":"私人股份资本所有制"},{"id":"C","text":"法人资本所有制"},{"id":"D","text":"国家资本所有制"}],"answer":["C"],"analysis":{"point":"","options":{"A":"私人资本所有制——是资本主义发展初期占主导地位的所有制形式。","B":"私人股份资本所有制——是19世纪末20世纪初，随着股份公司发展，占主导地位的所有制形式。","C":"法人资本所有制——是第二次世界大战后崛起并成为居主导地位的资本所有制形式，是本题正确答案。","D":"国家资本所有制——是第二次世界大战后新产生的所有制形式。"}}},{"id":"basic-mayuan-ch06-4","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 4 题"},"stem":"进入21世纪以来，随着经济全球化的深入发展，新一轮科技革命和产业变革进入空前密集活跃期，社会化大生产在世界范围内更大规模、更广范围、更深层次展开，世界格局深度调整，资本主义又呈现一些新变化新特征。当代资本主义最突出、最鲜明、最主要的特征是","choices":[{"id":"A","text":"科技创新加速资本主义生产方式变化"},{"id":"B","text":"国际金融资本的垄断一"},{"id":"C","text":"社会阶级层级结构呈现复杂性、多样化"},{"id":"D","text":"发达资本主义国家推行强权政治"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是当代资本主义变化的新特征。","B":"（原书未单独给出此项解析）","C":"是当代资本主义变化的新特征。","D":"是当代资本主义变化的新特征。"}}},{"id":"basic-mayuan-ch06-5","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 5 题"},"stem":"金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本。金融资本形成的主要途径包括","choices":[{"id":"A","text":"金融联系"},{"id":"B","text":"资本参与"},{"id":"C","text":"人事参与"},{"id":"D","text":"技术合作"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是金融资本形成的主要途径，是本题正确答案。","B":"是金融资本形成的主要途径，是本题正确答案。","C":"是金融资本形成的主要途径，是本题正确答案。","D":"技术合作非考点。"}}},{"id":"basic-mayuan-ch06-6","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 6 题"},"stem":"金融寡头在经济、政治和社会生活等方面实现统治的方式主要有","choices":[{"id":"A","text":"“参与制”"},{"id":"B","text":"“个人联合”"},{"id":"C","text":"建立政策咨询机构"},{"id":"D","text":"以工代赈"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是金融寡头在经济、政治和社会生活等方面实现统治的方式，是本题正确答案。","B":"是金融寡头在经济、政治和社会生活等方面实现统治的方式，是本题正确答案。","C":"是金融寡头在经济、政治和社会生活等方面实现统治的方式，是本题正确答案。","D":"以工代赈——是资本主义政府挽救经济危机的手段之一。"}}},{"id":"basic-mayuan-ch06-7","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 7 题"},"stem":"垄断价格是垄断组织在销售或购买商品时，凭借其垄断地位规定的、旨在保证获取最大限度利润的市场价格。垄断价格的形式有","choices":[{"id":"A","text":"成本价格"},{"id":"B","text":"生产价格"},{"id":"C","text":"垄断高价"},{"id":"D","text":"垄断低价"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"成本价格是不变资本和可变资本之和。","B":"生产价格是生产成本与平均利润之和。","C":"是垄断价格的两种形式，是本题正确答案。","D":"是垄断价格的两种形式，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-8","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 8 题"},"stem":"微观规制主要是指国家运用法律手段规范市场秩序，限制垄断，保护竞争，维护社会公众的合法权益。资本主义国家的微观规制的类型主要有","choices":[{"id":"A","text":"反托拉斯法"},{"id":"B","text":"公共事业规制"},{"id":"C","text":"文化教育规制"},{"id":"D","text":"社会经济规制"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是资本主义国家的微观规制的主要类型，是本题正确答案。","B":"是资本主义国家的微观规制的主要类型，是本题正确答案。","C":"文化教育规制非考点。","D":"是资本主义国家的微观规制的主要类型，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-9","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 9 题"},"stem":"金融垄断资本得以形成和壮大的重要制度条件是","choices":[{"id":"A","text":"金融自由化"},{"id":"B","text":"金融创新"},{"id":"C","text":"产业政策扶持"},{"id":"D","text":"科学技术进步"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是金融垄断资本得以形成和壮大的重要制度条件，是本题正确答案。","B":"是金融垄断资本得以形成和壮大的重要制度条件，是本题正确答案。","C":"产业政策扶持非考点。","D":"科学技术进步——是促进生产力发展的重要因素。"}}},{"id":"basic-mayuan-ch06-10","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 10 题"},"stem":"垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统治。垄断资本向世界范围扩展的基本形式主要有","choices":[{"id":"A","text":"借贷资本输出"},{"id":"B","text":"生产资本输出"},{"id":"C","text":"商品资本输出"},{"id":"D","text":"货币资本输出"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是垄断资本向世界范围扩展的基本形式，是本题正确答案。","B":"是垄断资本向世界范围扩展的基本形式，是本题正确答案。","C":"是垄断资本向世界范围扩展的基本形式，是本题正确答案。","D":"货币资本输出是错误说法。"}}},{"id":"basic-mayuan-ch06-11","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 11 题"},"stem":"第二次世界大战后，从事国际经济协调、维护国际经济秩序的主要国际经济组织有","choices":[{"id":"A","text":"联合国"},{"id":"B","text":"国际货币基金组织"},{"id":"C","text":"世界银行"},{"id":"D","text":"世界贸易组织"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"联合国非考点。","B":"是第二次世界大战后，从事国际经济协调、维护国际经济秩序的主要国际经济组织，是本题正确答案。","C":"是第二次世界大战后，从事国际经济协调、维护国际经济秩序的主要国际经济组织，是本题正确答案。","D":"是第二次世界大战后，从事国际经济协调、维护国际经济秩序的主要国际经济组织，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-12","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 12 题"},"stem":"科学技术的进步和生产力的发展为经济全球化提供了坚实的物质基础和根本的推动力。经济全球化的主要表现包括","choices":[{"id":"A","text":"政治全球化"},{"id":"B","text":"贸易全球化"},{"id":"C","text":"生产全球化"},{"id":"D","text":"金融全球化"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"政治全球化非考点。","B":"是经济全球化的主要表现，是本题正确答案。","C":"是经济全球化的主要表现，是本题正确答案。","D":"是经济全球化的主要表现，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-13","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 13 题"},"stem":"经济全球化是指在生产不断发展、科技加速进步、社会分工和国际分工不断深化、生产的社会化和国际化程度不断提高的情况下，世界各国、各地区的经济活动越来越超出某一国家和地区的范围而相互联系、相互依存的过程。推动经济全球化迅猛发展的因素主要有","choices":[{"id":"A","text":"科技进步和生产力发展"},{"id":"B","text":"跨国公司的发展"},{"id":"C","text":"各国经济体制变革和国际经济组织发展"},{"id":"D","text":"国际水平分工逐渐取代国际垂直分工"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是推动经济全球化迅猛发展的主要因素，是本题正确答案。","B":"是推动经济全球化迅猛发展的主要因素，是本题正确答案。","C":"是推动经济全球化迅猛发展的主要因素，是本题正确答案。","D":"国际水平分工逐渐取代国际垂直分工——是生产全球化的具体表现。"}}},{"id":"basic-mayuan-ch06-14","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 14 题"},"stem":"经济全球化对发展中国家的积极作用主要表现在","choices":[{"id":"A","text":"为发展中国家提供先进技术和管理经验"},{"id":"B","text":"为发展中国家提供更多的就业机会"},{"id":"C","text":"推动发展中国家国际贸易的发展"},{"id":"D","text":"促进发展中国家跨国公司的发展"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是经济全球化对发展中国家的积极作用，是本题正确答案。","B":"是经济全球化对发展中国家的积极作用，是本题正确答案。","C":"是经济全球化对发展中国家的积极作用，是本题正确答案。","D":"是经济全球化对发展中国家的积极作用，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-15","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 15 题"},"stem":"经济全球化是一把“双刃剑”，它在促进经济发展的同时也带来了一些负面影响，主要表现在","choices":[{"id":"A","text":"发达国家与发展中国家在经济全球化进程中的地位和收益不平等、不平衡"},{"id":"B","text":"加剧了发展中国家资源短缺"},{"id":"C","text":"加剧了发展中国家环境污染"},{"id":"D","text":"一定程度上增加了经济风险"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是经济全球化带来的负面影响，是本题正确答案。","B":"是经济全球化带来的负面影响，是本题正确答案。","C":"是经济全球化带来的负面影响，是本题正确答案。","D":"是经济全球化带来的负面影响，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-16","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 16 题"},"stem":"随着社会生产力的发展和工人阶级反抗力量的不断壮大，资本家及其代理人开始采取一些缓和劳资关系的激励制度，促使工人自觉地服从资本家的意志。这些制度主要有","choices":[{"id":"A","text":"职工参与决策"},{"id":"B","text":"终身雇佣"},{"id":"C","text":"职工持股"},{"id":"D","text":"集体谈判制度"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是资本家及其代理人采取的缓和劳资关系的激励制度，是本题正确答案。","B":"是资本家及其代理人采取的缓和劳资关系的激励制度，是本题正确答案。","C":"是资本家及其代理人采取的缓和劳资关系的激励制度，是本题正确答案。","D":"集体谈判制度非考点。"}}},{"id":"basic-mayuan-ch06-17","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 17 题"},"stem":"在当代资本主义生产关系中，社会阶层和阶级结构发生了新的变化。当代资本主义社会阶层和阶级结构的新变化表现为","choices":[{"id":"A","text":"资本家的地位和作用发生变化"},{"id":"B","text":"高级职业经理成为大公司的实际控制者"},{"id":"C","text":"知识型和服务型劳动者数量增加，劳动方式发生新变化"},{"id":"D","text":"周期性危机与结构性危机交织在一起"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是当代资本主义社会阶层和阶级结构的新变化，是本题正确答案。","B":"是当代资本主义社会阶层和阶级结构的新变化，是本题正确答案。","C":"是当代资本主义社会阶层和阶级结构的新变化，是本题正确答案。","D":"周期性危机与结构性危机交织在一起——是当代资本主义经济调节机制和经济危机形态的变化。"}}},{"id":"basic-mayuan-ch06-18","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 18 题"},"stem":"第二次世界大战后，资本主义政治制度的变化包括","choices":[{"id":"A","text":"政治制度多元化，公民权利扩大"},{"id":"B","text":"法治建设得到重视和加强"},{"id":"C","text":"改良主义政党影响扩大"},{"id":"D","text":"社会福利制度持续扩张"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是第二次世界大战后资本主义政治制度的变化，是本题正确答案。","B":"是第二次世界大战后资本主义政治制度的变化，是本题正确答案。","C":"是第二次世界大战后资本主义政治制度的变化，是本题正确答案。","D":"社会福利制度持续扩张——是第二次世界大战后资本主义劳资关系和分配关系的变化。"}}},{"id":"basic-mayuan-ch06-19","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 19 题"},"stem":"第二次世界大战后资本主义发生新变化的原因主要有","choices":[{"id":"A","text":"科学技术革命和生产力的发展，是资本主义发生变化的根本推动力量"},{"id":"B","text":"工人阶级争取自身权利和利益的斗争，是推动资本主义发生变化的重要力量"},{"id":"C","text":"社会主义制度初步显示的优越性对资本主义产生了重要影响"},{"id":"D","text":"主张改良主义的政党对资本主义制度的改革，对资本主义发生变化起到了重要作用"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是第二次世界大战后资本主义发生新变化的原因，是本题正确答案。","B":"是第二次世界大战后资本主义发生新变化的原因，是本题正确答案。","C":"是第二次世界大战后资本主义发生新变化的原因，是本题正确答案。","D":"是第二次世界大战后资本主义发生新变化的原因，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-20","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 20 题"},"stem":"进入21世纪以来，特别是2008年全球金融危机爆发之后，在国际贸易摩擦加剧、数字技术迅猛发展、生态危机不断恶化等背景下，全球资本主义进入一个新的发展阶段，发达资本主义国家的资本运动也随之出现一些新变化、新特征。这些新变化、新特征包括","choices":[{"id":"A","text":"科技创新加速资本主义生产方式变化"},{"id":"B","text":"国际金融垄断资本主义影响日益显现"},{"id":"C","text":"社会阶级层级结构呈现复杂性、多样化"},{"id":"D","text":"发达资本主义国家推行霸权主义和强权政治"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是进入21世纪以来资本主义呈现的新变化、新特征，是本题正确答案。","B":"是进入21世纪以来资本主义呈现的新变化、新特征，是本题正确答案。","C":"是进入21世纪以来资本主义呈现的新变化、新特征，是本题正确答案。","D":"是进入21世纪以来资本主义呈现的新变化、新特征，是本题正确答案。"}}},{"id":"basic-mayuan-ch06-21","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 21 题"},"stem":"国际金融资本垄断的特征主要表现在","choices":[{"id":"A","text":"金融垄断寡头化"},{"id":"B","text":"金融垄断国际化"},{"id":"C","text":"经济虚拟化、产业空心化"},{"id":"D","text":"生产集中化、产业规模化"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是国际金融资本垄断的主要特征，是本题正确答案。","B":"是国际金融资本垄断的主要特征，是本题正确答案。","C":"是国际金融资本垄断的主要特征，是本题正确答案。","D":"生产集中化、产业规模化——是资本主义发展的一般趋势和表现。"}}},{"id":"basic-mayuan-ch06-22","moduleId":"basic","subjectId":"mayuan","chapter":"第六章 资本主义的发展及其趋势","chapterKey":"第六章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第六章 第 22 题"},"stem":"由美国次贷危机引发的2008年国际金融危机是自20世纪30年代经济大萧条以来最为严重的全球性经济危机。在这场危机的影响下，西方国家的经济生活、政治生活和民生等各方面都出现了各种问题，主要表现在","choices":[{"id":"A","text":"生产力持续发展"},{"id":"B","text":"经济发展失调"},{"id":"C","text":"政治体制失灵"},{"id":"D","text":"社会融合机制失效"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"生产力持续发展——是资本主义发展的客观结果，而非出现的问题。","B":"是国际金融危机下资本主义国家内部出现的矛盾和冲突，是本题正确答案。","C":"是国际金融危机下资本主义国家内部出现的矛盾和冲突，是本题正确答案。","D":"是国际金融危机下资本主义国家内部出现的矛盾和冲突，是本题正确答案。"}}},{"id":"basic-mayuan-ch07-1","moduleId":"basic","subjectId":"mayuan","chapter":"第七章 社会主义的发展及其规律","chapterKey":"第七章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第七章 第 1 题"},"stem":"从1918年夏到1921年春，列宁领导的苏维埃政权实行了战时共产主义政策，在经济上采取了一系列特殊又带有强制性的非常措施。战时共产主义政策的主要特征是","choices":[{"id":"A","text":"余粮收集制和取消商品货币关系"},{"id":"B","text":"发展商品经济"},{"id":"C","text":"用粮食税制取代余粮收集制"},{"id":"D","text":"允许私人自由贸易"}],"answer":["A"],"analysis":{"point":"","options":{"A":"余粮收集制和取消商品货币关系——是战时共产主义政策的主要特征，是本题正确答案。","B":"是新经济政策的特征或内容。","C":"是新经济政策的特征或内容。","D":"是新经济政策的特征或内容。"}}},{"id":"basic-mayuan-ch07-2","moduleId":"basic","subjectId":"mayuan","chapter":"第七章 社会主义的发展及其规律","chapterKey":"第七章","n":2,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第七章 第 2 题"},"stem":"1871年爆发的巴黎公社革命，是第一国际精神的产儿，是无产阶级夺取政权的第一次伟大尝试。马克思、恩格斯总结的巴黎公社的经验有","choices":[{"id":"A","text":"无产阶级革命取得成功并保持胜利果实的首要条件是要有革命的武装"},{"id":"B","text":"必须打碎旧的国家机器，建立无产阶级的新型国家"},{"id":"C","text":"无产阶级政权是为人民服务的机关"},{"id":"D","text":"必须建立无产阶级政党，发挥党的政治领导作用"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是马克思、恩格斯总结的巴黎公社的经验，是本题正确答案。","B":"是马克思、恩格斯总结的巴黎公社的经验，是本题正确答案。","C":"是马克思、恩格斯总结的巴黎公社的经验，是本题正确答案。","D":"是马克思、恩格斯总结的巴黎公社的经验，是本题正确答案。"}}},{"id":"basic-mayuan-ch07-3","moduleId":"basic","subjectId":"mayuan","chapter":"第七章 社会主义的发展及其规律","chapterKey":"第七章","n":3,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第七章 第 3 题"},"stem":"19世纪初期以圣西门、傅立叶、欧文为代表的空想社会主义是科学社会主义的直接思想来源。空想社会主义的局限性主要表现在","choices":[{"id":"A","text":"未能揭示资本主义必然灭亡的经济根源"},{"id":"B","text":"看不到埋葬资本主义的力量"},{"id":"C","text":"找不到通往理想社会的现实道路"},{"id":"D","text":"对资本主义旧制度的辛辣批判，包含着许多切中要害的见解"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是空想社会主义的局限性，是本题正确答案。","B":"是空想社会主义的局限性，是本题正确答案。","C":"是空想社会主义的局限性，是本题正确答案。","D":"对资本主义旧制度的辛辣批判，包含着许多切中要害的见解——是空想社会主义的进步性，而非局限性。"}}},{"id":"basic-mayuan-ch07-4","moduleId":"basic","subjectId":"mayuan","chapter":"第七章 社会主义的发展及其规律","chapterKey":"第七章","n":4,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第七章 第 4 题"},"stem":"1848年2月，马克思、恩格斯为世界上第一个无产阶级政党“共产主义者同盟”所写的党纲《共产党宣言》的发表，标志着科学社会主义的产生。科学社会主义创立的理论基础是","choices":[{"id":"A","text":"唯物史观"},{"id":"B","text":"剩余价值学说"},{"id":"C","text":"劳动二重性理论"},{"id":"D","text":"辩证唯物主义"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是科学社会主义创立的理论基础，是本题正确答案。","B":"是科学社会主义创立的理论基础，是本题正确答案。","C":"劳动二重性理论——是“理解政治经济学的枢纽”。","D":"辩证唯物主义是马克思主义哲学的重要组成部分。"}}},{"id":"basic-mayuan-ch07-5","moduleId":"basic","subjectId":"mayuan","chapter":"第七章 社会主义的发展及其规律","chapterKey":"第七章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第七章 第 5 题"},"stem":"在俄国社会主义革命取得胜利的初期，特别是实行新经济政策期间，列宁对苏维埃俄国如何建设社会主义进行了深刻的理论思考，提出了许多精辟的论述。这些论述主要有","choices":[{"id":"A","text":"把建设社会主义作为一个长期探索、不断实践的过程"},{"id":"B","text":"把大力发展生产力、提高劳动生产率放在首要地位"},{"id":"C","text":"在多种经济成分并存的条件下，利用商品、货币和市场发展经济"},{"id":"D","text":"利用资本主义建设社会主义"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是实行新经济政策期间，列宁针对苏维埃俄国如何建设社会主义提出的精辟论述，是本题正确答案。","B":"是实行新经济政策期间，列宁针对苏维埃俄国如何建设社会主义提出的精辟论述，是本题正确答案。","C":"是实行新经济政策期间，列宁针对苏维埃俄国如何建设社会主义提出的精辟论述，是本题正确答案。","D":"是实行新经济政策期间，列宁针对苏维埃俄国如何建设社会主义提出的精辟论述，是本题正确答案。"}}},{"id":"basic-mayuan-ch07-6","moduleId":"basic","subjectId":"mayuan","chapter":"第七章 社会主义的发展及其规律","chapterKey":"第七章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第七章 第 6 题"},"stem":"建设社会主义必然具有艰巨性和长期性，这主要是因为","choices":[{"id":"A","text":"生产力发展状况的制约"},{"id":"B","text":"经济基础和上层建筑发展状况的制约"},{"id":"C","text":"国际环境的严峻挑战"},{"id":"D","text":"马克思主义执政党对社会主义发展道路的探索和对社会主义建设规律的认识，需要一个长期的过程"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是建设社会主义必然具有艰巨性和长期性的主要原因，是本题正确答案。","B":"是建设社会主义必然具有艰巨性和长期性的主要原因，是本题正确答案。","C":"是建设社会主义必然具有艰巨性和长期性的主要原因，是本题正确答案。","D":"是建设社会主义必然具有艰巨性和长期性的主要原因，是本题正确答案。"}}},{"id":"basic-mayuan-ch08-1","moduleId":"basic","subjectId":"mayuan","chapter":"第八章 共产主义崇高理想及其最终实现","chapterKey":"第八章","n":1,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第八章 第 1 题"},"stem":"马克思主义经典作家站在科学的立场上，提出并自觉运用了预见未来社会的方法论原则。这些方法论原则主要有","choices":[{"id":"A","text":"在揭示人类社会发展一般规律的基础上指明社会发展的方向"},{"id":"B","text":"在剖析资本主义旧世界的过程中阐发未来新世界的特点"},{"id":"C","text":"在社会主义社会发展中不断深化对未来共产主义社会的认识"},{"id":"D","text":"立足于揭示未来社会的一般特征，而不对各种细节作具体描绘"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是马克思主义经典作家预见未来社会的方法论原则，是本题正确答案。","B":"是马克思主义经典作家预见未来社会的方法论原则，是本题正确答案。","C":"是马克思主义经典作家预见未来社会的方法论原则，是本题正确答案。","D":"是马克思主义经典作家预见未来社会的方法论原则，是本题正确答案。"}}},{"id":"basic-mayuan-ch08-2","moduleId":"basic","subjectId":"mayuan","chapter":"第八章 共产主义崇高理想及其最终实现","chapterKey":"第八章","n":2,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"马原 · 第八章 第 2 题"},"stem":"共产主义一定能够实现，这是由人类社会的发展规律所决定的。共产主义社会的基本特征包括","choices":[{"id":"A","text":"物质财富极大丰富，消费资料按需分配"},{"id":"B","text":"社会关系高度和谐，人们精神境界极大提高"},{"id":"C","text":"实现每个人自由而全面的发展，人类从必然王国向自由王国飞跃"},{"id":"D","text":"以按劳分配为主体，多种分配方式并存"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是共产主义社会的基本特征，是本题正确答案。","B":"是共产主义社会的基本特征，是本题正确答案。","C":"是共产主义社会的基本特征，是本题正确答案。","D":"以按劳分配为主体，多种分配方式并存——是我国当前的分配制度，而非共产主义社会的基本特征。"}}},{"id":"basic-maozhongte-daolun-1","moduleId":"basic","subjectId":"maozhongte","chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","chapterKey":"导论","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 导论 第 1 题"},"stem":"1938年，毛泽东在党的六届六中全会上所作的政治报告中首次明确提出“马克思主义的中国化”的重大命题。这一政治报告是","choices":[{"id":"A","text":"《古田会议决议》"},{"id":"B","text":"《论新阶段》"},{"id":"C","text":"《论联合政府》"},{"id":"D","text":"《关于修改党章的报告》"}],"answer":["B"],"analysis":{"point":"","options":{"A":"《古田会议决议》——是中国共产党和红军建设的纲领性文献。","B":"《论新阶段》——是首次明确提出“马克思主义的中国化”重大命题的政治报告，是本题正确答案。","C":"《论联合政府》——是毛泽东在党的七大上所作的政治报告。","D":"《关于修改党章的报告》——是刘少奇在党的七大上所作的报告，报告对马克思主义中国化从理论上作了进一步的阐述，并指出毛泽东思想是“中国化的马克思主义”。"}}},{"id":"basic-maozhongte-daolun-2","moduleId":"basic","subjectId":"maozhongte","chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","chapterKey":"导论","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 导论 第 2 题"},"stem":"在马克思主义中国化时代化的历史进程中，第一次历史性飞跃是","choices":[{"id":"A","text":"马克思主义的系统传播"},{"id":"B","text":"遵义会议的成功召开"},{"id":"C","text":"“实事求是”思想路线的阐明"},{"id":"D","text":"毛泽东思想的形成"}],"answer":["D"],"analysis":{"point":"","options":{"A":"马克思主义的系统传播——是以李大钊发表《我的马克思主义观》为标志的。","B":"遵义会议的成功召开——是中国共产党独立自主解决中国实际问题的新阶段的开始。°《》《》","C":"（原书未单独给出此项解析）","D":"毛泽东思想的形成——是马克思主义中国化时代化的第一次历史性飞跃，是本题正确答案。"}}},{"id":"basic-maozhongte-daolun-3","moduleId":"basic","subjectId":"maozhongte","chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","chapterKey":"导论","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 导论 第 3 题"},"stem":"马克思主义传入中国后，科学社会主义的主张受到中国人民热烈欢迎，并最终扎根中国大地、开花结果。实现马克思主义中国化时代化的第一次历史性飞跃是在","choices":[{"id":"A","text":"中共二大"},{"id":"B","text":"中共七大"},{"id":"C","text":"中共六届六中全会"},{"id":"D","text":"中共七届二中全会"}],"answer":["B"],"analysis":{"point":"","options":{"A":"中共二大——是第一次提出反帝反封建的民主革命纲领的会议。","B":"中共七大——是实现马克思主义中国化时代化第一次历史性飞跃的会议，是本题正确答案。","C":"中共六届六中全会——是首次明确提出“马克思主义的中国化”重大命题的会议。","D":"中共七届二中全会——是中国革命在即将取得胜利时召开的会议，指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向。"}}},{"id":"basic-maozhongte-daolun-4","moduleId":"basic","subjectId":"maozhongte","chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","chapterKey":"导论","n":4,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 导论 第 4 题"},"stem":"马克思主义中国化时代化的科学内涵包括","choices":[{"id":"A","text":"运用马克思主义的立场、观点和方法，解决中国的实际问题"},{"id":"B","text":"总结和提炼中国革命、建设、改革的实践经验并将其上升为理论"},{"id":"C","text":"不断丰富和发展马克思主义的理论宝库，赋予马克思主义以新的时代内涵"},{"id":"D","text":"使马克思主义根植于中华优秀传统文化的土壤之中"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是马克思主义中国化时代化的科学内涵，是本题正确答案。","B":"是马克思主义中国化时代化的科学内涵，是本题正确答案。","C":"是马克思主义中国化时代化的科学内涵，是本题正确答案。","D":"是马克思主义中国化时代化的科学内涵，是本题正确答案。"}}},{"id":"basic-maozhongte-daolun-5","moduleId":"basic","subjectId":"maozhongte","chapter":"导论 马克思主义中国化时代化的历史进程与理论成果","chapterKey":"导论","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 导论 第 5 题"},"stem":"马克思主义中国化时代化，就是将马克思主义基本原理同中国具体实际相结合，不断形成具有中国特色的马克思主义理论成果的过程。因此，实现马克思主义中国化时代化，必须同","choices":[{"id":"A","text":"马克思主义经典著作相结合"},{"id":"B","text":"中国具体实际相结合"},{"id":"C","text":"世界社会主义国家建设经验相结合"},{"id":"D","text":"中华优秀传统文化相结合"}],"answer":["B","D"],"analysis":{"point":"","options":{"A":"非考点。","B":"即“两个结合”，是实现马克思主义中国化时代化的根本途径，是本题正确答案。","C":"非考点。","D":"即“两个结合”，是实现马克思主义中国化时代化的根本途径，是本题正确答案。"}}},{"id":"basic-maozhongte-ch01-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 1 题"},"stem":"明确把毛泽东思想确立为党的指导思想并写入党章的会议是","choices":[{"id":"A","text":"中共六大"},{"id":"B","text":"中共七大"},{"id":"C","text":"中共八大"},{"id":"D","text":"中共十二大"}],"answer":["B"],"analysis":{"point":"","options":{"A":"中共六大——是为了系统地总结第一次国内革命的经验教训，批判右倾投降主义和“左”倾盲动主义的错误，明确新形势下革命的性质和任务而召开的会议。","B":"中共七大——是明确把毛泽东思想确立为党的指导思想并写入党章的会议，是本题正确答案。","C":"中共八大——是1956年正确分析国内主要矛盾的变化，明确提出党和人民的主要任务的会议。","D":"中共十二大——是开始把中国带入建设有中国特色的社会主义的新的政治轨道的会议。"}}},{"id":"basic-maozhongte-ch01-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 2 题"},"stem":"群众路线，就是一切为了群众，一切依靠群众，从群众中来，到群众中去。这是","choices":[{"id":"A","text":"党的根本工作路线"},{"id":"B","text":"党的根本思想路线"},{"id":"C","text":"党的根本政治原则"},{"id":"D","text":"党的根本制度保证"}],"answer":["A"],"analysis":{"point":"","options":{"A":"党的根本工作路线——是群众路线，是本题正确答案。","B":"党的根本思想路线是实事求是。","C":"党的根本政治原则——是独立自主。","D":"党的根本制度保证——非考点。"}}},{"id":"basic-maozhongte-ch01-3","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 3 题"},"stem":"毛泽东思想的活的灵魂，是贯穿毛泽东思想各个组成部分的立场、观点和方法，其基本方面有三个，其中的精髓是","choices":[{"id":"A","text":"实事求是"},{"id":"B","text":"党的建设"},{"id":"C","text":"群众路线"},{"id":"D","text":"独立自主"}],"answer":["A"],"analysis":{"point":"","options":{"A":"实事求是——是毛泽东思想活的灵魂之一，是毛泽东思想的精髓，是毛泽东思想的基本点，是本题正确答案。","B":"党的建设是新民主主义革命的三大法宝之一。","C":"群众路线——是毛泽东思想活的灵魂之一，是我们党的生命线和根本工作路线，是我们党永葆青春活力和战斗力的重要传家宝。","D":"独立自主——是毛泽东思想活的灵魂之一，是中国共产党、中华人民共和国立党立国的重要原则，是党的根本政治原则，是中华民族精神之魂。"}}},{"id":"basic-maozhongte-ch01-4","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 4 题"},"stem":"毛泽东思想形成和发展的时代主题是","choices":[{"id":"A","text":"恢复和重建"},{"id":"B","text":"战争与革命"},{"id":"C","text":"和平与发展"},{"id":"D","text":"革命与改革"}],"answer":["B"],"analysis":{"point":"","options":{"A":"非考点。","B":"战争与革命——是毛泽东思想形成和发展的时代主题，是本题正确答案。","C":"和平与发展——是邓小平理论形成和发展的时代主题。","D":"非考点。"}}},{"id":"basic-maozhongte-ch01-5","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 5 题"},"stem":"毛泽东思想是以毛泽东同志为主要代表的中国共产党人领导实践和深入思考中国问题而形成的。毛泽东思想形成和发展的实践基础是","choices":[{"id":"A","text":"世界工人运动的蓬勃发展"},{"id":"B","text":"确立马克思主义为党的指导思想"},{"id":"C","text":"中国共产党领导人民进行革命和建设的成功实践"},{"id":"D","text":"推进改革开放和社会主义现代化建设的伟大实践"}],"answer":["C"],"analysis":{"point":"","options":{"A":"非考点。","B":"非考点。","C":"中国共产党领导人民进行革命和建设的成功实践——是毛泽东思想形成和发展的实践基础，是本题正确答案。","D":"推进改革开放和社会主义现代化建设的伟大实践——是中国特色社会主义理论体系形成发展的实践基础。"}}},{"id":"basic-maozhongte-ch01-6","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 6 题"},"stem":"毛泽东思想是在我国新民主主义革命、社会主义革命和社会主义建设的实践过程中，逐步形成和发展起来的。毛泽东思想初步形成的标志是","choices":[{"id":"A","text":"革命的统一战线理论的提出"},{"id":"B","text":"农村包围城市、武装夺取政权的革命道路理论的提出"},{"id":"C","text":"新民主主义革命理论的系统阐明"},{"id":"D","text":"“马克思主义的中国化”命题的提出"}],"answer":["B"],"analysis":{"point":"","options":{"A":"革命的统一战线理论的提出是在毛泽东思想趋于成熟时期。","B":"农村包围城市、武装夺取政权的革命道路理论的提出——是毛泽东思想初步形成的标志，是本题正确答案。","C":"新民主主义革命理论的系统阐明是毛泽东思想趋于成熟的标志。","D":"“马克思主义的中国化”命题的提出——是在毛泽东思想趋于成熟时期。"}}},{"id":"basic-maozhongte-ch01-7","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 7 题"},"stem":"毛泽东思想和中国特色社会主义理论体系是马克思主义中国化时代化的两大理论成果。贯穿这两大理论成果始终，并体现在两大理论成果各个基本观点中的世界观和方法论基础是","choices":[{"id":"A","text":"改革创新"},{"id":"B","text":"独立自主"},{"id":"C","text":"实事求是"},{"id":"D","text":"群众路线"}],"answer":["C"],"analysis":{"point":"","options":{"A":"改革创新是时代精神的核心。","B":"独立自主是毛泽东思想活的灵魂之一。","C":"实事求是——是贯穿毛泽东思想和中国特色社会主义理论体系始终，并体现在其各个基本观点中的世界观和方法论基础，是本题正确答案。","D":"群众路线是毛泽东思想活的灵魂之一。"}}},{"id":"basic-maozhongte-ch01-8","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 8 题"},"stem":"毛泽东思想的活的灵魂有三个基本方面，即","choices":[{"id":"A","text":"实事求是"},{"id":"B","text":"统一战线"},{"id":"C","text":"独立自主"},{"id":"D","text":"群众路线"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是毛泽东思想活的灵魂的三个基本方面，是本题正确答案。","B":"统一战线是新民主主义革命的三大法宝之一。","C":"是毛泽东思想活的灵魂的三个基本方面，是本题正确答案。","D":"是毛泽东思想活的灵魂的三个基本方面，是本题正确答案。"}}},{"id":"basic-maozhongte-ch01-9","moduleId":"basic","subjectId":"maozhongte","chapter":"第一章 毛泽东思想及其历史地位","chapterKey":"第一章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第一章 第 9 题"},"stem":"毛泽东思想是马克思列宁主义基本原理和中国具体实际相结合的产物，是中国共产党人集体智慧的结晶。毛泽东思想具有重要历史地位，它是","choices":[{"id":"A","text":"中国共产党和中国人民宝贵的精神财富"},{"id":"B","text":"推进中国特色社会主义事业的强大理论武器"},{"id":"C","text":"马克思主义中国化时代化的第一个重大理论成果"},{"id":"D","text":"中国革命和建设的科学指南"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是毛泽东思想的历史地位和重大意义，是本题正确答案。","B":"是“三个代表”重要思想乃至整个中国特色社会主义理论体系的重大意义。","C":"是毛泽东思想的历史地位和重大意义，是本题正确答案。","D":"是毛泽东思想的历史地位和重大意义，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 1 题"},"stem":"解决中国革命问题的基本前提是","choices":[{"id":"A","text":"分清敌友"},{"id":"B","text":"建立工农联盟"},{"id":"C","text":"形成统一战线"},{"id":"D","text":"认清中国国情"}],"answer":["D"],"analysis":{"point":"","options":{"A":"分清敌友是革命的首要问题。","B":"是中国革命问题中的统一战线问题。","C":"是中国革命问题中的统一战线问题。","D":"认清中国国情——是解决中国革命问题的基本前提，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 2 题"},"stem":"在半殖民地半封建的近代中国，社会矛盾呈现错综复杂的状况，在诸多社会矛盾中，最主要的矛盾是","choices":[{"id":"A","text":"封建主义和人民大众的矛盾"},{"id":"B","text":"帝国主义和中华民族的矛盾"},{"id":"C","text":"资产阶级和无产阶级的矛盾"},{"id":"D","text":"农民阶级和地主阶级的矛盾"}],"answer":["B"],"analysis":{"point":"","options":{"A":"封建主义和人民大众的矛盾——是近代中国主要矛盾之一，但不是最主要的矛盾。","B":"帝国主义和中华民族的矛盾——是近代中国最主要的矛盾，是本题正确答案。","C":"是近代中国的矛盾，但不是最主要的矛盾。","D":"是近代中国的矛盾，但不是最主要的矛盾。"}}},{"id":"basic-maozhongte-ch02-3","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 3 题"},"stem":"近代中国的社会性质和主要矛盾，决定了中国革命的性质是","choices":[{"id":"A","text":"无产阶级民主革命"},{"id":"B","text":"新民主主义革命"},{"id":"C","text":"资产阶级民主革命"},{"id":"D","text":"无产阶级社会主义革命"}],"answer":["C"],"analysis":{"point":"","options":{"A":"无产阶级民主革命——非考点。","B":"新民主主义革命——是中国资产阶级民主革命的一个时期，是新式的特殊的资产阶级民主主义的革命。","C":"资产阶级民主革命——是近代中国革命的性质，是本题正确答案。","D":"无产阶级社会主义革命——是1949—1956年所进行的革命。"}}},{"id":"basic-maozhongte-ch02-4","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 4 题"},"stem":"毛泽东将新民主主义革命总路线的内容完整地表述为“无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命”的文件是","choices":[{"id":"A","text":"1938 年的《论新阶段》"},{"id":"B","text":"1939年的《中国革命和中国共产党》"},{"id":"C","text":"1940年的《新民主主义论》"},{"id":"D","text":"1948年的《在晋绥干部会议上的讲话》"}],"answer":["D"],"analysis":{"point":"","options":{"A":"（原书未单独给出此项解析）","B":"（原书未单独给出此项解析）","C":"1940年的《新民主主义论》——阐述了新民主主义的政治、经济和文化。","D":"1948年的《在晋绥干部会议上的讲话》——完整地表述了新民主主义革命总路线的内容，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-5","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 5 题"},"stem":"毛泽东曾指出：“我们的革命要有不领错路和一定成功的把握。”因此，从一开始就要避免方向性错误。革命的首要问题是","choices":[{"id":"A","text":"农民问题"},{"id":"B","text":"分清敌友"},{"id":"C","text":"土地革命"},{"id":"D","text":"独立自主"}],"answer":["B"],"analysis":{"point":"","options":{"A":"农民问题是中国革命的基本问题。","B":"分清敌友——是革命的首要问题，是本题正确答案。","C":"土地革命是中国革命的基本内容。","D":"独立自主是毛泽东思想活的灵魂之一。"}}},{"id":"basic-maozhongte-ch02-6","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 6 题"},"stem":"中国社会进步和发展的最大障碍、近代中国贫困落后和一切灾难祸害的总根源是","choices":[{"id":"A","text":"帝国主义"},{"id":"B","text":"封建地主阶级"},{"id":"C","text":"封建主义"},{"id":"D","text":"官僚资产阶级"}],"answer":["A"],"analysis":{"point":"","options":{"A":"帝国主义——是中国社会进步和发展的最大障碍，是近代中国贫困落后和一切灾难祸害的总根源，是中国革命的首要对象，是本题正确答案。","B":"封建地主阶级——是中国经济现代化和政治民主化主要的、直接的障碍。","C":"封建主义——和帝国主义一起，是中国革命主要打击的两个敌人。","D":"官僚资产阶级——是依靠帝国主义、勾结封建势力、利用国家政权力量而发展起来的买办的、封建的阶级。"}}},{"id":"basic-maozhongte-ch02-7","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 7 题"},"stem":"帝国主义统治中国和封建军阀实行专制统治的社会基础是","choices":[{"id":"A","text":"封建土地所有制"},{"id":"B","text":"官僚资产阶级"},{"id":"C","text":"封建地主阶级"},{"id":"D","text":"封建思想的束缚"}],"answer":["C"],"analysis":{"point":"","options":{"A":"封建土地所有制是封建主义的经济基础。","B":"官僚资产阶级——是依靠帝国主义、勾结封建势力、利用国家政权力量而发展起来的买办的、封建的阶级。","C":"封建地主阶级——是帝国主义统治中国和封建军阀实行专制统治的社会基础，是本题正确答案。","D":"封建思想的束缚非考点。"}}},{"id":"basic-maozhongte-ch02-8","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 8 题"},"stem":"新民主主义革命总路线的完整表述为“无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命”。其中“人民大众的”是指","choices":[{"id":"A","text":"革命的动力"},{"id":"B","text":"革命的对象"},{"id":"C","text":"革命的性质"},{"id":"D","text":"革命的领导权"}],"answer":["A"],"analysis":{"point":"","options":{"A":"革命的动力——是“人民大众”，包括无产阶级、农民阶级、城市小资产阶级和民族资产阶级，是本题正确答案。","B":"革命的对象——是“三座大山”，即帝国主义、封建主义和官僚资本主义。","C":"革命的性质是资产阶级民主革命。","D":"革命的领导权——要掌握在无产阶级手中。"}}},{"id":"basic-maozhongte-ch02-9","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 9 题"},"stem":"近代中国最进步的、中国革命最基本的动力的阶级是","choices":[{"id":"A","text":"农民阶级"},{"id":"B","text":"无产阶级"},{"id":"C","text":"城市小资产阶级"},{"id":"D","text":"民族资产阶级"}],"answer":["B"],"analysis":{"point":"","options":{"A":"农民阶级是中国革命的主力军。","B":"无产阶级——是中国革命最基本的动力，是新的社会生产力的代表，是近代中国最进步的阶级，是中国革命的领导力量，是本题正确答案。","C":"城市小资产阶级——是无产阶级的可靠同盟者，是中国革命的动力之一。","D":"民族资产阶级——是中国革命的动力之一，但它既不可能充当革命的主要力量，更不可能是革命的领导力量。"}}},{"id":"basic-maozhongte-ch02-10","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 10 题"},"stem":"新民主主义革命总路线反映了中国革命的基本规律，指明了中国革命的对象、动力、领导力量、性质和前途。毛泽东在《新民主主义论》中指出，中国革命的基本问题是","choices":[{"id":"A","text":"政权问题"},{"id":"B","text":"农民问题"},{"id":"C","text":"无产阶级的领导权"},{"id":"D","text":"土地革命"}],"answer":["B"],"analysis":{"point":"","options":{"A":"政权问题是革命的根本问题。","B":"农民问题是中国革命的基本问题，是本题正确答案。","C":"无产阶级的领导权——是中国革命的中心问题，也是新民主主义革命理论的核心问题。","D":"土地革命是中国革命的基本内容。"}}},{"id":"basic-maozhongte-ch02-11","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 11 题"},"stem":"毛泽东说过：“革命战争是群众的战争，只有动员群众才能进行战争，只有依靠群众才能进行战争。”中国革命战争实质上就是","choices":[{"id":"A","text":"党领导下的工人运动"},{"id":"B","text":"党领导下的反帝爱国运动"},{"id":"C","text":"各个革命阶级的联合斗争"},{"id":"D","text":"党领导下的农民战争"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是中国革命中具体的革命活动。","B":"是中国革命中具体的革命活动。","C":"是中国革命中具体的革命活动。","D":"党领导下的农民战争——是中国革命战争的实质，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-12","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 12 题"},"stem":"毛泽东认为，民族资产阶级“对于中国革命具有矛盾的态度”。这是因为这个阶级","choices":[{"id":"A","text":"从未领导过革命"},{"id":"B","text":"极其依赖帝国主义和封建主义"},{"id":"C","text":"带有两面性"},{"id":"D","text":"是无产阶级最可靠的同盟军"}],"answer":["C"],"analysis":{"point":"","options":{"A":"从未领导过革命——是错误说法，旧民主主义革命主要是由资产阶级领导的。","B":"极其依赖帝国主义和封建主义——是民族资产阶级具有动摇性的原因。","C":"带有两面性——是民族资产阶级对中国革命具有矛盾态度的原因，是本题正确答案。","D":"是无产阶级最可靠的同盟军——是错误说法，贫雇农是无产阶级最可靠的同盟军。"}}},{"id":"basic-maozhongte-ch02-13","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 13 题"},"stem":"区别新旧两种不同范畴的民主主义革命的根本标志是","choices":[{"id":"A","text":"革命的领导权是掌握在无产阶级手中还是掌握在资产阶级手中"},{"id":"B","text":"革命的对象是封建地主阶级还是民族资产阶级"},{"id":"C","text":"革命的时间是在五四运动以前还是五四运动以后"},{"id":"D","text":"革命的结果是成功还是失败"}],"answer":["A"],"analysis":{"point":"","options":{"A":"革命的领导权是掌握在无产阶级手中还是掌握在资产阶级手中——是区别新旧两种不同范畴的民主主义革命的根本标志，是本题正确答案。","B":"革命的对象是封建地主阶级还是民族资产阶级——是资产阶级民主革命和社会主义革命的区别。","C":"革命的时间是在五四运动以前还是五四运动以后——是旧民主主义革命和新民主主义革命在发生时间上的区分。","D":"革命的结果是成功还是失败——是新旧两种民主主义革命的不同结局。"}}},{"id":"basic-maozhongte-ch02-14","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 14 题"},"stem":"无产阶级及其政党对中国革命的领导权不是自然而然得来的，而是在","choices":[{"id":"A","text":"与民族资产阶级的联合中实现的"},{"id":"B","text":"与资产阶级争夺领导权的斗争中实现的"},{"id":"C","text":"与封建主义争夺政权的斗争中实现的"},{"id":"D","text":"与农民阶级的联合中实现的"}],"answer":["B"],"analysis":{"point":"","options":{"A":"非考点。","B":"与资产阶级争夺领导权的斗争中实现的——是无产阶级领导权的由来，是本题正确答案。","C":"非考点。","D":"非考点。"}}},{"id":"basic-maozhongte-ch02-15","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 15 题"},"stem":"“无产阶级的政党应该知道无产阶级参加民族运动，不是附属资产阶级而参加，乃以自己阶级独立的地位与目的参加。”无产阶级实现领导权的关键是","choices":[{"id":"A","text":"给被领导者以物质福利，并进行政治教育"},{"id":"B","text":"建立以工农联盟为基础的广泛的统一战线"},{"id":"C","text":"保持党在思想上、政治上和组织上的独立性"},{"id":"D","text":"对资产阶级实行又联合又斗争的方针"}],"answer":["B"],"analysis":{"point":"","options":{"A":"给被领导者以物质福利，并进行政治教育——是无产阶级实现领导权的条件。","B":"建立以工农联盟为基础的广泛的统一战线——是无产阶级实现领导权的关键，是本题正确答案。","C":"是无产阶级坚持领导权的基本策略。","D":"是无产阶级坚持领导权的基本策略。"}}},{"id":"basic-maozhongte-ch02-16","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 16 题"},"stem":"无产阶级及其政党对中国革命的领导权不是自然而然得来的，保证领导权的坚强支柱是","choices":[{"id":"A","text":"坚持独立自主的原则"},{"id":"B","text":"加强无产阶级政党的建设"},{"id":"C","text":"建立一支无产阶级领导的以农民为主体的强大的革命武装"},{"id":"D","text":"建立以工农联盟为基础的广泛的统一战线"}],"answer":["C"],"analysis":{"point":"","options":{"A":"坚持独立自主的原则——是无产阶级坚持领导权的基本策略。","B":"加强无产阶级政党的建设——是无产阶级实现领导权的根本保证。","C":"建立一支无产阶级领导的以农民为主体的强大的革命武装——是无产阶级保证领导权的坚强支柱，是本题正确答案。","D":"建立以工农联盟为基础的广泛的统一战线——是无产阶级实现领导权的关键。"}}},{"id":"basic-maozhongte-ch02-17","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 17 题"},"stem":"毛泽东曾指出，新民主主义共和国，一方面和旧形式的、欧美式的资本主义的共和国相区别；另一方面，也和苏联式的社会主义的共和国相区别。我们的新民主主义国家的国体是","choices":[{"id":"A","text":"无产阶级专政"},{"id":"B","text":"各革命阶级联合专政"},{"id":"C","text":"资产阶级专政"},{"id":"D","text":"工农联合专政"}],"answer":["B"],"analysis":{"point":"","options":{"A":"非考点。","B":"各革命阶级联合专政——是新民主主义国家的国体，是无产阶级领导的以工农联盟为基础，包括小资产阶级、民族资产阶级和其他反帝反封建的人们在内的各革命阶级的联合专政，是本题正确答案。","C":"非考点。","D":"非考点。"}}},{"id":"basic-maozhongte-ch02-18","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":18,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 18 题"},"stem":"新民主主义经济纲领中极具特色的一项内容是","choices":[{"id":"A","text":"没收封建地主阶级的土地归农民所有"},{"id":"B","text":"没收官僚资产阶级的垄断资本归新民主主义国家所有"},{"id":"C","text":"各革命阶级联合专政"},{"id":"D","text":"保护民族工商业"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是新民主主义经济纲领的内容，但不是极具特色的内容。","B":"是新民主主义经济纲领的内容，但不是极具特色的内容。","C":"各革命阶级联合专政——是新民主主义政治纲领的内容，而不是经济纲领的内容。","D":"保护民族工商业——是新民主主义经济纲领中极具特色的一项内容，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-19","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":19,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 19 题"},"stem":"新民主主义经济纲领中，包含着新民主主义革命和社会主义革命的双重性质的内容是","choices":[{"id":"A","text":"没收封建地主阶级的土地归农民所有"},{"id":"B","text":"没收官僚资产阶级的垄断资本归新民主主义国家所有"},{"id":"C","text":"没收外国资本归新民主主义国家所有"},{"id":"D","text":"保护民族工商业"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是新民主主义经济纲领的内容，但不具有双重性质。","B":"没收官僚资产阶级的垄断资本归新民主主义国家所有——是新民主主义经济纲领中包含着新民主主义革命和社会主义革命的双重性质的内容，是本题正确答案。","C":"没收外国资本归新民主主义国家所有——非考点。","D":"是新民主主义经济纲领的内容，但不具有双重性质。"}}},{"id":"basic-maozhongte-ch02-20","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":20,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 20 题"},"stem":"新民主主义文化是民族的，就其内容说是","choices":[{"id":"A","text":"反对一切封建思想和迷信思想"},{"id":"B","text":"具有鲜明的民族风格、民族形式和民族特色，要有中国作风和中国气派"},{"id":"C","text":"反对帝国主义压迫，主张中华民族的尊严和独立"},{"id":"D","text":"要以人民群众的实践作为创作的源泉"}],"answer":["C"],"analysis":{"point":"","options":{"A":"反对一切封建思想和迷信思想——是新民主主义文化“科学的”内涵。","B":"具有鲜明的民族风格、民族形式和民族特色，要有中国作风和中国气派——是新民主主义文化“民族的”内涵，但这是就其形式说的，而非内容。","C":"就其内容说的，是本题正确答案。","D":"要以人民群众的实践作为创作的源泉——是新民主主义文化“大众的”内涵。"}}},{"id":"basic-maozhongte-ch02-21","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":21,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 21 题"},"stem":"新民主主义文化是大众的，也就是","choices":[{"id":"A","text":"反封建的文化"},{"id":"B","text":"反帝的文化"},{"id":"C","text":"民主的文化"},{"id":"D","text":"民族的文化"}],"answer":["C"],"analysis":{"point":"","options":{"A":"反封建的文化——是“科学的”。","B":"反帝的文化是“民族的”。","C":"民主的文化——是“大众的”，是本题正确答案。","D":"民族的文化——是新民主主义文化纲领的内容，与“科学的”“大众的”文化并列。"}}},{"id":"basic-maozhongte-ch02-22","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":22,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 22 题"},"stem":"1938年11月，毛泽东在党的六届六中全会上明确指出：“共产党的任务，基本地不是经过长期合法斗争以进入起义和战争，也不是先占城市后取乡村，而是走相反的道路。”从此把经过长期武装斗争，先占乡村，后取城市，最后夺取全国胜利，作为革命道路确立下来。毛泽东提出该观点的著作是","choices":[{"id":"A","text":"《战争和战略问题》"},{"id":"B","text":"《中国革命和中国共产党》"},{"id":"C","text":"《在晋绥干部会议上的讲话》"},{"id":"D","text":"《论新阶段》"}],"answer":["A"],"analysis":{"point":"","options":{"A":"《战争和战略问题》——是确立革命道路的著作，是本题正确答案。","B":"《中国革命和中国共产党》——是第一次提出“新民主主义的革命”科学概念的著作。","C":"《在晋绥干部会议上的讲话》——是完整表述新民主主义革命总路线的著作。","D":"《论新阶段》——是首次明确提出“马克思主义的中国化”重大命题的政治报告。"}}},{"id":"basic-maozhongte-ch02-23","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":23,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 23 题"},"stem":"中国革命的主要斗争形式是","choices":[{"id":"A","text":"土地革命"},{"id":"B","text":"群众路线"},{"id":"C","text":"农村包围城市"},{"id":"D","text":"武装斗争"}],"answer":["D"],"analysis":{"point":"","options":{"A":"土地革命——是中国革命的基本内容。","B":"群众路线是革命方法。","C":"农村包围城市是革命道路。","D":"武装斗争——是中国革命的主要斗争形式，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-24","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":24,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 24 题"},"stem":"中国革命走农村包围城市、武装夺取政权的道路，必须处理好土地革命、武装斗争、农村革命根据地建设三者之间的关系。其中，中国民主革命的基本内容是","choices":[{"id":"A","text":"土地革命"},{"id":"B","text":"武装斗争"},{"id":"C","text":"农村革命根据地建设"},{"id":"D","text":"党的建设"}],"answer":["A"],"analysis":{"point":"","options":{"A":"土地革命——是中国革命的基本内容，是本题正确答案。","B":"武装斗争——是中国革命的主要斗争形式，是农村革命根据地建设和土地革命的强有力保证。","C":"农村革命根据地建设——是中国革命的战略阵地，是进行武装斗争和开展土地革命的依托。","D":"党的建设是新民主主义革命的三大法宝之一。"}}},{"id":"basic-maozhongte-ch02-25","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":25,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 25 题"},"stem":"中国共产党之所以能够深入农村积蓄革命力量，建设农村革命根据地，最终实现农村包围城市并夺取政权，有多方面的原因。其中，为农村革命根据地建设和发展提供重要的主观条件的是","choices":[{"id":"A","text":"全国革命形势的继续向前发展"},{"id":"B","text":"党的领导的有力量及其政策的不错误"},{"id":"C","text":"近代中国四分五裂，军阀割据，存在不少的统治薄弱环节"},{"id":"D","text":"广大农村深受反动统治阶级的多重压迫和剥削"}],"answer":["B"],"analysis":{"point":"","options":{"A":"全国革命形势的继续向前发展——为在农村建设革命根据地提供了客观条件。","B":"党的领导的有力量及其政策的不错误——为农村革命根据地建设和发展提供了重要的主观条件，是本题正确答案。","C":"近代中国四分五裂，军阀割据，存在不少的统治薄弱环节——是客观方面的条件，为党在农村开展革命斗争、建设革命根据地提供了缝隙和可能。","D":"广大农村深受反动统治阶级的多重压迫和剥削——是客观方面的条件。"}}},{"id":"basic-maozhongte-ch02-26","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":26,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 26 题"},"stem":"中国革命之所以能走农村包围城市、武装夺取政权的道路，是由中国的特殊国情决定的。其中，农村革命根据地的创立、巩固和发展的坚强后盾是","choices":[{"id":"A","text":"广大农民的支持和参加"},{"id":"B","text":"党的领导的有力量及其政策的不错误"},{"id":"C","text":"反动统治阶级的多重压迫和剥削"},{"id":"D","text":"相当力量正式红军的存在"}],"answer":["D"],"analysis":{"point":"","options":{"A":"广大农民的支持和参加——是一种有力的客观条件，但不是坚强后盾。","B":"党的领导的有力量及其政策的不错误——为农村革命根据地建设和发展提供了重要的主观条件。","C":"反动统治阶级的多重压迫和剥削——是广大农民支持和参加农村革命根据地建设和发展的原因，是一种客观条件。","D":"相当力量正式红军的存在——为农村革命根据地的创立、巩固和发展提供了坚强后盾，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-27","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":27,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 27 题"},"stem":"中国共产党领导的革命统一战线包含两个联盟，其中，工人阶级同农民阶级、广大知识分子及其他劳动者的联盟，主要是","choices":[{"id":"A","text":"与地主阶级的联盟"},{"id":"B","text":"与民族资产阶级的联盟"},{"id":"C","text":"与农民阶级的联盟"},{"id":"D","text":"与知识分子的联盟"}],"answer":["C"],"analysis":{"point":"","options":{"A":"与地主阶级的联盟——是错误说法。","B":"与民族资产阶级的联盟是第二个联盟中的联盟。","C":"与农民阶级的联盟——是第一个联盟中主要的联盟，是本题正确答案。","D":"与知识分子的联盟——是第一个联盟中的联盟，但不是主要的。"}}},{"id":"basic-maozhongte-ch02-28","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":28,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 28 题"},"stem":"以下既是建设新型人民军队的根本原则，也是保持人民军队无产阶级性质和建军宗旨的根本前提的是","choices":[{"id":"A","text":"能打仗、打胜仗"},{"id":"B","text":"全心全意为人民服务"},{"id":"C","text":"坚持党对军队的绝对领导"},{"id":"D","text":"作风优良"}],"answer":["C"],"analysis":{"point":"","options":{"A":"能打仗、打胜仗——是军队的根本价值所在。","B":"全心全意为人民服务——是人民军队的唯一宗旨。","C":"坚持党对军队的绝对领导——是建设新型人民军队的根本原则，是保持人民军队无产阶级性质和建军宗旨的根本前提，是毛泽东建军思想的核心，是本题正确答案。","D":"作风优良——是我军的鲜明特色和政治优势。"}}},{"id":"basic-maozhongte-ch02-29","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":29,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 29 题"},"stem":"毛泽东提出统一战线、武装斗争、党的建设是党在中国革命中战胜敌人的三个主要的法宝的著作是","choices":[{"id":"A","text":"《新民主主义论》"},{"id":"B","text":"《星星之火，可以燎原》"},{"id":"C","text":"《论联合政府》"},{"id":"D","text":"《<共产党人〉发刊词》"}],"answer":["D"],"analysis":{"point":"","options":{"A":"《新民主主义论》——阐述了新民主主义的政治、经济和文化。","B":"《星星之火，可以燎原》——提出了革命道路理论。","C":"《论联合政府》——具体阐述了新民主主义的基本纲领。","D":"《〈共产党人〉发刊词》——提出了统一战线、武装斗争、党的建设是党在中国革命中战胜敌人的三个主要的法宝，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-30","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":30,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 30 题"},"stem":"新民主主义革命时期，毛泽东提出，加强党的思想建设，关键是要","choices":[{"id":"A","text":"贯彻民主集中制的原则"},{"id":"B","text":"坚持实事求是的思想路线"},{"id":"C","text":"以无产阶级思想克服和改造各种非无产阶级思想"},{"id":"D","text":"坚持密切联系群众的作风"}],"answer":["C"],"analysis":{"point":"","options":{"A":"贯彻民主集中制的原则——是加强党的组织建设的根本。","B":"坚持实事求是的思想路线——是思想建设的要求，但不是“关键”。","C":"以无产阶级思想克服和改造各种非无产阶级思想——是加强党的思想建设的关键，是本题正确答案。","D":"坚持密切联系群众的作风——是党的三大优良作风之一。"}}},{"id":"basic-maozhongte-ch02-31","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":31,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 31 题"},"stem":"加强党的组织建设，根本的是","choices":[{"id":"A","text":"贯彻民主集中制的原则"},{"id":"B","text":"维护中央权威和统一领导"},{"id":"C","text":"联系党的政治路线加强党的建设"},{"id":"D","text":"勇于自我革命"}],"answer":["A"],"analysis":{"point":"","options":{"A":"贯彻民主集中制的原则是加强党的组织建设的根本，是本题正确答案。","B":"维护中央权威和统一领导——是“两个维护”之一，是马克思主义执政党的重大建党原则。","C":"联系党的政治路线加强党的建设——是加强党的建设的经验之一。","D":"勇于自我革命——是中国共产党区别于其他政党的最显著的标志。"}}},{"id":"basic-maozhongte-ch02-32","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":32,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 32 题"},"stem":"近代中国革命的根本任务是","choices":[{"id":"A","text":"变革阻碍生产力发展的生产关系"},{"id":"B","text":"推翻帝国主义、封建主义和官僚资本主义的统治"},{"id":"C","text":"从根本上推翻反动腐朽的政治上层建筑"},{"id":"D","text":"为建设富强民主的国家、确立人民当家作主的政治制度、改善人民生活扫清障碍，创造必要的前提"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是近代中国革命的根本任务，是本题正确答案。","B":"是近代中国革命的根本任务，是本题正确答案。","C":"是近代中国革命的根本任务，是本题正确答案。","D":"是近代中国革命的根本任务，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-33","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":33,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 33 题"},"stem":"1948年1月，毛泽东在《关于目前党的政策中的几个重要问题》中指出：“新民主主义的政权是工人阶级领导的人民大众的反帝反封建的政权。”这较为明确地指出了新民主主义革命的对象具体包括","choices":[{"id":"A","text":"帝国主义"},{"id":"B","text":"封建主义"},{"id":"C","text":"民族资产阶级"},{"id":"D","text":"官僚资本主义"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是新民主主义革命的对象，是本题正确答案。","B":"是新民主主义革命的对象，是本题正确答案。","C":"民族资产阶级是社会主义革命的对象。","D":"是新民主主义革命的对象，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-34","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":34,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 34 题"},"stem":"无产阶级的领导权问题是","choices":[{"id":"A","text":"新民主主义革命理论的核心问题"},{"id":"B","text":"中国资产阶级民主革命的中心问题"},{"id":"C","text":"中国革命的基本问题"},{"id":"D","text":"中国革命的中心问题"}],"answer":["A","D"],"analysis":{"point":"","options":{"A":"是无产阶级的领导权问题，是本题正确答案。","B":"中国资产阶级民主革命的中心问题——是土地革命。","C":"中国革命的基本问题是农民问题。","D":"是无产阶级的领导权问题，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-35","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":35,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 35 题"},"stem":"中国无产阶级除具有一般无产阶级的基本优点外，还具有自身的特点和优点，包括","choices":[{"id":"A","text":"深受三重压迫，在革命斗争中比任何别的阶级都来得坚决和彻底"},{"id":"B","text":"分布集中，有利于革命思想的传播和强大革命力量的形成"},{"id":"C","text":"和农民有着天然的联系，便于和农民结成亲密的联盟，共同团结战斗"},{"id":"D","text":"与先进的生产方式相联系、没有私人占有的生产资料"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是中国无产阶级自身的特点和优点，是本题正确答案。","B":"是中国无产阶级自身的特点和优点，是本题正确答案。","C":"是中国无产阶级自身的特点和优点，是本题正确答案。","D":"与先进的生产方式相联系、没有私人占有的生产资料——是一般无产阶级的基本优点，不是中国无产阶级所特有的。"}}},{"id":"basic-maozhongte-ch02-36","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":36,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 36 题"},"stem":"1925年，毛泽东在《中国社会各阶级的分析》中指出，谁是我们的敌人？谁是我们的朋友？这个问题是革命的首要问题。因此，党在不同时期的革命的主要对象有","choices":[{"id":"A","text":"在国共合作的大革命时期，革命的主要对象是帝国主义支持下的国民党新军阀"},{"id":"B","text":"在土地革命战争时期，革命的主要对象是北洋军阀"},{"id":"C","text":"在抗日战争时期，革命的主要对象是日本帝国主义"},{"id":"D","text":"在解放战争时期，革命的主要对象是美帝国主义支持下的国民党反动派"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"是错误说法，大革命时期，革命的主要对象是帝国主义支持下的北洋军阀。","B":"是错误说法，土地革命战争时期，革命的主要对象是国民党新军阀。","C":"是正确说法，是本题正确答案。","D":"是正确说法，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-37","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":37,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 37 题"},"stem":"新民主主义革命与旧民主主义革命相比有新的内容和特点，集中表现在","choices":[{"id":"A","text":"处于世界无产阶级社会主义革命的时代，是世界无产阶级社会主义革命的一部分"},{"id":"B","text":"革命的领导力量是中国无产阶级及其先锋队——中国共产党"},{"id":"C","text":"革命的指导思想是马克思列宁主义"},{"id":"D","text":"革命的前途是社会主义而不是资本主义"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是新民主主义革命相比于旧民主主义革命的新的内容和特点，是本题正确答案。","B":"是新民主主义革命相比于旧民主主义革命的新的内容和特点，是本题正确答案。","C":"是新民主主义革命相比于旧民主主义革命的新的内容和特点，是本题正确答案。","D":"是新民主主义革命相比于旧民主主义革命的新的内容和特点，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-38","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":38,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 38 题"},"stem":"新民主主义革命与社会主义革命性质不同。新民主主义革命仍然属于资产阶级民主主义革命的范畴，是因为它","choices":[{"id":"A","text":"容许有利于国计民生的私人资本主义发展"},{"id":"B","text":"在经济上保护民族工商业"},{"id":"C","text":"要建立的是无产阶级专政"},{"id":"D","text":"为了推翻帝国主义、封建主义和官僚资本主义的反动统治"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是新民主主义革命仍然属于资产阶级民主主义革命的范畴的原因，是本题正确答案。","B":"是新民主主义革命仍然属于资产阶级民主主义革命的范畴的原因，是本题正确答案。","C":"要建立的是无产阶级专政——是社会主义革命的目的。","D":"是新民主主义革命仍然属于资产阶级民主主义革命的范畴的原因，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-39","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":39,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 39 题"},"stem":"新民主主义文化，就是无产阶级领导的人民大众的反帝反封建的文化，即民族的科学的大众的文化。其中，“科学的”文化的内涵包括","choices":[{"id":"A","text":"要尊重中国的历史，反对民族虚无主义"},{"id":"B","text":"反对一切封建思想和迷信思想，主张实事求是、客观真理及理论和实践的一致性"},{"id":"C","text":"剔除封建性的糟粕，吸收民主性的精华"},{"id":"D","text":"要以人民群众的实践作为创作的源泉，坚持为人民大众服务的方向"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是“科学的”文化的内涵，是本题正确答案。","B":"是“科学的”文化的内涵，是本题正确答案。","C":"是“科学的”文化的内涵，是本题正确答案。","D":"是“大众的”文化的内涵。"}}},{"id":"basic-maozhongte-ch02-40","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":40,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 40 题"},"stem":"中国革命必须走农村包围城市、武装夺取政权的道路，其决定因素包括","choices":[{"id":"A","text":"具体国情"},{"id":"B","text":"中国所处的时代特点"},{"id":"C","text":"共产国际的指示"},{"id":"D","text":"国际环境"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是中国革命必须走农村包围城市、武装夺取政权的道路的决定因素，是本题正确答案。","B":"是中国革命必须走农村包围城市、武装夺取政权的道路的决定因素，是本题正确答案。","C":"非考点。","D":"非考点。"}}},{"id":"basic-maozhongte-ch02-41","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":41,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 41 题"},"stem":"党的六届六中全会确立了经过长期武装斗争，先占乡村，后取城市，最后夺取全国胜利的革命道路。新民主主义革命道路形成的必然性包括","choices":[{"id":"A","text":"社会政治经济发展极端不平衡，四分五裂，军阀割据，存在不少的统治薄弱环节"},{"id":"B","text":"在半殖民地半封建的中国社会，内无民主制度，外无民族独立"},{"id":"C","text":"近代中国农民占全国人口的绝大多数，是无产阶级可靠的同盟军和革命的主力军"},{"id":"D","text":"党的领导的有力量及其政策的不错误"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"是新民主主义革命道路形成的可能性，而非必然性。","B":"是新民主主义革命道路形成的必然性，是本题正确答案。","C":"是新民主主义革命道路形成的必然性，是本题正确答案。","D":"是新民主主义革命道路形成的可能性，而非必然性。"}}},{"id":"basic-maozhongte-ch02-42","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":42,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 42 题"},"stem":"毛泽东在总结井冈山革命斗争的经验时，提出了“工农武装割据”的基本思想，指出中国革命走农村包围城市、武装夺取政权的道路，根本在于处理好三者的关系，这三者包括","choices":[{"id":"A","text":"农村革命根据地建设"},{"id":"B","text":"党的建设"},{"id":"C","text":"土地革命"},{"id":"D","text":"武装斗争"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是工农武装割据的三个组成部分，是本题正确答案。","B":"党的建设是新民主主义革命的三大法宝之一。","C":"是工农武装割据的三个组成部分，是本题正确答案。","D":"是工农武装割据的三个组成部分，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-43","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":43,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 43 题"},"stem":"党成立以来，多次与不同阶级包括资产阶级，建立了统一战线。中国革命必须建立最广泛的统一战线，是因为","choices":[{"id":"A","text":"半殖民地半封建的中国社会，诸多矛盾交织在一起"},{"id":"B","text":"中国半殖民地半封建社会的阶级状况是“两头小中间大”"},{"id":"C","text":"中国革命的长期性、残酷性及发展的不平衡性"},{"id":"D","text":"全国革命形势的继续向前发展，为在农村建设革命根据地提供了客观条件"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"是建立统一战线的可能性。","B":"是建立统一战线的必要性，是本题正确答案。","C":"是建立统一战线的必要性，是本题正确答案。","D":"是中国走农村包围城市革命道路的可能性。"}}},{"id":"basic-maozhongte-ch02-44","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":44,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 44 题"},"stem":"毛泽东同志指出：“中国新民主主义的革命要胜利，没有一个包括全民族绝大多数人口的最广泛的统一战线，是不可能的。”统一战线中的两个联盟是","choices":[{"id":"A","text":"工人阶级和非劳动人民的联盟"},{"id":"B","text":"工人阶级同农民阶级、广大知识分子及其他劳动者的联盟"},{"id":"C","text":"工人阶级同农民阶级的联盟"},{"id":"D","text":"工人阶级同广大知识分子及其他劳动者的联盟"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是统一战线中的两个联盟，是本题正确答案。","B":"是统一战线中的两个联盟，是本题正确答案。","C":"是第一个联盟中的联盟。","D":"是第一个联盟中的联盟。"}}},{"id":"basic-maozhongte-ch02-45","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":45,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 45 题"},"stem":"党建立、巩固和发展统一战线的实践经验主要有","choices":[{"id":"A","text":"坚持独立自主的原则"},{"id":"B","text":"正确对待资产阶级，尤其是民族资产阶级"},{"id":"C","text":"无差别对待各阶级、各派别"},{"id":"D","text":"建立巩固的工农联盟"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是党建立、巩固和发展统一战线的实践经验，是本题正确答案。","B":"是党建立、巩固和发展统一战线的实践经验，是本题正确答案。","C":"无差别对待各阶级、各派别——是错误说法，对待不同势力，要采取区别对待的方针。","D":"是党建立、巩固和发展统一战线的实践经验，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-46","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":46,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 46 题"},"stem":"1945年，毛泽东在《论联合政府》中这样总结：“我们的党从它一开始，就是一个以马克思列宁主义的理论为基础的党，这是因为这个主义是全世界无产阶级的最正确最革命的科学思想的结晶。”以马克思列宁主义的理论思想武装起来的中国共产党具备三大优良作风，这就是","choices":[{"id":"A","text":"自力更生、艰苦奋斗的作风"},{"id":"B","text":"理论联系实际的作风"},{"id":"C","text":"密切联系群众的作风"},{"id":"D","text":"批评与自我批评相结合的作风"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"自力更生、艰苦奋斗的作风——是党应该坚持的作风，但不属于党的三大优良作风。","B":"是党的三大优良作风，是本题正确答案。","C":"是党的三大优良作风，是本题正确答案。","D":"是党的三大优良作风，是本题正确答案。"}}},{"id":"basic-maozhongte-ch02-47","moduleId":"basic","subjectId":"maozhongte","chapter":"第二章 新民主主义革命理论","chapterKey":"第二章","n":47,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第二章 第 47 题"},"stem":"毛泽东系统地论述了统一战线、武装斗争和党的建设三者之间的关系，指出战胜敌人的两个基本武器是","choices":[{"id":"A","text":"武装斗争"},{"id":"B","text":"思想路线"},{"id":"C","text":"统一战线"},{"id":"D","text":"党的建设"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是中国革命的两个基本特点，是战胜敌人的两个基本武器，是本题正确答案。","B":"思想路线——是“一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理”。这不属于新民主主义革命的三大法宝的内容，所以并不是题干要求的“战胜敌人的两个基本武器”。","C":"是中国革命的两个基本特点，是战胜敌人的两个基本武器，是本题正确答案。","D":"党的建设——是新民主主义革命的三大法宝之一，党的组织是掌握统一战线和武装斗争这两个武器以实行对敌冲锋陷阵的英勇战士。"}}},{"id":"basic-maozhongte-ch03-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 1 题"},"stem":"从中华人民共和国成立到社会主义改造基本完成，这一时期，我国社会的性质是","choices":[{"id":"A","text":"封建社会"},{"id":"B","text":"新民主主义社会"},{"id":"C","text":"资本主义社会"},{"id":"D","text":"社会主义社会"}],"answer":["B"],"analysis":{"point":"","options":{"A":"封建社会——是从战国时期到鸦片战争的中国历史阶段。","B":"新民主主义社会——是从中华人民共和国成立到社会主义改造基本完成的过渡时期，是本题正确答案。","C":"资本主义社会——是西方国家的主要社会形态。","D":"社会主义社会——是从社会主义改造完成开始的。"}}},{"id":"basic-maozhongte-ch03-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 2 题"},"stem":"从中华人民共和国成立到社会主义改造基本完成，这一时期，我国社会的性质是新民主主义社会，它是我国","choices":[{"id":"A","text":"从封建主义到资本主义的过渡时期"},{"id":"B","text":"从新民主主义到社会主义的过渡时期"},{"id":"C","text":"从封建社会到新民主主义社会的过渡时期"},{"id":"D","text":"从资本主义到社会主义的过渡时期"}],"answer":["B"],"analysis":{"point":"","options":{"A":"非考点。","B":"从新民主主义到社会主义的过渡时期——是指从中华人民共和国成立到社会主义改造基本完成这一时期，这时我国社会的性质是新民主主义社会，是本题正确答案。","C":"非考点。","D":"非考点。"}}},{"id":"basic-maozhongte-ch03-3","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 3 题"},"stem":"以下标志着我国剥削制度被消灭的历史事件是","choices":[{"id":"A","text":"土地改革的基本完成"},{"id":"B","text":"中华人民共和国的成立"},{"id":"C","text":"社会主义改造的基本完成"},{"id":"D","text":"中国大陆的解放和统一"}],"answer":["C"],"analysis":{"point":"","options":{"A":"土地改革的基本完成——标志着消灭了封建地主土地所有制，消灭了地主阶级对农民的剥削。","B":"中华人民共和国的成立——标志着民族独立和人民解放的基本实现。","C":"社会主义改造的基本完成——标志着我国剥削制度被消灭，是本题正确答案。","D":"中国大陆的解放和统一——是中华人民共和国成立的成果之一。"}}},{"id":"basic-maozhongte-ch03-4","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 4 题"},"stem":"从中华人民共和国成立到社会主义改造基本完成，是我国从新民主主义到社会主义的过渡时期。这一时期，个体经济向社会主义集体经济过渡的形式是","choices":[{"id":"A","text":"国营经济"},{"id":"B","text":"私人资本主义经济"},{"id":"C","text":"合作社经济"},{"id":"D","text":"国家资本主义经济"}],"answer":["C"],"analysis":{"point":"","options":{"A":"国营经济——是通过没收官僚资本而形成的社会主义性质的经济成分，掌握着国民经济的命脉，处于领导地位。","B":"私人资本主义经济——是非过渡的形式。","C":"合作社经济——是个体经济向社会主义集体经济过渡的形式，是本题正确答案。","D":"国家资本主义经济——是私人资本主义经济向社会主义国营经济过渡的形式。"}}},{"id":"basic-maozhongte-ch03-5","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 5 题"},"stem":"1955年10月29日，毛泽东邀集全国工商业联合会执行委员会的委员，座谈私营工商业的社会主义改造问题，希望他们认清社会发展规律，掌握自己的命运，进一步接受社会主义改造。资本主义工商业的社会主义改造采取的过渡形式是","choices":[{"id":"A","text":"互助合作社"},{"id":"B","text":"国家资本主义"},{"id":"C","text":"和平赎买"},{"id":"D","text":"委托加工、计划订货"}],"answer":["B"],"analysis":{"point":"","options":{"A":"互助合作社——是在农业的社会主义改造中采取的过渡形式。","B":"国家资本主义——是在资本主义工商业的社会主义改造中采取的过渡形式，是本题正确答案。","C":"和平赎买——是改造资本主义工商业的方法，不是过渡形式。","D":"委托加工、计划订货——是初级形式的国家资本主义。"}}},{"id":"basic-maozhongte-ch03-6","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 6 题"},"stem":"以毛泽东同志为主要代表的中国共产党人根据马克思列宁主义关于农业社会主义改造的基本原理，从我国农村实际出发，开辟了一条适合我国情况的农业社会主义改造道路。对农业进行社会主义改造所遵循的原则是","choices":[{"id":"A","text":"互助合作化道路"},{"id":"B","text":"积极领导、稳步前进"},{"id":"C","text":"自愿互利、典型示范和国家帮助"},{"id":"D","text":"循序渐进"}],"answer":["C"],"analysis":{"point":"","options":{"A":"互助合作化道路——是“道路”，而非“原则”。","B":"积极领导、稳步前进——是“方针”。","C":"自愿互利、典型示范和国家帮助——是对农业进行社会主义改造所遵循的原则，是本题正确答案。","D":"循序渐进是“步骤”。"}}},{"id":"basic-maozhongte-ch03-7","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 7 题"},"stem":"在农业社会主义改造中，第三阶段是发展高级农业生产合作社，它的性质是","choices":[{"id":"A","text":"半社会主义性质"},{"id":"B","text":"初步社会主义性质"},{"id":"C","text":"完全的社会主义性质"},{"id":"D","text":"社会主义萌芽性质"}],"answer":["C"],"analysis":{"point":"","options":{"A":"半社会主义性质——是初级农业生产合作社，即初级社的性质。","B":"初步社会主义性质非考点。","C":"完全的社会主义性质——是高级农业生产合作社，即高级社的性质，是本题正确答案。","D":"社会主义萌芽性质——是互助组的性质。"}}},{"id":"basic-maozhongte-ch03-8","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 8 题"},"stem":"为了保证资本主义工商业社会主义改造的顺利进行，中共中央和国务院制定和实行了一系列正确的方针和政策，有步骤地开展改造活动。其中，高级形式的国家资本主义是","choices":[{"id":"A","text":"委托加工"},{"id":"B","text":"计划订货"},{"id":"C","text":"统购包销"},{"id":"D","text":"公私合营"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是初级形式的国家资本主义。","B":"是初级形式的国家资本主义。","C":"是初级形式的国家资本主义。","D":"公私合营——是高级形式的国家资本主义，包括个别企业的公私合营和全行业的公私合营，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-9","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 9 题"},"stem":"新民主主义社会不是一个独立的社会形态，在这个过渡性的社会形态之下，存在着多种经济成分，包括","choices":[{"id":"A","text":"集体经济"},{"id":"B","text":"农民和手工业者的个体经济"},{"id":"C","text":"半社会主义性质的合作社经济"},{"id":"D","text":"国家资本主义经济"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"集体经济——是在1953年的农业合作化运动中逐渐出现的，1956年年底，随着对农业的社会主义改造的完成，农村集体经济才正式形成。","B":"是新民主主义社会的经济成分，此外还有社会主义性质的国营经济和私人资本主义经济，是本题正确答案。","C":"是新民主主义社会的经济成分，此外还有社会主义性质的国营经济和私人资本主义经济，是本题正确答案。","D":"是新民主主义社会的经济成分，此外还有社会主义性质的国营经济和私人资本主义经济，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-10","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 10 题"},"stem":"在新民主主义社会的经济成分中，主要的是三种，包括","choices":[{"id":"A","text":"个体经济"},{"id":"B","text":"半社会主义经济"},{"id":"C","text":"社会主义经济"},{"id":"D","text":"资本主义经济"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是新民主主义社会主要的经济成分，是本题正确答案。","B":"半社会主义经济——是过渡形式的经济，并不是主要的经济成分。","C":"是新民主主义社会主要的经济成分，是本题正确答案。","D":"是新民主主义社会主要的经济成分，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-11","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 11 题"},"stem":"新民主主义时期三种基本的经济成分及与之相联系的三种基本的阶级力量之间的矛盾，集中表现为","choices":[{"id":"A","text":"社会主义和资本主义两条道路的矛盾"},{"id":"B","text":"封建主义和人民大众的矛盾"},{"id":"C","text":"工人阶级和资产阶级两个阶级的矛盾"},{"id":"D","text":"社会主义和帝国主义两大阵营的矛盾"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是新民主主义时期三种基本的经济成分及与之相联系的三种基本的阶级力量之间矛盾的集中表现，是本题正确答案。","B":"封建主义和人民大众的矛盾——是近代中国社会的主要矛盾。","C":"是新民主主义时期三种基本的经济成分及与之相联系的三种基本的阶级力量之间矛盾的集中表现，是本题正确答案。","D":"社会主义和帝国主义两大阵营的矛盾——是新中国面临的矛盾，与三种基本的经济成分及与之相联系的三种基本的阶级力量无关。"}}},{"id":"basic-maozhongte-ch03-12","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 12 题"},"stem":"“两重性，任何事物都有，而且永远都有，当然总是以不同的具体的形式表现出来，性质也各不相同。”中华人民共和国成立后，民族资产阶级的两重性表现为","choices":[{"id":"A","text":"革命性和动摇性"},{"id":"B","text":"软弱性和妥协性"},{"id":"C","text":"剥削工人取得利润"},{"id":"D","text":"愿意为中华人民共和国的建设服务，有接受社会主义改造的可能"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"是民主革命时期民族资产阶级两面性的表现。","B":"是民主革命时期民族资产阶级两面性的表现。","C":"是中华人民共和国成立后，社会主义改造时期民族资产阶级两重性的表现，是本题正确答案。","D":"是中华人民共和国成立后，社会主义改造时期民族资产阶级两重性的表现，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-13","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 13 题"},"stem":"对资本主义工商业的社会主义改造采取了和平赎买的方法。所谓“和平赎买”就是","choices":[{"id":"A","text":"将资本主义私有制改变为社会主义公有制"},{"id":"B","text":"由国家支付一笔巨额补偿资金"},{"id":"C","text":"国家有偿地将私营企业改变为国营企业"},{"id":"D","text":"国家无偿地没收官僚资本企业"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是和平赎买的含义，是本题正确答案。","B":"是错误说法，赎买的具体方式不是由国家支付一笔巨额补偿资金，而是让资本家在一定年限内从企业经营所得中获取一部分利润。","C":"是和平赎买的含义，是本题正确答案。","D":"针对的是官僚资本，与资本主义工商业无关。"}}},{"id":"basic-maozhongte-ch03-14","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 14 题"},"stem":"中国共产党根据马克思、恩格斯和列宁关于采用和平方式变革所有制的设想，结合中国的具体情况，提出了对资本主义工商业实行和平赎买的方针。对资本主义工商业实行和平赎买，有利于","choices":[{"id":"A","text":"发挥民族资产阶级中大多数人的知识、才能、技术专长和管理经验"},{"id":"B","text":"团结各民主党派和各界爱国民主人士，巩固和发展统一战线"},{"id":"C","text":"发挥私营工商业在国计民生方面的积极作用"},{"id":"D","text":"争取和团结那些原来同资产阶级相联系的知识分子为社会主义建设服务"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是对资本主义工商业实行和平赎买的意义，是本题正确答案。","B":"是对资本主义工商业实行和平赎买的意义，是本题正确答案。","C":"是对资本主义工商业实行和平赎买的意义，是本题正确答案。","D":"是对资本主义工商业实行和平赎买的意义，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-15","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 15 题"},"stem":"对资本主义工商业进行和平改造的可能性包括","choices":[{"id":"A","text":"民族资产阶级具有两面性"},{"id":"B","text":"中国共产党与民族资产阶级长期保持着统一战线的关系"},{"id":"C","text":"我国已经有了以工人阶级为领导、工农联盟为基础的人民民主专政的国家政权"},{"id":"D","text":"我国建立了强大的社会主义国营经济并掌握了国家的经济命脉"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是对资本主义工商业进行和平改造的可能性，是本题正确答案。","B":"是对资本主义工商业进行和平改造的可能性，是本题正确答案。","C":"是对资本主义工商业进行和平改造的可能性，是本题正确答案。","D":"是对资本主义工商业进行和平改造的可能性，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-16","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 16 题"},"stem":"初级形式的国家资本主义是国家对私营工商业实行","choices":[{"id":"A","text":"计划订货"},{"id":"B","text":"委托加工"},{"id":"C","text":"统购统销"},{"id":"D","text":"经销代销"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是初级形式的国家资本主义，是本题正确答案。","B":"是初级形式的国家资本主义，是本题正确答案。","C":"统购统销是当时国家对粮食和工业原料实行的政策。","D":"是初级形式的国家资本主义，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-17","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 17 题"},"stem":"在对资本主义工商业进行社会主义改造的过程中，企业利润分配采用“四马分肥”的阶段包括","choices":[{"id":"A","text":"全行业的公私合营阶段"},{"id":"B","text":"初级生产合作社"},{"id":"C","text":"个别企业的公私合营阶段"},{"id":"D","text":"加工订货、统购包销阶段"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"全行业的公私合营阶段——是企业利润实行“定股定息”的阶段。","B":"初级生产合作社——是农业社会主义改造经历的阶段。","C":"是企业利润分配采用“四马分肥”的阶段，是本题正确答案。","D":"是企业利润分配采用“四马分肥”的阶段，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-18","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 18 题"},"stem":"新中国成立初期，在土地改革完成后，我国广大农民的生产积极性大大提高。这种积极性集中表现在","choices":[{"id":"A","text":"土地承包的积极性上"},{"id":"B","text":"互助合作的积极性上"},{"id":"C","text":"集体经济的积极性上"},{"id":"D","text":"个体经济的积极性上"}],"answer":["B","D"],"analysis":{"point":"","options":{"A":"非考点。","B":"是土地改革完成后，我国广大农民生产积极性的表现，是本题正确答案。","C":"非考点。","D":"是土地改革完成后，我国广大农民生产积极性的表现，是本题正确答案。"}}},{"id":"basic-maozhongte-ch03-19","moduleId":"basic","subjectId":"maozhongte","chapter":"第三章 社会主义改造理论","chapterKey":"第三章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第三章 第 19 题"},"stem":"1956年年底，我国对农业、手工业和资本主义工商业的社会主义改造基本完成，这","choices":[{"id":"A","text":"标志着中国历史上长达数千年的封建专制政治的结束"},{"id":"B","text":"实现了中国由新民主主义向社会主义的转变"},{"id":"C","text":"标志着社会主义基本制度在我国初步确立"},{"id":"D","text":"标志着我国进入社会主义初级阶段"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"是新中国成立的伟大意义。","B":"是社会主义改造完成的历史意义，是本题正确答案。","C":"是社会主义改造完成的历史意义，是本题正确答案。","D":"是社会主义改造完成的历史意义，是本题正确答案。"}}},{"id":"basic-maozhongte-ch04-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 1 题"},"stem":"党探索中国社会主义建设道路的良好开端的标志是","choices":[{"id":"A","text":"毛泽东作《论十大关系》的报告"},{"id":"B","text":"毛泽东作《关于正确处理人民内部矛盾的问题》的报告"},{"id":"C","text":"中共八大的召开"},{"id":"D","text":"毛泽东提出“第二次结合”的任务"}],"answer":["A"],"analysis":{"point":"","options":{"A":"毛泽东作《论十大关系》的报告——标志着党探索中国社会主义建设道路的良好开端，是本题正确答案。","B":"毛泽东作《关于正确处理人民内部矛盾的问题》的报告——系统论述了社会主义社会矛盾的理论。","C":"中共八大的召开——是一次对社会主义建设道路的成功探索。","D":"（原书未单独给出此项解析）"}}},{"id":"basic-maozhongte-ch04-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 2 题"},"stem":"社会主义基本制度确立后，如何在中国这样一个经济文化比较落后的东方大国建设和巩固社会主义，是党面临的全新课题。毛泽东在《论十大关系》中，从十个方面论述了我国社会主义建设需要重点把握的重大关系。“十大关系”所围绕的基本方针是","choices":[{"id":"A","text":"正确处理人民内部矛盾"},{"id":"B","text":"调动一切积极因素为社会主义事业服务"},{"id":"C","text":"既反保守又反冒进、在综合平衡中稳步前进"},{"id":"D","text":"集中力量向科学进军"}],"answer":["B"],"analysis":{"point":"","options":{"A":"正确处理人民内部矛盾——是《关于正确处理人民内部矛盾的问题》的内容。","B":"调动一切积极因素为社会主义事业服务——是“十大关系”所围绕的基本方针，是本题正确答案。","C":"既反保守又反冒进、在综合平衡中稳步前进——是中共八大提出的经济建设方针。","D":"集中力量向科学进军——是1956年党中央发出的号召。"}}},{"id":"basic-maozhongte-ch04-3","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 3 题"},"stem":"毛泽东认为，社会主义社会存在两类性质完全不同的矛盾，两类不同性质的矛盾的存在是客观的。其中，社会主义国家政治生活的主题是正确处理","choices":[{"id":"A","text":"生产力和生产关系之间的矛盾"},{"id":"B","text":"工人阶级同民族资产阶级的矛盾"},{"id":"C","text":"敌我矛盾"},{"id":"D","text":"人民内部矛盾"}],"answer":["D"],"analysis":{"point":"","options":{"A":"生产力和生产关系之间的矛盾——是社会主义社会的基本矛盾。","B":"工人阶级同民族资产阶级的矛盾——是人民内部矛盾，是社会主义改造时期我国社会的主要矛盾。","C":"敌我矛盾——是人民同反抗社会主义革命、敌视和破坏社会主义建设的社会势力和社会集团的矛盾。","D":"人民内部矛盾——是居于主导地位的矛盾，所以正确处理人民内部矛盾是社会主义国家政治生活的主题，是本题正确答案。"}}},{"id":"basic-maozhongte-ch04-4","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 4 题"},"stem":"社会主义改造完成后，毛泽东强调要走一条有别于苏联的中国工业化道路的文章是","choices":[{"id":"A","text":"《一九五七年夏季的形势》"},{"id":"B","text":"《关于正确处理人民内部矛盾的问题》"},{"id":"C","text":"《论十大关系》"},{"id":"D","text":"《论人民民主专政》"}],"answer":["B"],"analysis":{"point":"","options":{"A":"《一九五七年夏季的形势》——提出要造成一个“六又”政治局面。","B":"《关于正确处理人民内部矛盾的问题》——明确提出了中国工业化道路的问题，主要是指重工业和轻工业、农业的发展关系问题，强调要走一条有别于苏联的中国工业化道路，是本题正确答案。","C":"《论十大关系》——明确提出要以苏为鉴，独立自主地探索适合中国情况的社会主义建设道路。","D":"《论人民民主专政》是新中国成立之前的文章。"}}},{"id":"basic-maozhongte-ch04-5","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 5 题"},"stem":"毛泽东指出，矛盾是普遍存在的，社会主义社会同样充满着矛盾，正是这些矛盾推动着社会主义社会不断地向前发展。在社会主义社会中，基本的矛盾仍然是","choices":[{"id":"A","text":"人民内部矛盾"},{"id":"B","text":"上层建筑和经济基础之间的矛盾"},{"id":"C","text":"生产关系和生产力之间的矛盾"},{"id":"D","text":"敌我矛盾"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"是社会主义社会的两类不同性质的矛盾。","B":"是社会主义社会中基本的矛盾，是本题正确答案。","C":"是社会主义社会中基本的矛盾，是本题正确答案。","D":"是社会主义社会的两类不同性质的矛盾。"}}},{"id":"basic-maozhongte-ch04-6","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 6 题"},"stem":"人民内部矛盾，包括工人阶级内部的矛盾，农民阶级内部的矛盾，知识分子内部的矛盾，工农两个阶级之间的矛盾，工人、农民同知识分子之间的矛盾，工人阶级和其他劳动人民同民族资产阶级的矛盾，也包括政府和人民群众之间的矛盾，民主同集中的矛盾，领导同被领导之间的矛盾，国家机关某些工作人员的官僚主义作风同群众之间的矛盾，等等。所以，人民内部矛盾是","choices":[{"id":"A","text":"对抗性的矛盾"},{"id":"B","text":"非对抗性的矛盾"},{"id":"C","text":"人民根本利益一致基础上的矛盾"},{"id":"D","text":"根本利益对立基础上的矛盾"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"是关于敌我矛盾的说法。","B":"是人民内部矛盾的性质，是本题正确答案。","C":"是人民内部矛盾的性质，是本题正确答案。","D":"是关于敌我矛盾的说法。"}}},{"id":"basic-maozhongte-ch04-7","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 7 题"},"stem":"毛泽东指出：“敌我之间和人民内部这两类矛盾的性质不同，解决的方法也不同。”解决敌我矛盾","choices":[{"id":"A","text":"是分清是非的问题"},{"id":"B","text":"应采用专政的方法"},{"id":"C","text":"应采用讨论的方法、批评的方法、说服教育的方法"},{"id":"D","text":"要在劳动中尽量使敌对分子改造成新人"}],"answer":["B","D"],"analysis":{"point":"","options":{"A":"是针对解决人民内部矛盾的。","B":"应采用专政的方法——是解决敌我矛盾的方法，是本题正确答案之一。","C":"应采用讨论的方法、批评的方法、说服教育的方法——是民主的方法，是解决人民内部矛盾的方法。","D":"要在劳动中尽量使敌对分子改造成新人——是专政的方法，是解决敌我矛盾的方法，是本题正确答案之一。"}}},{"id":"basic-maozhongte-ch04-8","moduleId":"basic","subjectId":"maozhongte","chapter":"第四章 社会主义建设道路初步探索的理论成果","chapterKey":"第四章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第四章 第 8 题"},"stem":"1957年，毛泽东运用对立统一规律，以正确处理人民内部矛盾为总题目，总结了我国社会主义革命和建设的经验，全面分析了社会主义社会的矛盾，提出了正确区分和解决两类不同性质的矛盾的方法，规定了正确处理人民内部矛盾的一系列正确方针。其中，对于政治思想领域的人民内部矛盾，具体的方针政策包括","choices":[{"id":"A","text":"实行“百花齐放、百家争鸣”的方针"},{"id":"B","text":"实行“统筹兼顾、适当安排”的方针"},{"id":"C","text":"坚持说服教育、讨论的方法"},{"id":"D","text":"实行“团结一批评一团结”的方针"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"实行“百花齐放、百家争鸣”的方针——是对于科学文化领域的人民内部矛盾所采取的方针政策。","B":"实行“统筹兼顾、适当安排”的方针——是对于物质利益、分配方面的人民内部矛盾所采取的方针政策。","C":"是对于政治思想领域的人民内部矛盾所采取的方针政策，是本题正确答案。","D":"是对于政治思想领域的人民内部矛盾所采取的方针政策，是本题正确答案。"}}},{"id":"basic-maozhongte-ch05-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第五章 中国特色社会主义理论体系的形成发展","chapterKey":"第五章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第五章 第 1 题"},"stem":"党的十一届三中全会以后，以邓小平同志为主要代表的中国共产党人，果断地纠正错误，又坚决地维护和继承了过去在理论上和实践上所取得的一切积极成果，同时结合中国实际，在实践中不懈探索。正是在探索和回答这一首要的基本的理论问题的过程中，我们党开创了中国特色社会主义的伟大事业。这里的“首要的基本的理论问题”是指","choices":[{"id":"A","text":"实现什么样的发展、怎样发展"},{"id":"B","text":"什么是社会主义、怎样建设社会主义"},{"id":"C","text":"建设什么样的党、怎样建设党"},{"id":"D","text":"建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党"}],"answer":["B"],"analysis":{"point":"","options":{"A":"实现什么样的发展、怎样发展是科学发展观回答的问题。","B":"什么是社会主义、怎样建设社会主义——是邓小平理论首要的基本的理论问题，在探索和回答这一问题的过程中，我们党开创了中国特色社会主义的伟大事业，是本题正确答案。","C":"建设什么样的党、怎样建设党——是“三个代表”重要思想回答的问题。","D":"建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党——是习近平新时代中国特色社会主义思想回答的问题。"}}},{"id":"basic-maozhongte-ch05-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第五章 中国特色社会主义理论体系的形成发展","chapterKey":"第五章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第五章 第 2 题"},"stem":"邓小平同志在领导改革开放和社会主义现代化建设的过程中，提出了许多具有开创意义的重大思想，创立了邓小平理论。邓小平理论是中国特色社会主义理论体系的奠基之作。邓小平理论轮廓的形成是在","choices":[{"id":"A","text":"党的十三大"},{"id":"B","text":"党的十一届三中全会"},{"id":"C","text":"党的十二大"},{"id":"D","text":"南方谈话"}],"answer":["A"],"analysis":{"point":"","options":{"A":"党的十三大——第一次对中国特色社会主义理论进行系统的概括，也标志着邓小平理论轮廓的形成，是本题正确答案。","B":"党的十一届三中全会——是重新确立解放思想、实事求是思想路线的会议，是确定把全党工作的着重点转移到社会主义现代化建设上来、作出实行改革开放的重大决策的会议。","C":"党的十二大——是将“中国特色社会主义”确定为我们党的全部理论和实践创新的主题的会议。","D":"南方谈话是邓小平理论走向成熟的标志。"}}},{"id":"basic-maozhongte-ch05-3","moduleId":"basic","subjectId":"maozhongte","chapter":"第五章 中国特色社会主义理论体系的形成发展","chapterKey":"第五章","n":3,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第五章 第 3 题"},"stem":"实践是理论创新的源泉。实践发展永无止境，我们认识真理、进行理论创新就永无止境。中国特色社会主义理论体系不是从天上掉下来的。中国特色社会主义理论体系形成发展的实践基础是","choices":[{"id":"A","text":"改革开放的伟大实践"},{"id":"B","text":"社会主义改造的成功实践"},{"id":"C","text":"社会主义现代化建设的生动实践"},{"id":"D","text":"社会主义建设初步探索的实践"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是中国特色社会主义理论体系形成发展的实践基础，是本题正确答案。","B":"属于毛泽东思想的实践基础。","C":"是中国特色社会主义理论体系形成发展的实践基础，是本题正确答案。","D":"属于毛泽东思想的实践基础。"}}},{"id":"basic-maozhongte-ch05-4","moduleId":"basic","subjectId":"maozhongte","chapter":"第五章 中国特色社会主义理论体系的形成发展","chapterKey":"第五章","n":4,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第五章 第 4 题"},"stem":"习近平新时代中国特色社会主义思想回答的重大时代课题包括","choices":[{"id":"A","text":"新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义"},{"id":"B","text":"建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国"},{"id":"C","text":"建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党"},{"id":"D","text":"什么是马克思主义中国化，怎样实现马克思主义中国化"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是习近平新时代中国特色社会主义思想回答的重大时代课题，是本题正确答案。","B":"是习近平新时代中国特色社会主义思想回答的重大时代课题，是本题正确答案。","C":"是习近平新时代中国特色社会主义思想回答的重大时代课题，是本题正确答案。","D":"是党成立百年来不断探索和回答的问题。"}}},{"id":"basic-maozhongte-ch06-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 1 题"},"stem":"在我国，社会主义本质论就是围绕在一个经济文化比较落后的国家如何建设社会主义、如何巩固和发展社会主义这一系列基本问题的理论构建。社会主义的本质是","choices":[{"id":"A","text":"坚持公有制的主体地位"},{"id":"B","text":"坚持计划经济和市场调节相结合"},{"id":"C","text":"我国正处于并将长期处于社会主义初级阶段"},{"id":"D","text":"解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕"}],"answer":["D"],"analysis":{"point":"","options":{"A":"坚持公有制的主体地位——是社会主义市场经济的一个基本特征，而非社会主义的本质。","B":"坚持计划经济和市场调节相结合——是我国社会主义经济体制改革的阶段性模式。","C":"我国正处于并将长期处于社会主义初级阶段——是我国的基本国情。","D":"解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕——是社会主义的本质，是本题正确答案。"}}},{"id":"basic-maozhongte-ch06-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 2 题"},"stem":"邓小平理论的精髓是","choices":[{"id":"A","text":"实事求是"},{"id":"B","text":"对外开放"},{"id":"C","text":"独立自主"},{"id":"D","text":"解放思想、实事求是"}],"answer":["D"],"analysis":{"point":"","options":{"A":"实事求是——是毛泽东思想的精髓。","B":"对外开放——是建设中国特色社会主义的一项基本国策。","C":"独立自主——是毛泽东思想活的灵魂之一。","D":"解放思想、实事求是——是邓小平理论的精髓，是本题正确答案。"}}},{"id":"basic-maozhongte-ch06-3","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 3 题"},"stem":"邓小平和我们党对当代中国基本国情的科学判断是","choices":[{"id":"A","text":"半殖民地半封建社会"},{"id":"B","text":"社会主义现代化建设和改革开放新时期"},{"id":"C","text":"我国正处于并将长期处于社会主义初级阶段"},{"id":"D","text":"中国特色社会主义进入新时代"}],"answer":["C"],"analysis":{"point":"","options":{"A":"半殖民地半封建社会——是近代中国的基本国情。","B":"社会主义现代化建设和改革开放新时期——是社会主义初级阶段中的一个时期。","C":"我国正处于并将长期处于社会主义初级阶段——是邓小平和我们党对当代中国基本国情的科学判断，是本题正确答案。","D":"中国特色社会主义进入新时代——是社会主义初级阶段中的一个时期。"}}},{"id":"basic-maozhongte-ch06-4","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 4 题"},"stem":"1979年3月30日，邓小平在党的理论工作务虚会上发表的讲话核心成为我们党和国家生存发展的政治基石。这一政治基石是","choices":[{"id":"A","text":"改革开放"},{"id":"B","text":"四项基本原则"},{"id":"C","text":"依法治国"},{"id":"D","text":"以经济建设为中心"}],"answer":["B"],"analysis":{"point":"","options":{"A":"改革开放——是强国之路，是我们党和国家发展进步的活力源泉。","B":"四项基本原则——是立国之本，是我们党和国家生存发展的政治基石，是本题正确答案。","C":"依法治国——是在党的十五大上提出的。","D":"能否坚持以经济建设为中心，是关系到我国社会主义现代化的成败、关系到社会主义的前途和命运的大问题。"}}},{"id":"basic-maozhongte-ch06-5","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 5 题"},"stem":"党在改革开放和社会主义现代化建设新时期实现的最根本的拨乱反正是","choices":[{"id":"A","text":"科学评价了毛泽东和毛泽东思想"},{"id":"B","text":"以经济建设为中心"},{"id":"C","text":"大规模平反冤假错案"},{"id":"D","text":"重新确立实事求是的思想路线"}],"answer":["B"],"analysis":{"point":"","options":{"A":"科学评价了毛泽东和毛泽东思想——是党的十一届六中全会的内容，党的十一届六中全会标志着党在指导思想上的拨乱反正的完成。","B":"以经济建设为中心——是党在改革开放和社会主义现代化建设新时期实现的最根本的拨乱反正，是本题正确答案。","C":"大规模平反冤假错案——是在党的十一届三中全会后开展的。","D":"重新确立实事求是的思想路线——是党的十一届三中全会的重要成果。"}}},{"id":"basic-maozhongte-ch06-6","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 6 题"},"stem":"党的十一届三中全会以后，我们党把工作重点转移到经济建设上来，强调社会主义的根本任务是","choices":[{"id":"A","text":"实现共同富裕"},{"id":"B","text":"坚持公有制的主体地位"},{"id":"C","text":"发展生产力"},{"id":"D","text":"建设富强、民主、文明的社会主义现代化国家"}],"answer":["C"],"analysis":{"point":"","options":{"A":"实现共同富裕是社会主义的根本目标。","B":"坚持公有制的主体地位——是社会主义市场经济的一个重要特征。","C":"发展生产力——是社会主义的根本任务，是本题正确答案。","D":"建设富强、民主、文明的社会主义现代化国家——是党在社会主义初级阶段的奋斗目标。"}}},{"id":"basic-maozhongte-ch06-7","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 7 题"},"stem":"“如果把产权性质改变的改革才认为是真正的改革，那么这种改革就不是社会主义性质的改革。”“改变中国的社会主义性质更不是改革。”这表明社会主义改革的性质是","choices":[{"id":"A","text":"社会主义基本制度的变革"},{"id":"B","text":"社会主义经济运行方式的改变"},{"id":"C","text":"对社会主义原有体制的修补"},{"id":"D","text":"社会主义制度的自我完善和发展"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是错误说法。","B":"社会主义经济运行方式的改变非考点。","C":"是错误说法。","D":"社会主义制度的自我完善和发展——是社会主义改革的性质，是本题正确答案。"}}},{"id":"basic-maozhongte-ch06-8","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 8 题"},"stem":"我国经济体制改革的核心问题是正确认识和处理","choices":[{"id":"A","text":"政府与企业的关系"},{"id":"B","text":"国有企业与私营企业的关系"},{"id":"C","text":"中央与地方的关系"},{"id":"D","text":"计划与市场的关系"}],"answer":["D"],"analysis":{"point":"","options":{"A":"非考点。","B":"非考点。","C":"非考点。","D":"正确认识和处理计划与市场的关系是我国经济体制改革的核心问题，是本题正确答案。"}}},{"id":"basic-maozhongte-ch06-9","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 9 题"},"stem":"1985年，邓小平指出：“现在世界上真正大的问题，带全球性的战略问题，一个是和平问题，一个是经济问题或者说是发展问题。……概括起来，就是东西南北四个字。”据此分析，当今世界所有问题的核心是","choices":[{"id":"A","text":"南北问题"},{"id":"B","text":"维护世界和平问题"},{"id":"C","text":"反对霸权主义、强权政治问题"},{"id":"D","text":"建立国际经济新秩序的问题"}],"answer":["A"],"analysis":{"point":"","options":{"A":"南北问题——是发展问题，是当今世界所有问题的核心，是本题正确答案。","B":"非考点。","C":"非考点。","D":"非考点。"}}},{"id":"basic-maozhongte-ch06-10","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 10 题"},"stem":"党的十三大从我国社会主义初级阶段的基本国情出发，在科学认识我国社会主要矛盾的基础上，提出了党在社会主义初级阶段的基本路线：“领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。”关于这条基本路线，以下说法正确的有","choices":[{"id":"A","text":"建设“富强、民主、文明的社会主义现代化国家”是党在初级阶段的奋斗目标"},{"id":"B","text":"“以经济建设为中心，坚持四项基本原则，坚持改革开放”是实现奋斗目标的基本途径"},{"id":"C","text":"“自力更生，艰苦创业”是实现初级阶段奋斗目标的根本立足点"},{"id":"D","text":"党的基本路线是国家的生命线、人民的幸福线"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是关于初级阶段基本路线的正确说法，是本题正确答案。","B":"是关于初级阶段基本路线的正确说法，是本题正确答案。","C":"是关于初级阶段基本路线的正确说法，是本题正确答案。","D":"是关于初级阶段基本路线的正确说法，是本题正确答案。"}}},{"id":"basic-maozhongte-ch06-11","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 11 题"},"stem":"1992年，邓小平在南方谈话中指出：“改革开放迈不开步子，不敢闯，说来说去就是怕资本主义的东西多了，走了资本主义道路。要害是姓资’还是姓‘社’的问题。”因此，判断改革和各方面工作是非得失的标准主要看","choices":[{"id":"A","text":"是否有利于发展社会主义社会的生产力"},{"id":"B","text":"是否有利于增强社会主义国家的综合国力"},{"id":"C","text":"是否有利于维护社会和谐稳定"},{"id":"D","text":"是否有利于提高人民生活水平"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是判断改革和各方面工作是非得失的“三个有利于”标准，是本题正确答案。","B":"是判断改革和各方面工作是非得失的“三个有利于”标准，是本题正确答案。","C":"非考点。","D":"是判断改革和各方面工作是非得失的“三个有利于”标准，是本题正确答案。"}}},{"id":"basic-maozhongte-ch06-12","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 12 题"},"stem":"实行对外开放是对中国经济发展停滞落后历史教训深刻总结的结果。邓小平反复强调：“任何国家要发达起来，闭关自守都不可能。我们吃过这个苦头，我们的老祖宗吃过这个苦头。”以下关于邓小平提出的对外开放的要求，说法正确的有","choices":[{"id":"A","text":"要高度珍惜并坚决维护中国人民经过长期奋斗得来的独立自主权利"},{"id":"B","text":"对外开放包括经济、科技、教育、文化等领域的开放"},{"id":"C","text":"对外开放包括对发达国家的开放，也包括对发展中国家的开放"},{"id":"D","text":"要大胆吸收和借鉴人类社会创造的一切文明成果"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是邓小平关于对外开放的要求，是本题正确答案。","B":"是邓小平关于对外开放的要求，是本题正确答案。","C":"是邓小平关于对外开放的要求，是本题正确答案。","D":"是邓小平关于对外开放的要求，是本题正确答案。"}}},{"id":"basic-maozhongte-ch06-13","moduleId":"basic","subjectId":"maozhongte","chapter":"第六章 邓小平理论","chapterKey":"第六章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第六章 第 13 题"},"stem":"南方谈话从根本上解除了过去的思想束缚，标志着邓小平的社会主义市场经济理论的形成。邓小平社会主义市场经济理论的内涵包括","choices":[{"id":"A","text":"坚持社会主义制度与市场经济的结合，是社会主义市场经济的优势所在"},{"id":"B","text":"市场经济作为资源配置的手段不具有制度属性"},{"id":"C","text":"计划经济和市场经济不是划分社会制度的标志"},{"id":"D","text":"市场经济和不同的社会制度结合，具有相同的性质"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是邓小平社会主义市场经济理论的内涵，是本题正确答案。","B":"是邓小平社会主义市场经济理论的内涵，是本题正确答案。","C":"是邓小平社会主义市场经济理论的内涵，是本题正确答案。","D":"是错误说法，市场经济和不同的社会制度结合，会表现出不同的性质。"}}},{"id":"basic-maozhongte-ch07-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第七章 “三个代表”重要思想","chapterKey":"第七章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第七章 第 1 题"},"stem":"“三个代表”重要思想反映了当代世界和中国的发展变化对党和国家工作的新要求，是加强和改进党的建设、推进我国社会主义自我完善和发展的强大理论武器，是党和国家必须长期坚持的指导思想。将“三个代表”重要思想写入党章的会议是","choices":[{"id":"A","text":"党的十四大"},{"id":"B","text":"党的十五大"},{"id":"C","text":"党的十六大"},{"id":"D","text":"党的十七大"}],"answer":["C"],"analysis":{"point":"","options":{"A":"党的十四大——高度评价了邓小平对创新中国特色社会主义理论的杰出贡献。","B":"党的十五大——正式提出“邓小平理论”这一概念，并将其写入党章。","C":"党的十六大——将“三个代表”重要思想写入党章，是本题正确答案。","D":"党的十七大将科学发展观写入党章。"}}},{"id":"basic-maozhongte-ch07-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第七章 “三个代表”重要思想","chapterKey":"第七章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第七章 第 2 题"},"stem":"“三个代表”重要思想在邓小平理论的基础上创造性地回答了“建设什么样的党、怎样建设党”的问题，是党和国家必须长期坚持的指导思想。“三个代表”重要思想指出，党执政兴国的第一要务是","choices":[{"id":"A","text":"创新"},{"id":"B","text":"以人民为中心"},{"id":"C","text":"解放和发展生产力"},{"id":"D","text":"发展"}],"answer":["D"],"analysis":{"point":"","options":{"A":"创新是引领发展的第一动力。","B":"以人民为中心——是新时代坚持和发展中国特色社会主义的根本立场，是贯穿党治国理政全部活动的一条红线。","C":"解放和发展生产力是社会主义的根本任务。","D":"发展——是党执政兴国的第一要务，是本题正确答案。"}}},{"id":"basic-maozhongte-ch07-3","moduleId":"basic","subjectId":"maozhongte","chapter":"第七章 “三个代表”重要思想","chapterKey":"第七章","n":3,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第七章 第 3 题"},"stem":"“三个代表”重要思想是对马克思列宁主义、毛泽东思想和邓小平理论的继承和发展，是中国特色社会主义理论体系的重要组成部分。“三个代表”重要思想的核心观点是","choices":[{"id":"A","text":"始终代表中国最广大人民的根本利益"},{"id":"B","text":"始终代表中国最民主的政治模式"},{"id":"C","text":"始终代表中国先进文化的前进方向"},{"id":"D","text":"始终代表中国先进生产力的发展要求"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是“三个代表”重要思想的核心观点，是本题正确答案。","B":"始终代表中国最民主的政治模式非考点。","C":"是“三个代表”重要思想的核心观点，是本题正确答案。","D":"是“三个代表”重要思想的核心观点，是本题正确答案。"}}},{"id":"basic-maozhongte-ch08-1","moduleId":"basic","subjectId":"maozhongte","chapter":"第八章 科学发展观","chapterKey":"第八章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第八章 第 1 题"},"stem":"胡锦涛指出，我国发展重要战略机遇期存在的基本条件和我国发展机遇大于挑战的基本面并没有因为国际国内形势新变化而发生根本性改变。“综观国际国内大势，我国发展仍处于可以大有作为的重要战略机遇期。”科学发展观的第一要义是","choices":[{"id":"A","text":"以人为本"},{"id":"B","text":"统筹兼顾"},{"id":"C","text":"全面协调可持续"},{"id":"D","text":"推动经济社会发展"}],"answer":["D"],"analysis":{"point":"","options":{"A":"以人为本——是科学发展观的核心立场。","B":"统筹兼顾是科学发展观的根本方法。","C":"全面协调可持续——是科学发展观的基本要求。","D":"推动经济社会发展——是科学发展观的第一要义，是本题正确答案。"}}},{"id":"basic-maozhongte-ch08-2","moduleId":"basic","subjectId":"maozhongte","chapter":"第八章 科学发展观","chapterKey":"第八章","n":2,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"毛中特 · 第八章 第 2 题"},"stem":"科学发展观是以胡锦涛同志为主要代表的中国共产党人，在新世纪新阶段全面建设小康社会进程中，在新的历史起点上推进中国特色社会主义事业的过程中形成和发展起来的，体现了马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想的历史逻辑和内在联系。科学发展观同邓小平理论、“三个代表”重要思想都","choices":[{"id":"A","text":"面对着共同的时代课题和历史任务"},{"id":"B","text":"坚持辩证唯物主义和历史唯物主义的世界观和方法论"},{"id":"C","text":"是对中国特色社会主义理论体系的接续发展"},{"id":"D","text":"坚持党的最高纲领和最低纲领的统一习近平新时代中国特色社会主义思想概论"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是科学发展观同邓小平理论、“三个代表”重要思想的相同点，是本题正确答案。","B":"是科学发展观同邓小平理论、“三个代表”重要思想的相同点，是本题正确答案。","C":"是错误说法，邓小平理论是中国特色社会主义理论体系的开篇之作。","D":"是科学发展观同邓小平理论、“三个代表”重要思想的相同点，是本题正确答案。"}}},{"id":"basic-xisixiang-daolun-1","moduleId":"basic","subjectId":"xisixiang","chapter":"导论","chapterKey":"导论","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 导论 第 1 题"},"stem":"道路问题是关系党的事业兴衰成败第一位的问题。历史和实践充分证明，只有社会主义才能救中国，只有社会主义才能发展中国，只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴。在我们党探索中国特色社会主义道路的过程中，我们取得成功的最大法宝是","choices":[{"id":"A","text":"“两个结合”"},{"id":"B","text":"“两个确立”"},{"id":"C","text":"“两个维护”"},{"id":"D","text":"“四个全面”"}],"answer":["A"],"analysis":{"point":"","options":{"A":"“两个结合”——是我们取得成功的最大法宝，是本题正确答案。","B":"“两个确立”——是新时代党和国家事业取得历史性成就、发生历史性变革的决定性因素。","C":"“两个维护”——是党的最高政治原则和根本政治规矩。","D":"“四个全面”——是中国特色社会主义事业的战略布局。"}}},{"id":"basic-xisixiang-daolun-2","moduleId":"basic","subjectId":"xisixiang","chapter":"导论","chapterKey":"导论","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 导论 第 2 题"},"stem":"以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，深刻总结并充分运用党成立以来的历史经验，从新的实际出发，创立了习近平新时代中国特色社会主义思想。其中，新时代坚持和发展中国特色社会主义的基本方略是","choices":[{"id":"A","text":"“六个必须坚持”"},{"id":"B","text":"“十四个坚持”"},{"id":"C","text":"“十个明确”"},{"id":"D","text":"“十三个方面成就”"}],"answer":["B"],"analysis":{"point":"","options":{"A":"“六个必须坚持”——是习近平新时代中国特色社会主义思想的世界观和方法论。","B":"“十四个坚持”——是新时代坚持和发展中国特色社会主义的基本方略，是本题正确答案。","C":"“十个明确”——是习近平新时代中国特色社会主义思想的主体内容。","D":"“十三个方面成就”——是习近平新时代中国特色社会主义思想的理论与实践成果。"}}},{"id":"basic-xisixiang-daolun-3","moduleId":"basic","subjectId":"xisixiang","chapter":"导论","chapterKey":"导论","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 导论 第 3 题"},"stem":"“六个必须坚持”相互联系、彼此支撑，贯通了唯物论和辩证法、认识论和实践论、真理论和价值论，赋予了马克思主义世界观和方法论以新的时代内涵，彰显了习近平新时代中国特色社会主义思想的理论品格和鲜明特征。其中，“必须坚持守正创新”体现了","choices":[{"id":"A","text":"历史唯物主义群众史观"},{"id":"B","text":"辩证唯物主义普遍联系原理"},{"id":"C","text":"矛盾的普遍性和客观性"},{"id":"D","text":"变与不变、继承与发展的内在联系"}],"answer":["D"],"analysis":{"point":"","options":{"A":"历史唯物主义群众史观——是“必须坚持人民至上”的体现。","B":"辩证唯物主义普遍联系原理——是“必须坚持系统观念”的体现。","C":"矛盾的普遍性和客观性——是“必须坚持问题导向”的体现。","D":"变与不变、继承与发展的内在联系——是“必须坚持守正创新”的体现，是本题正确答案。"}}},{"id":"basic-xisixiang-daolun-4","moduleId":"basic","subjectId":"xisixiang","chapter":"导论","chapterKey":"导论","n":4,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 导论 第 4 题"},"stem":"习近平新时代中国特色社会主义思想坚持科学社会主义基本原则，深刻总结和充分运用党的百年奋斗的历史经验，根据时代和实践发展变化，以全新的视野深化了对共产党执政规律、社会主义建设规律、人类社会发展规律的认识，实现了马克思主义中国化时代化新的飞跃。习近平新时代中国特色社会主义思想科学回答的重大时代课题有","choices":[{"id":"A","text":"新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义"},{"id":"B","text":"建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国"},{"id":"C","text":"建设什么样的党、怎样建设党"},{"id":"D","text":"建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是习近平新时代中国特色社会主义思想科学回答的重大时代课题，是本题正确答案。","B":"是习近平新时代中国特色社会主义思想科学回答的重大时代课题，是本题正确答案。","C":"建设什么样的党、怎样建设党——是“三个代表”重要思想回答的重大问题。","D":"是习近平新时代中国特色社会主义思想科学回答的重大时代课题，是本题正确答案。"}}},{"id":"basic-xisixiang-daolun-5","moduleId":"basic","subjectId":"xisixiang","chapter":"导论","chapterKey":"导论","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 导论 第 5 题"},"stem":"习近平新时代中国特色社会主义思想是当代中国马克思主义、21世纪马克思主义，是中华文化和中国精神的时代精华，实现了马克思主义中国化时代化新的飞跃。下列关于习近平新时代中国特色社会主义思想历史地位的评价，正确的有","choices":[{"id":"A","text":"开辟了马克思主义中国化时代化新境界"},{"id":"B","text":"使马克思主义这个魂脉和中华优秀传统文化这个根脉内在贯通、相互成就"},{"id":"C","text":"是中华民族的文化主体性最有力的体现"},{"id":"D","text":"是中国革命和建设的科学指南"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是关于习近平新时代中国特色社会主义思想历史地位的科学评价，是本题正确答案。","B":"是关于习近平新时代中国特色社会主义思想历史地位的科学评价，是本题正确答案。","C":"是关于习近平新时代中国特色社会主义思想历史地位的科学评价，是本题正确答案。","D":"是关于毛泽东思想历史地位的科学评价。"}}},{"id":"basic-xisixiang-ch01-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第一章 新时代坚持和发展中国特色社会主义","chapterKey":"第一章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第一章 第 1 题"},"stem":"科学社会主义诞生170多年来，人类社会发生了翻天覆地的变化，世界资本主义和社会主义都发生了很大变化，但是资本主义的基本矛盾没有变，工人阶级的历史使命没有变，科学社会主义的真理性没有变。科学社会主义基本原则是","choices":[{"id":"A","text":"马克思主义的活的灵魂"},{"id":"B","text":"马克思主义的核心内容"},{"id":"C","text":"马克思主义的政治立场"},{"id":"D","text":"马克思主义的基本方法"}],"answer":["B"],"analysis":{"point":"","options":{"A":"马克思主义的活的灵魂——是具体问题具体分析。","B":"马克思主义的核心内容——是科学社会主义基本原则，是本题正确答案。","C":"马克思主义的政治立场——是人民至上。","D":"马克思主义的基本方法——是建立在辩证唯物主义和历史唯物主义世界观和方法论基础上，指导我们正确认识世界和改造世界的思想方法和工作方法。"}}},{"id":"basic-xisixiang-ch01-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第一章 新时代坚持和发展中国特色社会主义","chapterKey":"第一章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第一章 第 2 题"},"stem":"在改革开放和社会主义现代化建设新时期，我们开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系，确立了中国特色社会主义制度，发展了中国特色社会主义文化，取得了举世瞩目的伟大成就，中国大踏步赶上了时代。必须坚定不移坚持和发展中国特色社会主义道路、理论、制度、文化，其中，制度是","choices":[{"id":"A","text":"实现途径"},{"id":"B","text":"行动指南"},{"id":"C","text":"根本保障"},{"id":"D","text":"精神力量"}],"answer":["C"],"analysis":{"point":"","options":{"A":"实现途径——是中国特色社会主义道路。","B":"行动指南——是中国特色社会主义理论体系。","C":"根本保障——是中国特色社会主义制度，是本题正确答案。","D":"精神力量——是中国特色社会主义文化。"}}},{"id":"basic-xisixiang-ch01-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第一章 新时代坚持和发展中国特色社会主义","chapterKey":"第一章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第一章 第 3 题"},"stem":"中国特色社会主义道路自信、理论自信、制度自信、文化自信，来源于实践、来源于人民、来源于真理。坚定中国特色社会主义道路自信、理论自信、制度自信、文化自信，中国共产党和中国人民有着深厚的根基和底气。我们坚定“四个自信”的理论支撑和根本依据是","choices":[{"id":"A","text":"深厚的实践基础和人民的广泛参与、深切认同"},{"id":"B","text":"马克思主义深刻揭示了社会主义必然代替资本主义的客观规律"},{"id":"C","text":"中国共产党的坚强领导"},{"id":"D","text":"连绵不绝的中华5 000多年文明"}],"answer":["B"],"analysis":{"point":"","options":{"A":"深厚的实践基础和人民的广泛参与、深切认同——是“四个自信”的坚实根基。","B":"马克思主义深刻揭示了社会主义必然代替资本主义的客观规律——是坚定“四个自信”的理论支撑和根本依据，是本题正确答案。","C":"中国共产党的坚强领导——是中国特色社会主义制度的最大优势。","D":"连绵不绝的中华5000多年文明——是中国特色社会主义的文化根脉和突出优势。"}}},{"id":"basic-xisixiang-ch01-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第一章 新时代坚持和发展中国特色社会主义","chapterKey":"第一章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第一章 第 4 题"},"stem":"人类社会是在矛盾运动中不断向前发展的，社会主要矛盾是各种社会矛盾的主要根源和集中反映，在社会矛盾运动中居于主导地位。中国特色社会主义进入新时代，我国社会的主要矛盾已经转化为","choices":[{"id":"A","text":"人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"},{"id":"B","text":"人民日益增长的物质文化需要同落后的社会生产之间的矛盾"},{"id":"C","text":"人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾"},{"id":"D","text":"人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾"}],"answer":["A"],"analysis":{"point":"","options":{"A":"人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾——是2017年党的十九大指出的新时代我国社会的主要矛盾，是本题正确答案。","B":"人民日益增长的物质文化需要同落后的社会生产之间的矛盾——是1981年党的十一届六中全会指出的我国社会的主要矛盾。","C":"是1956年党的八大指出的我国社会的主要矛盾。059. .","D":"是1956年党的八大指出的我国社会的主要矛盾。059. ."}}},{"id":"basic-xisixiang-ch01-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第一章 新时代坚持和发展中国特色社会主义","chapterKey":"第一章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第一章 第 5 题"},"stem":"历史和现实充分证明，我们党团结带领全国各族人民探索形成的党的基本理论、基本路线、基本方略是完全正确的，必须长期坚持、全面贯彻。我们党坚定信仰信念、把握历史主动的根本所在是","choices":[{"id":"A","text":"高举中国特色社会主义伟大旗帜"},{"id":"B","text":"中国特色社会主义制度"},{"id":"C","text":"拥有马克思主义科学理论指导"},{"id":"D","text":"坚持自信自立"}],"answer":["C"],"analysis":{"point":"","options":{"A":"高举中国特色社会主义伟大旗帜是实现新时代党的历史使命的根本要求。","B":"中国特色社会主义制度——是当代中国发展进步的根本制度保障。","C":"拥有马克思主义科学理论指导——是我们党坚定信仰信念、把握历史主动的根本所在，是本题正确答案。","D":"坚持自信自立——是内在精神特质，体现了客观规律性和主观能动性的有机结合。"}}},{"id":"basic-xisixiang-ch01-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第一章 新时代坚持和发展中国特色社会主义","chapterKey":"第一章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第一章 第 6 题"},"stem":"习近平总书记指出：“党的十一届三中全会是划时代的，开启了改革开放和社会主义现代化建设历史新时期。”改革开放以来我们取得一切成绩和进步的根本原因，归结起来就是","choices":[{"id":"A","text":"开辟了中国特色社会主义道路"},{"id":"B","text":"形成了中国特色社会主义理论体系"},{"id":"C","text":"确立了中国特色社会主义制度"},{"id":"D","text":"发展了中国特色社会主义文化"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是改革开放以来我们取得一切成绩和进步的根本原因，是本题正确答案。","B":"是改革开放以来我们取得一切成绩和进步的根本原因，是本题正确答案。","C":"是改革开放以来我们取得一切成绩和进步的根本原因，是本题正确答案。","D":"是改革开放以来我们取得一切成绩和进步的根本原因，是本题正确答案。"}}},{"id":"basic-xisixiang-ch01-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第一章 新时代坚持和发展中国特色社会主义","chapterKey":"第一章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第一章 第 7 题"},"stem":"在庆祝中国共产党成立95周年大会上，习近平总书记强调指出：“坚持不忘初心、继续前进，就要坚持中国特色社会主义道路自信、理论自信、制度自信、文化自信，坚持党的基本路线不动摇，不断把中国特色社会主义伟大事业推向前进。”改革开放以来，党和国家领导人一再强调要毫不动摇地坚持党的基本路线，这主要是因为，实践已经证明，党的基本路线是","choices":[{"id":"A","text":"党和国家的生命线、人民的幸福线"},{"id":"B","text":"实现科学发展的政治保证"},{"id":"C","text":"兴国、立国、强国的重大法宝"},{"id":"D","text":"思想路线的核心"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是关于党的基本路线的正确表述，是本题正确答案。","B":"是关于党的基本路线的正确表述，是本题正确答案。","C":"是关于党的基本路线的正确表述，是本题正确答案。","D":"思想路线的核心是实事求是。"}}},{"id":"basic-xisixiang-ch02-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","chapterKey":"第二章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第二章 第 1 题"},"stem":"中国梦是国家的梦、民族的梦，也是每一个中国人的梦。“民惟邦本，本固邦宁”，国家的富强、民族的振兴都要以人民的权利得到保障、利益得到实现、幸福得到满足为条件。因此，国家富强、民族振兴的根本出发点和落脚点是","choices":[{"id":"A","text":"人民幸福"},{"id":"B","text":"政治民主"},{"id":"C","text":"社会和谐"},{"id":"D","text":"经济发达"}],"answer":["A"],"analysis":{"point":"","options":{"A":"人民幸福——是国家富强、民族振兴的根本出发点和落脚点，是本题正确答案。","B":"政治民主——是国家富强在政治领域的体现。","C":"社会和谐——是国家富强在社会领域的体现。","D":"经济发达——是国家富强在经济领域的体现。"}}},{"id":"basic-xisixiang-ch02-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","chapterKey":"第二章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第二章 第 2 题"},"stem":"全面建成小康社会不是终点，而是新生活、新奋斗的起点。党的二十大进一步明确，从2020年到21世纪中叶可以分为两个阶段来安排。第一个阶段的奋斗目标是","choices":[{"id":"A","text":"全体人民共同富裕基本实现"},{"id":"B","text":"全面建成社会主义现代化强国"},{"id":"C","text":"基本实现社会主义现代化"},{"id":"D","text":"实现国家治理体系和治理能力现代化"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是第二个阶段奋斗目标的具体任务。","B":"全面建成社会主义现代化强国——是第二个阶段的奋斗目标。","C":"基本实现社会主义现代化——是第一个阶段的奋斗目标，是本题正确答案。","D":"是第二个阶段奋斗目标的具体任务。"}}},{"id":"basic-xisixiang-ch02-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","chapterKey":"第二章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第二章 第 3 题"},"stem":"习近平指出：“中国式现代化，是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自己国情的中国特色。”中国式现代化区别于西方现代化的显著标志是","choices":[{"id":"A","text":"人口规模巨大的现代化"},{"id":"B","text":"全体人民共同富裕的现代化"},{"id":"C","text":"人与自然和谐共生的现代化"},{"id":"D","text":"走和平发展道路的现代化"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是中国式现代化的中国特色，但不是中国式现代化区别于西方现代化的显著标志。","B":"全体人民共同富裕的现代化——是中国式现代化区别于西方现代化的显著标志，是本题正确答案。","C":"是中国式现代化的中国特色，但不是中国式现代化区别于西方现代化的显著标志。","D":"是中国式现代化的中国特色，但不是中国式现代化区别于西方现代化的显著标志。"}}},{"id":"basic-xisixiang-ch02-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","chapterKey":"第二章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第二章 第 4 题"},"stem":"中国式现代化是一项前无古人的开创性、探索性事业，也是一个复杂的系统工程。推进现代化最坚实的根基、最深厚的力量是","choices":[{"id":"A","text":"坚持中国特色社会主义道路"},{"id":"B","text":"人民群众"},{"id":"C","text":"坚持发扬斗争精神"},{"id":"D","text":"坚持深化改革开放"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是推进中国式现代化需要牢牢把握的重大原则，但不是推进现代化最坚实的根基、最深厚的力量。","B":"人民群众——是推进现代化最坚实的根基、最深厚的力量，是本题正确答案。","C":"是推进中国式现代化需要牢牢把握的重大原则，但不是推进现代化最坚实的根基、最深厚的力量。","D":"是推进中国式现代化需要牢牢把握的重大原则，但不是推进现代化最坚实的根基、最深厚的力量。"}}},{"id":"basic-xisixiang-ch02-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","chapterKey":"第二章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第二章 第 5 题"},"stem":"习近平指出：“一百年来，中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造，归结起来就是一个主题：实现中华民族伟大复兴。”实现中华民族伟大复兴的中国梦，本质是","choices":[{"id":"A","text":"国家富强"},{"id":"B","text":"民族振兴"},{"id":"C","text":"社会和谐"},{"id":"D","text":"人民幸福"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是中国梦的本质，是本题正确答案。","B":"是中国梦的本质，是本题正确答案。","C":"社会和谐——是国家富强在社会领域的体现。","D":"是中国梦的本质，是本题正确答案。"}}},{"id":"basic-xisixiang-ch02-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","chapterKey":"第二章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第二章 第 6 题"},"stem":"全面建成社会主义现代化强国的战略安排，丰富和拓展了全面建设社会主义现代化国家战略目标的内涵，与中华民族从站起来、富起来到强起来的历史逻辑高度契合，对动员全党全国各族人民万众一心实现中华民族伟大复兴的中国梦具有重大意义。下列属于我国到2035年要实现的奋斗目标的有","choices":[{"id":"A","text":"人均国内生产总值达到中等发达国家水平"},{"id":"B","text":"形成新发展格局"},{"id":"C","text":"建成教育强国、科技强国、人才强国"},{"id":"D","text":"全体人民共同富裕基本实现"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是我国到2035年要实现的奋斗目标，是本题正确答案。","B":"是我国到2035年要实现的奋斗目标，是本题正确答案。","C":"是我国到2035年要实现的奋斗目标，是本题正确答案。","D":"全体人民共同富裕基本实现——是我国到21世纪中叶要实现的奋斗目标。"}}},{"id":"basic-xisixiang-ch02-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","chapterKey":"第二章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第二章 第 7 题"},"stem":"中国式现代化是中国共产党领导的社会主义现代化，这是对中国式现代化的定性，是管总、管根本的。之所以强调党在中国式现代化建设中的领导地位，是因为","choices":[{"id":"A","text":"党的领导决定中国式现代化的根本性质"},{"id":"B","text":"党的领导激发建设中国式现代化的强劲动力"},{"id":"C","text":"党的领导凝聚建设中国式现代化的磅礴力量"},{"id":"D","text":"党的领导确保中国式现代化锚定奋斗目标行稳致远"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"均是强调党在中国式现代化建设中的领导地位的原因，是本题正确答案。","B":"均是强调党在中国式现代化建设中的领导地位的原因，是本题正确答案。","C":"均是强调党在中国式现代化建设中的领导地位的原因，是本题正确答案。","D":"均是强调党在中国式现代化建设中的领导地位的原因，是本题正确答案。"}}},{"id":"basic-xisixiang-ch03-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 1 题"},"stem":"党领导人民在百年奋斗中开辟了实现中华民族伟大复兴的正确道路，书写了中华民族几千年历史上最恢宏的史诗。习近平指出，中国最大的国情就是","choices":[{"id":"A","text":"人民民主专政"},{"id":"B","text":"中国共产党的领导"},{"id":"C","text":"人口规模巨大"},{"id":"D","text":"人民代表大会制度"}],"answer":["B"],"analysis":{"point":"","options":{"A":"人民民主专政——是我国的国体。","B":"中国共产党的领导——是中国最大的国情，是本题正确答案。","C":"人口规模巨大——是我国的国情之一，但不是最大的国情。","D":"人民代表大会制度——是我国的政体。"}}},{"id":"basic-xisixiang-ch03-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 2 题"},"stem":"与资本主义社会、传统的社会主义相比，中国特色社会主义制度具有自身的基本特征和制度优势，如作为我国根本政治制度的人民代表大会制度，中国共产党领导的多党合作和政治协商制度，公有制为主体、多种所有制经济共同发展的基本经济制度等。在这些制度优势中，最大的优势是","choices":[{"id":"A","text":"发展生产力"},{"id":"B","text":"全面深化改革开放"},{"id":"C","text":"全过程人民民主"},{"id":"D","text":"中国共产党领导"}],"answer":["D"],"analysis":{"point":"","options":{"A":"发展生产力——是社会主义的根本任务。","B":"全面深化改革开放——是新时代坚持和发展中国特色社会主义的根本动力。","C":"全过程人民民主——是社会主义民主政治的本质属性。","D":"中国共产党领导——是中国特色社会主义制度的最大优势，是本题正确答案。"}}},{"id":"basic-xisixiang-ch03-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 3 题"},"stem":"恩格斯强调：“没有权威，就不可能有任何的一致行动。”党保持团结统一和强大战斗力、不断取得胜利的关键所在是","choices":[{"id":"A","text":"党中央集中统一领导"},{"id":"B","text":"解放和增强社会活力"},{"id":"C","text":"思想引领力"},{"id":"D","text":"群众组织力"}],"answer":["A"],"analysis":{"point":"","options":{"A":"党中央集中统一领导——是党保持团结统一和强大战斗力、不断取得胜利的关键所在，是本题正确答案。","B":"解放和增强社会活力——是新时代全面深化改革的关键所在。","C":"思想引领力——是保证全党全国各族人民思想统一、步调一致的坚实基础。","D":"群众组织力——是我们党坚如磐石、坚不可摧的力量根基。"}}},{"id":"basic-xisixiang-ch03-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 4 题"},"stem":"习近平指出：“我们这么大一个党、这么大一个国家，如果没有党中央定于一尊的权威，党中央决定了的事都不去照办，还是各说各的话、各做各的事，那就什么事情也办不成了。”维护党中央权威和集中统一领导，最关键的是","choices":[{"id":"A","text":"坚决健全和完善党的领导制度体系"},{"id":"B","text":"坚决打赢反腐败斗争攻坚战持久战"},{"id":"C","text":"坚决维护习近平同志党中央的核心、全党的核心地位"},{"id":"D","text":"坚决贯彻党的理论、路线方针政策和党中央决策部署"}],"answer":["C"],"analysis":{"point":"","options":{"A":"坚决健全和完善党的领导制度体系——是坚持党的全面领导的要求。","B":"坚决打赢反腐败斗争攻坚战持久战——是推进反腐败斗争的要求。","C":"坚决维护习近平同志党中央的核心、全党的核心地位——是维护党中央权威和集中统一领导的最关键要求，是本题正确答案。","D":"坚决贯彻党的理论、路线方针政策和党中央决策部署——是维护党中央权威和集中统一领导的要求，但不是最关键要求。基础题篇"}}},{"id":"basic-xisixiang-ch03-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 5 题"},"stem":"习近平指出，中国特色社会主义制度是一个严密完整的科学制度体系，起四梁八柱作用的是根本制度、基本制度、重要制度。其中具有统领地位的是","choices":[{"id":"A","text":"人民代表大会制度"},{"id":"B","text":"党的领导制度"},{"id":"C","text":"基层群众自治制度"},{"id":"D","text":"民族区域自治制度"}],"answer":["B"],"analysis":{"point":"","options":{"A":"人民代表大会制度——是我国的根本政治制度。","B":"党的领导制度——是在中国特色社会主义制度中具有统领地位的制度，是本题正确答案。","C":"是我国的基本政治制度。","D":"是我国的基本政治制度。"}}},{"id":"basic-xisixiang-ch03-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 6 题"},"stem":"习近平指出：“一定要认清，中国最大的国情就是中国共产党的领导。什么是中国特色？这就是中国特色。”中国共产党领导是","choices":[{"id":"A","text":"解决一切经济社会问题的关键"},{"id":"B","text":"人民当家作主的可靠保障"},{"id":"C","text":"实现中华民族伟大复兴的根本保证"},{"id":"D","text":"中国特色社会主义事业的坚强核心"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"解决一切经济社会问题的关键——是发展。","B":"是中国共产党领导，是本题正确答案。","C":"是中国共产党领导，是本题正确答案。","D":"是中国共产党领导，是本题正确答案。"}}},{"id":"basic-xisixiang-ch03-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 7 题"},"stem":"坚持中国共产党的领导地位是一个重大的理论和实践问题。习近平明确指出：“在当今中国，没有大于中国共产党的政治力量或其他什么力量。党政军民学，东西南北中，党是领导一切的，是最高的政治领导力量。”中国共产党作为最高政治领导力量","choices":[{"id":"A","text":"得到了最广大人民群众的支持和拥护"},{"id":"B","text":"是由我国国家性质和政治制度体系决定的"},{"id":"C","text":"是新时代党治国理政的根本价值取向"},{"id":"D","text":"是由中华民族伟大复兴事业决定的"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是强调中国共产党是最高政治领导力量的原因，是本题正确答案。","B":"是强调中国共产党是最高政治领导力量的原因，是本题正确答案。","C":"是强调坚持人民至上的原因，坚持人民至上，是新时代党治国理政的根本价值取向。","D":"是强调中国共产党是最高政治领导力量的原因，是本题正确答案。"}}},{"id":"basic-xisixiang-ch03-8","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 8 题"},"stem":"习近平指出：“中国特色社会主义制度是一个严密完整的科学制度体系，起四梁八柱作用的是根本制度、基本制度、重要制度，其中具有统领地位的是党的领导制度。”党的领导制度是","choices":[{"id":"A","text":"国家治理体系和治理能力现代化的关键"},{"id":"B","text":"中国特色社会主义制度体系的核心"},{"id":"C","text":"党的领导核心地位的必然反映和内在要求"},{"id":"D","text":"贯穿党治国理政全部活动的一条红线"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是党的领导制度，是本题正确答案。","B":"是党的领导制度，是本题正确答案。","C":"是党的领导制度，是本题正确答案。","D":"贯穿党治国理政全部活动的一条红线——是坚持以人民为中心。"}}},{"id":"basic-xisixiang-ch03-9","moduleId":"basic","subjectId":"xisixiang","chapter":"第三章 坚持党的全面领导","chapterKey":"第三章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第三章 第 9 题"},"stem":"加强党中央对重大工作的领导，是我们党的优良传统和宝贵经验。早在土地革命战争时期，我们党就确立了各省委向中央报告的制度，要求各地及时向中央报告工作。党中央对重大工作的领导体制是","choices":[{"id":"A","text":"中国共产党区别于其他政党的最显著标志"},{"id":"B","text":"我们党作为马克思主义政党的根本要求"},{"id":"C","text":"加强党的全面领导的制度安排"},{"id":"D","text":"实现党的全面领导的直接体现"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"中国共产党区别于其他政党的最显著标志——是勇于自我革命。","B":"我们党作为马克思主义政党的根本要求——是旗帜鲜明讲政治。","C":"是党中央对重大工作的领导体制，是本题正确答案。","D":"是党中央对重大工作的领导体制，是本题正确答案。"}}},{"id":"basic-xisixiang-ch04-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 1 题"},"stem":"习近平指出：“人民是历史的创造者，人民是真正的英雄。波澜壮阔的中华民族发展史是中国人民书写的！博大精深的中华文明是中国人民创造的!历久弥新的中华民族精神是中国人民培育的！”这是因为，人民性是","choices":[{"id":"A","text":"马克思主义的内在品质"},{"id":"B","text":"马克思主义首要的和基本的观点"},{"id":"C","text":"马克思主义的本质属性和鲜明品格"},{"id":"D","text":"马克思主义的核心内容"}],"answer":["C"],"analysis":{"point":"","options":{"A":"马克思主义的内在品质——是革命性。","B":"马克思主义首要的和基本的观点——是实践观点。","C":"马克思主义的本质属性和鲜明品格——是人民性，是本题正确答案。","D":"马克思主义的核心内容——是科学社会主义基本原则。"}}},{"id":"basic-xisixiang-ch04-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 2 题"},"stem":"政治立场是一个政党观察、认识、处理政治问题的立足点，反映了这个政党的世界观、方法论和执政理念，体现了这个政党的根本属性。我们党的最大政治优势是","choices":[{"id":"A","text":"全过程人民民主"},{"id":"B","text":"人民当家作主"},{"id":"C","text":"全面从严治党"},{"id":"D","text":"密切联系群众"}],"answer":["D"],"analysis":{"point":"","options":{"A":"全过程人民民主——是社会主义民主政治的本质属性。","B":"人民当家作主——是社会主义民主政治的本质特征。","C":"全面从严治党——是新时代党的建设的鲜明主题。","D":"密切联系群众——是我们党的最大政治优势，是本题正确答案。"}}},{"id":"basic-xisixiang-ch04-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 3 题"},"stem":"党的十八大以来，以习近平同志为核心的党中央领导全党全国各族人民开创了中国特色社会主义新时代。新时代党治国理政的根本价值取向是","choices":[{"id":"A","text":"坚持深化改革开放"},{"id":"B","text":"坚持人民至上"},{"id":"C","text":"坚持和加强党的全面领导"},{"id":"D","text":"坚持发扬斗争精神"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是推进中国式现代化需要牢牢把握的重大原则。","B":"坚持人民至上——是新时代党治国理政的根本价值取向，是本题正确答案。","C":"是推进中国式现代化需要牢牢把握的重大原则。","D":"是推进中国式现代化需要牢牢把握的重大原则。"}}},{"id":"basic-xisixiang-ch04-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 4 题"},"stem":"习近平指出：“群众路线是我们党的生命线和根本工作路线，是我们党永葆青春活力和战斗力的重要传家宝。”我们党是在同人民群众的密切联系中成长、发展、壮大起来的。贯彻党的群众路线的有效途径是","choices":[{"id":"A","text":"调查研究"},{"id":"B","text":"武装斗争"},{"id":"C","text":"统一战线"},{"id":"D","text":"党的建设"}],"answer":["A"],"analysis":{"point":"","options":{"A":"调查研究——是贯彻党的群众路线的有效途径，是本题正确答案。","B":"是党在中国革命中战胜敌人的三个主要的法宝。","C":"是党在中国革命中战胜敌人的三个主要的法宝。","D":"是党在中国革命中战胜敌人的三个主要的法宝。"}}},{"id":"basic-xisixiang-ch04-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 5 题"},"stem":"坚持以人民为中心的发展思想，真正做到发展成果由人民共享，就必须落实到扎实推进全体人民共同富裕上，在推动共同富裕过程中促进人的全面发展。共同富裕是","choices":[{"id":"A","text":"中国特色社会主义的重要物质基础和政治基础"},{"id":"B","text":"中国特色社会主义的本质要求"},{"id":"C","text":"中国特色社会主义制度的重要支柱"},{"id":"D","text":"中国特色社会主义最本质的特征"}],"answer":["B"],"analysis":{"point":"","options":{"A":"中国特色社会主义的重要物质基础和政治基础——是国有企业。","B":"中国特色社会主义的本质要求——是共同富裕，是本题正确答案。","C":"中国特色社会主义制度的重要支柱——是社会主义基本经济制度。","D":"中国特色社会主义最本质的特征——是中国共产党领导。基础题篇"}}},{"id":"basic-xisixiang-ch04-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 6 题"},"stem":"习近平指出：“从建党的开天辟地，到新中国成立的改天换地，到改革开放的翻天覆地，再到党的十八大以来党和国家事业取得历史性成就、发生历史性变革，根本原因就在于我们党始终坚守了为中国人民谋幸福、为中华民族谋复兴的初心和使命。”人民立场是","choices":[{"id":"A","text":"中国共产党的根本政治立场"},{"id":"B","text":"我们党区别于其他政党的显著标志"},{"id":"C","text":"实现中华民族伟大复兴的根本保证"},{"id":"D","text":"决定当代中国命运的关键一招"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是人民立场，是本题正确答案。","B":"是人民立场，是本题正确答案。","C":"实现中华民族伟大复兴的根本保证——是中国共产党领导。","D":"决定当代中国命运的关键一招——是改革开放。"}}},{"id":"basic-xisixiang-ch04-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 7 题"},"stem":"习近平指出：“开展调查研究就是走群众路线，没有调查就没有发言权，就没有决策权。”不论过去、现在和将来，我们都要坚持一切为了群众、一切依靠群众，从群众中来到群众中去，把群众路线贯彻到治国理政全部活动之中。这是因为，群众路线是","choices":[{"id":"A","text":"我们党永葆青春活力和战斗力的重要传家宝"},{"id":"B","text":"我们党认识世界和改造世界的根本要求"},{"id":"C","text":"我们党的生命线和根本工作路线"},{"id":"D","text":"我们党始终坚持的根本工作方法"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是群众路线，是本题正确答案。","B":"我们党认识世界和改造世界的根本要求——是实事求是。","C":"是群众路线，是本题正确答案。","D":"是群众路线，是本题正确答案。"}}},{"id":"basic-xisixiang-ch04-8","moduleId":"basic","subjectId":"xisixiang","chapter":"第四章 坚持以人民为中心","chapterKey":"第四章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第四章 第 8 题"},"stem":"促进共同富裕，要把握好鼓励勤劳创新致富、坚持基本经济制度、尽力而为量力而行、坚持循序渐进的原则。总的思路是","choices":[{"id":"A","text":"扩大中等收入群体比重，增加低收入群体收入，合理调节高收入，取缔非法收入"},{"id":"B","text":"加大税收、社保、转移支付等调节力度并提高精准性"},{"id":"C","text":"坚持以人民为中心的发展思想，在高质量发展中促进共同富裕"},{"id":"D","text":"构建初次分配、再分配、三次分配协调配套的基础性制度安排"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是促进共同富裕的总的思路，是本题正确答案。","B":"是促进共同富裕的总的思路，是本题正确答案。","C":"是促进共同富裕的总的思路，是本题正确答案。","D":"是促进共同富裕的总的思路，是本题正确答案。"}}},{"id":"basic-xisixiang-ch05-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 1 题"},"stem":"党的十一届三中全会是划时代的，开启了改革开放和社会主义现代化建设新时期。党的十八届三中全会也是划时代的，实现了","choices":[{"id":"A","text":"马克思主义中国化时代化新的飞跃"},{"id":"B","text":"人民生活从温饱不足到总体小康、奔向全面小康的历史性跨越"},{"id":"C","text":"民主的全领域、全过程覆盖和贯通"},{"id":"D","text":"改革由局部探索、破冰突围到系统集成、全面深化的转变"}],"answer":["D"],"analysis":{"point":"","options":{"A":"马克思主义中国化时代化新的飞跃——是习近平新时代中国特色社会主义思想的意义。","B":"人民生活从温饱不足到总体小康、奔向全面小康的历史性跨越——是我们党领导人民在改革开放和社会主义现代化建设新时期取得的伟大成就。","C":"民主的全领域、全过程覆盖和贯通——是全过程人民民主的意义。","D":"改革由局部探索、破冰突围到系统集成、全面深化的转变——是党的十八届三中全会的意义，是本题正确答案。"}}},{"id":"basic-xisixiang-ch05-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 2 题"},"stem":"新时代全面深化改革开放，必须有利于进一步解放思想、进一步解放和发展社会生产力、进一步解放和增强社会活力。要不断完善各领域各方面的制度机制，使社会主义生产关系更加适应生产力的发展要求，使社会主义上层建筑更加适应经济基础的发展需要，更好激发全社会的创造活力，充分彰显中国特色社会主义制度的优越性。其中，新时代全面深化改革的关键所在是","choices":[{"id":"A","text":"解放思想"},{"id":"B","text":"解放和增强社会活力"},{"id":"C","text":"解放和发展社会生产力"},{"id":"D","text":"解放生产关系"}],"answer":["B"],"analysis":{"point":"","options":{"A":"解放思想是新时代全面深化改革开放的思想前提。","B":"解放和增强社会活力——是新时代全面深化改革的关键所在，是本题正确答案。","C":"解放和发展社会生产力——是改革开放的鲜明特征和首要任务。","D":"解放生产关系是解放和发展生产力的必然要求。"}}},{"id":"basic-xisixiang-ch05-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 3 题"},"stem":"习近平强调：“我们的改革开放是有方向、有立场、有原则的。”要保持战略定力，牢牢把握全面深化改革开放的正确方向，确保改革不改向、变革不变色。在全面深化改革开放的正确方向中，既是改革的目的，又是改革的条件的是","choices":[{"id":"A","text":"必须坚持和改善党的全面领导、坚持和完善中国特色社会主义制度"},{"id":"B","text":"必须坚持以人民为中心，促进社会公平正义、增进人民福祉"},{"id":"C","text":"必须有利于进一步解放思想、进一步解放和发展社会生产力、进一步解放和增强社会活力"},{"id":"D","text":"坚持党的全面领导、坚持以人民为中心、坚持守正创新、坚持以制度建设为主线、坚持全面依法治国、坚持系统观念"}],"answer":["C"],"analysis":{"point":"","options":{"A":"必须坚持和改善党的全面领导、坚持和完善中国特色社会主义制度——是改革的条件，但不是改革的目的。","B":"必须坚持以人民为中心，促进社会公平正义、增进人民福祉——是改革的目的，但不是改革的条件。","C":"必须有利于进一步解放思想、进一步解放和发展社会生产力、进一步解放和增强社会活力——既是改革的目的，又是改革的条件，是本题正确答案。","D":"坚持党的全面领导、坚持以人民为中心、坚持守正创新、坚持以制度建设为主线、坚持全面依法治国、坚持系统观念——是党的二十届三中全会提出的进一步全面深化改革的原则。"}}},{"id":"basic-xisixiang-ch05-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 4 题"},"stem":"全面深化改革开放必须有利于进一步解放思想、进一步解放和发展社会生产力、进一步解放和增强社会活力。习近平指出：“这‘三个进一步解放’既是改革的目的，又是改革的条件。”其中，解放和发展社会生产力是","choices":[{"id":"A","text":"社会主义改革的内在要求和基本目的"},{"id":"B","text":"改革开放的鲜明特征和首要任务"},{"id":"C","text":"新时代全面深化改革的关键所在"},{"id":"D","text":"开启改革开放事业的思想前提"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是关于解放和增强社会活力的正确表述。","B":"改革开放的鲜明特征和首要任务——是解放和发展社会生产力，是本题正确答案。","C":"是关于解放和增强社会活力的正确表述。","D":"开启改革开放事业的思想前提是解放思想。"}}},{"id":"basic-xisixiang-ch05-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 5 题"},"stem":"新时代全面深化改革具有全面性、系统性、整体性的鲜明特点，必须将其作为一个系统工程来把握。全面深化改革的总目标是","choices":[{"id":"A","text":"推进中国式现代化"},{"id":"B","text":"完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化"},{"id":"C","text":"深化供给侧结构性改革"},{"id":"D","text":"实现中华民族伟大复兴"}],"answer":["B"],"analysis":{"point":"","options":{"A":"推进中国式现代化——是党的二十届三中全会提出的进一步全面深化改革的主题。","B":"完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化——是全面深化改革的总目标，是本题正确答案。","C":"深化供给侧结构性改革——是经济工作的主线。","D":"实现中华民族伟大复兴——是近代以来中华民族最伟大的梦想。"}}},{"id":"basic-xisixiang-ch05-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 6 题"},"stem":"全面深化改革开放，不是某个领域某个方面的变革，而是涉及党和国家事业发展全局的体制机制变革。全面深化改革的总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化。其中，“完善和发展中国特色社会主义制度”规定了","choices":[{"id":"A","text":"改革的根本方向"},{"id":"B","text":"改革的鲜明指向"},{"id":"C","text":"改革的时代要求"},{"id":"D","text":"改革的出发点和落脚点"}],"answer":["A"],"analysis":{"point":"","options":{"A":"改革的根本方向——是完善和发展中国特色社会主义制度所规定的，是本题正确答案。","B":"是推进国家治理体系和治理能力现代化所明确的。","C":"是推进国家治理体系和治理能力现代化所明确的。","D":"改革的出发点和落脚点——是为了更好实现和维护人民利益、为了让老百姓过上好日子。"}}},{"id":"basic-xisixiang-ch05-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 7 题"},"stem":"中国特色社会主义制度的成熟定型是一个在改革中不断推进的过程。当前，我国发展还面临一系列突出矛盾和挑战，新时代坚持和发展中国特色社会主义的根本动力是","choices":[{"id":"A","text":"全面从严治党"},{"id":"B","text":"全面依法治国"},{"id":"C","text":"全面深化改革开放"},{"id":"D","text":"全面建设社会主义现代化国家"}],"answer":["C"],"analysis":{"point":"","options":{"A":"全面从严治党——是新时代党的建设的鲜明主题。","B":"全面依法治国——是坚持和发展中国特色社会主义的本质要求和重要保障。","C":"全面深化改革开放——是新时代坚持和发展中国特色社会主义的根本动力，是本题正确答案。","D":"（原书未单独给出此项解析）"}}},{"id":"basic-xisixiang-ch05-8","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 8 题"},"stem":"发展是党执政兴国的第一要务。党的二十届三中全会审议通过了《中共中央关于进一步全面深化改革、推进中国式现代化的决定》，并对未来五年的重大改革举措进行了部署。会议决定，此次进一步全面深化改革的重点仍是","choices":[{"id":"A","text":"政治体制改革"},{"id":"B","text":"文化体制改革"},{"id":"C","text":"经济体制改革"},{"id":"D","text":"行政体制改革"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是全面深化改革的内容，但不是党的二十届三中全会提出的进一步全面深化改革的重点。","B":"是全面深化改革的内容，但不是党的二十届三中全会提出的进一步全面深化改革的重点。","C":"经济体制改革——是党的二十届三中全会提出的进一步全面深化改革的重点，是本题正确答案。","D":"是全面深化改革的内容，但不是党的二十届三中全会提出的进一步全面深化改革的重点。"}}},{"id":"basic-xisixiang-ch05-9","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 9 题"},"stem":"恩格斯指出：“所谓‘社会主义社会’不是一种一成不变的东西，而应当和任何其他社会制度一样，把它看成是经常变化和改革的社会。”党的二十届三中全会强调，必须自觉把改革摆在更加突出位置。全面深化改革必须紧紧围绕的主题是","choices":[{"id":"A","text":"继续完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化"},{"id":"B","text":"推进中国式现代化"},{"id":"C","text":"制度建设"},{"id":"D","text":"重要领域和关键环节改革"}],"answer":["B"],"analysis":{"point":"","options":{"A":"继续完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化——是党的二十届三中全会提出的进一步全面深化改革的总目标。","B":"推进中国式现代化——是党的二十届三中全会提出的进一步全面深化改革的主题，是本题正确答案。","C":"制度建设是全面深化改革的主线。","D":"重要领域和关键环节改革——是统筹推进各领域各方面改革开放的突破口。"}}},{"id":"basic-xisixiang-ch05-10","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 10 题"},"stem":"改革开放以来，随着我国对外贸易的快速发展，货物贸易规模不断扩大。2009年，我国成为全球货物贸易第一大出口国和第二大进口国，货物进出口总额占国际市场的比重提升至8.7%。2013年，我国货物进出口总额占国际市场的比重进一步提升至11.0%，首次超越美国，成为全球货物贸易第一大国。此后除个别年份外我国一直保持全球第一，2023年我国货物进出口总额占国际市场的12.4%。改革开放是","choices":[{"id":"A","text":"全面建设社会主义现代化国家的出发点和落脚点"},{"id":"B","text":"决定当代中国命运的关键一招"},{"id":"C","text":"坚持和发展中国特色社会主义的必由之路"},{"id":"D","text":"当代中国最显著的特征、最壮丽的气象"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"全面建设社会主义现代化国家的出发点和落脚点——是让人民生活越过越好。","B":"是关于改革开放的正确表述，是本题正确答案。","C":"是关于改革开放的正确表述，是本题正确答案。","D":"是关于改革开放的正确表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch05-11","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 11 题"},"stem":"习近平强调：“我们的改革开放是有方向、有立场、有原则的。”要保持战略定力，牢牢把握全面深化改革开放的正确方向，确保改革不改向、变革不变色。坚持全面深化改革开放的正确方向，必须","choices":[{"id":"A","text":"坚持和改善党的全面领导、坚持和完善中国特色社会主义制度"},{"id":"B","text":"坚持以人民为中心，促进社会公平正义、增进人民福祉"},{"id":"C","text":"把发展质量问题摆在更为突出的位置，在质量效益提升的基础上实现经济持续健康发展"},{"id":"D","text":"有利于进一步解放思想、进一步解放和发展社会生产力、进一步解放和增强社会活力"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是坚持全面深化改革开放的正确方向，是本题正确答案。","B":"是坚持全面深化改革开放的正确方向，是本题正确答案。","C":"属于经济话题，属于“全面深化改革开放”的子课题，与“全面深化改革开放的正确方向”不在一个维度上。","D":"是坚持全面深化改革开放的正确方向，是本题正确答案。"}}},{"id":"basic-xisixiang-ch05-12","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 12 题"},"stem":"正确处理好改革发展稳定的关系，是我国改革开放的一条重要经验。改革发展稳定是我国社会主义现代化建设的三个重要支点。实践表明，如果不能正确处理三者的关系，就容易导致政局动荡、社会动乱，不仅难以抓住发展机遇，也会使已有的发展成果化为乌有。下列关于改革、发展、稳定的表述，正确的有","choices":[{"id":"A","text":"改革是经济社会发展的强大动力"},{"id":"B","text":"发展是解决一切经济社会问题的关键"},{"id":"C","text":"稳定是改革发展的前提"},{"id":"D","text":"把改善人民生活作为正确处理改革发展稳定关系的结合点"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是关于改革、发展、稳定的科学表述，是本题正确答案。","B":"是关于改革、发展、稳定的科学表述，是本题正确答案。","C":"是关于改革、发展、稳定的科学表述，是本题正确答案。","D":"是关于改革、发展、稳定的科学表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch05-13","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 13 题"},"stem":"习近平指出：“实践发展永无止境，解放思想永无止境，改革开放也永无止境，改革开放只有进行时、没有完成时。”改革开放永无止境是","choices":[{"id":"A","text":"社会基本矛盾运动规律的深刻反映"},{"id":"B","text":"强国建设、民族复兴的唯一正确道路"},{"id":"C","text":"推进党和人民事业发展的必然要求"},{"id":"D","text":"总结世界社会主义实践经验得出的重要结论"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是改革开放永无止境的重要性，是本题正确答案。","B":"强国建设、民族复兴的唯一正确道路——是中国式现代化。","C":"是改革开放永无止境的重要性，是本题正确答案。","D":"是改革开放永无止境的重要性，是本题正确答案。"}}},{"id":"basic-xisixiang-ch05-14","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 14 题"},"stem":"围绕党的中心任务谋划和部署改革，是党领导改革开放的成功经验。从实践经验和现实需要出发，中央政治局决定党的二十届三中全会研究进一步全面深化改革、推进中国式现代化问题。党的二十届三中全会","choices":[{"id":"A","text":"开创了改革开放的强国富民之路"},{"id":"B","text":"开启了新时代全面深化改革、系统整体设计推进改革新征程"},{"id":"C","text":"彰显了将改革进行到底的坚强决心和强烈使命担当"},{"id":"D","text":"是对新时代新征程举什么旗、走什么路的再宣示"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"开创了改革开放的强国富民之路是党的十一届三中全会的重大意义。","B":"开启了新时代全面深化改革、系统整体设计推进改革新征程——是党的十八届三中全会的重大意义。","C":"是党的二十届三中全会的重大意义，是本题正确答案。","D":"是党的二十届三中全会的重大意义，是本题正确答案。"}}},{"id":"basic-xisixiang-ch05-15","moduleId":"basic","subjectId":"xisixiang","chapter":"第五章 全面深化改革开放","chapterKey":"第五章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第五章 第 15 题"},"stem":"习近平指出，“中国将坚持实施更大范围、更宽领域、更深层次对外开放，坚持走中国式现代化道路，建设更高水平开放型经济新体制”。建设更高水平开放型经济新体制的举措有","choices":[{"id":"A","text":"依托我国超大规模市场优势，以国内大循环吸引全球资源要素，提升贸易投资合作质量和水平"},{"id":"B","text":"深化贸易投资领域体制机制改革，稳步扩大规则、规制、管理、标准等制度型开放"},{"id":"C","text":"推动货物贸易优化升级，创新服务贸易发展机制，发展数字贸易，加快建设贸易强国"},{"id":"D","text":"优化区域开放布局，实施自由贸易试验区提升战略，形成陆海内外联动、东西双向互济的开放格局"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是建设更高水平开放型经济新体制的举措，是本题正确答案。","B":"是建设更高水平开放型经济新体制的举措，是本题正确答案。","C":"是建设更高水平开放型经济新体制的举措，是本题正确答案。","D":"是建设更高水平开放型经济新体制的举措，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 1 题"},"stem":"进入新发展阶段，必须把发展质量问题摆在更为突出的位置，在质量效益明显提升的基础上实现经济持续健康发展。因此，新时代抓发展，必须更加突出发展理念，坚定不移贯彻创新、协调、绿色、开放、共享的新发展理念。其中，开放是","choices":[{"id":"A","text":"引领发展的第一动力"},{"id":"B","text":"持续健康发展的内在要求"},{"id":"C","text":"中国特色社会主义的本质要求"},{"id":"D","text":"国家繁荣发展的必由之路"}],"answer":["D"],"analysis":{"point":"","options":{"A":"引领发展的第一动力——是创新。","B":"持续健康发展的内在要求——是协调。","C":"中国特色社会主义的本质要求——是共享。","D":"国家繁荣发展的必由之路——是开放，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 2 题"},"stem":"新发展理念是一个系统的理论体系，回答了关于发展的目的、动力、方式、路径等一系列理论和实践问题，阐明了我们党关于发展的政治立场、价值导向、发展模式、发展道路等重大政治问题，深化了我们党对中国特色社会主义经济发展规律的认识，开拓了中国特色社会主义政治经济学新境界。其中，注重解决发展不平衡问题的是","choices":[{"id":"A","text":"协调发展"},{"id":"B","text":"绿色发展"},{"id":"C","text":"开放发展"},{"id":"D","text":"共享发展"}],"answer":["A"],"analysis":{"point":"","options":{"A":"协调发展——注重解决发展不平衡问题，是本题正确答案。","B":"绿色发展——注重解决人与自然和谐共生问题。","C":"开放发展——注重解决发展内外联动问题。","D":"共享发展——注重解决社会公平正义问题。"}}},{"id":"basic-xisixiang-ch06-07-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 3 题"},"stem":"高质量发展，是能够很好满足人民日益增长的美好生活需要的发展，是体现新发展理念的发展。高质量发展的根本目的是","choices":[{"id":"A","text":"创新"},{"id":"B","text":"协调"},{"id":"C","text":"开放"},{"id":"D","text":"共享"}],"answer":["D"],"analysis":{"point":"","options":{"A":"创新——是高质量发展的第一动力。","B":"协调——是高质量发展的内生特点。","C":"开放——是高质量发展的必由之路。","D":"共享——是高质量发展的根本目的，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 4 题"},"stem":"新时代以来，党中央作出一系列重大决策部署，推动高质量发展成为全党全社会的共识和自觉行动，高质量发展成为主旋律。同时，制约高质量发展的因素还大量存在，要高度重视，切实解决。推动高质量发展的内在要求和重要着力点是","choices":[{"id":"A","text":"构建新发展格局"},{"id":"B","text":"发展新质生产力"},{"id":"C","text":"贯彻新发展理念"},{"id":"D","text":"坚持和完善社会主义基本经济制度"}],"answer":["B"],"analysis":{"point":"","options":{"A":"构建新发展格局——是推动高质量发展的战略基点。","B":"发展新质生产力——是推动高质量发展的内在要求和重要着力点，是本题正确答案。","C":"贯彻新发展理念——是实现高质量发展的指导原则。","D":"坚持和完善社会主义基本经济制度——是实现高质量发展的保障。"}}},{"id":"basic-xisixiang-ch06-07-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 5 题"},"stem":"2024年1月31日，习近平在主持二十届中共中央政治局第十一次集体学习时指出，高质量发展需要新的生产力理论来指导，而新质生产力已经在实践中形成并展示出对高质量发展的强劲推动力、支撑力。发展新质生产力的核心要素是","choices":[{"id":"A","text":"高科技、高效能、高质量"},{"id":"B","text":"全要素生产率大幅提升"},{"id":"C","text":"全面深化改革"},{"id":"D","text":"科技创新"}],"answer":["D"],"analysis":{"point":"","options":{"A":"高科技、高效能、高质量是新质生产力的特征。","B":"全要素生产率大幅提升——是新质生产力的核心标志。","C":"全面深化改革——是培育和发展新质生产力的举措。","D":"科技创新——是发展新质生产力的核心要素，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 6 题"},"stem":"全面建成社会主义现代化强国，总的战略安排是分两步走，第一步是从2020年到2035年基本实现社会主义现代化；第二步是从2035年到21世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国。全面建设社会主义现代化国家的首要任务是","choices":[{"id":"A","text":"高质量发展"},{"id":"B","text":"构建新发展格局"},{"id":"C","text":"深化供给侧结构性改革"},{"id":"D","text":"推动经济实现质的有效提升和量的合理增长"}],"answer":["A"],"analysis":{"point":"","options":{"A":"高质量发展是全面建设社会主义现代化国家的首要任务，是本题正确答案。","B":"构建新发展格局是推动高质量发展的战略基点。","C":"深化供给侧结构性改革——是高质量发展的主线。","D":"推动经济实现质的有效提升和量的合理增长——是推动高质量发展的要求。"}}},{"id":"basic-xisixiang-ch06-07-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 7 题"},"stem":"社会主义市场经济体制是中国特色社会主义的重大理论和实践创新，是推动经济发展的重要制度保障。党的二十大将“构建高水平社会主义市场经济体制”作为加快构建新发展格局，着力推动高质量发展的重要战略任务。构建高水平社会主义市场经济体制的关键是","choices":[{"id":"A","text":"大力发展战略性新兴产业"},{"id":"B","text":"加快发展先进制造业"},{"id":"C","text":"要处理好政府和市场的关系"},{"id":"D","text":"保持优势产业的领先地位"}],"answer":["C"],"analysis":{"point":"","options":{"A":"大力发展战略性新兴产业——是培育引领国家未来产业发展的决定性力量的举措。","B":"加快发展先进制造业是提升实体经济的重点。","C":"要处理好政府和市场的关系——是构建高水平社会主义市场经济体制的关键，是本题正确答案。","D":"保持优势产业的领先地位——是支撑我国国际竞争力的基石。"}}},{"id":"basic-xisixiang-ch06-07-8","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 8 题"},"stem":"发展社会主义市场经济，既要发挥市场的作用，也要发挥政府的作用，但市场和政府的作用是不同的。下列属于市场作用的是","choices":[{"id":"A","text":"保持经济稳定"},{"id":"B","text":"保障公平竞争"},{"id":"C","text":"保障共同富裕"},{"id":"D","text":"保证以尽可能少的资源生产尽可能多的产品"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是政府的作用。","B":"是政府的作用。","C":"是政府的作用。","D":"保证以尽可能少的资源生产尽可能多的产品——是市场在资源配置中发挥决定性作用的体现，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-9","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 9 题"},"stem":"习近平总书记对新常态下中国经济的判断一针见血：“结构性问题最突出，矛盾的主要方面在供给侧。”推进供给侧改革是形势所迫，是问题倒逼的必然选择。改革攻坚，这个坎必须跨过去。供给侧结构性改革主要致力于","choices":[{"id":"A","text":"注重短期调控"},{"id":"B","text":"解决总量性问题"},{"id":"C","text":"优化要素配置和调整生产结构"},{"id":"D","text":"调节税收、财政支出、货币信贷"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是需求侧改革的举措。","B":"是需求侧改革的举措。","C":"优化要素配置和调整生产结构——是供给侧结构性改革的举措，是本题正确答案。","D":"是需求侧改革的举措。"}}},{"id":"basic-xisixiang-ch06-07-10","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 10 题"},"stem":"党的二十大报告擘画了以中国式现代化全面推进中华民族伟大复兴的宏伟蓝图，提出“加快构建新发展格局，着力推动高质量发展”。其中，构建新发展格局最本质的特征是","choices":[{"id":"A","text":"着力发展实体经济"},{"id":"B","text":"着力推动产业链供应链优化升级"},{"id":"C","text":"深化供给侧结构性改革"},{"id":"D","text":"实现高水平的自立自强"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是推动构建新发展格局的举措。","B":"是推动构建新发展格局的举措。","C":"深化供给侧结构性改革——是构建新发展格局的主线。","D":"实现高水平的自立自强——是构建新发展格局最本质的特征，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-11","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 11 题"},"stem":"全面建设社会主义现代化国家，最艰巨最繁重的任务依然在农村，最广泛最深厚的基础依然在农村。建设农业强国，必须走中国特色社会主义乡村振兴道路，大力实施乡村振兴战略，全面推进乡村振兴。实施乡村振兴战略的总目标是","choices":[{"id":"A","text":"坚持农业农村优先发展"},{"id":"B","text":"产业兴旺、生态宜居、乡风文明、治理有效、生活富裕"},{"id":"C","text":"建立健全城乡融合发展体制机制和政策体系"},{"id":"D","text":"农业农村现代化"}],"answer":["D"],"analysis":{"point":"","options":{"A":"坚持农业农村优先发展——是实施乡村振兴战略的总方针。","B":"产业兴旺、生态宜居、乡风文明、治理有效、生活富裕是实施乡村振兴战略的总要求。","C":"建立健全城乡融合发展体制机制和政策体系——是实施乡村振兴战略的制度保障。","D":"农业农村现代化——是实施乡村振兴战略的总目标，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-12","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 12 题"},"stem":"“强国必先强农，农强方能国强。没有农业强国就没有整个现代化强国；没有农业农村现代化，社会主义现代化就是不全面的。”党中央着眼全面建成社会主义现代化强国，作出全面推进乡村振兴、加快建设农业强国的战略部署。全面推进乡村振兴、建设农业强国的头等大事是","choices":[{"id":"A","text":"保障粮食和重要农产品稳定安全供给"},{"id":"B","text":"牢牢守住不发生规模性返贫致贫底线"},{"id":"C","text":"发展生态低碳农业"},{"id":"D","text":"加强农业基础设施建设"}],"answer":["A"],"analysis":{"point":"","options":{"A":"保障粮食和重要农产品稳定安全供给——是全面推进乡村振兴、建设农业强国的头等大事，是本题正确答案。","B":"牢牢守住不发生规模性返贫致贫底线是乡村振兴的底线任务。","C":"是全面推进乡村振兴的举措，但不是头等大事。","D":"是全面推进乡村振兴的举措，但不是头等大事。"}}},{"id":"basic-xisixiang-ch06-07-13","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 13 题"},"stem":"教育是强国建设、民族复兴之基。2024年9月9日至10日，全国教育大会在北京召开。习近平指出，建设教育强国是一项复杂的系统工程，需要我们紧紧围绕的根本任务是","choices":[{"id":"A","text":"立德树人"},{"id":"B","text":"人民满意"},{"id":"C","text":"教育公平"},{"id":"D","text":"服务高质量发展"}],"answer":["A"],"analysis":{"point":"","options":{"A":"立德树人——是教育的根本任务，是本题正确答案。","B":"人民满意——是发展教育的根本尺度。","C":"教育公平——是社会公平的重要基础。","D":"服务高质量发展——是建设教育强国的重要任务。"}}},{"id":"basic-xisixiang-ch06-07-14","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 14 题"},"stem":"“嫦娥”揽月，“天和”驻空，“天问”探火，“地壳一号”挺进地球深处，“奋斗者”号探秘万米深海，全球首座第四代核电站商运投产……中国式现代化要靠科技现代化作支撑，实现高质量发展要靠科技创新培育新动能。科技创新的源头是","choices":[{"id":"A","text":"科技体制改革"},{"id":"B","text":"健全新型举国体制"},{"id":"C","text":"基础研究"},{"id":"D","text":"国家战略科技力量"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是打赢关键核心技术攻坚战的举措。","B":"是打赢关键核心技术攻坚战的举措。","C":"基础研究——是科技创新的源头，是本题正确答案。","D":"国家战略科技力量——是世界科技强国竞争的着力点。"}}},{"id":"basic-xisixiang-ch06-07-15","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 15 题"},"stem":"高质量发展，是能够很好满足人民日益增长的美好生活需要的发展，是体现新发展理念的发展，是创新成为第一动力、协调成为内生特点、绿色成为普遍形态、开放成为必由之路、共享成为根本目的的发展。从供给看，高质量发展要求","choices":[{"id":"A","text":"产业体系比较完整"},{"id":"B","text":"生产组织方式网络化、智能化，创新力强"},{"id":"C","text":"产品和服务质量高"},{"id":"D","text":"不断满足人民群众个性化、多样化、不断升级的需求"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是从供给看，高质量发展的要求，是本题正确答案。","B":"是从供给看，高质量发展的要求，是本题正确答案。","C":"是从供给看，高质量发展的要求，是本题正确答案。","D":"是从需求看，高质量发展的要求。"}}},{"id":"basic-xisixiang-ch06-07-16","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 16 题"},"stem":"高质量发展是全面建设社会主义现代化国家的首要任务，是谋求国家发展和推动民族复兴的必由之路。在全面建设社会主义现代化国家的进程中，必须把握新发展阶段的特征与要求，完整、准确、全面贯彻新发展理念，加快构建新发展格局，坚持以高质量发展推进中国式现代化。高质量发展关系我国社会主义现代化建设全局，具有重大战略意义，主要体现在高质量发展","choices":[{"id":"A","text":"为全面建设社会主义现代化国家提供更为坚实的物质基础"},{"id":"B","text":"是我国经济发展和经济工作的主线"},{"id":"C","text":"是不断满足人民对美好生活需要的重要保证"},{"id":"D","text":"是维护国家长治久安的必然要求"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是高质量发展的重大战略意义，是本题正确答案。","B":"是供给侧结构性改革的地位。","C":"是高质量发展的重大战略意义，是本题正确答案。","D":"是高质量发展的重大战略意义，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-17","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 17 题"},"stem":"社会主义基本经济制度是中国特色社会主义制度的重要支柱，是新时代推动实现高质量发展的制度基础。党的十八大以来，以习近平同志为核心的党中央着眼于更好发挥社会主义制度优越性、推动高质量发展，对社会主义基本经济制度作出新概括。我国的社会主义基本经济制度包括","choices":[{"id":"A","text":"公有制为主体、多种所有制经济共同发展"},{"id":"B","text":"按劳分配为主体、多种分配方式并存"},{"id":"C","text":"人民代表大会制度"},{"id":"D","text":"社会主义市场经济体制"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是我国社会主义基本经济制度的内容，是本题正确答案。","B":"是我国社会主义基本经济制度的内容，是本题正确答案。","C":"人民代表大会制度——是我国的根本政治制度。","D":"是我国社会主义基本经济制度的内容，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-18","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 18 题"},"stem":"社会主义基本经济制度的新概括，充分体现了我们党对我国经济发展规律的深刻认识和科学把握。这一新概括，包括所有制、分配制度、资源配置体制机制等方面。下列关于这三方面关系的表述，正确的有","choices":[{"id":"A","text":"所有制结构是基本经济制度的基础，决定分配方式和资源配置方式"},{"id":"B","text":"合理有效的分配方式和资源配置方式有利于进一步完善所有制结构"},{"id":"C","text":"这三个方面对经济制度属性和经济发展方式有决定性影响"},{"id":"D","text":"这三个方面是新时代推动经济高质量发展的制度支撑"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是关于我国社会主义基本经济制度新概括的三方面关系的科学表述，是本题正确答案。","B":"是关于我国社会主义基本经济制度新概括的三方面关系的科学表述，是本题正确答案。","C":"是关于我国社会主义基本经济制度新概括的三方面关系的科学表述，是本题正确答案。","D":"是关于我国社会主义基本经济制度新概括的三方面关系的科学表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-19","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 19 题"},"stem":"公有制经济和非公有制经济都是社会主义市场经济的重要组成部分，都是我国经济社会发展的重要基础。要毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。我国的公有制经济包括","choices":[{"id":"A","text":"国有经济"},{"id":"B","text":"集体经济"},{"id":"C","text":"个体经济"},{"id":"D","text":"私营经济"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是我国公有制经济的重要组成部分，是本题正确答案。","B":"是我国公有制经济的重要组成部分，是本题正确答案。","C":"是我国非公有制经济的重要组成部分。","D":"是我国非公有制经济的重要组成部分。"}}},{"id":"basic-xisixiang-ch06-07-20","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 20 题"},"stem":"全面深化改革在各个领域不断推进，在国企改革领域也不例外。目前的国企改革，不仅强调效率，更要“双聚焦、双核心”，即“增强核心竞争力、增强核心功能”。我国高度重视国企改革，因为国有企业是","choices":[{"id":"A","text":"中国特色社会主义的重要物质基础"},{"id":"B","text":"中国特色社会主义的政治基础"},{"id":"C","text":"推进中国式现代化的生力军"},{"id":"D","text":"我们党执政兴国的依靠力量"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是我国高度重视国企改革的依据，也是国有企业的地位，是本题正确答案。","B":"是我国高度重视国企改革的依据，也是国有企业的地位，是本题正确答案。","C":"推进中国式现代化的生力军——是民营经济。","D":"是我国高度重视国企改革的依据，也是国有企业的地位，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-21","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 21 题"},"stem":"宏观调控是党和国家治理经济的重要方式，体现了中国特色社会主义制度的独特优势。宏观调控的主要任务是","choices":[{"id":"A","text":"保持经济总量平衡"},{"id":"B","text":"促进重大经济结构协调和生产力布局优化"},{"id":"C","text":"防范区域性、系统性风险"},{"id":"D","text":"稳定市场预期，实现经济持续健康发展"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是宏观调控的主要任务，是本题正确答案。","B":"是宏观调控的主要任务，是本题正确答案。","C":"是宏观调控的主要任务，是本题正确答案。","D":"是宏观调控的主要任务，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-22","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 22 题"},"stem":"党的二十大报告提出，“加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局”。构建新发展格局是","choices":[{"id":"A","text":"把握未来发展主动权的战略部署"},{"id":"B","text":"关系我国发展全局的重大战略任务"},{"id":"C","text":"新时代我国经济社会发展的鲜明主题"},{"id":"D","text":"推动高质量发展的战略基点"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是构建新发展格局的意义，是本题正确答案。","B":"是构建新发展格局的意义，是本题正确答案。","C":"新时代我国经济社会发展的鲜明主题——是高质量发展。","D":"是构建新发展格局的意义，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-23","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 23 题"},"stem":"现代化产业体系是国家经济现代化的重要标志。加快建设以实体经济为支撑的现代化产业体系，关系我们在未来发展和国际竞争中赢得战略主动。实体经济是","choices":[{"id":"A","text":"一国经济的立身之本、财富之源"},{"id":"B","text":"构筑未来发展战略优势的重要支撑"},{"id":"C","text":"发展经济的着力点"},{"id":"D","text":"全面建设社会主义现代化国家的基础性、战略性支撑"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是实体经济的重要地位，是本题正确答案。","B":"是实体经济的重要地位，是本题正确答案。","C":"是实体经济的重要地位，是本题正确答案。","D":"全面建设社会主义现代化国家的基础性、战略性支撑——是教育、科技、人才。"}}},{"id":"basic-xisixiang-ch06-07-24","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 24 题"},"stem":"党的二十大报告强调：“未来五年是全面建设社会主义现代化国家开局起步的关键时期。”要想开辟发展新领域新赛道，不断塑造发展新动能新优势，就必须不断强化全面建设社会主义现代化国家的基础性、战略性支撑。必须坚持","choices":[{"id":"A","text":"创新是第一动力"},{"id":"B","text":"科技是第一生产力"},{"id":"C","text":"社保是第一兜底"},{"id":"D","text":"人才是第一资源"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是强调教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑必须坚持的理念，是本题正确答案。","B":"是强调教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑必须坚持的理念，是本题正确答案。","C":"社保是第一兜底非考点。","D":"是强调教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑必须坚持的理念，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-25","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 25 题"},"stem":"2024年9月9日至10日，全国教育大会在北京召开。会上，习近平指出，教育是强国建设、民族复兴之基。党的十八大以来，我们坚持把教育作为国之大计、党之大计，确立到2035年建成教育强国的奋斗目标，不断推进教育体制机制改革，推动新时代教育事业取得历史性成就、发生格局性变化，教育强国建设迈出坚实步伐。建设教育强国是","choices":[{"id":"A","text":"世界科技强国竞争的着力点"},{"id":"B","text":"全面建成社会主义现代化强国的战略先导"},{"id":"C","text":"实现高水平科技自立自强的重要支撑"},{"id":"D","text":"促进全体人民共同富裕的有效途径"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"世界科技强国竞争的着力点——是国家战略科技力量。","B":"是建设教育强国的意义，是本题正确答案。","C":"是建设教育强国的意义，是本题正确答案。","D":"是建设教育强国的意义，是本题正确答案。"}}},{"id":"basic-xisixiang-ch06-07-26","moduleId":"basic","subjectId":"xisixiang","chapter":"第六~七章 高质量发展与战略支撑","chapterKey":"第六~七章","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第六~七章 第 26 题"},"stem":"2024年10月，国家统计局、科学技术部和财政部联合发布了《2023年全国科技经费投入统计公报》（简称《公报》)。《公报》数据显示，目前我国研究与试验发展经费总量仅次于美国，位居世界第二位。研究与试验发展经费投入持续加大，为我国加快实现高水平科技自立自强提供了有力保障。实现高水平科技自立自强是","choices":[{"id":"A","text":"应对风险挑战和维护国家利益的必然选择"},{"id":"B","text":"构建新发展格局、推动高质量发展的内在要求"},{"id":"C","text":"国家强盛和民族复兴的战略基石"},{"id":"D","text":"全面建成社会主义现代化强国的战略先导"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是实现高水平科技自立自强的意义，是本题正确答案。","B":"是实现高水平科技自立自强的意义，是本题正确答案。","C":"是实现高水平科技自立自强的意义，是本题正确答案。","D":"全面建成社会主义现代化强国的战略先导——是建设教育强国。"}}},{"id":"basic-xisixiang-ch08-09-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 1 题"},"stem":"习近平总书记强调：“中国特色社会主义是不是好，要看事实，要看中国人民的判断，而不是看那些戴着有色眼镜的人的主观臆断。中国共产党人和中国人民完全有信心为人类对更好社会制度的探索提供中国方案。”坚定中国特色社会主义制度自信，首先要坚定","choices":[{"id":"A","text":"对中国特色社会主义经济制度的自信"},{"id":"B","text":"对中国特色社会主义政治制度的自信"},{"id":"C","text":"对中国特色社会主义文化制度的自信"},{"id":"D","text":"对中国特色社会主义生态制度的自信"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是中国特色社会主义制度自信的表现，但不是首先要坚定的自信。","B":"对中国特色社会主义政治制度的自信——是坚定中国特色社会主义制度自信首先要坚定的自信，是本题正确答案。","C":"是中国特色社会主义制度自信的表现，但不是首先要坚定的自信。","D":"是中国特色社会主义制度自信的表现，但不是首先要坚定的自信。"}}},{"id":"basic-xisixiang-ch08-09-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 2 题"},"stem":"马克思主义认为，民主首先而且主要是一种国家制度。人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义。作为最广泛、最真实、最管用的民主，全过程人民民主是","choices":[{"id":"A","text":"社会主义民主政治的本质属性"},{"id":"B","text":"社会主义的本质"},{"id":"C","text":"中国特色社会主义最本质的特征"},{"id":"D","text":"社会主义的根本任务"}],"answer":["A"],"analysis":{"point":"","options":{"A":"社会主义民主政治的本质属性——是全过程人民民主，是本题正确答案。","B":"社会主义的本质——是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。","C":"中国特色社会主义最本质的特征——是中国共产党领导。","D":"社会主义的根本任务是发展生产力。"}}},{"id":"basic-xisixiang-ch08-09-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 3 题"},"stem":"中国共产党领导的多党合作和政治协商制度是中国共产党、中国人民和各民主党派、无党派人士的伟大政治创造。人民政协的主题是","choices":[{"id":"A","text":"长期共存、互相监督、肝胆相照、荣辱与共"},{"id":"B","text":"团结和民主"},{"id":"C","text":"政治协商、民主监督、参政议政"},{"id":"D","text":"大团结大联合"}],"answer":["B"],"analysis":{"point":"","options":{"A":"长期共存、互相监督、肝胆相照、荣辱与共——是中国共产党同各民主党派合作的基本方针。","B":"团结和民主——是人民政协的主题，是本题正确答案。","C":"政治协商、民主监督、参政议政是人民政协的职能。","D":"大团结大联合是统战工作的本质要求。"}}},{"id":"basic-xisixiang-ch08-09-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 4 题"},"stem":"西藏自治区成立60多年来，通过实行民族区域自治制度，从落后走向进步，从贫穷走向富裕，从封闭走向开放，社会制度实现了历史性的跨越。今天的西藏，社会稳定、经济发展、民生改善、生态向好，各方面成绩卓著。实践证明，民族区域自治制度是适合民族地区特点、具有中国特色的一项基本政治制度。民族区域自治的核心是","choices":[{"id":"A","text":"保障少数民族当家作主，管理本民族本地方事务的权利"},{"id":"B","text":"实现各民族平等、团结、合作和共同繁荣"},{"id":"C","text":"汉族离不开少数民族，少数民族离不开汉族"},{"id":"D","text":"凝聚力量，增进共识"}],"answer":["A"],"analysis":{"point":"","options":{"A":"保障少数民族当家作主，管理本民族本地方事务的权利——是民族区域自治的核心，是本题正确答案。","B":"实现各民族平等、团结、合作和共同繁荣——是我国处理民族问题的基本原则。","C":"是我国处理民族关系的指导思想。","D":"是我国处理民族关系的指导思想。"}}},{"id":"basic-xisixiang-ch08-09-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 5 题"},"stem":"实行人民民主，保证人民当家作主，实现形式是丰富多样的。经过长期探索，我国在通过依法选举让人民的代表来参与国家生活和社会生活管理的同时，找到了一种保证人民在日常政治生活中有广泛持续深入参与权利的特有民主形式。这一特有民主形式是","choices":[{"id":"A","text":"谈判民主"},{"id":"B","text":"协商民主"},{"id":"C","text":"票决民主"},{"id":"D","text":"竞争性民主"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是西方民主也会采用的形式，并非我国社会主义民主的特有形式。","B":"协商民主——是我国社会主义民主政治的特有形式和独特优势，是本题正确答案。","C":"是西方民主也会采用的形式，并非我国社会主义民主的特有形式。","D":"是西方民主也会采用的形式，并非我国社会主义民主的特有形式。"}}},{"id":"basic-xisixiang-ch08-09-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 6 题"},"stem":"统一战线是中国共产党夺取革命、建设、改革事业胜利的重要法宝，也是实现中华民族伟大复兴的重要法宝。统一战线最核心最根本的问题是","choices":[{"id":"A","text":"大团结大联合"},{"id":"B","text":"坚持求同存异"},{"id":"C","text":"壮大共同奋斗的力量"},{"id":"D","text":"坚持党的领导"}],"answer":["D"],"analysis":{"point":"","options":{"A":"大团结大联合——是统战工作的本质要求。","B":"坚持求同存异是统战工作的关键。","C":"壮大共同奋斗的力量是统战工作的目的。","D":"坚持党的领导——是统一战线最核心最根本的问题，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 7 题"},"stem":"党的十八大以来，我们党不断推进马克思主义民族理论中国化时代化，鲜明提出了新时代党的民族工作的主线、民族地区各项工作的主线，推动党的民族工作取得新的历史性成就。这一主线是","choices":[{"id":"A","text":"坚持民族平等、民族团结、各民族共同繁荣"},{"id":"B","text":"坚持民族区域自治制度"},{"id":"C","text":"保持各民族大杂居、小聚居的分布特点"},{"id":"D","text":"铸牢中华民族共同体意识"}],"answer":["D"],"analysis":{"point":"","options":{"A":"坚持民族平等、民族团结、各民族共同繁荣——是我国处理民族问题的基本原则。","B":"民族区域自治制度是中国特色解决民族问题的正确道路的重要内容和制度保障。","C":"保持各民族大杂居、小聚居的分布特点——是我国实行民族区域自治制度的现实依据。","D":"铸牢中华民族共同体意识——是新时代党的民族工作的主线，也是民族地区各项工作的主线，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-8","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 8 题"},"stem":"全面依法治国涉及一系列重大关系、利益格局和体制机制问题。其中，政治和法治关系的集中反映是","choices":[{"id":"A","text":"党和法的关系"},{"id":"B","text":"改革和法治的关系"},{"id":"C","text":"依法治国和以德治国的关系"},{"id":"D","text":"依法治国和依规治党的关系"}],"answer":["A"],"analysis":{"point":"","options":{"A":"党和法的关系是政治和法治关系的集中反映，是本题正确答案。","B":"是全面依法治国必须正确处理的重大关系。","C":"是全面依法治国必须正确处理的重大关系。","D":"是全面依法治国必须正确处理的重大关系。"}}},{"id":"basic-xisixiang-ch08-09-9","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 9 题"},"stem":"习近平指出：“全面推进依法治国涉及很多方面，在实际工作中必须有一个总揽全局、牵引各方的总抓手。”这个总抓手是","choices":[{"id":"A","text":"依法保障人民权益"},{"id":"B","text":"建设中国特色社会主义法治体系"},{"id":"C","text":"建设社会主义法治国家"},{"id":"D","text":"全面贯彻实施宪法"}],"answer":["B"],"analysis":{"point":"","options":{"A":"依法保障人民权益是推进全面依法治国的根本目的。","B":"建设中国特色社会主义法治体系——是全面推进依法治国的总抓手，是本题正确答案。","C":"建设社会主义法治国家——是全面推进依法治国的目标。","D":"全面贯彻实施宪法——是全面依法治国的首要任务。"}}},{"id":"basic-xisixiang-ch08-09-10","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 10 题"},"stem":"建设法治中国的总体目标，就是实现法律规范科学完备统一，执法司法公正高效权威，权力运行受到有效制约监督，人民合法权益得到充分尊重保障，法治信仰普遍确立，法治国家、法治政府、法治社会全面建成。具体来说，就是到2035年","choices":[{"id":"A","text":"中国特色社会主义法治体系初步形成"},{"id":"B","text":"法治国家、法治政府、法治社会基本建成"},{"id":"C","text":"职责明确、依法行政的政府治理体系日益健全"},{"id":"D","text":"相互配合、相互制约的司法权运行机制更加科学有效"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是建设法治中国到2025年的奋斗目标。","B":"法治国家、法治政府、法治社会基本建成——是建设法治中国到2035年的奋斗目标，是本题正确答案。","C":"是建设法治中国到2025年的奋斗目标。","D":"是建设法治中国到2025年的奋斗目标。"}}},{"id":"basic-xisixiang-ch08-09-11","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 11 题"},"stem":"人民民主建立在社会主义经济基础之上，体现了社会主义国家的性质，反映了社会主义制度的本质要求。人民民主是","choices":[{"id":"A","text":"社会主义的生命"},{"id":"B","text":"全面建设社会主义现代化国家的应有之义"},{"id":"C","text":"党领导人民治理国家的基本方式"},{"id":"D","text":"跳出历史周期率的第一个答案"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是关于人民民主的重要性的正确表述，是本题正确答案。","B":"是关于人民民主的重要性的正确表述，是本题正确答案。","C":"党领导人民治理国家的基本方式是依法治国。","D":"是关于人民民主的重要性的正确表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-12","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 12 题"},"stem":"中国特色社会主义政治发展道路，是党领导中国人民长期奋斗历史逻辑、理论逻辑、实践逻辑的必然结果，是坚持党的本质属性、践行党的根本宗旨的必然要求。走中国特色社会主义政治发展道路","choices":[{"id":"A","text":"最根本的是坚持党的领导"},{"id":"B","text":"必须积极稳妥推进政治体制改革"},{"id":"C","text":"必须始终保持政治定力"},{"id":"D","text":"必须坚持党的领导、人民当家作主、依法治国有机统一"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是走中国特色社会主义政治发展道路的要求，是本题正确答案。","B":"是走中国特色社会主义政治发展道路的要求，是本题正确答案。","C":"是走中国特色社会主义政治发展道路的要求，是本题正确答案。","D":"是走中国特色社会主义政治发展道路的要求，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-13","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 13 题"},"stem":"中国特色社会主义进入新时代以来，我们深化了对民主政治发展规律的认识，提出全过程人民民主的重大理念。我国全过程人民民主不仅有完整的制度程序，而且有完整的参与实践。全过程人民民主，起始于人民意愿充分表达，落实于人民意愿有效实现，实现了","choices":[{"id":"A","text":"过程民主和成果民主相统一"},{"id":"B","text":"程序民主和实质民主相统一"},{"id":"C","text":"直接民主和间接民主相统一"},{"id":"D","text":"人民民主和国家意志相统一"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是对全过程人民民主的科学评价，是本题正确答案。","B":"是对全过程人民民主的科学评价，是本题正确答案。","C":"是对全过程人民民主的科学评价，是本题正确答案。","D":"是对全过程人民民主的科学评价，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-14","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 14 题"},"stem":"我国的国家各项制度都是围绕人民当家作主构建的，国家治理体系都是围绕实现人民当家作主运转的，全过程人民民主具有完整的制度程序。这些制度程序，形成了全面、广泛、有机衔接的人民当家作主制度体系。这一制度体系包括","choices":[{"id":"A","text":"人民代表大会制度"},{"id":"B","text":"中国共产党领导的多党合作和政治协商制度"},{"id":"C","text":"民族区域自治制度"},{"id":"D","text":"基层群众自治制度"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"人民代表大会制度——是我国的根本政治制度，是本题正确答案。","B":"是我国的基本政治制度，是本题正确答案。","C":"是我国的基本政治制度，是本题正确答案。","D":"是我国的基本政治制度，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-15","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 15 题"},"stem":"中国特色社会主义政治制度是由根本政治制度、基本政治制度、重要政治制度等组成的制度体系。它们的关系是","choices":[{"id":"A","text":"重要政治制度是建立在我国根本政治制度和基本政治制度基础上的"},{"id":"B","text":"重要政治制度是由根本政治制度和基本政治制度派生而来的"},{"id":"C","text":"重要政治制度与我国根本政治制度、基本政治制度相衔接"},{"id":"D","text":"共同构成了中国特色社会主义政治制度的四梁八柱"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是关于我国根本政治制度、基本政治制度、重要政治制度的关系的科学表述，是本题正确答案。","B":"是关于我国根本政治制度、基本政治制度、重要政治制度的关系的科学表述，是本题正确答案。","C":"是关于我国根本政治制度、基本政治制度、重要政治制度的关系的科学表述，是本题正确答案。","D":"是关于我国根本政治制度、基本政治制度、重要政治制度的关系的科学表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-16","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 16 题"},"stem":"1949年9月，中国人民政治协商会议第一届全体会议代行全国人民代表大会的职权，代表全国人民的意志，宣告中华人民共和国的成立。新中国成立后，中国人民政治协商会议继续在国家的政治生活和社会生活以及对外友好活动中进行了许多工作，在推进改革开放和社会主义现代化建设，争取实现祖国统一，反对霸权主义、维护世界和平的斗争中，进一步发挥了重要作用。中国人民政治协商会议是","choices":[{"id":"A","text":"社会主义民主政治建设的基础"},{"id":"B","text":"社会主义协商民主的重要渠道和专门协商机构"},{"id":"C","text":"爱国统一战线组织"},{"id":"D","text":"具有中国特色的制度安排"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"社会主义民主政治建设的基础是基层群众自治制度。","B":"是关于中国人民政治协商会议的正确表述，是本题正确答案。","C":"是关于中国人民政治协商会议的正确表述，是本题正确答案。","D":"是关于中国人民政治协商会议的正确表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch08-09-17","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 17 题"},"stem":"党的二十届三中全会通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》强调，发展全过程人民民主是中国式现代化的本质要求，并对健全全过程人民民主制度体系作出部署，提出健全基层民主制度的任务。发展基层民主是","choices":[{"id":"A","text":"实现人民有效政治参与的重要渠道"},{"id":"B","text":"人民当家作主的有效途径"},{"id":"C","text":"社会主义民主最广泛的实践"},{"id":"D","text":"实现全过程人民民主的重要制度载体"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是发展基层民主的重要意义，是本题正确答案。","B":"是发展基层民主的重要意义，是本题正确答案。","C":"是发展基层民主的重要意义，是本题正确答案。","D":"实现全过程人民民主的重要制度载体——是人民代表大会制度。"}}},{"id":"basic-xisixiang-ch08-09-18","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 18 题"},"stem":"2015年召开的中央统战工作会议强调，我们党所处的历史方位、所面临的内外形势、所肩负的使命任务发生了重大变化。越是变化大，越是要把统一战线发展好、把统战工作开展好。统一战线作为党的一项长期方针，决不能动摇。中国共产党之所以高度重视统战工作，因为统一战线是","choices":[{"id":"A","text":"夺取革命、建设和改革事业胜利的重要法宝"},{"id":"B","text":"实现中华民族伟大复兴的重要法宝"},{"id":"C","text":"中国共产党的一大政治优势"},{"id":"D","text":"人民当家作主的根本保证"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是关于统一战线的正确表述，是本题正确答案。","B":"是关于统一战线的正确表述，是本题正确答案。","C":"是关于统一战线的正确表述，是本题正确答案。","D":"人民当家作主的根本保证——是中国共产党的领导。"}}},{"id":"basic-xisixiang-ch08-09-19","moduleId":"basic","subjectId":"xisixiang","chapter":"第八~九章 社会主义民主政治与法治建设","chapterKey":"第八~九章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第八~九章 第 19 题"},"stem":"我国法治建设的成就可以列举出十几条、几十条，但归结起来就是开辟了中国特色社会主义法治道路这一条。中国特色社会主义法治道路的核心要义，就是要","choices":[{"id":"A","text":"坚持党的领导"},{"id":"B","text":"坚持中国特色社会主义制度"},{"id":"C","text":"坚持法律面前人人平等"},{"id":"D","text":"贯彻中国特色社会主义法治理论"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是中国特色社会主义法治道路的核心要义，是本题正确答案。","B":"是中国特色社会主义法治道路的核心要义，是本题正确答案。","C":"坚持法律面前人人平等——是坚持和拓展中国特色社会主义法治道路的原则。","D":"是中国特色社会主义法治道路的核心要义，是本题正确答案。"}}},{"id":"basic-xisixiang-ch10-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 1 题"},"stem":"习近平指出：“如果没有中华五千年文明，哪里有什么中国特色？如果不是中国特色，哪有我们今天这么成功的中国特色社会主义道路？”一个国家、一个民族发展中最基本、最深沉、最持久的力量是","choices":[{"id":"A","text":"道路自信"},{"id":"B","text":"理论自信"},{"id":"C","text":"制度自信"},{"id":"D","text":"文化自信"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是“四个自信”的内容，但不是最基本、最深沉、最持久的力量。","B":"是“四个自信”的内容，但不是最基本、最深沉、最持久的力量。","C":"是“四个自信”的内容，但不是最基本、最深沉、最持久的力量。","D":"文化自信——是更基础、更广泛、更深厚的自信，是一个国家、一个民族发展中最基本、最深沉、最持久的力量，是本题正确答案。"}}},{"id":"basic-xisixiang-ch10-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 2 题"},"stem":"文化是一个国家、一个民族的灵魂。国家的富强，民族的振兴，无不伴随着文化的历史性进步。建设社会主义文化强国、推动社会主义文化繁荣兴盛，关键在于","choices":[{"id":"A","text":"坚持百花齐放、百家争鸣"},{"id":"B","text":"坚持为人民服务、为社会主义服务"},{"id":"C","text":"坚定中国特色社会主义文化自信"},{"id":"D","text":"坚定创新创造"}],"answer":["C"],"analysis":{"point":"","options":{"A":"坚持百花齐放、百家争鸣——是繁荣发展社会主义文化的重要方针。","B":"坚持为人民服务、为社会主义服务——是决定社会主义文化事业前途命运的关键。","C":"坚定中国特色社会主义文化自信——是建设社会主义文化强国、推动社会主义文化繁荣兴盛的关键，是本题正确答案。","D":"创新创造是文化的生命所在。"}}},{"id":"basic-xisixiang-ch10-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 3 题"},"stem":"“当今世界，要说哪个政党、哪个国家、哪个民族能够自信的话，那中国共产党、中华人民共和国、中华民族是最有理由自信的。”我们坚定文化自信的深厚基础是","choices":[{"id":"A","text":"中华优秀传统文化"},{"id":"B","text":"中国特色社会主义伟大实践"},{"id":"C","text":"革命文化"},{"id":"D","text":"社会主义先进文化"}],"answer":["A"],"analysis":{"point":"","options":{"A":"中华优秀传统文化——是我们坚定文化自信的深厚基础，是本题正确答案。","B":"中国特色社会主义伟大实践——是我们坚定文化自信的现实基础。","C":"是我们坚定文化自信的坚强基石。","D":"是我们坚定文化自信的坚强基石。"}}},{"id":"basic-xisixiang-ch10-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 4 题"},"stem":"习近平强调：“没有先进文化的积极引领，没有人民精神世界的极大丰富，没有民族精神力量的不断增强，一个国家、一个民族不可能屹立于世界民族之林。”中国特色社会主义文化发展道路，是推动社会主义文化繁荣兴盛的唯一正确道路。决定社会主义文化事业前途命运的关键是","choices":[{"id":"A","text":"坚定中国特色社会主义文化自信"},{"id":"B","text":"推动中华优秀传统文化创造性转化、创新性发展"},{"id":"C","text":"弘扬革命文化和社会主义先进文化"},{"id":"D","text":"坚持为人民服务、为社会主义服务的根本方向"}],"answer":["D"],"analysis":{"point":"","options":{"A":"坚定中国特色社会主义文化自信——是建设社会主义文化强国、推动社会主义文化繁荣兴盛的关键。","B":"推动中华优秀传统文化创造性转化、创新性发展——是我们坚定文化自信的深厚基础。","C":"弘扬革命文化和社会主义先进文化——是我们坚定文化自信的坚强基石。","D":"坚持为人民服务、为社会主义服务的根本方向——是决定社会主义文化事业前途命运的关键，是本题正确答案。"}}},{"id":"basic-xisixiang-ch10-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 5 题"},"stem":"加强马克思主义理论建设，是不断巩固马克思主义在意识形态领域的指导地位、不断巩固全党全国人民团结奋斗的共同思想基础的必然要求。当代中国哲学社会科学区别于其他哲学社会科学的根本标志是","choices":[{"id":"A","text":"全体人民共同富裕"},{"id":"B","text":"勇于自我革命"},{"id":"C","text":"坚持以马克思主义为指导"},{"id":"D","text":"人民立场"}],"answer":["C"],"analysis":{"point":"","options":{"A":"全体人民共同富裕——是中国式现代化区别于西方现代化的显著标志。","B":"勇于自我革命——是中国共产党区别于其他政党的最显著标志，也是我们党最大的优势、最鲜明的品格。","C":"坚持以马克思主义为指导——是当代中国哲学社会科学区别于其他哲学社会科学的根本标志，是本题正确答案。","D":"人民立场——是中国共产党的根本政治立场，是我们党区别于其他政党的显著标志。"}}},{"id":"basic-xisixiang-ch10-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 6 题"},"stem":"新闻舆论工作处在意识形态斗争前沿，是治国理政、定国安邦的大事。新形势下做好新闻舆论工作的关键是","choices":[{"id":"A","text":"管好用好互联网"},{"id":"B","text":"坚持正确的政治方向"},{"id":"C","text":"新闻媒体"},{"id":"D","text":"核心价值观"}],"answer":["A"],"analysis":{"point":"","options":{"A":"管好用好互联网——是新形势下做好新闻舆论工作的关键，是本题正确答案。","B":"坚持正确的政治方向——是做好新闻舆论工作的第一位要求。","C":"新闻媒体——是社会舆论的发射器和放大器。","D":"核心价值观——是一个民族赖以维系的精神纽带，是一个国家共同的思想道德基础。"}}},{"id":"basic-xisixiang-ch10-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 7 题"},"stem":"中华优秀传统文化有很多重要元素，共同塑造出中华文明的突出特性，即连续性、创新性、统一性、包容性、和平性。其中，从根本上决定了中华民族必然走自己的路的突出特性是","choices":[{"id":"A","text":"连续性"},{"id":"B","text":"创新性"},{"id":"C","text":"统一性"},{"id":"D","text":"包容性"}],"answer":["A"],"analysis":{"point":"","options":{"A":"连续性——从根本上决定了中华民族必然走自己的路，是本题正确答案。","B":"创新性从根本上决定了中华民族守正不守旧、尊古不复古的进取精神，决定了中华民族不惧新挑战、勇于接受新事物的无畏品格。","C":"统一性——从根本上决定了中华民族各民族文化融为一体、即使遭遇重大挫折也牢固凝聚，决定了国土不可分、国家不可乱、民族不可散、文明不可断的共同信念，决定了国家统一永远是中国核心利益的核心，决定了一个坚强统一的国家是各族人民的命运所系。","D":"包容性——从根本上决定了中华民族交往交流交融的历史取向，决定了中国各宗教信仰多元并存的和谐格局，决定了中华文化对世界文明兼收并蓄的开放胸怀。"}}},{"id":"basic-xisixiang-ch10-8","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 8 题"},"stem":"繁荣发展文化事业和文化产业，是满足人民精神文化需求、保障人民文化权益的基本途径。其中，繁荣发展文化产业，必须坚持放在首位的是","choices":[{"id":"A","text":"社会效益"},{"id":"B","text":"经济效益"},{"id":"C","text":"人文效益"},{"id":"D","text":"产业效益"}],"answer":["A"],"analysis":{"point":"","options":{"A":"社会效益——是繁荣发展文化产业必须坚持放在首位的效益，是本题正确答案。","B":"经济效益——是坚持把社会效益放在首位的同时必须兼顾、努力实现统一的效益。","C":"非考点。","D":"非考点。"}}},{"id":"basic-xisixiang-ch10-9","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 9 题"},"stem":"文化软实力集中体现了一个国家基于文化而具有的凝聚力和生命力，以及由此产生的吸引力和影响力。一个国家的文化软实力，从根本上说，取决于","choices":[{"id":"A","text":"实施公民道德建设工程"},{"id":"B","text":"核心价值观的生命力、凝聚力、感召力"},{"id":"C","text":"举精神旗帜、立精神支柱、建精神家园"},{"id":"D","text":"发展文化事业、提升公共文化服务水平"}],"answer":["B"],"analysis":{"point":"","options":{"A":"实施公民道德建设工程——是不断提高全体人民道德素质的灵魂工程。","B":"核心价值观的生命力、凝聚力、感召力——是一个国家的文化软实力的根本决定因素，是本题正确答案。","C":"举精神旗帜、立精神支柱、建精神家园——是当代中国文艺的崇高使命。","D":"发展文化事业、提升公共文化服务水平——是保障人民文化权益、改善人民生活品质、补齐文化发展短板的重要途径。"}}},{"id":"basic-xisixiang-ch10-10","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 10 题"},"stem":"新中国成立以来，我国文化进出口规模持续扩大，结构不断优化，中华文化“走出去”步伐加快。2012年我国文化产品进出口总额为887.5亿美元，2023年达到1621.8亿美元。我国与“一带一路”共建国家和地区文化产品进出口总额由2012年的129.1亿美元增加到2023年的484.5亿美元。新话语、新形式助推文化交流国际化水平进一步提高，国家文化软实力、中华文化感召力、国际传播影响力显著提升。文化繁荣兴盛是","choices":[{"id":"A","text":"建设社会主义现代化强国的应有之义"},{"id":"B","text":"社会主义生产的根本目的"},{"id":"C","text":"实现中华民族伟大复兴的精神支撑"},{"id":"D","text":"在世界文化激荡中站稳脚跟的前提基础"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是文化繁荣兴盛的意义，是本题正确答案。","B":"社会主义生产的根本目的——是增进民生福祉。","C":"是文化繁荣兴盛的意义，是本题正确答案。","D":"是文化繁荣兴盛的意义，是本题正确答案。"}}},{"id":"basic-xisixiang-ch10-11","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 11 题"},"stem":"坚定文化自信，是事关国运兴衰、事关文化安全、事关民族精神独立性的大问题。坚定中国特色社会主义道路自信、理论自信、制度自信，说到底就是要坚定文化自信。讲文化自信，我们有充分理由和充足底气，因为中国特色社会主义文化","choices":[{"id":"A","text":"熔铸于生机勃勃的社会主义先进文化"},{"id":"B","text":"承继于激昂向上的革命文化"},{"id":"C","text":"源自博大精深的中华优秀传统文化"},{"id":"D","text":"植根于中国特色社会主义伟大实践"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是我们坚定文化自信的依据和来源，是本题正确答案。","B":"是我们坚定文化自信的依据和来源，是本题正确答案。","C":"是我们坚定文化自信的依据和来源，是本题正确答案。","D":"是我们坚定文化自信的依据和来源，是本题正确答案。"}}},{"id":"basic-xisixiang-ch10-12","moduleId":"basic","subjectId":"xisixiang","chapter":"第十章 建设社会主义文化强国","chapterKey":"第十章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十章 第 12 题"},"stem":"没有文化事业和文化产业的发展，文化资源就不可能转变为现实的文化力量。发展文化事业和文化产业，要体现社会主义的制度特色。发展文化产业，就是要","choices":[{"id":"A","text":"坚持市场主导"},{"id":"B","text":"践行公益性、基本性、均等性、便利性的要求"},{"id":"C","text":"满足人民群众的基本精神文化需求"},{"id":"D","text":"努力实现社会效益和经济效益的统一"}],"answer":["A","D"],"analysis":{"point":"","options":{"A":"是发展文化产业的导向和基本要求，是本题正确答案。","B":"是发展文化事业的导向和基本要求。","C":"是发展文化事业的导向和基本要求。","D":"是发展文化产业的导向和基本要求，是本题正确答案。"}}},{"id":"basic-xisixiang-ch11-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 1 题"},"stem":"民生是老百姓最关心的问题，涉及分配、就业、教育、医疗、住房、社会保障等方面。随着经济社会的发展进步，人民生活品质的不断提高，民生内涵也在不断丰富。解决民生问题的“总钥匙”是","choices":[{"id":"A","text":"就业"},{"id":"B","text":"发展"},{"id":"C","text":"收入分配"},{"id":"D","text":"社会保障"}],"answer":["B"],"analysis":{"point":"","options":{"A":"就业——是最基本的民生。","B":"发展——是解决民生问题的“总钥匙”，是本题正确答案。","C":"收入分配——是民生之源，是改善民生、实现发展成果由人民共享最重要最直接的方式。","D":"社会保障——是保障和改善民生、维护社会公平、增进人民福社的基本制度保障。"}}},{"id":"basic-xisixiang-ch11-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 2 题"},"stem":"在发展中保障和改善民生是中国式现代化的重大任务。要在发展过程中始终注重民生、保障民生、改善民生，根据经济发展和财力状况，逐步提高人民生活水平，让群众得到更多看得见、摸得着的实惠，不断厚植民生福祉。保障和改善民生的重要前提是","choices":[{"id":"A","text":"坚持尽力而为、量力而行"},{"id":"B","text":"解决人民群众最关心最直接最现实的利益问题"},{"id":"C","text":"正确把握民生和发展的关系"},{"id":"D","text":"坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果"}],"answer":["C"],"analysis":{"point":"","options":{"A":"坚持尽力而为、量力而行——是保障和改善民生的重要方针。","B":"解决人民群众最关心最直接最现实的利益问题——是保障和改善民生的重中之重。","C":"正确把握民生和发展的关系——是保障和改善民生的重要前提，是本题正确答案。","D":"坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果——是保障和改善民生的重要原则。"}}},{"id":"basic-xisixiang-ch11-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 3 题"},"stem":"江山就是人民，人民就是江山。我们要实现好、维护好、发展好最广大人民根本利益，就必须紧紧抓住人民最关心最直接最现实的利益问题。要坚持在发展中保障和改善民生，其中，最基本的民生是","choices":[{"id":"A","text":"收入分配"},{"id":"B","text":"就业"},{"id":"C","text":"人民健康"},{"id":"D","text":"社会保障"}],"answer":["B"],"analysis":{"point":"","options":{"A":"收入分配——是民生之源，是改善民生、实现发展成果由人民共享最重要最直接的方式。","B":"就业——是最基本的民生，是本题正确答案。","C":"人民健康——是社会文明进步的基础，是民族昌盛和国家富强的重要标志。","D":"社会保障——是保障和改善民生、维护社会公平、增进人民福社的基本制度保障。"}}},{"id":"basic-xisixiang-ch11-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 4 题"},"stem":"共同富裕是全体人民共同富裕，是人民群众物质生活和精神生活都富裕，不是少数人的富裕，也不是整齐划一的平均主义。促进共同富裕的基础性制度是","choices":[{"id":"A","text":"社会主义基本经济制度"},{"id":"B","text":"所有制制度"},{"id":"C","text":"分配制度"},{"id":"D","text":"社会主义市场经济体制"}],"answer":["C"],"analysis":{"point":"","options":{"A":"社会主义基本经济制度——是推进共同富裕的制度基础。","B":"是社会主义基本经济制度的具体方面，但不是促进共同富裕的基础性制度。","C":"分配制度——是促进共同富裕的基础性制度，是本题正确答案。","D":"是社会主义基本经济制度的具体方面，但不是促进共同富裕的基础性制度。"}}},{"id":"basic-xisixiang-ch11-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 5 题"},"stem":"深化收入分配制度改革是全面深化改革的重要内容。要坚持按劳分配为主体、多种分配方式并存，构建初次分配、再分配、第三次分配协调配套的制度体系。下列属于第三次分配手段的是","choices":[{"id":"A","text":"增加劳动者特别是一线劳动者的劳动报酬，提高劳动报酬在初次分配中的比重"},{"id":"B","text":"健全劳动、资本、土地、知识、技术、管理、数据等生产要素由市场评价贡献、按贡献决定报酬的机制"},{"id":"C","text":"引导、支持有意愿有能力的企业、社会组织和个人积极参与公益慈善事业"},{"id":"D","text":"健全以税收、社会保障、转移支付等为主要手段的调节机制"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是初次分配的手段。","B":"是初次分配的手段。","C":"是第三次分配的手段，是本题正确答案。","D":"是再分配的手段。"}}},{"id":"basic-xisixiang-ch11-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 6 题"},"stem":"加快完善社会治理体系，是一项系统性工程，要根据社会治理实际和人民新期待，进一步创新社会治理理念，健全社会治理制度，改进社会治理方式，不断推进社会治理体系和治理能力现代化。其中，完善社会治理体系的先导是","choices":[{"id":"A","text":"理念"},{"id":"B","text":"制度"},{"id":"C","text":"方式方法"},{"id":"D","text":"政府"}],"answer":["A"],"analysis":{"point":"","options":{"A":"理念——是完善社会治理体系的先导，是本题正确答案。","B":"制度——是完善社会治理体系的保障。","C":"方式方法——是完善社会治理体系的重要内容。","D":"政府——是加强和创新社会治理的主导力量。"}}},{"id":"basic-xisixiang-ch11-7","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 7 题"},"stem":"习近平总书记在地方考察时多次谈到基层减负。在重庆，习近平总书记详细了解近年来社区减负效果，深刻指出：“为基层减负要明确权责，不能什么事都压给基层，基层该承担哪些工作，要把职责事项搞清楚。”这是因为，基层治理是","choices":[{"id":"A","text":"新时代加强社会建设的重要着力点"},{"id":"B","text":"社会文明进步的基础"},{"id":"C","text":"最基本的民生"},{"id":"D","text":"国家治理的基石"}],"answer":["D"],"analysis":{"point":"","options":{"A":"新时代加强社会建设的重要着力点——是健全和完善社会保障体系。","B":"社会文明进步的基础——是人民健康。","C":"最基本的民生——是就业。","D":"国家治理的基石——是基层治理，是本题正确答案。"}}},{"id":"basic-xisixiang-ch11-8","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 8 题"},"stem":"中国特色社会主义进入新时代以来，我国经济社会发展取得了举世瞩目的重大成就。居民收入增长与经济增长基本同步，全国居民人均可支配收入年均增长5.1%。居民消费价格年均上涨2.1%。新增劳动力平均受教育年限从13.5年提高到14年。基本养老保险参保人数增加1.4亿、覆盖10.5亿人，基本医保水平稳步提高。多年累计改造棚户区住房4200多万套，上亿人出棚进楼、实现安居。我国人民生活水平不断提高表明，增进民生福祉是","choices":[{"id":"A","text":"坚持立党为公、执政为民的本质要求"},{"id":"B","text":"社会主义生产的根本目的"},{"id":"C","text":"当前中国共产党的中心任务"},{"id":"D","text":"全面建设社会主义现代化国家的应有之义"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是关于增进民生福祉的正确表述，是本题正确答案。","B":"是关于增进民生福祉的正确表述，是本题正确答案。","C":"当前中国共产党的中心任务——是以中国式现代化全面推进中华民族伟大复兴。","D":"是关于增进民生福祉的正确表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch11-9","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 9 题"},"stem":"改革开放前，农村居民从集体得到的工分收入是最主要的收入来源。改革开放后，随着大量农村富余劳动力向第二、第三产业转移，工资性收入成为拉动农村居民收入快速增长的重要来源。进入21世纪后，随着各种惠农补贴的发放、农村社会保障制度的完善和脱贫攻坚政策的深入推进，转移性收入快速增长。收入分配是","choices":[{"id":"A","text":"民生之源"},{"id":"B","text":"社会主义基本经济制度的基础"},{"id":"C","text":"最普惠的民生福祉"},{"id":"D","text":"改善民生、实现发展成果由人民共享最重要最直接的方式"}],"answer":["A","D"],"analysis":{"point":"","options":{"A":"是关于收入分配的正确表述，是本题正确答案。","B":"社会主义基本经济制度的基础——是公有制为主体、多种所有制经济共同发展的所有制结构。","C":"最普惠的民生福祉——是良好生态环境。","D":"是关于收入分配的正确表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch11-10","moduleId":"basic","subjectId":"xisixiang","chapter":"第十一章 以保障和改善民生为重点加强社会建设","chapterKey":"第十一章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十一章 第 10 题"},"stem":"就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发展，事关国家长治久安。党的十八大以来，党中央坚持把就业工作摆在治国理政的突出位置，强化就业优先政策，健全就业促进机制，有效应对各种压力挑战，城镇新增就业年均1300万人，为民生改善和经济发展提供了重要支撑。在这个过程中，我们不断深化对新时代就业工作规律的认识，积累了许多经验，主要包括","choices":[{"id":"A","text":"坚持把就业作为民生之本"},{"id":"B","text":"坚持创业带动就业"},{"id":"C","text":"坚持营造公平就业环境"},{"id":"D","text":"坚持扩大就业容量和提升就业质量相结合"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是新时代我们在就业工作方面积累的经验，是本题正确答案。","B":"是新时代我们在就业工作方面积累的经验，是本题正确答案。","C":"是新时代我们在就业工作方面积累的经验，是本题正确答案。","D":"是新时代我们在就业工作方面积累的经验，是本题正确答案。"}}},{"id":"basic-xisixiang-ch12-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十二章 建设社会主义生态文明","chapterKey":"第十二章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十二章 第 1 题"},"stem":"习近平指出：“绿色发展，就其要义来讲，是要解决好人与自然和谐共生问题。”解决生态环境问题的治本之策是","choices":[{"id":"A","text":"推进自然保护地体系建设"},{"id":"B","text":"绿色低碳发展"},{"id":"C","text":"制度建设"},{"id":"D","text":"积极参与全球气候治理"}],"answer":["B"],"analysis":{"point":"","options":{"A":"推进自然保护地体系建设——是加强生态系统保护的具体举措。","B":"绿色低碳发展——是解决生态环境问题的治本之策，是本题正确答案。","C":"制度建设——是推进生态文明建设的重中之重。","D":"积极参与全球气候治理——是推动全球可持续发展的基本要求。"}}},{"id":"basic-xisixiang-ch12-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十二章 建设社会主义生态文明","chapterKey":"第十二章","n":2,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十二章 第 2 题"},"stem":"绿水青山就是金山银山，这是重要的发展理念，也是推进现代化建设的重大原则。这一理念，阐明了经济发展与生态环境保护之间的关系。生态环境问题归根到底是","choices":[{"id":"A","text":"经济发展方式问题"},{"id":"B","text":"生活方式问题"},{"id":"C","text":"文化问题"},{"id":"D","text":"历史问题"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是导致生态环境问题的根源，是本题正确答案。","B":"是导致生态环境问题的根源，是本题正确答案。","C":"非考点。","D":"非考点。"}}},{"id":"basic-xisixiang-ch12-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十二章 建设社会主义生态文明","chapterKey":"第十二章","n":3,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十二章 第 3 题"},"stem":"习近平总书记指出，坚持绿色发展是发展观的一场深刻革命。绿色发展是人与自然和谐共生的发展。生态环境问题归根到底是发展方式和生活方式问题，要从根本上解决，必须深刻理解坚持绿色发展是发展理念、发展模式、生活方式、空间治理方式的深刻变革。加快形成绿色生产方式和生活方式的主要举措有","choices":[{"id":"A","text":"加快推动产业结构、能源结构、交通运输结构等调整优化"},{"id":"B","text":"推进各类资源节约集约利用"},{"id":"C","text":"积极稳妥推进碳达峰碳中和"},{"id":"D","text":"坚持把建设美丽中国转化为全体人民自觉行动"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是加快形成绿色生产方式和生活方式的主要举措，是本题正确答案。","B":"是加快形成绿色生产方式和生活方式的主要举措，是本题正确答案。","C":"是加快形成绿色生产方式和生活方式的主要举措，是本题正确答案。","D":"是加快形成绿色生产方式和生活方式的主要举措，是本题正确答案。"}}},{"id":"basic-xisixiang-ch12-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十二章 建设社会主义生态文明","chapterKey":"第十二章","n":4,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十二章 第 4 题"},"stem":"建设美丽中国，是全面建设社会主义现代化国家的重要目标，也是满足人民日益增长的优美生态环境需要的必然要求。到2035年，我国发展的总体目标，体现在生态方面是","choices":[{"id":"A","text":"实现碳达峰目标"},{"id":"B","text":"实现碳中和目标"},{"id":"C","text":"美丽中国目标基本实现"},{"id":"D","text":"广泛形成绿色生产生活方式"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"实现碳达峰目标——是我国到2030年的目标。","B":"实现碳中和目标——是我国到2060年的目标。","C":"是我国到2035年的目标，是本题正确答案。","D":"是我国到2035年的目标，是本题正确答案。"}}},{"id":"basic-xisixiang-ch13-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十三章 维护和塑造国家安全","chapterKey":"第十三章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十三章 第 1 题"},"stem":"面对更为复杂多变的国家安全形势，以习近平同志为核心的党中央创造性提出并发展总体国家安全观，坚持统筹发展和安全，加快构建统筹各领域安全的新安全格局，推进国家安全体系和能力现代化，为强国建设、民族复兴提供坚强安全保障。总体国家安全观的宗旨是","choices":[{"id":"A","text":"人民安全"},{"id":"B","text":"经济安全"},{"id":"C","text":"政治安全"},{"id":"D","text":"国际安全"}],"answer":["A"],"analysis":{"point":"","options":{"A":"人民安全——是总体国家安全观的宗旨，是本题正确答案。","B":"经济安全——是总体国家安全观的基础。","C":"政治安全——是总体国家安全观的根本。","D":"促进国际安全是总体国家安全观的依托。"}}},{"id":"basic-xisixiang-ch13-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十三章 维护和塑造国家安全","chapterKey":"第十三章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十三章 第 2 题"},"stem":"构建新安全格局是应对国家安全形势新变化新趋势的战略选择，是全面贯彻落实总体国家安全观的重大举措。其中，应对各领域安全风险挑战的首要任务是","choices":[{"id":"A","text":"维护政治安全"},{"id":"B","text":"维护经济安全"},{"id":"C","text":"维护人民安全"},{"id":"D","text":"维护国土安全"}],"answer":["A"],"analysis":{"point":"","options":{"A":"维护政治安全——是应对各领域安全风险挑战的首要任务，是本题正确答案。","B":"是坚持总体国家安全观的要求。","C":"是坚持总体国家安全观的要求。","D":"维护国土安全——是维护重点领域国家安全的要求。"}}},{"id":"basic-xisixiang-ch13-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十三章 维护和塑造国家安全","chapterKey":"第十三章","n":3,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十三章 第 3 题"},"stem":"我国之所以强调必须坚定不移贯彻总体国家安全观，把维护国家安全贯穿党和国家工作各方面全过程，是因为国家安全是","choices":[{"id":"A","text":"民族复兴的根基"},{"id":"B","text":"强国建设的根本保证"},{"id":"C","text":"国家繁荣和民族振兴的根本出发点"},{"id":"D","text":"关乎国家发展稳定和社会长治久安的重大战略问题"}],"answer":["A","D"],"analysis":{"point":"","options":{"A":"是关于国家安全的正确表述，是本题正确答案。","B":"强国建设的根本保证——是党的领导。","C":"国家繁荣和民族振兴的根本出发点——是人民幸福。","D":"是关于国家安全的正确表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch13-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十三章 维护和塑造国家安全","chapterKey":"第十三章","n":4,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十三章 第 4 题"},"stem":"构建新安全格局是应对国家安全形势新变化新趋势的战略选择，是全面贯彻落实总体国家安全观的重大举措。构建统筹各领域安全的新安全格局，必须把维护政治安全作为应对各领域安全风险挑战的首要任务。之所以把维护政治安全放在首要位置，是因为政治安全","choices":[{"id":"A","text":"是总体国家安全的保障"},{"id":"B","text":"是一切国家生存和发展的基础条件"},{"id":"C","text":"涉及国家主权、政权、制度和意识形态的稳固"},{"id":"D","text":"决定和影响着国家的经济安全、军事安全、社会安全等各个领域的安全"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"是关于军事、科技、文化、社会安全的表述。","B":"是关于政治安全的正确表述，是本题正确答案。","C":"是关于政治安全的正确表述，是本题正确答案。","D":"是关于政治安全的正确表述，是本题正确答案。"}}},{"id":"basic-xisixiang-ch14-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十四章 建设巩固国防和强大人民军队","chapterKey":"第十四章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十四章 第 1 题"},"stem":"党在会议报告中对全面推进国防和军队现代化作出新的战略安排：到2020年，国防和军队建设要基本实现机械化，信息化建设取得重大进展，战略能力有大的提升；到2035年，基本实现国防和军队现代化；到21世纪中叶，把人民军队全面建成世界一流军队。这一部署，绘就了建设强大人民军队的路线图、时间表。有效履行我军根本职能的内在要求的唯一标准是","choices":[{"id":"A","text":"听党指挥"},{"id":"B","text":"战斗力"},{"id":"C","text":"作风优良"},{"id":"D","text":"科技"}],"answer":["B"],"analysis":{"point":"","options":{"A":"听党指挥——是灵魂，决定军队建设的政治方向。","B":"战斗力——是有效履行我军根本职能的内在要求的唯一标准，是本题正确答案。","C":"作风优良——是保证，关系军队的性质、宗旨、本色。","D":"科技是核心战斗力，是军事发展中最活跃、最具革命性的因素。"}}},{"id":"basic-xisixiang-ch14-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十四章 建设巩固国防和强大人民军队","chapterKey":"第十四章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十四章 第 2 题"},"stem":"古田会议确立了思想建党、政治建军原则。新的征程上，开创国防和军队现代化新局面，必须全面推进政治建军、改革强军、科技强军、人才强军、依法治军，加快把人民军队建设成为世界一流军队。政治建军是","choices":[{"id":"A","text":"推动人民军队高质量发展、赢得军事竞争和未来战争主动的关键因素"},{"id":"B","text":"决定人民军队发展壮大、制胜未来的关键一招"},{"id":"C","text":"党建军治军的基本方式"},{"id":"D","text":"人民军队的立军之本"}],"answer":["D"],"analysis":{"point":"","options":{"A":"推动人民军队高质量发展、赢得军事竞争和未来战争主动的关键因素——是人才。","B":"决定人民军队发展壮大、制胜未来的关键一招是改革。","C":"党建军治军的基本方式——是依法治军。","D":"人民军队的立军之本——是政治建军，是本题正确答案。"}}},{"id":"basic-xisixiang-ch14-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十四章 建设巩固国防和强大人民军队","chapterKey":"第十四章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十四章 第 3 题"},"stem":"“强国必须强军，军强才能国安”“建设一支听党指挥、能打胜仗、作风优良的人民军队，是实现两个一百年’奋斗目标、实现中华民族伟大复兴的战略支撑”。人民军队的建军之本、强军之魂是","choices":[{"id":"A","text":"党对人民军队的绝对领导"},{"id":"B","text":"国防和军队现代化"},{"id":"C","text":"为人民服务"},{"id":"D","text":"能打胜仗"}],"answer":["A"],"analysis":{"point":"","options":{"A":"党对人民军队的绝对领导——是人民军队的建军之本、强军之魂，是本题正确答案。","B":"国防和军队现代化——是我们党的战略任务和奋斗目标。","C":"为人民服务——是人民军队的宗旨。","D":"能打胜仗是核心，反映军队的根本职能和军队建设的根本指向。"}}},{"id":"basic-xisixiang-ch14-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十四章 建设巩固国防和强大人民军队","chapterKey":"第十四章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十四章 第 4 题"},"stem":"坚持党对人民军队的绝对领导，是马克思主义建党建军的一条基本原则。习近平指出：“坚持党指挥枪、建设自己的人民军队，是党在血与火的斗争中得出的颠扑不破的真理。”坚持党对人民军队绝对领导的根本制度和根本实现形式是","choices":[{"id":"A","text":"军政民政团结"},{"id":"B","text":"首长分工负责制"},{"id":"C","text":"科技强军战略"},{"id":"D","text":"军委主席负责制"}],"answer":["D"],"analysis":{"point":"","options":{"A":"军政民政团结——是巩固提高一体化国家战略体系和能力的政治保障。","B":"首长分工负责制——是党领导军队的一整套制度体系中的重要制度，但不是根本制度。","C":"科技强军战略——是把人民军队建设成为世界一流军队的具体要求。","D":"军委主席负责制——是坚持党对人民军队绝对领导的根本制度和根本实现形式，是本题正确答案。"}}},{"id":"basic-xisixiang-ch14-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第十四章 建设巩固国防和强大人民军队","chapterKey":"第十四章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十四章 第 5 题"},"stem":"人民军队是执行党的政治任务的武装集团，党和人民所需就是军队使命任务所系。人民军队自成立起，就始终为争取民族独立、人民解放和实现国家富强、人民幸福而英勇奋斗。进入新时代，人民军队的使命任务是","choices":[{"id":"A","text":"为促进世界和平与发展提供战略支撑"},{"id":"B","text":"为维护我国海外利益提供战略支撑"},{"id":"C","text":"为捍卫国家主权、统一和领土完整提供战略支撑"},{"id":"D","text":"为巩固中国共产党领导和我国社会主义制度提供战略支撑"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是新时代人民军队的使命任务，是本题正确答案。","B":"是新时代人民军队的使命任务，是本题正确答案。","C":"是新时代人民军队的使命任务，是本题正确答案。","D":"是新时代人民军队的使命任务，是本题正确答案。"}}},{"id":"basic-xisixiang-ch15-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十五章 坚持“一国两制”和推进祖国完全统一","chapterKey":"第十五章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十五章 第 1 题"},"stem":"习近平总书记在庆祝香港回归祖国25周年大会暨香港特别行政区第六届政府就职典礼上强调，“一国两制”是前无古人的伟大创举。“一国两制”的根本宗旨是","choices":[{"id":"A","text":"保证特别行政区享有高度自治权，保持香港、澳门长期繁荣稳定"},{"id":"B","text":"维护国家主权、安全、发展利益，早日实现祖国统一"},{"id":"C","text":"保证特别行政区享有高度自治权，早日实现祖国统一"},{"id":"D","text":"维护国家主权、安全、发展利益，保持香港、澳门长期繁荣稳定"}],"answer":["D"],"analysis":{"point":"","options":{"A":"非考点。","B":"非考点。","C":"非考点。","D":"维护国家主权、安全、发展利益，保持香港、澳门长期繁荣稳定——是“一国两制”的根本宗旨，是本题正确答案。"}}},{"id":"basic-xisixiang-ch15-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十五章 坚持“一国两制”和推进祖国完全统一","chapterKey":"第十五章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十五章 第 2 题"},"stem":"习近平总书记在庆祝香港回归祖国25周年大会暨香港特别行政区第六届政府就职典礼上强调，“一国两制”方针是一个完整的体系。“一国两制”方针的最高原则是","choices":[{"id":"A","text":"维护国家主权、安全、发展利益"},{"id":"B","text":"保证香港享有高度自治权"},{"id":"C","text":"保持原有的资本主义制度长期不变"},{"id":"D","text":"保持香港的独特地位和优势"}],"answer":["A"],"analysis":{"point":"","options":{"A":"维护国家主权、安全、发展利益——是“一国两制”方针的最高原则，是本题正确答案。","B":"是在“一国”原则的基础之上实行“两制”的要求。","C":"是在“一国”原则的基础之上实行“两制”的要求。","D":"是在“一国”原则的基础之上实行“两制”的要求。"}}},{"id":"basic-xisixiang-ch15-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十五章 坚持“一国两制”和推进祖国完全统一","chapterKey":"第十五章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十五章 第 3 题"},"stem":"解决台湾问题、实现祖国完全统一，是全体中华儿女的共同愿望，是中华民族根本利益所在。党的十八大以来，在以习近平同志为核心的党中央坚强领导下，在两岸同胞共同努力下，两岸关系取得重要积极成果。两岸关系和平发展的政治基础是","choices":[{"id":"A","text":"深化两岸利益融合，共创两岸互利双赢，增进两岸同胞福祉"},{"id":"B","text":"坚持“九二共识”，反对“台独”"},{"id":"C","text":"增强两岸同胞的民族认同、文化认同、国家认同"},{"id":"D","text":"相互尊重，求同存异"}],"answer":["B"],"analysis":{"point":"","options":{"A":"深化两岸利益融合，共创两岸互利双赢，增进两岸同胞福祉——是推动两岸关系和平发展的宗旨。","B":"坚持“九二共识”，反对“台独”——是两岸关系和平发展的政治基础，是本题正确答案。","C":"增强两岸同胞的民族认同、文化认同、国家认同——是两岸关系和平发展的人文交流方面的内容。","D":"相互尊重，求同存异——是我国处理国与国之间关系的方针。"}}},{"id":"basic-xisixiang-ch15-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十五章 坚持“一国两制”和推进祖国完全统一","chapterKey":"第十五章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十五章 第 4 题"},"stem":"新时代党解决台湾问题的总体方略内涵丰富、逻辑严密、系统完备，深刻回答了推进祖国统一的一系列重大理论和实践问题，是我们党对台大政方针的继承发展和集大成。其中，统一的历史方位是","choices":[{"id":"A","text":"坚持团结台湾同胞、争取台湾民心"},{"id":"B","text":"坚持在祖国大陆发展进步基础上解决台湾问题"},{"id":"C","text":"坚持在中华民族伟大复兴进程中推进祖国统一"},{"id":"D","text":"坚持推动两岸关系和平发展、融合发展"}],"answer":["C"],"analysis":{"point":"","options":{"A":"坚持团结台湾同胞、争取台湾民心是统一的根本动力。","B":"坚持在祖国大陆发展进步基础上解决台湾问题——是统一的战略思路。","C":"坚持在中华民族伟大复兴进程中推进祖国统一——是统一的历史方位，是本题正确答案。","D":"坚持推动两岸关系和平发展、融合发展是统一的实践途径。"}}},{"id":"basic-xisixiang-ch15-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第十五章 坚持“一国两制”和推进祖国完全统一","chapterKey":"第十五章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十五章 第 5 题"},"stem":"解决台湾问题、实现祖国完全统一，是党矢志不渝的历史任务，是全体中华儿女的共同愿望，是实现中华民族伟大复兴的必然要求。祖国统一的最大障碍是","choices":[{"id":"A","text":"外部势力干涉"},{"id":"B","text":"“台独”分裂"},{"id":"C","text":"两岸长期存在的政治分歧"},{"id":"D","text":"历史遗留问题"}],"answer":["B"],"analysis":{"point":"","options":{"A":"外部势力干涉——是中国统一的突出障碍。","B":"“台独”分裂是祖国统一的最大障碍，是本题正确答案。","C":"两岸长期存在的政治分歧——是影响两岸关系行稳致远的总根子。","D":"历史遗留问题——是台湾问题产生的原因。"}}},{"id":"basic-xisixiang-ch15-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第十五章 坚持“一国两制”和推进祖国完全统一","chapterKey":"第十五章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十五章 第 6 题"},"stem":"习近平总书记在庆祝香港回归祖国25周年大会暨香港特别行政区第六届政府就职典礼上指出：“一国两制’在香港的丰富实践给我们留下很多宝贵经验，也留下不少深刻启示。”这些启示有","choices":[{"id":"A","text":"必须全面准确贯彻“一国两制”方针"},{"id":"B","text":"必须坚持中央全面管治权和保障特别行政区高度自治权相统一"},{"id":"C","text":"必须落实“爱国者治港”"},{"id":"D","text":"必须保持香港的独特地位和优势"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是“一国两制”在香港的丰富实践给我们的深刻启示，是本题正确答案。","B":"是“一国两制”在香港的丰富实践给我们的深刻启示，是本题正确答案。","C":"是“一国两制”在香港的丰富实践给我们的深刻启示，是本题正确答案。","D":"是“一国两制”在香港的丰富实践给我们的深刻启示，是本题正确答案。"}}},{"id":"basic-xisixiang-ch16-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十六章 中国特色大国外交和推动构建人类命运共同体","chapterKey":"第十六章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十六章 第 1 题"},"stem":"2023年，从中国—中亚峰会到第三届“一带一路”国际合作高峰论坛，从对俄罗斯进行国事访问到出席南非金砖国家领导人第十五次会晤，中国特色大国外交牢牢把握的主线是","choices":[{"id":"A","text":"为中国人民谋幸福、为中华民族谋复兴"},{"id":"B","text":"服务民族复兴、促进人类进步"},{"id":"C","text":"坚持走和平发展道路"},{"id":"D","text":"推动构建人类命运共同体"}],"answer":["B"],"analysis":{"point":"","options":{"A":"为中国人民谋幸福、为中华民族谋复兴——是中国共产党人的初心和使命。","B":"服务民族复兴、促进人类进步——是中国特色大国外交牢牢把握的主线，是本题正确答案。","C":"坚持走和平发展道路——是新时代中国外交的基本原则。","D":"推动构建人类命运共同体——是新时代我国对外工作的总目标。"}}},{"id":"basic-xisixiang-ch16-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十六章 中国特色大国外交和推动构建人类命运共同体","chapterKey":"第十六章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十六章 第 2 题"},"stem":"习近平指出：“我们要坚持走和平发展道路，但决不能放弃我们的正当权益，决不能牺牲国家核心利益。任何外国不要指望我们会拿自己的核心利益做交易，不要指望我们会吞下损害我国主权、安全、发展利益的苦果。”我国对外工作的出发点和落脚点是","choices":[{"id":"A","text":"维护国家主权、安全、发展利益"},{"id":"B","text":"坚持走和平发展道路"},{"id":"C","text":"独立自主的和平外交政策"},{"id":"D","text":"推动构建新型国际关系"}],"answer":["A"],"analysis":{"point":"","options":{"A":"维护国家主权、安全、发展利益——是我国对外工作的出发点和落脚点，是本题正确答案。","B":"是我国对外工作的主张和政策。","C":"是我国对外工作的主张和政策。","D":"是我国对外工作的主张和政策。"}}},{"id":"basic-xisixiang-ch16-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十六章 中国特色大国外交和推动构建人类命运共同体","chapterKey":"第十六章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十六章 第 3 题"},"stem":"进入新时代，我国面临的国际环境和外交工作担负的使命任务发生新的变化，我国对外工作需要展现新气象、实现新作为。新时代，我国对外工作的总目标是","choices":[{"id":"A","text":"维护国家主权、安全、发展利益"},{"id":"B","text":"推动构建人类命运共同体"},{"id":"C","text":"高质量共建“一带一路”"},{"id":"D","text":"坚持走和平发展道路"}],"answer":["B"],"analysis":{"point":"","options":{"A":"维护国家主权、安全、发展利益——是我国对外工作的出发点和落脚点。","B":"推动构建人类命运共同体——是新时代我国对外工作的总目标，是本题正确答案。","C":"高质量共建“一带一路”——是推动构建人类命运共同体的实践平台。","D":"坚持走和平发展道路——是新时代中国外交的基本原则。"}}},{"id":"basic-xisixiang-ch16-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十六章 中国特色大国外交和推动构建人类命运共同体","chapterKey":"第十六章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十六章 第 4 题"},"stem":"2023年10月10日，国务院新闻办公室发布《共建“一带一路”：构建人类命运共同体的重大实践》白皮书。共建“一带一路”不仅给相关国家带来实实在在的利益，也为推进经济全球化健康发展、破解全球发展难题和完善全球治理体系作出积极贡献。共建“一带一路”的主线是","choices":[{"id":"A","text":"高标准、可持续、惠民生"},{"id":"B","text":"共商、共建、共享"},{"id":"C","text":"开放、绿色、廉洁"},{"id":"D","text":"互联互通"}],"answer":["D"],"analysis":{"point":"","options":{"A":"高标准、可持续、惠民生——是共建“一带一路”的目标。","B":"共商、共建、共享——是共建“一带一路”的原则。","C":"开放、绿色、廉洁——是共建“一带一路”的理念。","D":"互联互通——是共建“一带一路”的主线，是本题正确答案。"}}},{"id":"basic-xisixiang-ch16-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第十六章 中国特色大国外交和推动构建人类命运共同体","chapterKey":"第十六章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十六章 第 5 题"},"stem":"党的十八大以来，在以习近平同志为核心的党中央坚强领导下，我们提出亲诚惠容周边外交理念，倡导推动构建周边命运共同体，以元首外交为引领，同周边国家深化全方位合作、加强各领域交流、共同维护和平稳定，形成务实高效的周边工作框架，推动周边工作取得历史性成就、发生历史性变革。周边是","choices":[{"id":"A","text":"实现发展繁荣的重要基础"},{"id":"B","text":"国家安全的宗旨"},{"id":"C","text":"运筹外交全局的首要"},{"id":"D","text":"推动构建人类命运共同体的实践平台"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是关于我国外交周边工作的正确表述，是本题正确答案。","B":"国家安全的宗旨是人民安全。","C":"是关于我国外交周边工作的正确表述，是本题正确答案。","D":"推动构建人类命运共同体的实践平台——是共建“一带一路”。"}}},{"id":"basic-xisixiang-ch16-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第十六章 中国特色大国外交和推动构建人类命运共同体","chapterKey":"第十六章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十六章 第 6 题"},"stem":"推动构建人类命运共同体，是当代中国共产党人回答和解决关乎人类前途命运的时代之问的中国方案，是应对人类共同挑战、建设更加繁荣美好世界的人间正道，也是新时代对外工作的总目标。推动构建人类命运共同体的重要依托是","choices":[{"id":"A","text":"全球发展倡议"},{"id":"B","text":"全球安全倡议"},{"id":"C","text":"全球文明倡议"},{"id":"D","text":"全球治理倡议"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是推动构建人类命运共同体的重要依托，是本题正确答案。","B":"是推动构建人类命运共同体的重要依托，是本题正确答案。","C":"是推动构建人类命运共同体的重要依托，是本题正确答案。","D":"是推动构建人类命运共同体的重要依托，是本题正确答案。"}}},{"id":"basic-xisixiang-ch17-1","moduleId":"basic","subjectId":"xisixiang","chapter":"第十七章 全面从严治党","chapterKey":"第十七章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十七章 第 1 题"},"stem":"高度重视和不断加强党的自身建设，是中国共产党从小到大、由弱到强，从挫折中奋起，在战胜困难中不断成熟的一大法宝，也是党领导的伟大事业不断取得胜利的根本保证。中国特色社会主义进入新时代，党的建设的根本方针是","choices":[{"id":"A","text":"全面加强党的执政本领"},{"id":"B","text":"坚持党要管党、全面从严治党"},{"id":"C","text":"坚持解放思想、改革创新"},{"id":"D","text":"全面推进党的政治建设"}],"answer":["B"],"analysis":{"point":"","options":{"A":"全面加强党的执政本领——是党的建设的目标。","B":"坚持党要管党、全面从严治党——是新时代党的建设的根本方针，是本题正确答案。","C":"坚持解放思想、改革创新——是我们推进各项工作的要求。","D":"政治建设是党的根本性建设，不是党的建设的根本方针。"}}},{"id":"basic-xisixiang-ch17-2","moduleId":"basic","subjectId":"xisixiang","chapter":"第十七章 全面从严治党","chapterKey":"第十七章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十七章 第 2 题"},"stem":"党的建设是根据党在不同时期的形势任务的要求而开展的。中国特色社会主义进入新时代，党对新时代党的建设提出了新的总要求。其中，新时代党的建设的着力点是","choices":[{"id":"A","text":"调动全党积极性、主动性、创造性"},{"id":"B","text":"加强党的长期执政能力建设、先进性和纯洁性建设"},{"id":"C","text":"坚定理想信念宗旨"},{"id":"D","text":"党的政治建设"}],"answer":["A"],"analysis":{"point":"","options":{"A":"调动全党积极性、主动性、创造性——是新时代党的建设的着力点，是本题正确答案。","B":"加强党的长期执政能力建设、先进性和纯洁性建设——是新时代党的建设的主线。","C":"坚定理想信念宗旨——是新时代党的建设的根基。","D":"党的政治建设——是新时代党的建设的统领。"}}},{"id":"basic-xisixiang-ch17-3","moduleId":"basic","subjectId":"xisixiang","chapter":"第十七章 全面从严治党","chapterKey":"第十七章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十七章 第 3 题"},"stem":"全面从严治党是党永葆生机活力、走好新的赶考之路的必由之路，是新时代党的建设的鲜明主题。必须坚持以党的政治建设为统领，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，把党建设成为始终走在时代前列、人民衷心拥护、勇于自我革命、经得起各种风浪考验、朝气蓬勃的马克思主义执政党。其中，党的基础性建设是","choices":[{"id":"A","text":"政治建设"},{"id":"B","text":"思想建设"},{"id":"C","text":"纪律建设"},{"id":"D","text":"制度建设"}],"answer":["B"],"analysis":{"point":"","options":{"A":"政治建设——是党的根本性建设。","B":"思想建设——是党的基础性建设，是本题正确答案。","C":"加强纪律建设是全面从严治党的治本之策。","D":"加强党内法规制度建设是全面从严治党的长远之策、根本之策。"}}},{"id":"basic-xisixiang-ch17-4","moduleId":"basic","subjectId":"xisixiang","chapter":"第十七章 全面从严治党","chapterKey":"第十七章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十七章 第 4 题"},"stem":"习近平总书记在党史学习教育动员大会上的讲话中强调：“旗帜鲜明讲政治、保证党的团结和集中统一是党的生命，也是我们党能成为百年大党、创造世纪伟业的关键所在。”党的政治建设的首要任务是","choices":[{"id":"A","text":"保证全党服从中央，维护党中央权威和集中统一领导"},{"id":"B","text":"坚定执行党的政治路线"},{"id":"C","text":"完善和落实民主集中制的各项制度"},{"id":"D","text":"加强党性锻炼，不断提高政治觉悟和政治能力"}],"answer":["A"],"analysis":{"point":"","options":{"A":"保证全党服从中央，维护党中央权威和集中统一领导——是党的政治建设的首要任务，是本题正确答案。","B":"是党的政治建设的内容。","C":"是党的组织建设的内容。","D":"是党的政治建设的内容。"}}},{"id":"basic-xisixiang-ch17-5","moduleId":"basic","subjectId":"xisixiang","chapter":"第十七章 全面从严治党","chapterKey":"第十七章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十七章 第 5 题"},"stem":"著名民主人士黄炎培先生曾说：“一部历史，‘政怠宦成’的也有，人亡政息’的也有，‘求荣取辱’的也有。总之，没有能跳出这个周期率。”如何跳出“其兴也淳焉，其亡也忽焉”的历史周期率，毛泽东给出的答案是“民主”，“只有让人民来监督政府，政府才不敢松懈”。经过不懈努力，我们党找到了跳出治乱兴衰历史周期率的第二个答案，这就是","choices":[{"id":"A","text":"艰苦奋斗"},{"id":"B","text":"自我革命"},{"id":"C","text":"全面深化改革"},{"id":"D","text":"全面依法治国"}],"answer":["B"],"analysis":{"point":"","options":{"A":"艰苦奋斗——是中国共产党的优良作风。","B":"自我革命——是我们党找到的跳出治乱兴衰历史周期率的第二个答案，是本题正确答案。","C":"全面深化改革——是新时代坚持和发展中国特色社会主义的根本动力。","D":"全面依法治国——是中国特色社会主义的本质要求和重要保障。"}}},{"id":"basic-xisixiang-ch17-6","moduleId":"basic","subjectId":"xisixiang","chapter":"第十七章 全面从严治党","chapterKey":"第十七章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"习思想 · 第十七章 第 6 题"},"stem":"腐败是我们党面临的最大威胁。当前，反腐败斗争形势仍然严峻复杂，铲除腐败滋生土壤和条件任务仍然艰巨繁重。坚决打好反腐败斗争攻坚战、持久战、总体战，必须深化标本兼治，一体推进“三不腐”，在铲除腐败滋生的土壤和条件上下更大功夫，一步不停歇、半步不退让，坚定不移把反腐败斗争向纵深推进，为“十五五”时期经济社会发展提供有力保障。之所以说反腐败斗争一刻不能停，必须永远吹冲锋号，是因为反腐败是","choices":[{"id":"A","text":"最彻底的自我革命"},{"id":"B","text":"全面从严治党的“必答题”"},{"id":"C","text":"新时代党的建设的主线"},{"id":"D","text":"党的政治建设的首要任务"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是关于反腐败的正确表述，是本题正确答案。","B":"是关于反腐败的正确表述，是本题正确答案。","C":"新时代党的建设的主线——是加强党的长期执政能力建设、先进性和纯洁性建设。","D":"党的政治建设的首要任务——是保证全党服从中央，维护党中央权威和集中统一领导。"}}},{"id":"basic-shigang-ch01-1","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 1 题"},"stem":"鸦片战争失败后，清政府被迫与英国签订了中国近代史上的第一个不平等条约——中英《南京条约》。中英《南京条约》签订后，美国趁火打劫，逼迫清政府签订的不平等条约是","choices":[{"id":"A","text":"《虎门条约》"},{"id":"B","text":"《望厦条约》"},{"id":"C","text":"《黄埔条约》"},{"id":"D","text":"《天津条约》"}],"answer":["B"],"analysis":{"point":"","options":{"A":"《虎门条约》——是清政府同英国签订的不平等条约。","B":"《望厦条约》——是中英《南京条约》签订后美国逼迫清政府签订的不平等条约，是本题正确答案。","C":"《黄埔条约》——是清政府同法国签订的不平等条约。","D":"《天津条约》——是第二次鸦片战争期间英国强迫清政府签订的不平等条约。"}}},{"id":"basic-shigang-ch01-2","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 2 题"},"stem":"认识中国近代一切社会问题和革命问题的最基本的依据是","choices":[{"id":"A","text":"反帝反封建的革命任务"},{"id":"B","text":"近代中国的基本国情"},{"id":"C","text":"资本- 帝国主义的侵略"},{"id":"D","text":"民族资产阶级的软弱性"}],"answer":["B"],"analysis":{"point":"","options":{"A":"反帝反封建的革命任务是近代中国的历史任务。","B":"近代中国的基本国情——是认识中国近代一切社会问题和革命问题的最基本的依据，是本题正确答案。","C":"资本-帝国主义的侵略——是近代中国沦为半殖民地半封建社会的原因之一。","D":"民族资产阶级的软弱性——是近代中国民族资产阶级的两面性之一。"}}},{"id":"basic-shigang-ch01-3","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 3 题"},"stem":"中国从封建社会逐步沦为半殖民地半封建社会，中国社会的阶级关系也发生了深刻的变动。近代中国最早产生的新的阶级是","choices":[{"id":"A","text":"民族资产阶级"},{"id":"B","text":"官僚买办资产阶级"},{"id":"C","text":"工人阶级"},{"id":"D","text":"城市小资产阶级"}],"answer":["C"],"analysis":{"point":"","options":{"A":"民族资产阶级是在洋务运动后期诞生的。","B":"官僚买办资产阶级——是在19世纪六七十年代后逐步产生的。","C":"工人阶级——最早出现于19世纪四五十年代外国资本主义在华企业中，是近代中国最早产生的新的阶级，是本题正确答案。","D":"城市小资产阶级——是在19世纪中后期逐步形成的新兴社会阶层。"}}},{"id":"basic-shigang-ch01-4","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 4 题"},"stem":"近代中国半殖民地半封建社会的矛盾，呈现错综复杂的状况。其中，贯穿整个中国半殖民地半封建社会的始终，并对中国近代社会的发展变化起着决定性作用的最主要的矛盾是","choices":[{"id":"A","text":"农民阶级和地主阶级的矛盾"},{"id":"B","text":"无产阶级和资产阶级的矛盾"},{"id":"C","text":"封建主义和人民大众的矛盾"},{"id":"D","text":"帝国主义和中华民族的矛盾"}],"answer":["D"],"analysis":{"point":"","options":{"A":"均是中国近代社会的阶级矛盾，但不是最主要的矛盾。","B":"均是中国近代社会的阶级矛盾，但不是最主要的矛盾。","C":"均是中国近代社会的阶级矛盾，但不是最主要的矛盾。","D":"帝国主义和中华民族的矛盾——是对中国近代社会的发展变化起着决定性作用的最主要的矛盾，是本题正确答案。"}}},{"id":"basic-shigang-ch01-5","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 5 题"},"stem":"中华民族具有5000多年连绵不断的文明历史，为人类文明进步作出了不可磨灭的贡献。鸦片战争以后，中国逐步成为半殖民地半封建社会，国家蒙辱、人民蒙难、文明蒙尘，中华民族遭受了前所未有的劫难。近代中国社会进步和发展的最大障碍是","choices":[{"id":"A","text":"官僚资本主义的垄断"},{"id":"B","text":"封建地主阶级的腐朽统治"},{"id":"C","text":"民族资产阶级的软弱"},{"id":"D","text":"帝国主义的侵略"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是近代中国社会进步和发展的障碍，但不是最大障碍。","B":"是近代中国社会进步和发展的障碍，但不是最大障碍。","C":"是近代中国社会进步和发展的障碍，但不是最大障碍。","D":"帝国主义的侵略——是近代中国社会进步和发展的最大障碍，是本题正确答案。"}}},{"id":"basic-shigang-ch01-6","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 6 题"},"stem":"自1840年鸦片战争以来，资本-帝国主义列强发动了一次又一次的侵华战争。资本-帝国主义列强对中国的侵略，首先和主要的方式是","choices":[{"id":"A","text":"经济掠夺"},{"id":"B","text":"军事侵略"},{"id":"C","text":"政治控制"},{"id":"D","text":"文化渗透"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是资本-帝国主义列强对中国侵略的方式，但不是首先和主要的侵略方式。","B":"军事侵略——是资本-帝国主义列强对中国进行的首先和主要的侵略方式，是本题正确答案。","C":"是资本-帝国主义列强对中国侵略的方式，但不是首先和主要的侵略方式。","D":"是资本-帝国主义列强对中国侵略的方式，但不是首先和主要的侵略方式。"}}},{"id":"basic-shigang-ch01-7","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 7 题"},"stem":"自1840年鸦片战争以来，资本-帝国主义列强发动了一次又一次的侵华战争。中国从封建社会逐步演变为半殖民地半封建社会，资本-帝国主义列强也从多方面开启了对中国的侵略。其中，军事侵略表现在","choices":[{"id":"A","text":"把持中国海关"},{"id":"B","text":"大肆宣扬“种族优劣论”"},{"id":"C","text":"强占租借地和划分势力范围"},{"id":"D","text":"实行商品倾销和资本输出"}],"answer":["C"],"analysis":{"point":"","options":{"A":"把持中国海关——是西方列强对中国进行政治控制的方式。","B":"大肆宣扬“种族优劣论”——是西方列强对中国进行文化渗透的方式。","C":"强占租借地和划分势力范围——是西方列强对中国进行军事侵略的方式，是本题正确答案。","D":"实行商品倾销和资本输出——是西方列强对中国进行经济掠夺的方式。"}}},{"id":"basic-shigang-ch01-8","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 8 题"},"stem":"鸦片战争以后，资本-帝国主义列强通过发动侵略战争，强迫中国签订一系列不平等条约，破坏中国的领土主权、领海主权、关税主权、司法主权等，并逐步控制中国的政治、经济、外交和军事。为了统治中国，资本-帝国主义列强在政治上采取的最主要方式是","choices":[{"id":"A","text":"扩大对中国的商品倾销和资本输出"},{"id":"B","text":"把持中国海关"},{"id":"C","text":"控制中国政府，操纵中国的内政和外交"},{"id":"D","text":"设立完全由外国直接控制和统治的租界"}],"answer":["C"],"analysis":{"point":"","options":{"A":"扩大对中国的商品倾销和资本输出——是列强对中国进行经济掠夺的方式。","B":"把持中国海关——是列强控制中国政治的重要手段之一，但不是最主要的方式。","C":"控制中国政府，操纵中国的内政和外交——是列强控制中国政治的最主要方式，是本题正确答案。","D":"设立完全由外国直接控制和统治的租界——是列强对中国发动军事侵略的结果。"}}},{"id":"basic-shigang-ch01-9","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 9 题"},"stem":"中国近代史，是一部充满灾难、落后挨打的屈辱史，是一部中国人民探索救国之路，实现自由、民主的探索史，是一部中华民族抵抗侵略，打倒帝国主义以实现民族解放、打倒封建主义以实现人民富强的斗争史。中国近代史上，中国人民第一次大规模的反侵略武装斗争是","choices":[{"id":"A","text":"太平天国农民战争"},{"id":"B","text":"三元里人民的抗英斗争"},{"id":"C","text":"台湾高山族的抗日斗争"},{"id":"D","text":"义和团抗击八国联军的斗争"}],"answer":["B"],"analysis":{"point":"","options":{"A":"太平天国农民战争——是中国旧式农民战争的最高峰。","B":"三元里人民的抗英斗争——是中国近代史上中国人民第一次大规模的反侵略武装斗争，是本题正确答案。","C":"台湾高山族的抗日斗争——是1895年台湾高山族人民反抗日本殖民统治的斗争。","D":"义和团抗击八国联军的斗争——是19世纪末一场以“扶清灭洋”为口号的农民运动。"}}},{"id":"basic-shigang-ch01-10","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 10 题"},"stem":"在西方列强野蛮侵略中国的同时，伟大的中华民族和不屈的华夏子孙，进行了一系列的抗争，有的来自社会底层，有的来自清政府内部，有的是群众自发的，有的是政府组织的。下列事件中，属于政府组织的抗争的是","choices":[{"id":"A","text":"三元里抗英斗争"},{"id":"B","text":"台湾反割台斗争"},{"id":"C","text":"左宗棠收复新疆"},{"id":"D","text":"义和团反帝运动"}],"answer":["C"],"analysis":{"point":"","options":{"A":"三元里抗英斗争——是中国近代史上中国人民第一次大规模的反侵略武装斗争。","B":"台湾反割台斗争——是台湾人民和台湾义勇军自发组织的抗争。","C":"左宗棠收复新疆——是在清朝中央政府统一指挥下，维护中国主权和领土完整的战争，是本题正确答案。","D":"义和团反帝运动——是农民阶级自发兴起的反抗运动。"}}},{"id":"basic-shigang-ch01-11","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 11 题"},"stem":"19世纪末，帝国主义列强通过发动侵华战争、强迫签订不平等条约等方式加紧对中国的侵略，其对中国的争夺和瓜分的图谋达到高潮是在","choices":[{"id":"A","text":"中日甲午战争爆发后"},{"id":"B","text":"第一次鸦片战争爆发后"},{"id":"C","text":"八国联军侵华战争爆发后"},{"id":"D","text":"中法战争爆发后"}],"answer":["A"],"analysis":{"point":"","options":{"A":"中日甲午战争爆发后——列强对中国的争夺和瓜分的图谋达到高潮，是本题正确答案。","B":"第一次鸦片战争爆发后——中国开始沦为半殖民地半封建社会。","C":"八国联军侵华战争爆发后——中国的民族危机加重。","D":"中法战争爆发后中国的民族危机加重。"}}},{"id":"basic-shigang-ch01-12","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 12 题"},"stem":"帝国主义侵略中国的最终目的，是要瓜分中国、灭亡中国。1895年，中国在甲午战争中战败后，列强掀起了瓜分中国的狂潮，这集中表现在","choices":[{"id":"A","text":"竞相租借港湾和划分势力范围"},{"id":"B","text":"外国资本在中国近代工业中争夺垄断地位"},{"id":"C","text":"设立中国近代史上第一个外国租界"},{"id":"D","text":"从侵占中国周边邻国发展到蚕食中国边疆地区"}],"answer":["A"],"analysis":{"point":"","options":{"A":"竞相租借港湾和划分势力范围——是列强掀起瓜分中国狂潮的集中表现，是本题正确答案。","B":"外国资本在中国近代工业中争夺垄断地位——是外国资本进入中国后始终都在进行的行为。","C":"设立中国近代史上第一个外国租界——是在1845年《上海租地章程》中规定的。","D":"从侵占中国周边邻国发展到蚕食中国边疆地区——发生在19世纪70至80年代。"}}},{"id":"basic-shigang-ch01-13","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 13 题"},"stem":"19世纪末20世纪初，帝国主义列强掀起瓜分中国的狂潮，却最终未能瓜分和灭亡中国。其最根本的原因是","choices":[{"id":"A","text":"帝国主义列强之间的矛盾和互相制约"},{"id":"B","text":"中国地域辽阔、人口众多，难以有效统治"},{"id":"C","text":"清政府与部分列强达成妥协，维持了表面统治"},{"id":"D","text":"中华民族进行的不屈不挠的反侵略斗争"}],"answer":["D"],"analysis":{"point":"","options":{"A":"帝国主义列强之间的矛盾和互相制约——是列强未能瓜分和灭亡中国的一个重要原因。","B":"非考点。","C":"非考点。","D":"中华民族进行的不屈不挠的反侵略斗争——是列强不能瓜分和灭亡中国的根本原因，是本题正确答案。"}}},{"id":"basic-shigang-ch01-14","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 14 题"},"stem":"自鸦片战争以来，近代中国历次反侵略战争均以中国战败、被迫签订不平等条约而告终。下列选项中，从根本上导致近代中国反侵略战争屡遭失败的原因是","choices":[{"id":"A","text":"帝国主义列强武器装备先进，军事力量远超中国"},{"id":"B","text":"近代中国军队战斗力薄弱，战略战术指挥失当"},{"id":"C","text":"近代中国半殖民地半封建的社会制度腐败"},{"id":"D","text":"近代中国科学技术落后，经济发展水平低下"}],"answer":["C"],"analysis":{"point":"","options":{"A":"均属于近代中国反侵略战争失败的重要原因。","B":"均属于近代中国反侵略战争失败的重要原因。","C":"近代中国半殖民地半封建的社会制度腐败——是近代中国反侵略战争失败的根本原因，是本题正确答案。","D":"均属于近代中国反侵略战争失败的重要原因。"}}},{"id":"basic-shigang-ch01-15","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 15 题"},"stem":"在近代中国，率先冲破闭关锁国的思想桎梏，主动了解西方世界，主张学习西方先进技术，被称为“睁眼看世界的第一人”的是","choices":[{"id":"A","text":"魏源"},{"id":"B","text":"郑观应"},{"id":"C","text":"林则徐"},{"id":"D","text":"严复"}],"answer":["C"],"analysis":{"point":"","options":{"A":"魏源——是《海国图志》的作者，提出了“师夷长技以制夷”的主张。","B":"郑观应是早期维新派的代表。","C":"林则徐——是近代中国睁眼看世界的第一人，是本题正确答案。","D":"严复——是《天演论》的翻译者，提出了“救亡”的口号。"}}},{"id":"basic-shigang-ch01-16","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 16 题"},"stem":"19世纪末，中国人民的民族意识开始普遍觉醒的标志性事件是","choices":[{"id":"A","text":"中日甲午战争"},{"id":"B","text":"鸦片战争"},{"id":"C","text":"八国联军侵华战争"},{"id":"D","text":"中法战争"}],"answer":["A"],"analysis":{"point":"","options":{"A":"中日甲午战争——是近代中国人民的民族意识开始普遍觉醒的标志，是本题正确答案。","B":"鸦片战争——是近代中国人开始睁眼看世界的标志。","C":"八国联军侵华战争——推动了近代中国民族意识的进一步高涨。","D":"中法战争非考点。"}}},{"id":"basic-shigang-ch01-17","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 17 题"},"stem":"1894年，孙中山在檀香山创立中国第一个资产阶级革命团体兴中会时，喊出的时代最强音是","choices":[{"id":"A","text":"“师夷长技以制夷”"},{"id":"B","text":"“驱除鞑虏，恢复中华”"},{"id":"C","text":"“振兴中华”"},{"id":"D","text":"“创立民国，平均地权”"}],"answer":["C"],"analysis":{"point":"","options":{"A":"“师夷长技以制夷”——是魏源在《海国图志》中提出的主张。","B":"“驱除鞑虏，恢复中华”——是中国同盟会革命纲领“三民主义”中民族主义的内容。","C":"“振兴中华”——是孙中山在兴中会成立时喊出的时代最强音，是本题正确答案。","D":"“创立民国，平均地权”——是中国同盟会革命纲领“三民主义”中民权主义和民生主义的内容。"}}},{"id":"basic-shigang-ch01-18","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 18 题"},"stem":"1842年，鸦片战争以清政府的失败而告终，此后清政府被迫与西方列强签订了一系列不平等条约。下列选项中，属于鸦片战争后中国与列强签订的不平等条约的有","choices":[{"id":"A","text":"《南京条约》"},{"id":"B","text":"《虎门条约》"},{"id":"C","text":"《望厦条约》"},{"id":"D","text":"《黄埔条约》"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"都属于鸦片战争后中国与列强签订的不平等条约，是本题正确答案。","B":"都属于鸦片战争后中国与列强签订的不平等条约，是本题正确答案。","C":"都属于鸦片战争后中国与列强签订的不平等条约，是本题正确答案。","D":"都属于鸦片战争后中国与列强签订的不平等条约，是本题正确答案。"}}},{"id":"basic-shigang-ch01-19","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 19 题"},"stem":"鸦片战争后，英国等西方列强通过《南京条约》《虎门条约》等一系列不平等条约，大肆破坏中国的主权完整。下列选项中，属于该时期被西方列强破坏的中国主权的有","choices":[{"id":"A","text":"领土主权"},{"id":"B","text":"领海主权"},{"id":"C","text":"司法主权"},{"id":"D","text":"关税主权"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"都属于鸦片战争后中国被西方列强破坏的主权，是本题正确答案。","B":"都属于鸦片战争后中国被西方列强破坏的主权，是本题正确答案。","C":"都属于鸦片战争后中国被西方列强破坏的主权，是本题正确答案。","D":"都属于鸦片战争后中国被西方列强破坏的主权，是本题正确答案。"}}},{"id":"basic-shigang-ch01-20","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 20 题"},"stem":"近代以来，中华民族面临着两大历史任务，无数仁人志士为此进行了不懈探索。下列选项中，属于近代中华民族面临的两大历史任务的有","choices":[{"id":"A","text":"争取民族独立、人民解放"},{"id":"B","text":"实现国家富强、人民幸福"},{"id":"C","text":"推翻封建主义、建立资本主义共和国"},{"id":"D","text":"消灭阶级、实现共产主义"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"属于近代中华民族面临的两大历史任务，是本题正确答案。","B":"属于近代中华民族面临的两大历史任务，是本题正确答案。","C":"推翻封建主义、建立资本主义共和国——是资产阶级革命派的奋斗目标。","D":"消灭阶级、实现共产主义——是中国共产党的最高理想和最终目标。"}}},{"id":"basic-shigang-ch01-21","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 21 题"},"stem":"19世纪末，帝国主义列强掀起瓜分中国的狂潮，但其瓜分中国的图谋最终破产。究其原因，主要有","choices":[{"id":"A","text":"中国封建势力对帝国主义列强的妥协与依附"},{"id":"B","text":"帝国主义列强之间的矛盾和互相制约"},{"id":"C","text":"中华民族进行的不屈不挠的反侵略斗争"},{"id":"D","text":"清政府开展洋务运动推动了国家实力的显著提升"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"中国封建势力对帝国主义列强的妥协与依附——是帝国主义列强能够掀起瓜分中国狂潮的重要条件。","B":"是列强瓜分中国图谋破产的原因，是本题正确答案。","C":"是列强瓜分中国图谋破产的原因，是本题正确答案。","D":"清政府开展洋务运动推动了国家实力的显著提升——是洋务运动的进步意义。"}}},{"id":"basic-shigang-ch01-22","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 22 题"},"stem":"鸦片战争以后，西方列强通过发动侵略战争，强迫中国签订了一系列不平等条约，使中国沦为半殖民地半封建社会。中国逐步沦为半殖民地社会的原因包括","choices":[{"id":"A","text":"中国已经丧失了完全独立的地位"},{"id":"B","text":"列强把中国卷入世界资本主义经济体系和世界市场之中"},{"id":"C","text":"中国仍然维持着独立国家和政府的名义"},{"id":"D","text":"西方列强不愿意中国成为独立的资本主义国家"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是中国逐步沦为半殖民地社会的原因，是本题正确答案。","B":"是中国逐步沦为半封建社会的原因。","C":"是中国逐步沦为半殖民地社会的原因，是本题正确答案。","D":"是中国逐步沦为半封建社会的原因。"}}},{"id":"basic-shigang-ch01-23","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 23 题"},"stem":"在半殖民地半封建社会的条件下，中国不可能在独立的基础上与外国发生经济往来。资本-帝国主义列强同中国发生经济关系，不是为了推动中国经济的发展，而是为了控制中国的经济。列强控制中国经济的方式有","choices":[{"id":"A","text":"在中国设立出版机构宣传西学"},{"id":"B","text":"控制中国的关税和盐税"},{"id":"C","text":"在中国设立银行"},{"id":"D","text":"控制中国的交通运输业"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"在中国设立出版机构宣传西学——是列强对中国进行文化渗透的方式。","B":"是列强控制中国经济的方式，是本题正确答案。","C":"是列强控制中国经济的方式，是本题正确答案。","D":"是列强控制中国经济的方式，是本题正确答案。"}}},{"id":"basic-shigang-ch01-24","moduleId":"basic","subjectId":"shigang","chapter":"第一章 进入近代后中华民族的磨难与抗争","chapterKey":"第一章","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第一章 第 24 题"},"stem":"1894年7月丰岛海战后，中日两国相互宣战，战至1895年2月北洋海军全军覆没，中日两国各自改革30年后的决战以清政府惨败而告终，1895年4月清政府被迫签署《马关条约》。这场战争对中国产生了极其严重的影响，表现在","choices":[{"id":"A","text":"清政府已经彻底沦为“洋人的朝廷”"},{"id":"B","text":"中断了清政府通过洋务运动向近代化转型的努力"},{"id":"C","text":"中国付出了丧失领土主权的极大代价"},{"id":"D","text":"清政府损失了海军主力"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"清政府已经彻底沦为“洋人的朝廷”——是《辛丑条约》对中国产生的影响。","B":"是《马关条约》对中国产生的影响，是本题正确答案。","C":"是《马关条约》对中国产生的影响，是本题正确答案。","D":"是《马关条约》对中国产生的影响，是本题正确答案。"}}},{"id":"basic-shigang-ch02-1","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 1 题"},"stem":"太平天国农民战争期间颁布了多部纲领性文件，其中，最能体现太平天国社会理想和农民起义特色的纲领性文件是","choices":[{"id":"A","text":"《天朝田亩制度》"},{"id":"B","text":"《资政新篇》"},{"id":"C","text":"《原道觉世训》"},{"id":"D","text":"《劝世良言》"}],"answer":["A"],"analysis":{"point":"","options":{"A":"《天朝田亩制度》——是最能体现太平天国社会理想和农民起义特色的纲领性文件，是本题正确答案。","B":"《资政新篇》——是中国近代史上第一个比较系统的发展资本主义的方案。","C":"《原道觉世训》——是太平天国的宗教理论著作，主要用于动员群众。","D":"《劝世良言》——是基督教布道书，为洪秀全创立拜上帝教提供了思想素材。"}}},{"id":"basic-shigang-ch02-2","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 2 题"},"stem":"在19世纪中叶的亚洲民族解放运动中，时间最久、规模最大、影响最深的一次运动是","choices":[{"id":"A","text":"三元里人民的抗英斗争"},{"id":"B","text":"太平天国农民战争"},{"id":"C","text":"捻军起义"},{"id":"D","text":"义和团运动"}],"answer":["B"],"analysis":{"point":"","options":{"A":"三元里人民的抗英斗争——是中国近代史上中国人民第一次大规模的反侵略武装斗争。","B":"太平天国农民战争——是19世纪中叶亚洲民族解放运动中，时间最久、规模最大、影响最深的一次运动，是本题正确答案。","C":"捻军起义——是19世纪中叶与太平天国农民战争同期并相互配合的农民运动。","D":"义和团运动——是19世纪末一场以“扶清灭洋”为口号的农民运动。"}}},{"id":"basic-shigang-ch02-3","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 3 题"},"stem":"中国近代历史上，诞生了多个试图推动国家变革的方案，其中第一个比较系统地提出发展资本主义的近代化改革方案的是","choices":[{"id":"A","text":"《资政新篇》"},{"id":"B","text":"《天朝田亩制度》"},{"id":"C","text":"《应诏统筹全局折》"},{"id":"D","text":"《中华民国临时约法》"}],"answer":["A"],"analysis":{"point":"","options":{"A":"《资政新篇》——是中国近代史上第一个比较系统的发展资本主义的方案，是本题正确答案。","B":"《天朝田亩制度》——是最能体现太平天国社会理想和农民起义特色的纲领性文件。","C":"《应诏统筹全局折》——是戊戌变法的施政纲领。","D":"《中华民国临时约法》——是中国历史上第一部具有资产阶级共和国宪法性质的法典。"}}},{"id":"basic-shigang-ch02-4","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 4 题"},"stem":"从19世纪60年代开始，洋务运动以“自强”“求富”为目标，先后创办近代军事工业、民用企业，筹建新式海军等，试图通过学习西方先进技术实现国家富强。下列选项中，标志着洋务运动彻底失败的事件是","choices":[{"id":"A","text":"太平天国农民战争的全面爆发"},{"id":"B","text":"资产阶级维新派发起戊戌变法"},{"id":"C","text":"甲午战争中北洋海军全军覆没"},{"id":"D","text":"义和团运动引发八国联军侵华"}],"answer":["C"],"analysis":{"point":"","options":{"A":"太平天国农民战争的全面爆发——是清政府对人民疯狂压迫的结果。","B":"资产阶级维新派发起戊戌变法——是洋务运动失败后资产阶级寻求制度变革的尝试。","C":"（原书未单独给出此项解析）","D":"义和团运动引发八国联军侵华——是洋务运动失败后发生的事件。"}}},{"id":"basic-shigang-ch02-5","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 5 题"},"stem":"19世纪末，随着中国民族资本主义的初步发展，民族资产阶级作为新的政治力量开始登上历史舞台，他们迫切要求为发展资本主义开辟道路。其中，中国民族资产阶级登上政治舞台的第一次表演是","choices":[{"id":"A","text":"太平天国农民战争"},{"id":"B","text":"辛亥革命"},{"id":"C","text":"戊戌维新运动"},{"id":"D","text":"洋务运动"}],"answer":["C"],"analysis":{"point":"","options":{"A":"太平天国农民战争——是中国旧式农民战争的最高峰。","B":"辛亥革命——是中国民族资产阶级领导的一次比较完全意义上的资产阶级民主革命。","C":"戊戌维新运动——是中国民族资产阶级登上政治舞台的第一次表演，是本题正确答案。","D":"洋务运动——是地主阶级洋务派发起的爱国救亡运动。"}}},{"id":"basic-shigang-ch02-6","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 6 题"},"stem":"洋务运动是近代中国第一次大规模模仿、学习西方工业化的运动，以“师夷长技以自强”为目一了道路。其中，民用工业的性质基本属于","choices":[{"id":"A","text":"中外合资性质"},{"id":"B","text":"封建主义性质"},{"id":"C","text":"官僚买办性质"},{"id":"D","text":"资本主义性质"}],"answer":["D"],"analysis":{"point":"","options":{"A":"非考点。","B":"封建主义性质——是洋务运动早期兴办的军用工业的性质。","C":"非考点。","D":"资本主义性质——是洋务运动后期兴办的民用工业的性质，是本题正确答案。"}}},{"id":"basic-shigang-ch02-7","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 7 题"},"stem":"第二次鸦片战争后，清朝统治集团内部一部分人震惊于列强的“船坚炮利”，主张学习西方以求“自强”，洋务运动由此兴起。洋务运动的一个重要内容就是创办新式学堂。洋务派创办的翻译学堂是","choices":[{"id":"A","text":"京师大学堂"},{"id":"B","text":"京师同文馆"},{"id":"C","text":"福州船政学堂"},{"id":"D","text":"广州万木草堂"}],"answer":["B"],"analysis":{"point":"","options":{"A":"京师大学堂——是“百日维新”保留下来的学堂。","B":"京师同文馆——是洋务派创办的翻译学堂，是本题正确答案。","C":"福州船政学堂——是洋务派创办的军事学堂。","D":"广州万木草堂——是维新派代表人物康有为主持创办的学堂。"}}},{"id":"basic-shigang-ch02-8","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 8 题"},"stem":"戊戌维新运动时期，在光绪皇帝发布的新政诏令中，并没有采纳的维新派多次提出的主张是","choices":[{"id":"A","text":"保护和奖励农工商业和交通采矿业"},{"id":"B","text":"裁减旧式绿营兵，改练新式陆军"},{"id":"C","text":"创设学堂，提倡西学，设立译书局，翻译外国书籍，派人出国留学"},{"id":"D","text":"设议院、开国会、制宪法等政治主张"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是在戊戌维新运动时期被采纳的措施。","B":"是在戊戌维新运动时期被采纳的措施。","C":"是在戊戌维新运动时期被采纳的措施。","D":"设议院、开国会、制宪法等政治主张——是在戊戌维新运动时期未被采纳的措施，直到实施清末“新政”时，这些内容才被提上日程，是本题正确答案。"}}},{"id":"basic-shigang-ch02-9","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 9 题"},"stem":"甲午战争的惨败，造成了新的民族危机，激发了新的民族觉醒。以康有为、梁启超、谭嗣同、严复等为主要代表人物的资产阶级维新派，开展了一系列宣传维新主张的活动。当时，封建守旧派和反对改变封建政治制度的洋务派对维新思想发动攻击，于是维新派与守旧派之间展开了一场激烈论战。维新派与守旧派的论战，实质上","choices":[{"id":"A","text":"选择了以武装起义推翻清王朝统治的斗争方式"},{"id":"B","text":"划清了革命与改良的界限"},{"id":"C","text":"是资产阶级思想与封建主义思想在中国的第一次正面交锋"},{"id":"D","text":"创立了近代中国第一个领导资产阶级革命的全国性政党"}],"answer":["C"],"analysis":{"point":"","options":{"A":"选择了以武装起义推翻清王朝统治的斗争方式——是中国资产阶级革命派与改良派的根本不同之处。","B":"划清了革命与改良的界限是革命派与改良派论战的历史意义。","C":"是资产阶级思想与封建主义思想在中国的第一次正面交锋——是维新派与守旧派论战的实质，是本题正确答案。","D":"创立了近代中国第一个领导资产阶级革命的全国性政党——是同盟会成立的历史意义。"}}},{"id":"basic-shigang-ch02-10","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 10 题"},"stem":"洋务运动期间，洋务派为支撑洋务事业的开展，创办了一批新式学堂以培养专业人才。下列选项中，属于洋务派创办的新式学堂主要类型的有","choices":[{"id":"A","text":"法政学堂"},{"id":"B","text":"工艺学堂"},{"id":"C","text":"军事学堂"},{"id":"D","text":"翻译学堂"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"法政学堂非考点。","B":"是洋务派创办的新式学堂的主要类型，是本题正确答案。","C":"是洋务派创办的新式学堂的主要类型，是本题正确答案。","D":"是洋务派创办的新式学堂的主要类型，是本题正确答案。"}}},{"id":"basic-shigang-ch02-11","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 11 题"},"stem":"洋务运动作为中国近代化的开端，在推进军事、工业、教育近代化方面作出了尝试，但最终未能实现“自强”“求富”的目标。下列选项中，属于洋务运动的失败原因的有","choices":[{"id":"A","text":"洋务运动具有封建性"},{"id":"B","text":"洋务派与顽固派的激烈论战"},{"id":"C","text":"洋务运动对列强具有依赖性"},{"id":"D","text":"洋务企业的管理具有腐朽性"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"都属于洋务运动失败的原因，是本题正确答案。","B":"洋务派与顽固派的激烈论战——属于洋务运动的内容。","C":"都属于洋务运动失败的原因，是本题正确答案。","D":"都属于洋务运动失败的原因，是本题正确答案。"}}},{"id":"basic-shigang-ch02-12","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 12 题"},"stem":"戊戌维新运动的失败，主要是由于维新派自身的局限和以慈禧太后为首的强大的守旧势力的反对。其中，维新派自身的局限性包括","choices":[{"id":"A","text":"不敢否定封建主义"},{"id":"B","text":"民族资产阶级力量弱小"},{"id":"C","text":"对帝国主义抱有幻想"},{"id":"D","text":"惧怕人民群众"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是维新派自身的局限性，是本题正确答案。","B":"民族资产阶级力量弱小——是戊戌维新运动失败的客观原因。","C":"是维新派自身的局限性，是本题正确答案。","D":"是维新派自身的局限性，是本题正确答案。"}}},{"id":"basic-shigang-ch02-13","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 13 题"},"stem":"洋务派在创办军事工业中遇到资金奇缺、原料和燃料供应不足，以及交通运输落后等困难，需要加以解决，因此兴办了一些民用企业。这些企业包括","choices":[{"id":"A","text":"开平矿务局"},{"id":"B","text":"金陵机器局"},{"id":"C","text":"轮船招商局"},{"id":"D","text":"福州船政局"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是洋务派兴办的民用企业，是本题正确答案。","B":"是洋务派创办的军事工业。","C":"是洋务派兴办的民用企业，是本题正确答案。","D":"是洋务派创办的军事工业。"}}},{"id":"basic-shigang-ch02-14","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 14 题"},"stem":"19世纪90年代，资产阶级维新派创办的学会主要有","choices":[{"id":"A","text":"华兴会"},{"id":"B","text":"强学会"},{"id":"C","text":"南学会"},{"id":"D","text":"保国会"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"华兴会——是资产阶级革命派在20世纪初创办的资产阶级革命团体。","B":"是19世纪90年代，资产阶级维新派创办的学会，是本题正确答案。","C":"是19世纪90年代，资产阶级维新派创办的学会，是本题正确答案。","D":"是19世纪90年代，资产阶级维新派创办的学会，是本题正确答案。"}}},{"id":"basic-shigang-ch02-15","moduleId":"basic","subjectId":"shigang","chapter":"第二章 不同社会力量对国家出路的早期探索","chapterKey":"第二章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第二章 第 15 题"},"stem":"中国民族资产阶级维新派与封建守旧派之间展开激烈论战的议题主要有","choices":[{"id":"A","text":"要不要变法"},{"id":"B","text":"要不要兴民权、设议院，实行君主立宪"},{"id":"C","text":"要不要推翻帝制，实行共和"},{"id":"D","text":"要不要废八股、改科举和兴西学"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是维新派与守旧派论战的三个议题，是本题正确答案。","B":"是维新派与守旧派论战的三个议题，是本题正确答案。","C":"要不要推翻帝制，实行共和——是资产阶级革命派与改良派论战的核心问题之一。","D":"是维新派与守旧派论战的三个议题，是本题正确答案。"}}},{"id":"basic-shigang-ch03-1","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 1 题"},"stem":"随着民族危机的加深和民族资本主义的初步发展，中国资产阶级开始登上政治舞台。1894年，孙中山在美国檀香山组建了中国近代史上第一个资产阶级革命团体，这个团体是","choices":[{"id":"A","text":"强学会"},{"id":"B","text":"同盟会"},{"id":"C","text":"华兴会"},{"id":"D","text":"兴中会"}],"answer":["D"],"analysis":{"point":"","options":{"A":"强学会——是资产阶级维新派建立的政治团体，属于改良派组织。","B":"同盟会——是近代中国第一个领导资产阶级革命的全国性政党。","C":"华兴会——是资产阶级革命派创立的革命团体，时间上晚于兴中会。","D":"兴中会——是由孙中山组建的中国近代史上第一个资产阶级革命团体，是本题正确答案。"}}},{"id":"basic-shigang-ch03-2","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 2 题"},"stem":"20世纪初，随着资产阶级革命思想的广泛传播和革命形势的迅速发展，分散的地方性革命团体已不能适应革命发展的需要。为了集中革命力量，统一革命步伐，1905年8月，近代中国第一个领导资产阶级革命的全国性政党在日本东京成立。这个政党是","choices":[{"id":"A","text":"同盟会"},{"id":"B","text":"兴中会"},{"id":"C","text":"南京临时政府"},{"id":"D","text":"中华革命党"}],"answer":["A"],"analysis":{"point":"","options":{"A":"同盟会——是近代中国第一个领导资产阶级革命的全国性政党，是本题正确答案。","B":"兴中会——是由孙中山组建的中国近代史上第一个资产阶级革命团体。","C":"南京临时政府——是中国第一个资产阶级共和国性质的革命政权。","D":"中华革命党——是1914年孙中山在日本创建的革命政党，时间上晚于同盟会。"}}},{"id":"basic-shigang-ch03-3","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 3 题"},"stem":"1905年，同盟会以《民报》为机关报，并确立了革命纲领，是近代中国第一个领导资产阶级革命的全国性政党，它的成立标志着","choices":[{"id":"A","text":"中国民族资产阶级首次登上政治舞台"},{"id":"B","text":"中国资产阶级民主革命进入了一个新的阶段"},{"id":"C","text":"中国资产阶级民主革命由依靠少数精英逐渐转变为依靠广大工农群众"},{"id":"D","text":"帝国主义和中华民族的矛盾开始占支配地位"}],"answer":["B"],"analysis":{"point":"","options":{"A":"中国民族资产阶级首次登上政治舞台——是在戊戌维新运动中。","B":"中国资产阶级民主革命进入了一个新的阶段——是同盟会成立的意义，是本题正确答案。","C":"中国资产阶级民主革命由依靠少数精英逐渐转变为依靠广大工农群众——是错误说法，同盟会的革命活动主要依靠资产阶级、小资产阶级知识分子，未能深入发动和依靠广大工农群众。","D":"帝国主义和中华民族的矛盾开始占支配地位——是鸦片战争导致的结果。"}}},{"id":"basic-shigang-ch03-4","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 4 题"},"stem":"在孙中山的思想中，“创立民国”属于","choices":[{"id":"A","text":"民族主义"},{"id":"B","text":"民权主义"},{"id":"C","text":"民生主义"},{"id":"D","text":"民主主义"}],"answer":["B"],"analysis":{"point":"","options":{"A":"民族主义——对应的是“驱除鞑虏，恢复中华”。","B":"民权主义——对应的是“创立民国”，是本题正确答案。","C":"民生主义——对应的是“平均地权”。","D":"民主主义不属于三民主义的内容。"}}},{"id":"basic-shigang-ch03-5","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 5 题"},"stem":"孙中山领导的同盟会先后发动了多次武装起义，其中影响最大的是","choices":[{"id":"A","text":"武昌起义"},{"id":"B","text":"黄花岗起义"},{"id":"C","text":"萍浏醴起义"},{"id":"D","text":"南昌起义"}],"answer":["B"],"analysis":{"point":"","options":{"A":"武昌起义掀起了辛亥革命的高潮。","B":"黄花岗起义——是同盟会发动的影响最大的武装起义，是本题正确答案。","C":"萍浏醴起义——是同盟会成立后发动的第一次大规模的武装起义。","D":"南昌起义——是1927年中国共产党发动的武装起义。"}}},{"id":"basic-shigang-ch03-6","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 6 题"},"stem":"中国历史上第一部具有资产阶级共和国宪法性质的法典是","choices":[{"id":"A","text":"《中华苏维埃共和国宪法大纲》"},{"id":"B","text":"《中华民国临时约法》"},{"id":"C","text":"《钦定宪法大纲》"},{"id":"D","text":"《中国人民政治协商会议共同纲领》"}],"answer":["B"],"analysis":{"point":"","options":{"A":"《中华苏维埃共和国宪法大纲》——是1931年中华苏维埃第一次全国代表大会通过的宪法性文件，具有新民主主义性质。","B":"《中华民国临时约法》——是中国历史上第一部具有资产阶级共和国宪法性质的法典，是本题正确答案。","C":"《钦定宪法大纲》——是清末“新政”时期清政府颁布的一部具有封建性质的宪法性文件。","D":"《中国人民政治协商会议共同纲领》——是1949年中国人民政治协商会议第一届全体会议通过的文件，具有新民主主义性质。"}}},{"id":"basic-shigang-ch03-7","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 7 题"},"stem":"毛泽东指出，辛亥革命“有它胜利的地方，也有它失败的地方。你们看，辛亥革命把皇帝赶跑，这不是胜利了吗？说它失败，是说辛亥革命只把一个皇帝赶跑，中国仍旧在帝国主义和封建主义的压迫之下，反帝反封建的革命任务并没有完成”。辛亥革命失败的根本原因是","choices":[{"id":"A","text":"在半殖民地半封建的中国，资本主义的建国方案是行不通的"},{"id":"B","text":"没有提出彻底的反帝反封建的革命纲领"},{"id":"C","text":"不能充分发动和依靠人民群众"},{"id":"D","text":"不能建立坚强的革命政党"}],"answer":["A"],"analysis":{"point":"","options":{"A":"在半殖民地半封建的中国，资本主义的建国方案是行不通的——是辛亥革命失败的根本原因，是本题正确答案。","B":"是辛亥革命失败的主观原因。","C":"是辛亥革命失败的主观原因。","D":"是辛亥革命失败的主观原因。"}}},{"id":"basic-shigang-ch03-8","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 8 题"},"stem":"1905年11月，孙中山在同盟会机关报《民报》发刊词中，将同盟会的纲领概括为三大主义，即民族主义、民权主义、民生主义，后被称为三民主义。孙中山的三民主义学说","choices":[{"id":"A","text":"是一个比较完整而明确的资产阶级民主革命纲领"},{"id":"B","text":"划清了革命与改良的界限"},{"id":"C","text":"同中国共产党在民主革命阶段的纲领基本一致"},{"id":"D","text":"是中国历史上第一部具有资产阶级共和国宪法性质的法典"}],"answer":["A"],"analysis":{"point":"","options":{"A":"是一个比较完整而明确的资产阶级民主革命纲领——是对三民主义学说的定位，三民主义学说初步描绘了资产阶级共和国方案，是本题正确答案。","B":"划清了革命与改良的界限——是资产阶级革命派和改良派论战的意义。","C":"同中国共产党在民主革命阶段的纲领基本一致——是关于新三民主义的正确表述。","D":"是中国历史上第一部具有资产阶级共和国宪法性质的法典——是《中华民国临时约法》的地位。"}}},{"id":"basic-shigang-ch03-9","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 9 题"},"stem":"1905年11月，孙中山在同盟会机关报《民报》发刊词中，将同盟会的纲领概括为民族主义、民权主义、民生主义，后被称为三民主义。其中，民生主义指的是“平均地权”，所采用的方法是","choices":[{"id":"A","text":"核定全国土地，按照“耕者有其田”的原则平分给农民"},{"id":"B","text":"废除封建土地所有制，但保留资产阶级的土地"},{"id":"C","text":"征收地价税和土地增价归公"},{"id":"D","text":"将土地所有权分给农民"}],"answer":["C"],"analysis":{"point":"","options":{"A":"核定全国土地，按照“耕者有其田”的原则平分给农民——是在新三民主义中提出的。","B":"废除封建土地所有制，但保留资产阶级的土地——是错误说法，民生主义没有正面触及封建土地所有制。","C":"征收地价税和土地增价归公——是“平均地权”所采用的方法，是本题正确答案。","D":"将土地所有权分给农民——是错误说法，民生主义并未将土地所有权分给农民。"}}},{"id":"basic-shigang-ch03-10","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 10 题"},"stem":"1905年至1907年间，资产阶级革命派与改良派展开了一场大论战。这场论战的焦点是","choices":[{"id":"A","text":"要不要推翻帝制，实行共和"},{"id":"B","text":"要不要以革命手段推翻清王朝"},{"id":"C","text":"要不要发动广大民众"},{"id":"D","text":"要不要进行社会革命"}],"answer":["B"],"analysis":{"point":"","options":{"A":"属于资产阶级革命派与改良派论战的内容，但不是论战的焦点。","B":"要不要以革命手段推翻清王朝——是资产阶级革命派与改良派论战的焦点，是本题正确答案。","C":"要不要发动广大民众——并不是资产阶级革命派与改良派的论战内容。","D":"属于资产阶级革命派与改良派论战的内容，但不是论战的焦点。"}}},{"id":"basic-shigang-ch03-11","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 11 题"},"stem":"1911年10月10日晚，驻武昌的新军工程第八营的革命党人打响了起义的第一枪。起义军一夜之间就占领武昌，取得首义的胜利。武昌起义","choices":[{"id":"A","text":"是同盟会成立后发动的第一次武装起义"},{"id":"B","text":"使得在中国延续了两千多年的封建帝制终于覆灭"},{"id":"C","text":"拉开了中国完全意义上的近代民族民主革命的序幕"},{"id":"D","text":"使得革命势力发展到了长江流域和黄河流域的大部分地区"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是同盟会成立后发动的第一次武装起义——是萍浏醴起义的意义。","B":"使得在中国延续了两千多年的封建帝制终于覆灭——是清帝退位的意义。","C":"拉开了中国完全意义上的近代民族民主革命的序幕——是武昌起义的意义，是本题正确答案。","D":"使得革命势力发展到了长江流域和黄河流域的大部分地区——是北伐战争的成果。"}}},{"id":"basic-shigang-ch03-12","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 12 题"},"stem":"1905年，中国同盟会在日本东京成立后，不仅同改良主义思想进行了正面交锋，更是派遣会员回到国内，发动了一系列反清武装起义，其中掀起辛亥革命高潮的起义是","choices":[{"id":"A","text":"萍浏醴起义"},{"id":"B","text":"黄花岗起义"},{"id":"C","text":"南昌起义"},{"id":"D","text":"武昌起义"}],"answer":["D"],"analysis":{"point":"","options":{"A":"萍浏醴起义——是同盟会成立后发动的第一次武装起义。","B":"黄花岗起义——是同盟会发动的影响最大的武装起义。","C":"南昌起义是1927年中国共产党发动的武装起义。","D":"武昌起义——是掀起辛亥革命高潮的起义，是本题正确答案。"}}},{"id":"basic-shigang-ch03-13","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 13 题"},"stem":"1913年宋教仁被刺杀后，孙中山开始看清袁世凯的真面目，毅然发动的武装反袁斗争是","choices":[{"id":"A","text":"“二次革命”"},{"id":"B","text":"护国运动"},{"id":"C","text":"护法运动"},{"id":"D","text":"广州起义"}],"answer":["A"],"analysis":{"point":"","options":{"A":"“二次革命”——是宋教仁被刺杀后孙中山发动的武装起义，是本题正确答案。","B":"护国运动——是针对袁世凯复辟帝制而发动的。","C":"护法运动——是针对段祺瑞拒绝恢复《中华民国临时约法》和国会而发动的。","D":"广州起义——主要有两次：第一次是1911年同盟会举行的，也称黄花岗起义；第二次是1927年中国共产党在广州发动的反抗国民党右派的起义。"}}},{"id":"basic-shigang-ch03-14","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 14 题"},"stem":"辛亥革命失败后，以孙中山为代表的革命派继续反对封建军阀的专制统治，努力挽救共和制度。在段祺瑞变本加厉地推行独裁卖国的反动统治后，孙中山举起了“护法”的旗帜，但护法运动最终还是失败了。护法运动的失败，标志着","choices":[{"id":"A","text":"中国旧民主主义革命向新民主主义革命的转变"},{"id":"B","text":"中国资产阶级民主革命进入了一个新的阶段"},{"id":"C","text":"中国完全沦为半殖民地半封建性质的社会"},{"id":"D","text":"中国民族资产阶级领导的旧民主主义革命的终结"}],"answer":["D"],"analysis":{"point":"","options":{"A":"中国旧民主主义革命向新民主主义革命的转变——是以五四运动为开端的。一","B":"（原书未单独给出此项解析）","C":"中国完全沦为半殖民地半封建性质的社会——是《辛丑条约》签订的结果。","D":"中国民族资产阶级领导的旧民主主义革命的终结——是以护法运动失败为标志的，是本题正确答案。"}}},{"id":"basic-shigang-ch03-15","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 15 题"},"stem":"1905年11月，孙中山先生将同盟会的纲领概括为三大主义，即民族主义、民权主义、民生主义，后被称为三民主义，其中民族主义的内容包括","choices":[{"id":"A","text":"驱除鞑虏"},{"id":"B","text":"恢复中华"},{"id":"C","text":"创立民国"},{"id":"D","text":"平均地权"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是三民主义中民族主义的内容，是本题正确答案。","B":"是三民主义中民族主义的内容，是本题正确答案。","C":"创立民国是三民主义中民权主义的内容。","D":"平均地权——是三民主义中民生主义的内容。"}}},{"id":"basic-shigang-ch03-16","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 16 题"},"stem":"辛亥革命虽然推翻了清王朝的统治，但并没有完成反帝反封建的革命任务。从主观方面来说，其失败的原因在于资产阶级革命派本身存在着许多弱点和错误，主要有","choices":[{"id":"A","text":"没有提出彻底的反帝反封建的革命纲领"},{"id":"B","text":"不能充分发动和依靠人民群众"},{"id":"C","text":"资本主义道路在中国行不通"},{"id":"D","text":"不能建立坚强的革命政党，作为团结一切革命力量的强有力的核心"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是资产阶级革命派本身存在的弱点和错误，是本题正确答案。","B":"是资产阶级革命派本身存在的弱点和错误，是本题正确答案。","C":"资本主义道路在中国行不通——是辛亥革命失败的根本原因，属于客观原因。","D":"是资产阶级革命派本身存在的弱点和错误，是本题正确答案。"}}},{"id":"basic-shigang-ch03-17","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 17 题"},"stem":"辛亥革命的爆发，是中国社会矛盾运动的必然产物，是当时中国人民争取民族独立、振兴中华深切愿望的集中反映，也是当时中国人民为救亡图存而前赴后继顽强斗争的集中体现。辛亥革命爆发的历史条件有","choices":[{"id":"A","text":"学习了西方的科学技术，巩固了边防"},{"id":"B","text":"民族危机加深，社会矛盾激化"},{"id":"C","text":"清末“新政”的破产"},{"id":"D","text":"资产阶级革命派具备了阶级基础且形成了骨干力量"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"学习了西方的科学技术，巩固了边防——是洋务运动的内容和作用。","B":"是辛亥革命爆发的历史条件，是本题正确答案。","C":"是辛亥革命爆发的历史条件，是本题正确答案。","D":"是辛亥革命爆发的历史条件，是本题正确答案。"}}},{"id":"basic-shigang-ch03-18","moduleId":"basic","subjectId":"shigang","chapter":"第三章 辛亥革命与君主专制制度的终结","chapterKey":"第三章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第三章 第 18 题"},"stem":"1903年，章士钊在译著《孙逸仙》中称：“孙逸仙者，近今谈革命者之初祖，实行革命者之北辰，此有耳目者所同认。”2025年3月12日，首都各界人士会聚北京中山公园中山堂，举行简短而庄严的仪式，纪念孙中山先生逝世100周年，深切缅怀这位伟大的民主革命先行者。孙中山先生对中国革命的历史贡献有","choices":[{"id":"A","text":"喊出了“振兴中华”这个时代的最强音"},{"id":"B","text":"开创了比较完全意义上的资产阶级民主革命"},{"id":"C","text":"在领导人民推翻帝制、建立共和国的斗争中建立了历史功勋"},{"id":"D","text":"建立了坚强的革命政党，作为团结一切革命力量的强有力的核心"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是孙中山先生对中国革命的历史贡献，是本题正确答案。","B":"是孙中山先生对中国革命的历史贡献，是本题正确答案。","C":"是孙中山先生对中国革命的历史贡献，是本题正确答案。","D":"建立了坚强的革命政党，作为团结一切革命力量的强有力的核心——是错误说法，同盟会内部组织比较松懈，并不是强有力的革命领导核心。"}}},{"id":"basic-shigang-ch04-1","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 1 题"},"stem":"1915年兴起的新文化运动，是一场伟大的思想解放运动。它的主要阵地是","choices":[{"id":"A","text":"《民报》和同盟会"},{"id":"B","text":"《时务报》和万木草堂"},{"id":"C","text":"《新青年》杂志和北京大学"},{"id":"D","text":"《湘江评论》和岳麓书院"}],"answer":["C"],"analysis":{"point":"","options":{"A":"《民报》和同盟会——是资产阶级革命派宣传三民主义的主要阵地。","B":"《时务报》和万木草堂——是资产阶级维新派在戊戌维新运动时期的主要阵地。","C":"《新青年》杂志和北京大学——是新文化运动的主要阵地，是本题正确答案。","D":"《湘江评论》和岳麓书院——非考点。"}}},{"id":"basic-shigang-ch04-2","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 2 题"},"stem":"1917年俄国十月革命的胜利，给中国送来了马克思列宁主义，中国的先进分子由此看到了解决中国问题的新出路。在中国大地上率先举起马克思主义旗帜的人是","choices":[{"id":"A","text":"李大钊"},{"id":"B","text":"陈独秀"},{"id":"C","text":"毛泽东"},{"id":"D","text":"周恩来"}],"answer":["A"],"analysis":{"point":"","options":{"A":"李大钊——是在中国大地上率先举起马克思主义旗帜的人，是本题正确答案。","B":"陈独秀——是早期马克思主义者和新文化运动的发起者。","C":"毛泽东——是马克思主义中国化命题的提出者。","D":"周恩来——是早期马克思主义者和中国共产党主要领导人之一。"}}},{"id":"basic-shigang-ch04-3","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 3 题"},"stem":"马克思主义在中国的传播经历了一个从初步介绍到系统阐述的过程。标志着马克思主义在中国进入比较系统的传播阶段的文章是","choices":[{"id":"A","text":"《Bolshevism 的胜利》"},{"id":"B","text":"《庶民的胜利》"},{"id":"C","text":"《资政新篇》"},{"id":"D","text":"《我的马克思主义观》"}],"answer":["D"],"analysis":{"point":"","options":{"A":"歌颂了十月革命和布尔什维主义的胜利。","B":"歌颂了十月革命和布尔什维主义的胜利。","C":"《资政新篇》——是太平天国农民战争时期提出的发展资本主义的方案。","D":"《我的马克思主义观》——标志着马克思主义在中国进入比较系统的传播阶段，是本题正确答案。"}}},{"id":"basic-shigang-ch04-4","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 4 题"},"stem":"1919年5月4日，一场声势浩大的爱国运动在北京爆发，并迅速席卷全国。这场运动的爆发，有着深刻的社会历史根源，其直接导火线是","choices":[{"id":"A","text":"新文化运动的深入发展"},{"id":"B","text":"俄国十月革命的胜利"},{"id":"C","text":"巴黎和会上中国外交的失败"},{"id":"D","text":"中国工人阶级队伍的壮大"}],"answer":["C"],"analysis":{"point":"","options":{"A":"新文化运动的深入发展——是五四运动爆发的思想基础。","B":"俄国十月革命的胜利是五四运动爆发的时代背景。","C":"巴黎和会上中国外交的失败——是五四运动爆发的直接导火线，是本题正确答案。","D":"中国工人阶级队伍的壮大——是五四运动爆发的阶级基础。"}}},{"id":"basic-shigang-ch04-5","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 5 题"},"stem":"毛泽东同志在分析中国革命历史时指出，从鸦片战争到五四运动，中国人民为了反对帝国主义和封建统治进行了英勇不屈的斗争，其中主要的是太平天国农民战争和资产阶级领导的辛亥革命，但都失败了。中国旧民主主义革命走向新民主主义革命的转折点是","choices":[{"id":"A","text":"五四运动"},{"id":"B","text":"新文化运动"},{"id":"C","text":"中国共产党的成立"},{"id":"D","text":"第一次国共合作的实现"}],"answer":["A"],"analysis":{"point":"","options":{"A":"五四运动——是中国旧民主主义革命走向新民主主义革命的转折点，是本题正确答案。","B":"新文化运动——为五四运动的爆发和马克思主义的传播奠定了思想基础。","C":"中国共产党的成立——是中华民族发展史上开天辟地的大事变，点亮了民族复兴的灯塔。","D":"第一次国共合作的实现——是国民党一大胜利召开的意义。"}}},{"id":"basic-shigang-ch04-6","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 6 题"},"stem":"五四运动是中国近现代史上具有里程碑意义的重大事件，孕育了伟大五四精神。五四精神的核心是","choices":[{"id":"A","text":"爱国主义"},{"id":"B","text":"进步精神"},{"id":"C","text":"民主与科学"},{"id":"D","text":"解放思想"}],"answer":["A"],"analysis":{"point":"","options":{"A":"爱国主义——是五四精神的核心，是本题正确答案。","B":"非考点。","C":"民主与科学——是新文化运动的主要内容。","D":"非考点。"}}},{"id":"basic-shigang-ch04-7","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 7 题"},"stem":"自鸦片战争以来，中华民族遭受了巨大磨难，逐步沦为半殖民地半封建社会。面对深重的民族危机，无数仁人志士前赴后继，先后发起了各种救亡图存运动。其中，中国人民和中华民族第一次全面觉醒是在","choices":[{"id":"A","text":"辛亥革命"},{"id":"B","text":"新文化运动"},{"id":"C","text":"五四运动"},{"id":"D","text":"中国共产党的成立"}],"answer":["C"],"analysis":{"point":"","options":{"A":"辛亥革命仅仅促进了思想解放。","B":"新文化运动——是一次伟大的思想启蒙运动，为五四运动的爆发准备了思想条件。一和","C":"（原书未单独给出此项解析）","D":"中国共产党的成立——是中华民族发展史上开天辟地的大事变，点亮了民族复兴的灯塔。"}}},{"id":"basic-shigang-ch04-8","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 8 题"},"stem":"1924年，中国国民党第一次全国代表大会的召开标志着第一次国共合作正式形成。第一次国共合作的政治基础是","choices":[{"id":"A","text":"联俄、联共、扶助农工的三大政策"},{"id":"B","text":"旧三民主义"},{"id":"C","text":"中国共产党的民主革命纲领"},{"id":"D","text":"新三民主义的政纲"}],"answer":["D"],"analysis":{"point":"","options":{"A":"联俄、联共、扶助农工的三大政策——是贯彻新三民主义的具体政策。","B":"旧三民主义是辛亥革命的指导思想。","C":"中国共产党的民主革命纲领——是中共二大提出的反帝反封建纲领。","D":"新三民主义的政纲——是第一次国共合作的政治基础，是本题正确答案。"}}},{"id":"basic-shigang-ch04-9","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 9 题"},"stem":"在中国共产党领导的工人运动史上，多次罢工斗争成为反帝反封建革命的重要力量。其中，以组织严密、规模宏大、坚持时间长而著称，并创下中国工人运动史上持续时间最长纪录的政治大罢工是","choices":[{"id":"A","text":"香港海员大罢工"},{"id":"B","text":"安源路矿工人大罢工"},{"id":"C","text":"京汉铁路工人大罢工"},{"id":"D","text":"省港大罢工"}],"answer":["D"],"analysis":{"point":"","options":{"A":"香港海员大罢工——是中国工人阶级第一次直接对抗帝国主义势力的斗争。","B":"安源路矿工人大罢工——是中国共产党第一次独立领导并取得完全胜利的工人斗争。","C":"京汉铁路工人大罢工——是中国共产党领导的第一次工人运动高潮的顶点。","D":"省港大罢工——是中国工人运动史上持续时间最长的一次政治大罢工，是本题正确答案。"}}},{"id":"basic-shigang-ch04-10","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 10 题"},"stem":"中国共产党一经成立，中国革命就展现了新的面貌。中国共产党成立之后不久，就开始采取民族资产阶级、小资产阶级的政党和政治派别没有采取过也不可能采取的革命方法，即","choices":[{"id":"A","text":"群众路线的方法"},{"id":"B","text":"土地革命的方法"},{"id":"C","text":"武装斗争的方法"},{"id":"D","text":"统一战线的方法"}],"answer":["A"],"analysis":{"point":"","options":{"A":"群众路线的方法——是中国共产党成立后所采取的革命方法，是本题正确答案。","B":"都属于具体的革命政策。","C":"都属于具体的革命政策。","D":"都属于具体的革命政策。"}}},{"id":"basic-shigang-ch04-11","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 11 题"},"stem":"我国工会是中国共产党领导的工人阶级群众组织，是党联系职工群众的桥梁和纽带。共产党早期组织领导的第一个工会是","choices":[{"id":"A","text":"衙前农民协会"},{"id":"B","text":"长辛店工人俱乐部"},{"id":"C","text":"上海机器工会"},{"id":"D","text":"中华全国总工会"}],"answer":["C"],"analysis":{"point":"","options":{"A":"衙前农民协会——是中国第一个农民协会。","B":"长辛店工人俱乐部非考点。","C":"上海机器工会——是中国共产党早期组织领导的第一个工会，是本题正确答案。","D":"中华全国总工会——是在1925年5月第二次全国劳动大会上成立的。"}}},{"id":"basic-shigang-ch04-12","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 12 题"},"stem":"在近代中国历史上，中国国民党和中国共产党都是以救国救民为己任而诞生的革命政党。为了“打倒列强，除军阀，实现国家统一”，国共两党走向第一次合作。第一次国共合作正式形成的标志是","choices":[{"id":"A","text":"国民党一大事实上确认了联俄、联共、扶助农工的三大革命政策"},{"id":"B","text":"西安事变的和平解决"},{"id":"C","text":"《中共中央为公布国共合作宣言》的发表"},{"id":"D","text":"《关于中国共产党与国民党的关系问题的决议》的发布"}],"answer":["A"],"analysis":{"point":"","options":{"A":"国民党一大事实上确认了联俄、联共、扶助农工的三大革命政策——标志着第一次国共合作正式形成，是本题正确答案。","B":"西安事变的和平解决——标志着十年内战局面基本结束，国内和平初步实现。","C":"《中共中央为公布国共合作宣言》的发表——标志着以国共两党第二次合作为基础的抗日民族统一战线正式形成。","D":"《关于中国共产党与国民党的关系问题的决议》的发布——对国共第一次合作起了推动作用。"}}},{"id":"basic-shigang-ch04-13","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 13 题"},"stem":"1926年9月1日，毛泽东发表《国民革命与农民运动》一文，指出国民革命的中心问题是","choices":[{"id":"A","text":"土地革命"},{"id":"B","text":"分清敌友"},{"id":"C","text":"无产阶级的领导权"},{"id":"D","text":"农民问题"}],"answer":["D"],"analysis":{"point":"","options":{"A":"土地革命是中国资产阶级民主革命的中心问题。","B":"分清敌友是中国革命的首要问题。","C":"无产阶级的领导权是中国革命的中心问题。","D":"农民问题——是国民革命的中心问题，是本题正确答案。"}}},{"id":"basic-shigang-ch04-14","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 14 题"},"stem":"1927年，蒋介石、汪精卫先后叛变革命，实行清党分共政策后，国民党蜕变成了","choices":[{"id":"A","text":"工人、农民、城市小资产阶级和民族资产阶级的革命联盟"},{"id":"B","text":"代表地主阶级、买办性的大资产阶级利益的反动集团控制的政党"},{"id":"C","text":"以资产阶级革命派为主体的革命政党"},{"id":"D","text":"以走“中间道路”为目标的第三势力政党"}],"answer":["B"],"analysis":{"point":"","options":{"A":"工人、农民、城市小资产阶级和民族资产阶级的革命联盟——是第一次国共合作时期国民党的性质。","B":"代表地主阶级、买办性的大资产阶级利益的反动集团控制的政党——是蒋介石、汪精卫先后叛变革命后国民党的性质，是本题正确答案。","C":"以资产阶级革命派为主体的革命政党——是孙中山在辛亥革命期间领导的同盟会的性质。","D":"以走“中间道路”为目标的第三势力政党——是解放战争时期民主党派的性质。"}}},{"id":"basic-shigang-ch04-15","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 15 题"},"stem":"中国国民党第一次全国代表大会召开后，国共合作实现，中国人民反帝爱国运动蓬勃发展。1925年，由中国共产党领导的群众性反帝爱国运动，并掀起国民大革命高潮的事件是","choices":[{"id":"A","text":"黄埔军校的成立"},{"id":"B","text":"北伐战争"},{"id":"C","text":"五卅运动"},{"id":"D","text":"二七惨案"}],"answer":["C"],"analysis":{"point":"","options":{"A":"黄埔军校的成立——旨在为国民革命培养军事人才。","B":"北伐战争——是为了消灭孙传芳、吴佩孚和张作霖三大军阀。","C":"五卅运动——是国民大革命高潮的起点，是本题正确答案。","D":"二七惨案非考点。"}}},{"id":"basic-shigang-ch04-16","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 16 题"},"stem":"1915年兴起的新文化运动，是一场伟大的思想解放运动。新文化运动初期的基本内容包括","choices":[{"id":"A","text":"提倡民主和科学，反对专制和迷信盲从"},{"id":"B","text":"提倡个性解放，反对封建礼教"},{"id":"C","text":"提倡马克思主义，反对资产阶级改良主义"},{"id":"D","text":"提倡新文学，反对旧文学，实行文学革命"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是新文化运动初期的基本内容，是本题正确答案。","B":"是新文化运动初期的基本内容，是本题正确答案。","C":"提倡马克思主义，反对资产阶级改良主义——是五四运动后的新文化运动的内容。","D":"是新文化运动初期的基本内容，是本题正确答案。"}}},{"id":"basic-shigang-ch04-17","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 17 题"},"stem":"五四运动后，在马克思主义与中国工人运动相结合的进程中，中国早期马克思主义者的队伍开始形成并逐步壮大。这支队伍主要包括","choices":[{"id":"A","text":"新文化运动的精神领袖"},{"id":"B","text":"五四爱国运动的左翼骨干"},{"id":"C","text":"一部分原中国同盟会会员、辛亥革命时期的活动家"},{"id":"D","text":"留学欧美的自由主义知识分子"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是中国早期马克思主义者的队伍的组成部分，是本题正确答案。","B":"是中国早期马克思主义者的队伍的组成部分，是本题正确答案。","C":"是中国早期马克思主义者的队伍的组成部分，是本题正确答案。","D":"留学欧美的自由主义知识分子——非考点。"}}},{"id":"basic-shigang-ch04-18","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 18 题"},"stem":"在北洋军阀反动统治的艰难环境中，以李大钊为代表的早期马克思主义者掀起了一场研究、传播马克思主义的思想运动。这场运动一开始就","choices":[{"id":"A","text":"重视对马克思主义基本理论的学习"},{"id":"B","text":"注意从中国的实际出发，学习、运用马克思主义"},{"id":"C","text":"提出知识分子应当同劳动群众相结合的思想"},{"id":"D","text":"明确提出马克思主义与中国实际相结合的命题"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是早期马克思主义思想运动的三大特点，是本题正确答案。","B":"是早期马克思主义思想运动的三大特点，是本题正确答案。","C":"是早期马克思主义思想运动的三大特点，是本题正确答案。","D":"明确提出马克思主义与中国实际相结合的命题——是在中共六届六中全会上。"}}},{"id":"basic-shigang-ch04-19","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 19 题"},"stem":"五四运动后，马克思主义在中国的传播逐步深入，各地共产党早期组织纷纷建立并开展了一系列活动，为中国共产党的成立奠定了重要基础。下列属于中国共产党早期组织的主要活动的有","choices":[{"id":"A","text":"研究和宣传马克思主义，研究中国实际问题"},{"id":"B","text":"联合国民党左派力量，筹备建立革命统一战线"},{"id":"C","text":"到工人中去进行宣传和组织工作"},{"id":"D","text":"进行关于建党问题的讨论和实际组织工作"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"都属于中国共产党早期组织的主要活动，是本题正确答案。","B":"联合国民党左派力量，筹备建立革命统一战线——是第一次国共合作前夕（1923年中共三大后）的重要工作。","C":"都属于中国共产党早期组织的主要活动，是本题正确答案。","D":"都属于中国共产党早期组织的主要活动，是本题正确答案。"}}},{"id":"basic-shigang-ch04-20","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 20 题"},"stem":"1927年，在国民革命蓬勃发展的进程中，国民党右派相继发动反革命政变，血腥镇压共产党人和革命群众，导致第一次国共合作破裂、大革命走向失败。下列标志着大革命失败的历史事件有","choices":[{"id":"A","text":"中山舰事件"},{"id":"B","text":"四一二反革命政变"},{"id":"C","text":"马日事变"},{"id":"D","text":"七一五反革命政变"}],"answer":["B","D"],"analysis":{"point":"","options":{"A":"中山舰事件——是国民党右派限制和打击共产党的行动，此时国共合作仍在继续。","B":"是标志着大革命失败的历史事件，是本题正确答案。","C":"马日事变——是国民党右派发动的局部反革命政变，不是标志着大革命失败的事件。","D":"是标志着大革命失败的历史事件，是本题正确答案。"}}},{"id":"basic-shigang-ch04-21","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 21 题"},"stem":"1915年，陈独秀在其主编的《新青年》（原名《青年杂志》)上刊载文章，提倡民主与科学，反对封建文化，揭开了新文化运动的序幕。这次运动沉重打击了统治中国2000多年的传统礼教，启发了人们的民主觉悟，推动了现代科学在中国的发展。但是，初期的新文化运动也存在着明显的局限性，这些局限性包括","choices":[{"id":"A","text":"将资本主义民主作为改造中国的思想武器"},{"id":"B","text":"把改造国民性置于优先的地位"},{"id":"C","text":"不具备马克思主义的批判精神"},{"id":"D","text":"对孔学进行了彻底的否定"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是新文化运动初期存在的明显的局限性，是本题正确答案。","B":"是新文化运动初期存在的明显的局限性，是本题正确答案。","C":"是新文化运动初期存在的明显的局限性，是本题正确答案。","D":"对孔学进行了彻底的否定——是错误说法，新文化运动的思想家们对孔学的批判是充满理性的。"}}},{"id":"basic-shigang-ch04-22","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 22 题"},"stem":"中国共产党的成立，是近现代中国历史发展的必然产物，是中国人民在救亡图存斗争中顽强求索的必然产物，是实现中华民族伟大复兴的必然产物。建党初期，中国共产党要胜利地担负起自己的历史使命，必须不断地加强自身的建设，这是因为","choices":[{"id":"A","text":"在党内，出身于小资产阶级的党员占有相当大的数量"},{"id":"B","text":"新生的中国共产党迫切需要把大量的农民阶级和城市小资产阶级改造成为无产阶级"},{"id":"C","text":"中国共产党是在一个经济文化落后的半殖民地半封建社会开始自己的活动的"},{"id":"D","text":"中国共产党要把马克思列宁主义同中国实际结合起来，不能不经历一个曲折的探索过程"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是建党初期，中国共产党必须不断地加强自身的建设的原因，是本题正确答案。","B":"新生的中国共产党迫切需要把大量的农民阶级和城市小资产阶级改造成为无产阶级——是错误说法，中国共产党改造的是小农思想和小资思想，而不是直接改造阶级。","C":"是建党初期，中国共产党必须不断地加强自身的建设的原因，是本题正确答案。","D":"是建党初期，中国共产党必须不断地加强自身的建设的原因，是本题正确答案。"}}},{"id":"basic-shigang-ch04-23","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 23 题"},"stem":"第一次国内革命战争，又称“大革命”，是1924年至1927年中国人民在中国共产党和中国国民党合作领导下进行的反帝反封建的革命斗争。大革命失败的客观原因有","choices":[{"id":"A","text":"资产阶级发生严重的动摇"},{"id":"B","text":"中国共产党领导人的右倾机会主义错误"},{"id":"C","text":"反革命力量的强大"},{"id":"D","text":"蒋介石、汪精卫背叛革命"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是大革命失败的客观原因，是本题正确答案。","B":"中国共产党领导人的右倾机会主义错误——是大革命失败的主观原因之一。","C":"是大革命失败的客观原因，是本题正确答案。","D":"是大革命失败的客观原因，是本题正确答案。"}}},{"id":"basic-shigang-ch04-24","moduleId":"basic","subjectId":"shigang","chapter":"第四章 中国共产党成立和中国革命新局面","chapterKey":"第四章","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第四章 第 24 题"},"stem":"1925年1月，中国共产党第四次全国代表大会在上海召开。这次会议的成果有","choices":[{"id":"A","text":"提出了工农联盟问题"},{"id":"B","text":"事实上确立了毛泽东在党中央和红军的领导地位"},{"id":"C","text":"提出了无产阶级在民主革命中的领导权问题"},{"id":"D","text":"彻底清算了以陈独秀为代表的右倾机会主义错误"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是中共四大的成果，是本题正确答案。","B":"事实上确立了毛泽东在党中央和红军的领导地位——是遵义会议的成果。","C":"是中共四大的成果，是本题正确答案。","D":"彻底清算了以陈独秀为代表的右倾机会主义错误——是八七会议的内容。"}}},{"id":"basic-shigang-ch05-1","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 1 题"},"stem":"1927年大革命失败后，国民党反动派对共产党人和革命群众实行血腥屠杀，中国革命陷入低潮。在此危急关头，中国共产党毅然发动武装起义，奋起反抗国民党的反动统治。其中，打响了武装反抗国民党反动派第一枪的历史事件是","choices":[{"id":"A","text":"百色起义"},{"id":"B","text":"秋收起义"},{"id":"C","text":"广州起义"},{"id":"D","text":"南昌起义"}],"answer":["D"],"analysis":{"point":"","options":{"A":"百色起义——是创建左右江革命根据地的关键起义。","B":"秋收起义——公开打出了“工农革命军”旗帜。","C":"广州起义——是由张太雷和叶挺、叶剑英等领导的起义。","D":"南昌起义——打响了武装反抗国民党反动派的第一枪，是中国共产党独立领导革命战争、创建人民军队和武装夺取政权的开端，是本题正确答案。"}}},{"id":"basic-shigang-ch05-2","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 2 题"},"stem":"1927年10月，毛泽东率领秋收起义部队抵达井冈山地区，开始创建中国第一个农村革命根据地。在随后巩固和扩大根据地的斗争中，湘赣边界成立的第一个红色政权是","choices":[{"id":"A","text":"遂川县工农兵政府"},{"id":"B","text":"茶陵县工农兵政府"},{"id":"C","text":"宁冈县工农兵政府"},{"id":"D","text":"湘赣边界工农兵苏维埃政府"}],"answer":["B"],"analysis":{"point":"","options":{"A":"非考点。","B":"茶陵县工农兵政府——是毛泽东领导井冈山革命根据地斗争后，在湘赣边界成立的第一个红色政权，是本题正确答案。","C":"非考点。","D":"非考点。"}}},{"id":"basic-shigang-ch05-3","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 3 题"},"stem":"1931年11月，中华苏维埃共和国在江西瑞金成立，其政权组织形式以新型民主制度为核心，强调工农兵群众当家作主。这一制度是","choices":[{"id":"A","text":"人民民主专政制度"},{"id":"B","text":"参议会制度"},{"id":"C","text":"工农兵代表大会制度"},{"id":"D","text":"人民代表大会制度"}],"answer":["C"],"analysis":{"point":"","options":{"A":"人民民主专政是中华人民共和国的国体。","B":"参议会制度——是抗日战争时期中国共产党领导实行的政治制度。","C":"工农兵代表大会制度——是中华苏维埃共和国实行的政治制度，是本题正确答案。","D":"人民代表大会制度——是1954年第一届全国人民代表大会正式确立的我国的根本政治制度。"}}},{"id":"basic-shigang-ch05-4","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 4 题"},"stem":"1927年9月29日，毛泽东领导起义军在江西省永新县三湾村进行了著名的三湾改编，从组织上确立了党对军队的领导。三湾改编是","choices":[{"id":"A","text":"中国共产党和红军建设的纲领性文献"},{"id":"B","text":"中国共产党创建人民军队和武装夺取政权的开端"},{"id":"C","text":"建设无产阶级领导的新型人民军队的重要开端"},{"id":"D","text":"由大革命失败到土地革命战争兴起的历史性转变"}],"answer":["C"],"analysis":{"point":"","options":{"A":"中国共产党和红军建设的纲领性文献——是《古田会议决议》。","B":"中国共产党创建人民军队和武装夺取政权的开端——是南昌起义。","C":"建设无产阶级领导的新型人民军队的重要开端——是三湾改编，是本题正确答案。","D":"由大革命失败到土地革命战争兴起的历史性转变——是八七会议。"}}},{"id":"basic-shigang-ch05-5","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 5 题"},"stem":"1929年12月下旬，红四军党的第九次代表大会在福建上杭县古田村召开，会议总结了红军创立以来的经验，通过了著名的《古田会议决议》。《古田会议决议》的中心思想是","choices":[{"id":"A","text":"中国共产党必须服从共产国际的领导"},{"id":"B","text":"武装斗争是中国革命的主要形式"},{"id":"C","text":"在农村根据地广泛开展土地革命"},{"id":"D","text":"用无产阶级思想进行军队和党的建设"}],"answer":["D"],"analysis":{"point":"","options":{"A":"中国共产党必须服从共产国际的领导——是中共二大的内容。","B":"武装斗争是中国革命的主要形式——是毛泽东在《<共产党人〉发刊词》一文中正式提出的。","C":"在农村根据地广泛开展土地革命——是《井冈山土地法》颁布后实施的土地政策。","D":"用无产阶级思想进行军队和党的建设——是《古田会议决议》的中心思想，是本题正确答案。"}}},{"id":"basic-shigang-ch05-6","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 6 题"},"stem":"1935年1月，红军攻克黔北重镇遵义，中共中央在此召开了政治局扩大会议，即遵义会议。会议集中解决了当时具有决定意义的军事和组织问题。遵义会议是中国共产党历史上一个生死攸关的转折点。这次会议的重大意义在于","choices":[{"id":"A","text":"宣告了国民党反动派消灭中国共产党和红军的图谋彻底失败"},{"id":"B","text":"确立了“农村包围城市、武装夺取政权”的革命道路"},{"id":"C","text":"开始确立以毛泽东为主要代表的马克思主义正确路线在党中央的领导地位"},{"id":"D","text":"制定了抗日民族统一战线的策略方针"}],"answer":["C"],"analysis":{"point":"","options":{"A":"宣告了国民党反动派消灭中国共产党和红军的图谋彻底失败——是长征胜利的历史意义。","B":"确立了“农村包围城市、武装夺取政权”的革命道路——是1938年中共六届六中全会的内容。","C":"开始确立以毛泽东为主要代表的马克思主义正确路线在党中央的领导地位——是遵义会议的重大意义，是本题正确答案。","D":"制定了抗日民族统一战线的策略方针——是瓦窑堡会议的核心内容。"}}},{"id":"basic-shigang-ch05-7","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 7 题"},"stem":"1936年10月，中国工农红军主力历经二万五千里转战，胜利完成战略转移，创造了中国革命史上的伟大奇迹。红军长征胜利的伟大意义集中体现在","choices":[{"id":"A","text":"宣告了国民党反动派消灭中国共产党和红军的图谋彻底失败"},{"id":"B","text":"宣告了中国共产党和红军肩负着民族希望胜利实现了北上抗日的战略转移"},{"id":"C","text":"实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折"},{"id":"D","text":"铸就了伟大的长征精神"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"均是红军长征胜利的伟大意义的集中体现，是本题正确答案。","B":"均是红军长征胜利的伟大意义的集中体现，是本题正确答案。","C":"均是红军长征胜利的伟大意义的集中体现，是本题正确答案。","D":"均是红军长征胜利的伟大意义的集中体现，是本题正确答案。"}}},{"id":"basic-shigang-ch05-8","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 8 题"},"stem":"1927年8月7日，中共中央在湖北汉口原俄租界三教街41号（现鄱阳街139号）召开了紧急会议，即八七会议。八七会议给正处在思想混乱和组织涣散中的中国共产党指明了新的出路。下列关于八七会议的内容，说法正确的有","choices":[{"id":"A","text":"坚决纠正和结束了陈独秀的右倾主义错误"},{"id":"B","text":"阐述了加强党的思想建设的极端重要性"},{"id":"C","text":"确定了土地革命和武装反抗国民党反动派的总方针"},{"id":"D","text":"第一次提出了“政权是由枪杆子中取得的”思想"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是八七会议的内容，是本题正确答案。","B":"阐述了加强党的思想建设的极端重要性——是古田会议的主要内容。","C":"是八七会议的内容，是本题正确答案。","D":"是八七会议的内容，是本题正确答案。"}}},{"id":"basic-shigang-ch05-9","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 9 题"},"stem":"1929年9月，中共中央给红四军前委的指示信中指出：先有农村红军，后有城市政权，这是中国革命的特征，这是中国经济基础的产物。毛泽东深刻论证红色政权能够长期存在并发展的主客观条件、提出工农武装割据思想的著作是","choices":[{"id":"A","text":"《中国社会各阶级的分析》"},{"id":"B","text":"《井冈山的斗争》"},{"id":"C","text":"《反对本本主义》"},{"id":"D","text":"《中国的红色政权为什么能够存在？》"}],"answer":["B","D"],"analysis":{"point":"","options":{"A":"《中国社会各阶级的分析》——科学剖析了当时中国社会各阶级的经济地位、政治态度及其在革命中的作用，提出“分清敌友”是中国革命的首要问题。","B":"是提出工农武装割据思想的著作，是本题正确答案。","C":"《反对本本主义》——阐明了坚持辩证唯物主义的思想路线即坚持理论与实际相结合的原则的极端重要性。","D":"是提出工农武装割据思想的著作，是本题正确答案。"}}},{"id":"basic-shigang-ch05-10","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 10 题"},"stem":"1927年大革命失败后，中国共产党在农村坚持武装斗争，广泛开展土地革命，建立农村革命根据地。党在土地革命战争时期实行的正确的土地政策和阶级政策包括","choices":[{"id":"A","text":"保存富农阶层"},{"id":"B","text":"限制富农"},{"id":"C","text":"保护中农利益使之不受侵犯"},{"id":"D","text":"依靠贫雇农"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"保存富农阶层是中华人民共和国成立初期的土地改革所采取的阶级政策。","B":"是党在土地革命战争时期实行的正确的土地政策和阶级政策，是本题正确答案。","C":"是党在土地革命战争时期实行的正确的土地政策和阶级政策，是本题正确答案。","D":"是党在土地革命战争时期实行的正确的土地政策和阶级政策，是本题正确答案。"}}},{"id":"basic-shigang-ch05-11","moduleId":"basic","subjectId":"shigang","chapter":"第五章 中国革命的新道路","chapterKey":"第五章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第五章 第 11 题"},"stem":"1925年深秋，青年毛泽东独立寒秋，面对滚滚北去的湘江，发出了“问苍茫大地，谁主沉浮？”的历史之问，当时中国革命洪流汹涌，前途未卜。十一年后的1936年，毛泽东已率领红军历经千难万险，完成了伟大的战略转移，于陕北高原眺望北国风雪，挥毫写下“数风流人物，还看今朝”的时代强音，其间豪情，从容自信。两首《沁园春》，一问一答，背后不仅是毛泽东个人心境的转变，更是中国共产党从幼年逐渐走向成熟的历史见证。这十一年间，中国共产党","choices":[{"id":"A","text":"完成了从大革命失败到土地革命战争兴起的转折"},{"id":"B","text":"找到了农村包围城市、武装夺取政权的革命道路"},{"id":"C","text":"开启了党独立自主解决中国革命实际问题的新阶段"},{"id":"D","text":"实现了马克思主义和中国实际相结合的第一次飞跃"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是中国共产党在土地革命战争时期经历的重大事件，是本题正确答案。","B":"是中国共产党在土地革命战争时期经历的重大事件，是本题正确答案。","C":"是中国共产党在土地革命战争时期经历的重大事件，是本题正确答案。","D":"实现了马克思主义和中国实际相结合的第一次飞跃——是1945年中共七大胜利召开的意义。"}}},{"id":"basic-shigang-ch06-1","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 1 题"},"stem":"1931年，日本帝国主义蓄意制造侵华事件，发动了对中国东北的武装进攻。标志着中国抗日战争起点的历史事件是","choices":[{"id":"A","text":"七七事变"},{"id":"B","text":"九一八事变"},{"id":"C","text":"华北事变"},{"id":"D","text":"一·二八事变"}],"answer":["B"],"analysis":{"point":"","options":{"A":"七七事变——是日本全面侵华战争的开端，开辟了世界反法西斯战争的东方主战场。","B":"九一八事变——是日本侵华战争的开端，是中国抗日战争的起点，是本题正确答案。","C":"华北事变——是日本企图侵占华北、进而灭亡中国的一系列事件的总称。","D":"一·二八事变——是日本进攻上海的局部侵华事件，是九一八事变后中国局部抗战的重要组成"}}},{"id":"basic-shigang-ch06-2","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 2 题"},"stem":"1935年，日本帝国主义策动“华北自治”，中华民族危机空前严重。北平（今北京）学生发出“华北之大，已经安放不得一张平静的书桌了”的悲愤呐喊，并在中国共产党地下党组织的领导下发动了一场声势浩大的抗日游行。这场运动促进了中华民族的觉醒，标志着中国人民抗日救亡运动新高潮的到来。这一历史事件是","choices":[{"id":"A","text":"西安事变"},{"id":"B","text":"一·二八事变"},{"id":"C","text":"一二·九运动"},{"id":"D","text":"五四运动"}],"answer":["C"],"analysis":{"point":"","options":{"A":"西安事变的和平解决是当时时局转换的枢纽，十年内战局面基本结束，国内和平初步实现。","B":"一·二八事变——是日本进攻上海的局部侵华事件，是九一八事变后中国局部抗战的重要组成","C":"一二·九运动——标志着中国人民抗日救亡运动新高潮的到来，是本题正确答案。","D":"五四运动是中国新民主主义革命的开端。"}}},{"id":"basic-shigang-ch06-3","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 3 题"},"stem":"1937年全民族抗战爆发后，中国军队奋起抵抗，打破日军不可战胜的神话，取得全民族抗战以来中国军队主动寻歼敌人的第一次重大胜利的战役是","choices":[{"id":"A","text":"平型关大捷"},{"id":"B","text":"台儿庄战役"},{"id":"C","text":"百团大战"},{"id":"D","text":"淞沪会战"}],"answer":["A"],"analysis":{"point":"","options":{"A":"平型关大捷——是全民族抗战以来中国军队主动寻歼敌人的第一次重大胜利，打破了日军不可战胜的神话，是本题正确答案。","B":"台儿庄战役是抗战初期国民党正面战场取得的大捷。","C":"百团大战是八路军在华北地区发动的大规模战略性进攻战役。","D":"淞沪会战——是全民族抗战初期正面战场的大规模防御战役，最终以上海沦陷而告终。"}}},{"id":"basic-shigang-ch06-4","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 4 题"},"stem":"在抗日战争初期，国共两党军队为抗击日本侵略者，进行了多次合作。其中，国共两党军队合作抗日、配合最好的一次战役是","choices":[{"id":"A","text":"平型关大捷"},{"id":"B","text":"台儿庄战役"},{"id":"C","text":"忻口会战"},{"id":"D","text":"武汉会战"}],"answer":["C"],"analysis":{"point":"","options":{"A":"平型关大捷——是全民族抗战以来中国军队主动寻歼敌人的第一次重大胜利。","B":"台儿庄战役——是抗战初期国民党正面战场取得的大捷。","C":"忻口会战——是国共两党军队合作抗日、配合最好的一次战役，是本题正确答案。","D":"武汉会战——是抗战时期战略防御阶段规模最大的战役，国共合作较为广泛，时间晚于忻口会战。"}}},{"id":"basic-shigang-ch06-5","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 5 题"},"stem":"在抗日战争时期，中国共产党领导的抗日根据地建设中，首要的、根本的任务是","choices":[{"id":"A","text":"开展经济建设"},{"id":"B","text":"加强政权建设"},{"id":"C","text":"推进文化建设"},{"id":"D","text":"强化军事训练"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是抗日根据地建设的内容，但不是首要的、根本的任务。","B":"加强政权建设——是抗日根据地建设中首要的、根本的任务，是本题正确答案。","C":"是抗日根据地建设的内容，但不是首要的、根本的任务。","D":"强化军事训练是提升抗日武装战斗力的举措。"}}},{"id":"basic-shigang-ch06-6","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 6 题"},"stem":"1942年，中国共产党在全党范围内开展了延安整风运动，旨在破除党内的错误思想、统一全党认识，为抗战胜利与党的建设奠定思想基础。此次整风运动最主要的任务是","choices":[{"id":"A","text":"反对官僚主义"},{"id":"B","text":"反对主观主义"},{"id":"C","text":"反对宗派主义"},{"id":"D","text":"反对党八股"}],"answer":["B"],"analysis":{"point":"","options":{"A":"反对官僚主义——是新中国成立初期“三反”运动的内容。","B":"反对主观主义——是延安整风运动最主要的任务，属于整顿学风，是本题正确答案。","C":"反对宗派主义——是延安整风运动的内容之一，属于整顿党风。","D":"反对党八股——是延安整风运动的内容之一，属于整顿文风。"}}},{"id":"basic-shigang-ch06-7","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 7 题"},"stem":"为了纠正党内存在的各种非无产阶级思想，中国共产党在延安开展了整风运动。其中，整风运动的重点是反对","choices":[{"id":"A","text":"经验主义"},{"id":"B","text":"宗派主义"},{"id":"C","text":"教条主义"},{"id":"D","text":"党八股"}],"answer":["C"],"analysis":{"point":"","options":{"A":"经验主义是主观主义的表现之一。","B":"宗派主义——是延安整风运动要反对的错误倾向，属于整顿党风。","C":"教条主义——是主观主义的表现之一，反对教条主义是延安整风运动的重点，是本题正确答案。","D":"党八股是延安整风运动要反对的错误倾向，属于整顿文风。"}}},{"id":"basic-shigang-ch06-8","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 8 题"},"stem":"在土地革命战争后期和全民族抗日战争时期，毛泽东思想在同教条主义的斗争中不断丰富发展，实现了马克思主义中国化的第一次历史性飞跃。其中，毛泽东思想得到多方面展开而趋于成熟的标志是","choices":[{"id":"A","text":"“农村包围城市、武装夺取政权”革命道路理论的形成"},{"id":"B","text":"新民主主义理论的系统阐明"},{"id":"C","text":"党的七大将毛泽东思想确立为党的指导思想"},{"id":"D","text":"《论十大关系》《关于正确处理人民内部矛盾的问题》的发表"}],"answer":["B"],"analysis":{"point":"","options":{"A":"“农村包围城市、武装夺取政权”革命道路理论的形成——是毛泽东思想初步形成的标志。","B":"新民主主义理论的系统阐明是毛泽东思想趋于成熟的标志，是本题正确答案。","C":"党的七大将毛泽东思想确立为党的指导思想是毛泽东思想正式确立的标志。","D":"《论十大关系》《关于正确处理人民内部矛盾的问题》的发表——是毛泽东思想在社会主义建设时期继续发展的重要成果。"}}},{"id":"basic-shigang-ch06-9","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 9 题"},"stem":"根据《波茨坦公告》的相关规定，中国抗日战争取得完全胜利的重要标志是","choices":[{"id":"A","text":"台湾及澎湖列岛重归中国主权管辖"},{"id":"B","text":"日本正式签署无条件投降书"},{"id":"C","text":"中国战区日军投降仪式在南京举行"},{"id":"D","text":"东北三省全部光复"}],"answer":["A"],"analysis":{"point":"","options":{"A":"台湾及澎湖列岛重归中国主权管辖——是中国抗日战争取得完全胜利的重要标志，是本题正确答案。","B":"非考点。","C":"非考点。","D":"非考点。"}}},{"id":"basic-shigang-ch06-10","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 10 题"},"stem":"抗日战争时期，通过《关于目前形势与党的任务决定》分析了国民党片面抗战路线的实质和危害，主张实行全面抗战路线，即人民战争路线的会议是","choices":[{"id":"A","text":"洛川会议"},{"id":"B","text":"瓦窑堡会议"},{"id":"C","text":"中共六届六中全会"},{"id":"D","text":"古田会议"}],"answer":["A"],"analysis":{"point":"","options":{"A":"洛川会议——主张实行全面抗战路线，是本题正确答案。","B":"瓦窑堡会议——提出了党的抗日民族统一战线的新政策。","C":"中共六届六中全会——明确提出了“马克思主义的中国化”的命题。","D":"古田会议——确立了“党指挥枪”的原则。"}}},{"id":"basic-shigang-ch06-11","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 11 题"},"stem":"毛泽东在《论持久战》中指出，中国抗日战争取得胜利最关键的阶段是","choices":[{"id":"A","text":"战略防御阶段"},{"id":"B","text":"战略相持阶段"},{"id":"C","text":"战略反攻阶段"},{"id":"D","text":"战略坚守阶段"}],"answer":["B"],"analysis":{"point":"","options":{"A":"战略防御阶段——是抗日战争三阶段的第一个阶段。","B":"战略相持阶段——是抗日战争三阶段的第二个阶段，是抗日战争取得胜利最关键的阶段，是本题正确答案。","C":"战略反攻阶段——是抗日战争三阶段的第三个阶段。","D":"战略坚守阶段非考点。"}}},{"id":"basic-shigang-ch06-12","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 12 题"},"stem":"1941年1月，震惊中外的皖南事变爆发后，《新华日报》刊出周恩来的题词手迹：“为江南死国难者志哀！”“千古奇冤，江南一叶，同室操戈，相煎何急?!”大敌当前，中国共产党以民族利益为重，为避免抗日民族统一战线的破裂，提出的策略总方针是","choices":[{"id":"A","text":"坚持抗战、团结、进步，反对妥协、分裂、倒退"},{"id":"B","text":"有理、有利、有节"},{"id":"C","text":"又联合又斗争"},{"id":"D","text":"发展进步势力、争取中间势力、孤立顽固势力"}],"answer":["D"],"analysis":{"point":"","options":{"A":"坚持抗战、团结、进步，反对妥协、分裂、倒退——是中国共产党提出的抗战三大口号。","B":"有理、有利、有节是中国共产党在同顽固派作斗争时坚持的原则。","C":"又联合又斗争——是中国共产党对待顽固派的政策。","D":"发展进步势力、争取中间势力、孤立顽固势力——是抗日民族统一战线的策略总方针，是本题正确答案。"}}},{"id":"basic-shigang-ch06-13","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 13 题"},"stem":"中国共产党关于抗日民族统一战线的策略总方针是发展进步势力、争取中间势力、孤立顽固势力。毛泽东把统一战线视为与党和军队平等的、取得革命胜利的三大法宝之一。在抗日民族统一战线中，进步势力主要是指","choices":[{"id":"A","text":"工人、农民、城市小资产阶级和民族资产阶级"},{"id":"B","text":"民族资产阶级、开明绅士和地方实力派"},{"id":"C","text":"工人、农民和城市小资产阶级"},{"id":"D","text":"大地主大资产阶级的抗日派"}],"answer":["C"],"analysis":{"point":"","options":{"A":"工人、农民、城市小资产阶级和民族资产阶级——民族资产阶级属于中间势力，其余阶级属于进步势力。","B":"民族资产阶级、开明绅士和地方实力派——属于中间势力。","C":"工人、农民和城市小资产阶级属于进步势力，是本题正确答案。","D":"大地主大资产阶级的抗日派——属于顽固势力。"}}},{"id":"basic-shigang-ch06-14","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 14 题"},"stem":"延安整风运动，使全党确立了一条实事求是的辩证唯物主义的思想路线，使干部在思想上大大地提高了一步，使党达到了空前的团结，在中国共产党历史上具有深远的历史意义。标志着延安整风运动胜利结束的著作是","choices":[{"id":"A","text":"《改造我们的学习》"},{"id":"B","text":"《<共产党人>发刊词》"},{"id":"C","text":"《中国革命和中国共产党》"},{"id":"D","text":"《关于若干历史问题的决议》"}],"answer":["D"],"analysis":{"point":"","options":{"A":"《改造我们的学习》——标志着延安整风运动的开始。","B":"《<共产党人〉发刊词》——提出了中国共产党在中国革命中战胜敌人的“三大法宝”。","C":"《中国革命和中国共产党》——首次提出“新民主主义革命”的科学概念。","D":"《关于若干历史问题的决议》——是标志着延安整风运动胜利结束的著作，是本题正确答案。"}}},{"id":"basic-shigang-ch06-15","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 15 题"},"stem":"中国人民抗日战争是近代以来中国人民反抗外敌入侵持续时间最长、规模最大、牺牲最多的民族解放斗争，也是第一次取得完全胜利的民族解放斗争。中国人民抗日战争胜利的决定因素是","choices":[{"id":"A","text":"全民族抗战"},{"id":"B","text":"以爱国主义为核心的民族精神"},{"id":"C","text":"中国共产党的中流砥柱作用"},{"id":"D","text":"世界反法西斯力量的同情和支持"}],"answer":["B"],"analysis":{"point":"","options":{"A":"全民族抗战——是中国人民抗日战争胜利的重要法宝。","B":"以爱国主义为核心的民族精神是中国人民抗日战争胜利的决定因素，是本题正确答案。","C":"中国共产党的中流砥柱作用——是中国人民抗日战争胜利的关键。","D":"世界反法西斯力量的同情和支持——是中国人民抗日战争胜利的外部因素。"}}},{"id":"basic-shigang-ch06-16","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 16 题"},"stem":"1937年七七事变爆发后，全面抗战由此开始。国共两党加快了合作谈判的进程，经过多次协商，两党最终就合作抗日达成共识。以国共两党第二次合作为基础的抗日民族统一战线正式形成的标志是","choices":[{"id":"A","text":"西安事变的和平解决"},{"id":"B","text":"国民党中央通讯社发表《中共中央为公布国共合作宣言》"},{"id":"C","text":"蒋介石发表实际上承认中国共产党合法地位的谈话"},{"id":"D","text":"卢沟桥事变爆发，全民族抗战开始"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"西安事变的和平解决——标志着十年内战局面基本结束，国内和平初步实现。","B":"是以国共两党第二次合作为基础的抗日民族统一战线正式形成的标志，是本题正确答案。","C":"是以国共两党第二次合作为基础的抗日民族统一战线正式形成的标志，是本题正确答案。","D":"卢沟桥事变爆发，全民族抗战开始——开辟了世界反法西斯战争的东方主战场。"}}},{"id":"basic-shigang-ch06-17","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 17 题"},"stem":"抗日民族统一战线是以国共两党第二次合作为基础建立的全民族抗战阵线，相较于大革命时期的第一次国民革命统一战线，它面临的历史背景和斗争任务更为复杂，因此具有鲜明的新特点。下列选项中，属于抗日民族统一战线新特点的有","choices":[{"id":"A","text":"广泛的民族性和复杂的阶级矛盾"},{"id":"B","text":"国共双方有政权有军队的合作"},{"id":"C","text":"实行共产党员以个人身份加入国民党的党内合作形式"},{"id":"D","text":"没有正式的固定的组织形式和协商一致的具体的共同纲领"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"属于抗日民族统一战线的新特点，是本题正确答案。","B":"属于抗日民族统一战线的新特点，是本题正确答案。","C":"实行共产党员以个人身份加入国民党的党内合作形式——是第一次国民革命统一战线的组织形式，并不是第二次合作中的新特点。","D":"属于抗日民族统一战线的新特点，是本题正确答案。"}}},{"id":"basic-shigang-ch06-18","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 18 题"},"stem":"抗日战争进入相持阶段后，面对团结抗战局面出现的中途妥协和内部分裂两大危险，中国共产党明确提出的口号包括","choices":[{"id":"A","text":"“坚持抗战到底—反对中途妥协”"},{"id":"B","text":"“巩固国内团结——反对内部分裂”"},{"id":"C","text":"“停止内战一致抗日”"},{"id":"D","text":"“力求全国进步——反对向后倒退”"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是抗日战争进入相持阶段后中国共产党提出的政治口号，是本题正确答案。","B":"是抗日战争进入相持阶段后中国共产党提出的政治口号，是本题正确答案。","C":"“停止内战—一致抗日”——是1935年前后为停止国共内战、推动抗日民族统一战线初步形成提出的口号。","D":"是抗日战争进入相持阶段后中国共产党提出的政治口号，是本题正确答案。"}}},{"id":"basic-shigang-ch06-19","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 19 题"},"stem":"1945年召开的中共七大总结了中国共产党在长期革命斗争中形成的优良作风，明确概括为党的三大优良作风，即","choices":[{"id":"A","text":"理论和实践相结合的作风"},{"id":"B","text":"和人民群众紧密联系在一起的作风"},{"id":"C","text":"自我批评的作风"},{"id":"D","text":"艰苦奋斗的作风"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是中共七大总结的党的三大优良作风，是本题正确答案。","B":"是中共七大总结的党的三大优良作风，是本题正确答案。","C":"是中共七大总结的党的三大优良作风，是本题正确答案。","D":"艰苦奋斗的作风——不属于中共七大所明确概括的三大优良作风的范畴。"}}},{"id":"basic-shigang-ch06-20","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 20 题"},"stem":"在中国共产党地下党组织的领导下，1935年12月9日，北平（今北京）学生举行声势浩大的抗日游行，这就是一二·九运动。它促进了中华民族的觉醒，标志着中国人民抗日救亡运动新高潮的到来。一二·九运动喊出的口号有","choices":[{"id":"A","text":"“反对华北自治”"},{"id":"B","text":"“外争主权、内除国贼”"},{"id":"C","text":"“打倒日本帝国主义”"},{"id":"D","text":"“停止内战，一致对外”"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是一二·九运动喊出的口号，是本题正确答案。","B":"“外争主权、内除国贼”——是五四运动的口号。","C":"是一二·九运动喊出的口号，是本题正确答案。","D":"是一二·九运动喊出的口号，是本题正确答案。"}}},{"id":"basic-shigang-ch06-21","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 21 题"},"stem":"在土地革命战争后期和抗日战争时期，毛泽东思想得到系统总结和多方面展开而趋于成熟。下列毛泽东的科学著作，写于这两个时期的有","choices":[{"id":"A","text":"《星星之火，可以燎原》"},{"id":"B","text":"《反对本本主义》"},{"id":"C","text":"《新民主主义论》"},{"id":"D","text":"《论联合政府》"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"是毛泽东在土地革命战争前期撰写的著作。","B":"是毛泽东在土地革命战争前期撰写的著作。","C":"是毛泽东在土地革命战争后期和抗日战争时期撰写的著作，是本题正确答案。","D":"是毛泽东在土地革命战争后期和抗日战争时期撰写的著作，是本题正确答案。"}}},{"id":"basic-shigang-ch06-22","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 22 题"},"stem":"抗日民族统一战线是以国共合作为基础的。中国共产党在统一战线中坚持独立自主原则，既统一，又独立。坚持这一原则，共产党必须","choices":[{"id":"A","text":"保持在思想上、政治上和组织上的独立性"},{"id":"B","text":"坚持对人民军队的绝对领导"},{"id":"C","text":"一切经过统一战线，一切服从统一战线"},{"id":"D","text":"对国民党采取又团结又斗争、以斗争求团结的方针"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是中国共产党在抗日民族统一战线中坚持独立自主原则的措施，是本题正确答案。","B":"是中国共产党在抗日民族统一战线中坚持独立自主原则的措施，是本题正确答案。","C":"一切经过统一战线，一切服从统一战线——是王明在抗战初期提出的右倾路线，是错误说法。","D":"是中国共产党在抗日民族统一战线中坚持独立自主原则的措施，是本题正确答案。"}}},{"id":"basic-shigang-ch06-23","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 23 题"},"stem":"抗日根据地的政权，是中国共产党领导下的抗日民族统一战线性质的政权。在政权机关工作人员的名额分配上实行“三三制”原则，“三三制”的人员构成分别是指","choices":[{"id":"A","text":"共产党员"},{"id":"B","text":"中间派"},{"id":"C","text":"民族资产阶级"},{"id":"D","text":"党外进步人士"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是“三三制”原则的内容，是本题正确答案。","B":"是“三三制”原则的内容，是本题正确答案。","C":"民族资产阶级属于“三三制”原则中的中间派。","D":"是“三三制”原则的内容，是本题正确答案。"}}},{"id":"basic-shigang-ch06-24","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 24 题"},"stem":"在中国共产党的领导下，中国人民浴血奋战，付出了巨大牺牲，为世界反法西斯战争胜利作出了不可磨灭的历史贡献。中国人民抗日战争与世界反法西斯战争的关系，表现在","choices":[{"id":"A","text":"中国人民抗日战争牵制和削弱了日本的力量，使之不敢贸然北进，使苏联避免了东西两面作战"},{"id":"B","text":"中国人民抗日战争推迟了日本发动太平洋战争的时间，使之不能全力南进，减轻了美、英军队的压力"},{"id":"C","text":"中国人民抗日战争为同盟国军队实施战略反攻创造了有利条件"},{"id":"D","text":"中国人民抗日战争得到了世界上所有爱好和平与正义的反法西斯力量的同情和支持"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是中国人民抗日战争与世界反法西斯战争关系的表现，是本题正确答案。","B":"是中国人民抗日战争与世界反法西斯战争关系的表现，是本题正确答案。","C":"是中国人民抗日战争与世界反法西斯战争关系的表现，是本题正确答案。","D":"是中国人民抗日战争与世界反法西斯战争关系的表现，是本题正确答案。"}}},{"id":"basic-shigang-ch06-25","moduleId":"basic","subjectId":"shigang","chapter":"第六章 中华民族的抗日战争","chapterKey":"第六章","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第六章 第 25 题"},"stem":"2025年是中国人民抗日战争暨世界反法西斯战争胜利80周年，也是台湾光复80周年。台湾回归中国是第二次世界大战胜利成果和战后国际秩序的重要组成部分。台湾属于中国的历史和法理事实不容置疑。第二次世界大战期间，一系列具有国际法效力的文件都确认了中国对台湾的主权，这些文件包括","choices":[{"id":"A","text":"《开罗宣言》"},{"id":"B","text":"《波茨坦公告》"},{"id":"C","text":"《德黑兰宣言》"},{"id":"D","text":"《日本投降书》"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"均是确认中国对台湾主权的文件，是本题正确答案。","B":"均是确认中国对台湾主权的文件，是本题正确答案。","C":"《德黑兰宣言》——商讨的是在欧洲开辟第二战场的问题，与台湾问题无关。","D":"均是确认中国对台湾主权的文件，是本题正确答案。"}}},{"id":"basic-shigang-ch07-1","moduleId":"basic","subjectId":"shigang","chapter":"第七章 为建立新中国而奋斗","chapterKey":"第七章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第七章 第 1 题"},"stem":"1949年新中国成立前夕，在正式宪法颁布之前，起到临时宪法作用，并被称为“全国人民的大宪章”的文件是","choices":[{"id":"A","text":"《中国人民政治协商会议共同纲领》"},{"id":"B","text":"《中华人民共和国宪法》"},{"id":"C","text":"《中华民国临时约法》"},{"id":"D","text":"《中国土地法大纲》"}],"answer":["A"],"analysis":{"point":"","options":{"A":"《中国人民政治协商会议共同纲领》——是在第一届中国人民政治协商会议上通过的文件，具有临时宪法的性质，是本题正确答案。","B":"《中华人民共和国宪法》——是我国第一部社会主义类型的宪法。","C":"《中华民国临时约法》——是辛亥革命后制定的资产阶级性质的宪法性文件。","D":"《中国土地法大纲》——是1947年中国共产党颁布的土地改革的纲领性文件，其核心是废除封建土地所有制、实现耕者有其田。"}}},{"id":"basic-shigang-ch07-2","moduleId":"basic","subjectId":"shigang","chapter":"第七章 为建立新中国而奋斗","chapterKey":"第七章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第七章 第 2 题"},"stem":"抗日战争胜利后，某些民主党派的领导人曾经鼓吹“中间路线”：在政治上，“必须实现英美式的民主政治”，但不准地主官僚资本家操纵；在经济上，“应当实行改良的资本主义”，但不容官僚买办资本横行。他们所主张的，实质上是","choices":[{"id":"A","text":"社会主义的道路"},{"id":"B","text":"新民主主义的道路"},{"id":"C","text":"旧民主主义的道路"},{"id":"D","text":"军阀独裁的道路"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是中国共产党要走的道路。","B":"是中国共产党要走的道路。","C":"旧民主主义的道路——是解放战争时期民主党派所主张的道路，是本题正确答案。","D":"军阀独裁的道路——是蒋介石集团所坚持的道路。"}}},{"id":"basic-shigang-ch07-3","moduleId":"basic","subjectId":"shigang","chapter":"第七章 为建立新中国而奋斗","chapterKey":"第七章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第七章 第 3 题"},"stem":"解放战争时期，标志着中国革命已经发展到了一个历史的转折点，是蒋介石20年反革命统治由发展到消灭的转折点，也是100多年来帝国主义在中国的统治由发展到消灭的转折点的事件是","choices":[{"id":"A","text":"粉碎国民党的全面进攻和重点进攻"},{"id":"B","text":"人民解放军的战略进攻"},{"id":"C","text":"辽沈、淮海、平津三大战役取得胜利"},{"id":"D","text":"人民解放军横渡长江"}],"answer":["B"],"analysis":{"point":"","options":{"A":"都属于解放战争时期的重要事件。","B":"人民解放军的战略进攻——是蒋介石反革命统治和帝国主义在中国的统治由发展到消灭的转折点，是本题正确答案。","C":"都属于解放战争时期的重要事件。","D":"都属于解放战争时期的重要事件。"}}},{"id":"basic-shigang-ch07-4","moduleId":"basic","subjectId":"shigang","chapter":"第七章 为建立新中国而奋斗","chapterKey":"第七章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第七章 第 4 题"},"stem":"庆祝新中国成立70周年前夕，习近平总书记专程来到位于北京西北郊的香山革命纪念地。香山是新中国启航的地方，是中国共产党人“进京赶考”的首站。1949年3月，毛泽东等中央领导人率领中共中央机关和中国人民解放军总部，从西柏坡赶赴北平，进驻北平香山，标志着","choices":[{"id":"A","text":"中国共产党成为全国范围的执政党"},{"id":"B","text":"中国革命重心从农村转向城市"},{"id":"C","text":"延续22年之久的国民党反动统治的覆灭"},{"id":"D","text":"帝国主义在中国的统治由发展到消灭的转折点"}],"answer":["B"],"analysis":{"point":"","options":{"A":"中国共产党成为全国范围的执政党是新中国成立的意义。","B":"中国革命重心从农村转向城市——是以毛泽东等中央领导人率领中共中央机关和中国人民解放军总部从西柏坡迁驻北平香山为标志的，是本题正确答案。","C":"延续22年之久的国民党反动统治的覆灭——是人民解放军占领南京的意义。","D":"帝国主义在中国的统治由发展到消灭的转折点——是人民解放军战略进攻的意义。"}}},{"id":"basic-shigang-ch07-5","moduleId":"basic","subjectId":"shigang","chapter":"第七章 为建立新中国而奋斗","chapterKey":"第七章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第七章 第 5 题"},"stem":"中国共产党领导的多党合作和政治协商制度，是我国的一项基本政治制度，是具有中国特色的政党制度。它有利于坚持和改善中国共产党的领导，充分吸纳各方面的意见，集中全国人民的意志和力量，实现广泛民主和集中领导、充满活力和富有效率的统一。这一政党制度确立的标志是","choices":[{"id":"A","text":"《论人民民主专政》的发表"},{"id":"B","text":"《中华人民共和国宪法》的颁布"},{"id":"C","text":"中国人民政治协商会议第一届全体会议的召开"},{"id":"D","text":"中华人民共和国的成立"}],"answer":["C"],"analysis":{"point":"","options":{"A":"《论人民民主专政》的发表——为新中国的建立奠定了理论基础和政策基础。","B":"《中华人民共和国宪法》的颁布——标志着我国第一部正式宪法的诞生。","C":"中国人民政治协商会议第一届全体会议的召开——标志着中国共产党领导的多党合作和政治协商制度正式确立，是本题正确答案。","D":"中华人民共和国的成立——标志着中国新民主主义革命的基本胜利。"}}},{"id":"basic-shigang-ch07-6","moduleId":"basic","subjectId":"shigang","chapter":"第七章 为建立新中国而奋斗","chapterKey":"第七章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第七章 第 6 题"},"stem":"1947年7月至9月，中国共产党在河北省平山县召开全国土地会议，制定和通过了《中国土地法大纲》，此后解放区广大农村迅速掀起土地改革运动的热潮。此次土改在中国历史上","choices":[{"id":"A","text":"第一次采取了消灭封建剥削关系的政策"},{"id":"B","text":"使解放区农民在政治上翻了身"},{"id":"C","text":"从根本上摧毁了中国封建制度的根基"},{"id":"D","text":"完成了从几千年的分散个体劳动向集体所有、集体经营的历史性转变"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"第一次采取了消灭封建剥削关系的政策——是土地革命战争时期的土地政策。","B":"是解放区土地改革的历史意义，是本题正确答案。","C":"是解放区土地改革的历史意义，是本题正确答案。","D":"完成了从几千年的分散个体劳动向集体所有、集体经营的历史性转变——是1956年农业社会主义改造完成的意义。"}}},{"id":"basic-shigang-ch08-1","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 1 题"},"stem":"我国历史上规模最大，也是历次土地改革运动中进行得最好的一次土地改革是","choices":[{"id":"A","text":"抗日战争时期的减租减息政策"},{"id":"B","text":"1950年至1953年春的土地改革"},{"id":"C","text":"解放战争时期的《中国土地法大纲》"},{"id":"D","text":"新中国成立后的农业合作化运动"}],"answer":["B"],"analysis":{"point":"","options":{"A":"抗日战争时期的减租减息政策——仅仅是在削弱封建剥削，未彻底废除封建土地所有制。","B":"1950年至1953年春的土地改革——是中国共产党领导的土地改革运动中规模最大、进行得最好的一次土地改革，是本题正确答案。","C":"解放战争时期的《中国土地法大纲》——是在新中国成立前的解放区开展土地改革期间所颁布的文件，并未覆盖全国。","D":"新中国成立后的农业合作化运动——属于社会主义革命范畴，并不是土地改革的政策。"}}},{"id":"basic-shigang-ch08-2","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 2 题"},"stem":"1949年新中国成立后，中国共产党领导全国人民开展了恢复国民经济、进行社会主义改造的一系列工作，逐步实现从新民主主义社会向社会主义社会的过渡。标志着中国开始进入全面建设社会主义历史阶段的事件是","choices":[{"id":"A","text":"1949 年中华人民共和国的成立"},{"id":"B","text":"1956年生产资料所有制的社会主义改造基本完成"},{"id":"C","text":"1956年中共八大的召开"},{"id":"D","text":"1957年第一个五年计划的超额完成"}],"answer":["B"],"analysis":{"point":"","options":{"A":"1949年中华人民共和国的成立——标志着新民主主义革命基本胜利，中国进入新民主主义社会。","B":"1956年生产资料所有制的社会主义改造基本完成——标志着社会主义基本制度在中国确立，中国开始进入全面建设社会主义的历史阶段，是本题正确答案。","C":"1956年中共八大的召开——正确分析了当时国内的主要矛盾和主要任务。","D":"1957年第一个五年计划的超额完成——奠定了我国社会主义工业化的初步基础，是全面建设社会主义初期取得的重要成就。"}}},{"id":"basic-shigang-ch08-3","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 3 题"},"stem":"1950年6月召开的中共七届三中全会，是新中国成立后中国共产党举行的第一次中央全会，也是新中国成立初期召开的最重要的会议，为三年经济恢复时期党的工作规定了策略路线和行动纲领。毛泽东指出当前阶段的中心任务是","choices":[{"id":"A","text":"开始向社会主义过渡"},{"id":"B","text":"争取国家财政经济状况的基本好转"},{"id":"C","text":"调动一切积极因素为社会主义事业服务"},{"id":"D","text":"不要四面出击"}],"answer":["B"],"analysis":{"point":"","options":{"A":"开始向社会主义过渡——是在1952年年底国民经济基本恢复之后才开始提出和实施的。","B":"争取国家财政经济状况的基本好转——是中共七届三中全会确定的中心任务，是本题正确答案。","C":"调动一切积极因素为社会主义事业服务——是《论十大关系》提出的基本方针。","D":"不要四面出击——是中共七届三中全会制定的战略策略方针。"}}},{"id":"basic-shigang-ch08-4","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 4 题"},"stem":"1950年至1953年春，我国在新解放区进行废除封建土地制度的改革。土地改革中对待富农的政策，由解放战争时期征收富农多余土地财产的政策改变为","choices":[{"id":"A","text":"“耕者有其田”的政策"},{"id":"B","text":"限制富农的政策"},{"id":"C","text":"保存富农经济的政策"},{"id":"D","text":"消灭富农的政策"}],"answer":["C"],"analysis":{"point":"","options":{"A":"“耕者有其田”的政策——是解放战争时期的土地改革政策。","B":"限制富农的政策——是土地革命战争时期对待富农的政策。","C":"保存富农经济的政策——是新中国成立初期在新解放区土地改革中对待富农的政策，是本题正确答案。","D":"消灭富农的政策——是错误的土地政策。"}}},{"id":"basic-shigang-ch08-5","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 5 题"},"stem":"新中国成立初期，面临着许多严重的困难和一些紧迫的问题。党和政府教育广大干部和党员必须经受住执政的考验、接管城市的考验和生活环境变化的考验。1951年年底到1952年10月，中国共产党在党政军机关开展“三反”运动。这一运动","choices":[{"id":"A","text":"为资本主义工商业改造和国家大规模经济建设奠定了基础"},{"id":"B","text":"制定了党在新中国成立初期的战略策略方针"},{"id":"C","text":"基本上肃清了国民党遗留在大陆的反动势力"},{"id":"D","text":"是以反贪污、反浪费、反官僚主义为核心的群众性政治运动"}],"answer":["D"],"analysis":{"point":"","options":{"A":"为资本主义工商业改造和国家大规模经济建设奠定了基础——属于“五反”运动的意义。","B":"制定了党在新中国成立初期的战略策略方针——属于中共七届三中全会的内容。","C":"基本上肃清了国民党遗留在大陆的反动势力——属于镇压反革命运动的意义。","D":"是以反贪污、反浪费、反官僚主义为核心的群众性政治运动——属于“三反”运动的意义，是本题正确答案。"}}},{"id":"basic-shigang-ch08-6","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 6 题"},"stem":"1953年12月，中共中央宣传部发布《为动员一切力量把我国建设成为一个伟大的社会主义国家而斗争—关于党在过渡时期总路线的学习和宣传提纲》，对党在过渡时期的总路线作了完整表述。在这个总路线中，主要任务是","choices":[{"id":"A","text":"进行土地改革"},{"id":"B","text":"完成民主革命遗留任务"},{"id":"C","text":"恢复国民经济"},{"id":"D","text":"实现国家工业化"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是新中国成立初期（1949—1952年）面临的重要任务。","B":"是新中国成立初期（1949—1952年）面临的重要任务。","C":"是新中国成立初期（1949—1952年）面临的重要任务。","D":"实现国家工业化——是党在过渡时期（1953—1956年）的主要任务，是本题正确答案。"}}},{"id":"basic-shigang-ch08-7","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 7 题"},"stem":"在对农业进行社会主义改造的过程中，具有半社会主义性质的是","choices":[{"id":"A","text":"互助组"},{"id":"B","text":"初级农业生产合作社"},{"id":"C","text":"高级农业生产合作社"},{"id":"D","text":"供销合作社"}],"answer":["B"],"analysis":{"point":"","options":{"A":"互助组——是农业社会主义改造的第一步，具有社会主义萌芽性质。","B":"初级农业生产合作社——是农业社会主义改造的第二步，具有半社会主义性质，是本题正确答案。","C":"高级农业生产合作社——是农业社会主义改造的第三步，具有完全的社会主义性质。","D":"供销合作社——是手工业社会主义改造的第二步，具有半社会主义性质。"}}},{"id":"basic-shigang-ch08-8","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 8 题"},"stem":"1953年春，中共中央制定了经过国家资本主义改造资本主义工商业的政策。我国对资本主义工商业的社会主义改造采取的方法是","choices":[{"id":"A","text":"公私合营"},{"id":"B","text":"和平赎买"},{"id":"C","text":"国家资本主义"},{"id":"D","text":"统购包销"}],"answer":["B"],"analysis":{"point":"","options":{"A":"公私合营——是高级形式的国家资本主义采取的方式。","B":"和平赎买——是对资本主义工商业进行社会主义改造的方式，是本题正确答案。","C":"国家资本主义——是对资本主义工商业进行改造使其逐步过渡到社会主义的主要形式。","D":"统购包销——是初级形式的国家资本主义采取的方式。"}}},{"id":"basic-shigang-ch08-9","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 9 题"},"stem":"1949年10月1日，首都军民30万人齐集北京天安门广场，欢庆中华人民共和国的诞生。中华人民共和国的成立，标志着","choices":[{"id":"A","text":"新民主主义革命取得了基本的胜利"},{"id":"B","text":"半殖民地半封建社会的结束"},{"id":"C","text":"中国共产党的地位发生了根本性的变化"},{"id":"D","text":"社会主义基本制度的确立"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是中华人民共和国成立的意义，是本题正确答案。","B":"是中华人民共和国成立的意义，是本题正确答案。","C":"是中华人民共和国成立的意义，是本题正确答案。","D":"社会主义基本制度的确立——是1956年社会主义改造基本完成的历史意义。"}}},{"id":"basic-shigang-ch08-10","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 10 题"},"stem":"中华人民共和国的成立，宣告了中国人民当家作主的时代已经到来。但是，新生的共和国面临着许多严重的困难和一些紧迫的问题。中华人民共和国成立初期的两大任务是","choices":[{"id":"A","text":"由新民主主义社会转变为社会主义社会"},{"id":"B","text":"动员人民努力医治战争创伤，恢复破败的国民经济"},{"id":"C","text":"继续完成新民主主义革命的遗留任务，彻底解决中国人民同三大敌人的矛盾"},{"id":"D","text":"稳步地由农业国变为工业国"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"（原书未单独给出此项解析）","B":"是中华人民共和国成立初期的两大任务，是本题正确答案。","C":"是中华人民共和国成立初期的两大任务，是本题正确答案。","D":"（原书未单独给出此项解析）"}}},{"id":"basic-shigang-ch08-11","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 11 题"},"stem":"新中国成立伊始，面临许多严重困难和紧迫问题。完成民主革命的遗留任务是中国共产党和人民政府领导全国各族人民进行捍卫巩固新政权、建设新中国的政策措施之一。民主革命的遗留任务是","choices":[{"id":"A","text":"进行农业、手工业和资本主义工商业的社会主义改造"},{"id":"B","text":"进行土地制度改革"},{"id":"C","text":"废除封建婚姻制度"},{"id":"D","text":"镇压反革命运动"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"进行农业、手工业和资本主义工商业的社会主义改造——是社会主义革命的任务。","B":"是新民主主义革命的遗留任务，是本题正确答案。","C":"是新民主主义革命的遗留任务，是本题正确答案。","D":"是新民主主义革命的遗留任务，是本题正确答案。"}}},{"id":"basic-shigang-ch08-12","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 12 题"},"stem":"中华人民共和国的成立，标志着我国新民主主义革命阶段的基本结束和社会主义革命阶段的开始。新民主主义社会不是一种独立的社会形态，在经济上存在着五种经济成分，其中属于过渡形式的经济成分有","choices":[{"id":"A","text":"合作社经济"},{"id":"B","text":"国营经济"},{"id":"C","text":"国家资本主义经济"},{"id":"D","text":"个体经济"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是新民主主义社会五种经济成分中的过渡性经济成分，是本题正确答案。","B":"国营经济——是新民主主义社会五种经济成分中的主要经济成分之一，居于领导地位。","C":"是新民主主义社会五种经济成分中的过渡性经济成分，是本题正确答案。","D":"个体经济——是新民主主义社会五种经济成分中的主要经济成分之一，占绝对优势。"}}},{"id":"basic-shigang-ch08-13","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 13 题"},"stem":"中华人民共和国成立初期，面对复杂的国际形势，以毛泽东为主要代表的中国共产党人提出了一系列重要外交方针，为新中国外交奠定基础。下列属于这一时期的外交方针的有","choices":[{"id":"A","text":"“另起炉灶”"},{"id":"B","text":"和平共处五项原则"},{"id":"C","text":"“打扫干净屋子再请客”"},{"id":"D","text":"“一边倒”"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是新中国成立初期我国的外交方针，是本题正确答案。","B":"和平共处五项原则——是20世纪50年代提出的外交基本原则。","C":"是新中国成立初期我国的外交方针，是本题正确答案。","D":"是新中国成立初期我国的外交方针，是本题正确答案。"}}},{"id":"basic-shigang-ch08-14","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 14 题"},"stem":"1951年年底至1952年10月，中国共产党在党政军机关开展了“三反”运动，其内容包括","choices":[{"id":"A","text":"反行贿"},{"id":"B","text":"反贪污"},{"id":"C","text":"反浪费"},{"id":"D","text":"反官僚主义"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"（原书未单独给出此项解析）","B":"是“三反”运动的内容，是本题正确答案。","C":"是“三反”运动的内容，是本题正确答案。","D":"是“三反”运动的内容，是本题正确答案。"}}},{"id":"basic-shigang-ch08-15","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 15 题"},"stem":"1957年4月，中共中央下发《关于整风运动的指示》，旨在改进党的作风、密切党与人民群众的联系。此次整风运动明确的核心内容包括","choices":[{"id":"A","text":"反对官僚主义"},{"id":"B","text":"反对宗派主义"},{"id":"C","text":"反对主观主义"},{"id":"D","text":"反对贪污浪费"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是1957年整风运动的核心内容，是本题正确答案。","B":"是1957年整风运动的核心内容，是本题正确答案。","C":"是1957年整风运动的核心内容，是本题正确答案。","D":"（原书未单独给出此项解析）"}}},{"id":"basic-shigang-ch08-16","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 16 题"},"stem":"我国在全面建设社会主义时期取得了一系列重要成就，主要包括","choices":[{"id":"A","text":"建立了独立的、比较完整的工业体系和国民经济体系"},{"id":"B","text":"人民生活水平提高，文化教育医疗事业得到发展"},{"id":"C","text":"取得“两弹一星”等一批重要科技成果"},{"id":"D","text":"国际地位提高，国际环境得到改善"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"均是全面建设社会主义时期的主要成就，是本题正确答案。","B":"均是全面建设社会主义时期的主要成就，是本题正确答案。","C":"均是全面建设社会主义时期的主要成就，是本题正确答案。","D":"均是全面建设社会主义时期的主要成就，是本题正确答案。"}}},{"id":"basic-shigang-ch08-17","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 17 题"},"stem":"20世纪50年代中期，邓小平多次强调，执政的中国共产党必须接受来自几个方面的监督，具体包括","choices":[{"id":"A","text":"党内的监督"},{"id":"B","text":"人民群众的监督"},{"id":"C","text":"海外人士的监督"},{"id":"D","text":"民主党派和无党派民主人士的监督"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是执政的中国共产党必须接受的监督，是本题正确答案。","B":"是执政的中国共产党必须接受的监督，是本题正确答案。","C":"海外人士的监督非考点。","D":"是执政的中国共产党必须接受的监督，是本题正确答案。"}}},{"id":"basic-shigang-ch08-18","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 18 题"},"stem":"1956年9月15日至27日，中国共产党第八次全国代表大会在北京举行。这是中国共产党在新中国成立以后召开的第一次全国代表大会。英国《星期日泰晤士报》在评论毛泽东的开幕词和刘少奇的政治报告时认为，中共八大的气氛“是充满了信心、喜悦、乐观和团结的”。下列关于中共八大的表述正确的有","choices":[{"id":"A","text":"大会肯定“三个主体，三个补充”思想"},{"id":"B","text":"会议讨论并通过了第一部《中华人民共和国宪法》"},{"id":"C","text":"大会通过的新党章是中国共产党在全国执政以后制定的第一部党章"},{"id":"D","text":"会议正确分析了国内形势和主要矛盾的变化"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是关于中共八大的正确表述，是本题正确答案。","B":"会议讨论并通过了第一部《中华人民共和国宪法》——是1954年中华人民共和国第一届全国人民代表大会的内容。","C":"是关于中共八大的正确表述，是本题正确答案。","D":"是关于中共八大的正确表述，是本题正确答案。"}}},{"id":"basic-shigang-ch08-19","moduleId":"basic","subjectId":"shigang","chapter":"第八章 中华人民共和国的成立与中国社会主义建设道路的探索","chapterKey":"第八章","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第八章 第 19 题"},"stem":"毛泽东在《关于正确处理人民内部矛盾的问题》中提出，解决人民内部矛盾的方法有","choices":[{"id":"A","text":"民主的方法"},{"id":"B","text":"说服教育的方法"},{"id":"C","text":"“团结一批评一团结”的方法"},{"id":"D","text":"专政的方法"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是解决人民内部矛盾的方法，是本题正确答案。","B":"是解决人民内部矛盾的方法，是本题正确答案。","C":"是解决人民内部矛盾的方法，是本题正确答案。","D":"专政的方法——是解决敌我矛盾的方法。"}}},{"id":"basic-shigang-ch09-1","moduleId":"basic","subjectId":"shigang","chapter":"第九章 改革开放与中国特色社会主义的开创和发展","chapterKey":"第九章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第九章 第 1 题"},"stem":"将解放思想、实事求是，坚持实践标准提到党的思想路线的高度，成为开辟中国特色社会主义道路、开创中国特色社会主义新理论的宣言书的是","choices":[{"id":"A","text":"《关于建国以来党的若干历史问题的决议》"},{"id":"B","text":"《党和国家领导制度的改革》"},{"id":"C","text":"《解放思想，实事求是，团结一致向前看》"},{"id":"D","text":"《实践是检验真理的唯一标准》"}],"answer":["C"],"analysis":{"point":"","options":{"A":"《关于建国以来党的若干历史问题的决议》——是在中共十一届六中全会上通过的，对毛泽东和毛泽东思想进行了科学评价。","B":"《党和国家领导制度的改革》——非考点。","C":"《解放思想，实事求是，团结一致向前看》——是开辟中国特色社会主义道路、开创中国特色社会主义新理论的宣言书，是本题正确答案。","D":"《实践是检验真理的唯一标准》——是拨乱反正和改革开放的思想先导。"}}},{"id":"basic-shigang-ch09-2","moduleId":"basic","subjectId":"shigang","chapter":"第九章 改革开放与中国特色社会主义的开创和发展","chapterKey":"第九章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第九章 第 2 题"},"stem":"1981年6月27日至29日召开的中共十一届六中全会上，《关于建国以来党的若干历史问题的决议》（简称《历史决议》)获得一致通过。《历史决议》的通过标志着","choices":[{"id":"A","text":"全党首次对中国革命基本问题的认识达到在马克思列宁主义基础上的一致"},{"id":"B","text":"马克思主义中国化的任务基本完成"},{"id":"C","text":"邓小平理论轮廓的初步形成"},{"id":"D","text":"党在指导思想上的拨乱反正胜利完成"}],"answer":["D"],"analysis":{"point":"","options":{"A":"全党首次对中国革命基本问题的认识达到在马克思列宁主义基础上的一致——是中共六届七中全会的历史意义。","B":"马克思主义中国化的任务基本完成——是错误说法，该任务一直在推进。","C":"邓小平理论轮廓的初步形成——是党的十三大的历史意义。","D":"党在指导思想上的拨乱反正胜利完成——是中共十一届六中全会通过的《关于建国以来党的若干历史问题的决议》的历史意义，是本题正确答案。"}}},{"id":"basic-shigang-ch09-3","moduleId":"basic","subjectId":"shigang","chapter":"第九章 改革开放与中国特色社会主义的开创和发展","chapterKey":"第九章","n":3,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第九章 第 3 题"},"stem":"1978年5月11日，《光明日报》发表了《实践是检验真理的唯一标准》一文，引起了全国范围内的广泛注意和讨论。关于真理标准问题的讨论","choices":[{"id":"A","text":"重新确立了实事求是的思想路线"},{"id":"B","text":"成为开创建设有中国特色社会主义新理论的宣言书"},{"id":"C","text":"成为拨乱反正和改革开放的思想先导"},{"id":"D","text":"是继延安整风运动之后又一场马克思主义思想解放运动"}],"answer":["C","D"],"analysis":{"point":"","options":{"A":"重新确立了实事求是的思想路线——是中共十一届三中全会的成就。","B":"成为开创建设有中国特色社会主义新理论的宣言书——是《解放思想，实事求是，团结一致向前看》的贡献。","C":"是关于真理标准问题讨论的历史意义，是本题正确答案。","D":"是关于真理标准问题讨论的历史意义，是本题正确答案。"}}},{"id":"basic-shigang-ch09-4","moduleId":"basic","subjectId":"shigang","chapter":"第九章 改革开放与中国特色社会主义的开创和发展","chapterKey":"第九章","n":4,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第九章 第 4 题"},"stem":"1978年12月18日到22日，党的十一届三中全会在北京召开。会议的主要任务是确定把全党工作重点转移到社会主义现代化建设上来。这次全会是中华人民共和国成立以来党的历史上具有深远意义的伟大转折。全会结束了粉碎“四人帮”后两年来党和国家工作在徘徊中前进的局面，标志着中国共产党","choices":[{"id":"A","text":"重新确立了马克思主义的思想路线、政治路线、组织路线"},{"id":"B","text":"形成了以邓小平为核心的党的中央领导集体"},{"id":"C","text":"开始了在思想、政治、组织等领域的全面拨乱反正"},{"id":"D","text":"揭开了社会主义改革开放的序幕"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是中共十一届三中全会的贡献，是本题正确答案。","B":"是中共十一届三中全会的贡献，是本题正确答案。","C":"是中共十一届三中全会的贡献，是本题正确答案。","D":"是中共十一届三中全会的贡献，是本题正确答案。"}}},{"id":"basic-shigang-ch09-5","moduleId":"basic","subjectId":"shigang","chapter":"第九章 改革开放与中国特色社会主义的开创和发展","chapterKey":"第九章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第九章 第 5 题"},"stem":"我国经济体制的改革首先在农村取得突破性进展。党的十一届三中全会曾指出：“我国农业近二十年来的发展速度不快，它同人民的需要和四个现代化的需要之间存在着极其尖锐的矛盾。”当时我国农业和农村经济发展面临的主要问题有","choices":[{"id":"A","text":"农民的温饱问题尚未完全解决"},{"id":"B","text":"农村的土地改革尚未完成"},{"id":"C","text":"人民公社体制亟待改革"},{"id":"D","text":"乡镇企业管理体制亟待改革"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是改革开放初期我国农业和农村经济发展面临的主要问题，是本题正确答案。","B":"农村的土地改革尚未完成——是错误说法，我国的土地改革在1953年年初已基本完成。开080","C":"是改革开放初期我国农业和农村经济发展面临的主要问题，是本题正确答案。","D":"（原书未单独给出此项解析）"}}},{"id":"basic-shigang-ch10-1","moduleId":"basic","subjectId":"shigang","chapter":"第十章 中国特色社会主义进入新时代","chapterKey":"第十章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"史纲 · 第十章 第 1 题"},"stem":"中国共产党第十九次全国代表大会于2017年10月18日至10月24日在北京召开。这次大会的主题：不忘初心，牢记使命，高举中国特色社会主义伟大旗帜，决胜全面建成小康社会，夺取新时代中国特色社会主义伟大胜利，为实现中华民族伟大复兴的中国梦不懈奋斗。我们党的初心和使命是","choices":[{"id":"A","text":"为中国人民谋幸福，为中华民族谋复兴"},{"id":"B","text":"全心全意为人民服务"},{"id":"C","text":"实现共产主义社会"},{"id":"D","text":"实现共同富裕"}],"answer":["A"],"analysis":{"point":"","options":{"A":"为中国人民谋幸福，为中华民族谋复兴——是中国共产党人的初心和使命，是本题正确答案。","B":"全心全意为人民服务——是中国共产党的根本宗旨。","C":"实现共产主义社会——是共产主义者的奋斗目标。","D":"实现共同富裕——是社会主义的根本目的。3"}}},{"id":"basic-sixiu-xulun-1","moduleId":"basic","subjectId":"sixiu","chapter":"绪论 担当复兴大任 成就时代新人","chapterKey":"绪论","n":1,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 绪论 第 1 题"},"stem":"思想道德和法律都是调节人们思想行为、协调人际关系、维护社会秩序的重要手段。二者的不同点在于","choices":[{"id":"A","text":"调节领域不同"},{"id":"B","text":"调节方式不同"},{"id":"C","text":"调节目标不同"},{"id":"D","text":"服务不同的经济基础"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是思想道德和法律的不同点，是本题正确答案。","B":"是思想道德和法律的不同点，是本题正确答案。","C":"是思想道德和法律的不同点，是本题正确答案。","D":"是错误说法，思想道德和法律都是上层建筑的组成部分，共同服务于一定的经济基础。"}}},{"id":"basic-sixiu-xulun-2","moduleId":"basic","subjectId":"sixiu","chapter":"绪论 担当复兴大任 成就时代新人","chapterKey":"绪论","n":2,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 绪论 第 2 题"},"stem":"关于思想道德建设和法治建设的关系，以下说法正确的有","choices":[{"id":"A","text":"法治建设为思想道德建设提供制度支撑和法律保障"},{"id":"B","text":"社会主义思想道德建设和法治建设紧密联系，相互补充、相互促进"},{"id":"C","text":"法治建设为思想道德建设提供国家强制力保障"},{"id":"D","text":"思想道德建设为法治建设提供思想指引和价值基础"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是关于思想道德建设和法治建设的关系的正确表述，是本题正确答案。","B":"是关于思想道德建设和法治建设的关系的正确表述，是本题正确答案。","C":"是关于思想道德建设和法治建设的关系的正确表述，是本题正确答案。","D":"是关于思想道德建设和法治建设的关系的正确表述，是本题正确答案。"}}},{"id":"basic-sixiu-ch01-1","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 1 题"},"stem":"人的本质属性是","choices":[{"id":"A","text":"自然属性"},{"id":"B","text":"社会属性"},{"id":"C","text":"自然属性和社会属性"},{"id":"D","text":"精神属性"}],"answer":["B"],"analysis":{"point":"","options":{"A":"自然属性——是人的属性之一，但不是人的本质属性。","B":"社会属性——是人的本质属性，是本题正确答案。","C":"自然属性和社会属性——是马克思对于人的属性的划分。","D":"精神属性——非考点。"}}},{"id":"basic-sixiu-ch01-2","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 2 题"},"stem":"马克思运用辩证唯物主义和历史唯物主义的立场、观点、方法，揭开了人的本质之谜。人的本质是","choices":[{"id":"A","text":"能进行复杂思维活动的高等动物"},{"id":"B","text":"一切社会关系的总和"},{"id":"C","text":"单个人所固有的抽象物"},{"id":"D","text":"能够使用语言、具有复杂的社会组织与科技发展的生物"}],"answer":["B"],"analysis":{"point":"","options":{"A":"非考点。","B":"一切社会关系的总和——是人的本质，是本题正确答案。","C":"是错误说法，该说法并没有看到人的本质属性是社会属性。","D":"非考点。"}}},{"id":"basic-sixiu-ch01-3","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 3 题"},"stem":"社会发展是一个社会在经济、政治、文化、科技、教育、卫生等各个领域所取得的全面进步和变革。社会发展的根本目标是","choices":[{"id":"A","text":"全体人民共同富裕"},{"id":"B","text":"社会成员素质的不断提高"},{"id":"C","text":"推动和实现人的全面发展"},{"id":"D","text":"人与自然和谐共生"}],"answer":["C"],"analysis":{"point":"","options":{"A":"仅仅是社会主义社会的发展目标，而非所有社会的发展目标。","B":"社会成员素质的不断提高——是社会发展的重要基础，不是根本目标。","C":"推动和实现人的全面发展——是社会发展的根本目标，是本题正确答案。","D":"是社会发展要实现的目标，但不是根本目标。"}}},{"id":"basic-sixiu-ch01-4","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 4 题"},"stem":"个人与社会的关系问题，形成于人类社会及其文明发展的开端，而它能够被明确地提出和强调，却是近代以来的事。它既是人类及其社会的永恒主题，同时又被现实生活以价值论或价值观的形式突出地呈现出来。个人与社会的关系，最根本的是","choices":[{"id":"A","text":"个体性与社会性的统一关系"},{"id":"B","text":"个人利益与社会利益的关系"},{"id":"C","text":"个人需要与社会需要的统一关系"},{"id":"D","text":"个人权利与承担社会责任的统一关系"}],"answer":["B"],"analysis":{"point":"","options":{"A":"个体性与社会性的统一关系——是“个人与社会的关系”的另一种表述方式。","B":"个人利益与社会利益的关系——是个人与社会的最根本的关系，是本题正确答案。","C":"个人需要与社会需要的统一关系——是个人与社会的关系在需要层面的体现。","D":"个人权利与承担社会责任的统一关系——是个人与社会的关系在法律层面的体现。"}}},{"id":"basic-sixiu-ch01-5","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 5 题"},"stem":"人生观的作用主要通过人生目的、人生态度、人生价值三个方面体现出来。这三个方面相互联系、相辅相成，其中居于核心地位的是","choices":[{"id":"A","text":"人生状态"},{"id":"B","text":"人生态度"},{"id":"C","text":"人生价值"},{"id":"D","text":"人生目的"}],"answer":["D"],"analysis":{"point":"","options":{"A":"人生状态——非考点。","B":"是人生观的组成部分，但不是核心。","C":"是人生观的组成部分，但不是核心。","D":"人生目的——是对人为什么活着这一人生根本问题的认识和回答，是人生观的核心，是本题正确答案。"}}},{"id":"basic-sixiu-ch01-6","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 6 题"},"stem":"古往今来，人们对人生目的的探索从未停止过，思想家们孜孜以求留下了难以计数的答案。人类社会迄今最先进的人生追求是","choices":[{"id":"A","text":"服务人民、奉献社会"},{"id":"B","text":"认真、务实、乐观、进取"},{"id":"C","text":"顾全大局、遵纪守法"},{"id":"D","text":"自由、民主、平等、人权"}],"answer":["A"],"analysis":{"point":"","options":{"A":"服务人民、奉献社会——是人类社会迄今最先进的人生追求，是本题正确答案。","B":"认真、务实、乐观、进取——是正确的人生态度，不是人生追求。","C":"顾全大局、遵纪守法——是集体主义中对公民最基本的道德要求。","D":"自由、民主、平等、人权——是资本主义宣传的价值观。"}}},{"id":"basic-sixiu-ch01-7","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 7 题"},"stem":"钱学森曾经说过：“我作为一名中国的科技工作者，活着的目的就是为人民服务，如果人民最后对我的一生所做的工作表示满意的话，那才是最高的奖赏。”这说明评价人生价值的根本尺度是","choices":[{"id":"A","text":"个体在社会中的地位"},{"id":"B","text":"个体在社会中的影响"},{"id":"C","text":"个体对社会和他人的生存和发展的贡献"},{"id":"D","text":"个体对自身物质和精神需要的满足程度"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是错误说法。","B":"是错误说法。","C":"个体对社会和他人的生存和发展的贡献——是评价人生价值的根本尺度，是本题正确答案。","D":"个体对自身物质和精神需要的满足程度——是人生的自我价值的体现，不是评价人生价值的根本尺度。"}}},{"id":"basic-sixiu-ch01-8","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 8 题"},"stem":"《风雨哈佛路》中，主人公丽兹出生在美国的贫民窟，从小就承受着家庭的千疮百孔，父母吸毒，母亲患有精神分裂症。贫穷的丽兹只能四处乞讨和流浪，生活的苦难似乎无穷无尽。随着慢慢成长，丽兹知道，只有读书成才才能改变自身命运。贫困并没有止住丽兹前进的决心，她最终实现了人生目标。由此得知，人生目的十分重要。按照马克思的观点，人生目的的作用表现为","choices":[{"id":"A","text":"决定人生道路"},{"id":"B","text":"决定人生态度"},{"id":"C","text":"决定人生价值选择"},{"id":"D","text":"决定人的本质"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是人生目的的作用，是本题正确答案。","B":"是人生目的的作用，是本题正确答案。","C":"是人生目的的作用，是本题正确答案。","D":"是错误说法，人的本质是一切社会关系的总和，不由人生目的决定。"}}},{"id":"basic-sixiu-ch01-9","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 9 题"},"stem":"人生价值内在地包含了人生的自我价值和社会价值两个方面，其中，人生的社会价值是","choices":[{"id":"A","text":"对自身物质和精神需要的满足程度"},{"id":"B","text":"个体的实践活动对社会、他人所具有的价值"},{"id":"C","text":"对人生问题的一种相对稳定的心理倾向和精神状态"},{"id":"D","text":"社会存在和发展的重要条件"}],"answer":["B","D"],"analysis":{"point":"","options":{"A":"对自身物质和精神需要的满足程度——是人生的自我价值的主要表现。","B":"是关于人生的社会价值的正确表述，是本题正确答案。","C":"对人生问题的一种相对稳定的心理倾向和精神状态——是人生态度的含义。","D":"是关于人生的社会价值的正确表述，是本题正确答案。"}}},{"id":"basic-sixiu-ch01-10","moduleId":"basic","subjectId":"sixiu","chapter":"第一章 领悟人生真谛把握人生方向","chapterKey":"第一章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第一章 第 10 题"},"stem":"人生价值是指人的生命及其实践活动对于社会和个人所具有的作用和意义。正确评价人生价值的方法包括","choices":[{"id":"A","text":"既要看贡献的大小，也要看尽力的程度"},{"id":"B","text":"既要树立崇高理想，也要直面复杂现实"},{"id":"C","text":"既要尊重物质贡献，也要尊重精神贡献"},{"id":"D","text":"既要注重社会贡献，也要注重自身完善"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是正确评价人生价值的方法，是本题正确答案。","B":"是实现人生价值的做法，不是评价方法。第五部分","C":"是正确评价人生价值的方法，是本题正确答案。","D":"是正确评价人生价值的方法，是本题正确答案。"}}},{"id":"basic-sixiu-ch02-1","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 1 题"},"stem":"理想作为一种精神现象，是人类社会实践的产物。理想源于现实，又超越现实，在现实中有多种类型。从主体上划分，理想可分为","choices":[{"id":"A","text":"崇高理想和一般理想"},{"id":"B","text":"个人理想和社会理想"},{"id":"C","text":"道德理想和政治理想"},{"id":"D","text":"生活理想和职业理想"}],"answer":["B"],"analysis":{"point":"","options":{"A":"崇高理想和一般理想——是从层次上划分的理想。","B":"个人理想和社会理想——是从主体上划分的理想，是本题正确答案。","C":"是从内容上划分的理想。","D":"是从内容上划分的理想。"}}},{"id":"basic-sixiu-ch02-2","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 2 题"},"stem":"人们需要的丰富多彩，导致了信念的丰富多彩。在信念体系中，最高层次的信念是","choices":[{"id":"A","text":"理想"},{"id":"B","text":"信仰"},{"id":"C","text":"情感"},{"id":"D","text":"实践"}],"answer":["B"],"analysis":{"point":"","options":{"A":"理想——是不同于信念的精神现象。","B":"信仰——是最高层次的信念，是本题正确答案。","C":"情感非考点。","D":"实践——是物质性的活动，而信念是精神现象。"}}},{"id":"basic-sixiu-ch02-3","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 3 题"},"stem":"在整个理想体系中，最根本、最重要的是","choices":[{"id":"A","text":"个人理想"},{"id":"B","text":"道德理想"},{"id":"C","text":"政治理想"},{"id":"D","text":"社会理想"}],"answer":["D"],"analysis":{"point":"","options":{"A":"个人理想——是由社会理想规定的。","B":"是按照不同的内容划分的理想，但都不是最根本、最重要的。","C":"是按照不同的内容划分的理想，但都不是最根本、最重要的。","D":"社会理想——是在整个理想体系中，最根本、最重要的内容，是本题正确答案。"}}},{"id":"basic-sixiu-ch02-4","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 4 题"},"stem":"如果缺少支撑，人的精神世界就如同无根之木、无基之塔。一个人在精神生活领域“安身立命”的根本是","choices":[{"id":"A","text":"价值观"},{"id":"B","text":"世界观"},{"id":"C","text":"理想信念"},{"id":"D","text":"人生目的"}],"answer":["C"],"analysis":{"point":"","options":{"A":"价值观——是人们对事物的意义和价值的反映与判断，对人的具体行为起着规范和导向作用。","B":"世界观——是人们对生活在其中的世界以及人与世界的关系的总体看法和根本观点。","C":"理想信念——是一个人在精神生活领域“安身立命”的根本，是本题正确答案。","D":"人生目的——是人生观的核心。"}}},{"id":"basic-sixiu-ch02-5","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 5 题"},"stem":"理想是人们在实践中形成的、有实现可能性的、对未来社会和自身发展目标的向往与追求，它具有","choices":[{"id":"A","text":"超越性"},{"id":"B","text":"实践性"},{"id":"C","text":"长期性"},{"id":"D","text":"时代性"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是理想的特征，是本题正确答案。","B":"是理想的特征，是本题正确答案。","C":"长期性——非考点。基础题篇","D":"是理想的特征，是本题正确答案。"}}},{"id":"basic-sixiu-ch02-6","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 6 题"},"stem":"信念是人们在一定的认识基础上确立的对某种思想或事物坚信不疑并身体力行的精神状态。信念具有","choices":[{"id":"A","text":"执着性"},{"id":"B","text":"超越性"},{"id":"C","text":"多样性"},{"id":"D","text":"支撑性"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是信念的特征，是本题正确答案。","B":"超越性——是理想的特征。","C":"是信念的特征，是本题正确答案。","D":"是信念的特征，是本题正确答案。"}}},{"id":"basic-sixiu-ch02-7","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 7 题"},"stem":"志存高远的人，再遥远的地方也能达到，再坚固的东西也能突破。下列关于理想信念的理解，正确的有","choices":[{"id":"A","text":"理想和信念总是相互依存"},{"id":"B","text":"理想是信念所指的对象"},{"id":"C","text":"信念是理想实现的保障"},{"id":"D","text":"理想是最高层次的信念"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是关于理想信念关系的正确说法，是本题正确答案。","B":"是关于理想信念关系的正确说法，是本题正确答案。","C":"是关于理想信念关系的正确说法，是本题正确答案。","D":"是错误说法，信仰是最高层次的信念。"}}},{"id":"basic-sixiu-ch02-8","moduleId":"basic","subjectId":"sixiu","chapter":"第二章 追求远大理想坚定崇高信念","chapterKey":"第二章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第二章 第 8 题"},"stem":"青年时期是一个人确立理想信念最集中最突出的时期。青年人在确立自己的理想信念时，应该","choices":[{"id":"A","text":"使社会理想服从于个人理想"},{"id":"B","text":"学会对不同的理想信念进行辨别和选择"},{"id":"C","text":"把个人的理想信念与社会的理想信念结合起来"},{"id":"D","text":"离开人的生活体验和实际行动，单纯地读书学习"}],"answer":["B","C"],"analysis":{"point":"","options":{"A":"是错误说法，当个人理想与社会理想发生矛盾时，应该使个人理想服从于社会理想。","B":"是青年人在确立理想信念时的正确做法，是本题正确答案。","C":"是青年人在确立理想信念时的正确做法，是本题正确答案。","D":"是错误说法，确立理想信念不能离开人的生活体验和实际行动。"}}},{"id":"basic-sixiu-ch03-1","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 1 题"},"stem":"在5 000多年的历史发展进程中，中华民族形成了伟大民族精神，其核心是","choices":[{"id":"A","text":"一心为公"},{"id":"B","text":"创新"},{"id":"C","text":"爱国主义"},{"id":"D","text":"勤劳勇敢"}],"answer":["C"],"analysis":{"point":"","options":{"A":"一心为公是集体主义的最高层次。","B":"创新是中华民族最深沉的民族禀赋。","C":"爱国主义——是伟大民族精神的核心，是本题正确答案。","D":"勤劳勇敢——是中华民族精神的重要内容之一，但不是中华民族精神的核心。"}}},{"id":"basic-sixiu-ch03-2","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 2 题"},"stem":"检验一个人对祖国忠诚程度的试金石是","choices":[{"id":"A","text":"爱祖国灿烂的文化"},{"id":"B","text":"爱祖国的大好河山"},{"id":"C","text":"爱自己的骨肉同胞"},{"id":"D","text":"爱自己的国家"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是爱国主义基本内涵的表现。","B":"是爱国主义基本内涵的表现。","C":"爱自己的骨肉同胞——不仅是爱国主义基本内涵的表现，也是检验一个人对祖国忠诚程度的试金石，是本题正确答案。","D":"是爱国主义基本内涵的表现。"}}},{"id":"basic-sixiu-ch03-3","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 3 题"},"stem":"时代精神是每一个时代特有的普遍精神实质，是激励一个民族奋发图强、振兴祖国的强大精神动力，构成同时代精神文明建设的重要内容。我们应该大力弘扬的时代精神的核心是","choices":[{"id":"A","text":"富强民主"},{"id":"B","text":"文明和谐"},{"id":"C","text":"自强不息"},{"id":"D","text":"改革创新"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是社会主义核心价值观的主要内容。","B":"是社会主义核心价值观的主要内容。","C":"自强不息是中华民族精神的重要内容之一。","D":"改革创新是时代精神的核心，是本题正确答案。"}}},{"id":"basic-sixiu-ch03-4","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 4 题"},"stem":"在当代中国，爱国主义的本质就是","choices":[{"id":"A","text":"尊重和传承中华民族历史文化"},{"id":"B","text":"坚持爱国和爱党、爱社会主义高度统一"},{"id":"C","text":"爱自己的骨肉同胞"},{"id":"D","text":"坚持立足中国又面向世界"}],"answer":["B"],"analysis":{"point":"","options":{"A":"尊重和传承中华民族历史文化——是新时代爱国主义的基本要求之一。","B":"坚持爱国和爱党、爱社会主义高度统一——是当代中国爱国主义的本质，是本题正确答案。","C":"爱自己的骨肉同胞——是检验一个人对祖国忠诚程度的试金石。","D":"坚持立足中国又面向世界——是新时代爱国主义的基本要求之一。"}}},{"id":"basic-sixiu-ch03-5","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 5 题"},"stem":"当前，中国特色社会主义进入新时代，中华民族伟大复兴正处于关键时期。新时代加强爱国主义教育，对于振奋民族精神、凝聚全民族力量，实现中华民族伟大复兴的中国梦，具有重大而深远的意义。弘扬新时代爱国主义的重要着力点和落脚点是","choices":[{"id":"A","text":"坚持爱国爱党爱社会主义相统一"},{"id":"B","text":"维护祖国统一和民族团结"},{"id":"C","text":"尊重和传承中华民族历史和优秀传统文化"},{"id":"D","text":"坚持立足民族又面向世界"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是新时代爱国主义的基本要求。","B":"维护祖国统一和民族团结——不仅是新时代爱国主义的基本要求，也是弘扬新时代爱国主义的重要着力点和落脚点，是本题正确答案。","C":"是新时代爱国主义的基本要求。","D":"是新时代爱国主义的基本要求。"}}},{"id":"basic-sixiu-ch03-6","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 6 题"},"stem":"当今，国际形势继续发生深刻复杂变化，对国际竞争产生重要影响。世界多极化、经济全球化、文化多样化、社会信息化的不断深化，改变了国际竞争的内涵和具体形态。当今国际竞争新优势的集中体现是","choices":[{"id":"A","text":"综合国力"},{"id":"B","text":"经济发展程度"},{"id":"C","text":"文化软实力"},{"id":"D","text":"创新能力"}],"answer":["D"],"analysis":{"point":"","options":{"A":"非考点。","B":"非考点。","C":"文化软实力——是当今世界综合国力竞争的重要因素。","D":"创新能力——是当今国际竞争新优势的集中体现，是本题正确答案。"}}},{"id":"basic-sixiu-ch03-7","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 7 题"},"stem":"我国在历史上长期处于世界领先地位，取得了许多永载史册的辉煌成果。明者因时而变，知者随事而制。中华民族最深沉的民族禀赋是","choices":[{"id":"A","text":"爱国主义"},{"id":"B","text":"集体主义"},{"id":"C","text":"创新"},{"id":"D","text":"诚实守信"}],"answer":["C"],"analysis":{"point":"","options":{"A":"爱国主义是中华民族精神的核心。","B":"集体主义是社会主义道德的原则。","C":"创新——是中华民族最深沉的民族禀赋，是本题正确答案。","D":"诚实守信——是个人立身处世的基本价值规范，也是社会存续发展的重要价值基石。"}}},{"id":"basic-sixiu-ch03-8","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 8 题"},"stem":"在漫漫的历史进程中，中华民族形成了崇尚精神的优秀传统，表现在","choices":[{"id":"A","text":"对物质生活与精神生活相互关系的独到理解上"},{"id":"B","text":"对理想的不懈追求上"},{"id":"C","text":"对品格养成的重视"},{"id":"D","text":"强调道德修养和道德教化"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是中华民族崇尚精神的优秀传统的表现，是本题正确答案。","B":"是中华民族崇尚精神的优秀传统的表现，是本题正确答案。","C":"是中华民族崇尚精神的优秀传统的表现，是本题正确答案。","D":"是中华民族崇尚精神的优秀传统的表现，是本题正确答案。"}}},{"id":"basic-sixiu-ch03-9","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 9 题"},"stem":"一百多年前，中国共产党的先驱们创建了中国共产党，形成了伟大建党精神，其内涵是","choices":[{"id":"A","text":"坚持真理、坚守理想"},{"id":"B","text":"不怕牺牲、英勇斗争"},{"id":"C","text":"践行初心、担当使命"},{"id":"D","text":"对党忠诚、不负人民"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是伟大建党精神的内涵，是本题正确答案。","B":"是伟大建党精神的内涵，是本题正确答案。","C":"是伟大建党精神的内涵，是本题正确答案。","D":"是伟大建党精神的内涵，是本题正确答案。"}}},{"id":"basic-sixiu-ch03-10","moduleId":"basic","subjectId":"sixiu","chapter":"第三章 继承优良传统弘扬中国精神","chapterKey":"第三章","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第三章 第 10 题"},"stem":"人无精神则不立，国无精神则不强。精神是一个民族赖以长久生存的灵魂，唯有精神上达到一定的高度，这个民族才能在历史的洪流中屹立不倒、奋勇向前。习近平总书记高度重视中国精神的培育和弘扬，指出“实现中国梦必须弘扬中国精神”，中国精神是时代精神和民族精神的统一。关于民族精神和时代精神的关系，下列说法正确的有","choices":[{"id":"A","text":"一切民族精神都曾经是一定历史阶段中带动潮流、引领风尚、推动社会发展的时代精神"},{"id":"B","text":"一切时代精神都将随着历史的变迁逐步融入民族精神的长河之中"},{"id":"C","text":"民族精神和时代精神共同构成了我们当今时代的中国精神"},{"id":"D","text":"民族精神和时代精神的核心是爱国主义，都是一个民族赖以生存发展的精神支撑"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是关于民族精神和时代精神关系的正确说法，是本题正确答案。","B":"是关于民族精神和时代精神关系的正确说法，是本题正确答案。","C":"是关于民族精神和时代精神关系的正确说法，是本题正确答案。","D":"是错误说法，时代精神的核心是改革创新。"}}},{"id":"basic-sixiu-ch04-1","moduleId":"basic","subjectId":"sixiu","chapter":"第四章 明确价值要求 践行价值准则","chapterKey":"第四章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第四章 第 1 题"},"stem":"中华文明的核心价值理念是","choices":[{"id":"A","text":"文明"},{"id":"B","text":"和谐"},{"id":"C","text":"爱国"},{"id":"D","text":"诚信"}],"answer":["B"],"analysis":{"point":"","options":{"A":"文明——是社会进步的重要标志，也是社会主义现代化国家的重要特征。","B":"和谐——是中华文明的核心价值理念，是本题正确答案。","C":"爱国——是最深沉、最持久的情感，是每个公民应当遵循的最基本的价值准则，也是中华民族的优良传统。","D":"诚信——是个人立身处世的基本价值规范，是社会存续发展的重要价值基石。"}}},{"id":"basic-sixiu-ch04-2","moduleId":"basic","subjectId":"sixiu","chapter":"第四章 明确价值要求 践行价值准则","chapterKey":"第四章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第四章 第 2 题"},"stem":"社会主义核心价值观把涉及国家、社会、公民的价值要求融为一体，体现了社会主义本质要求。其中，体现了马克思主义唯物史观生产力标准的根本要求的是","choices":[{"id":"A","text":"民主"},{"id":"B","text":"富强"},{"id":"C","text":"富裕"},{"id":"D","text":"文明"}],"answer":["B"],"analysis":{"point":"","options":{"A":"民主——是人民当家作主，人民民主是社会主义的生命。","B":"富强——是促进社会进步、人的自由全面发展的物质基础，体现了马克思主义唯物史观生产力标准的根本要求，是本题正确答案。","C":"富裕非考点。","D":"文明——是社会进步的重要标志，是社会主义现代化国家的重要特征。"}}},{"id":"basic-sixiu-ch04-3","moduleId":"basic","subjectId":"sixiu","chapter":"第四章 明确价值要求 践行价值准则","chapterKey":"第四章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第四章 第 3 题"},"stem":"党的十八大明确提出了培育和践行社会主义核心价值观的根本任务。其中，国家层面的价值目标是","choices":[{"id":"A","text":"自由、平等、公正、法治"},{"id":"B","text":"爱国、敬业、诚信、友善"},{"id":"C","text":"富强、民主、文明、和谐"},{"id":"D","text":"多元、普世、包容、人本"}],"answer":["C"],"analysis":{"point":"","options":{"A":"自由、平等、公正、法治——是社会层面的价值取向。","B":"爱国、敬业、诚信、友善是公民个人层面的价值准则。","C":"富强、民主、文明、和谐——是国家层面的价值目标，是本题正确答案。","D":"非考点。"}}},{"id":"basic-sixiu-ch04-4","moduleId":"basic","subjectId":"sixiu","chapter":"第四章 明确价值要求 践行价值准则","chapterKey":"第四章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第四章 第 4 题"},"stem":"人类社会发展的历史表明，对一个民族、一个国家来说，最持久、最深层的力量是全社会共同认可的核心价值观。社会主义核心价值观的根本特性是","choices":[{"id":"A","text":"革命性"},{"id":"B","text":"真实性"},{"id":"C","text":"人民性"},{"id":"D","text":"先进性"}],"answer":["C"],"analysis":{"point":"","options":{"A":"革命性——是马克思主义的基本特征。","B":"真实性——是社会主义核心价值观与以往价值观的一个重要区别。","C":"人民性——是社会主义核心价值观的根本特性，是本题正确答案。","D":"先进性——是社会主义核心价值观的特性，但不是根本特性。"}}},{"id":"basic-sixiu-ch04-5","moduleId":"basic","subjectId":"sixiu","chapter":"第四章 明确价值要求 践行价值准则","chapterKey":"第四章","n":5,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第四章 第 5 题"},"stem":"价值观就是主体对客体有无价值、价值大小的立场和态度，是对价值及其相关内容的基本观点和看法。价值观","choices":[{"id":"A","text":"是一定社会形态、社会性质的集中体现"},{"id":"B","text":"蕴含着特定的阶级立场"},{"id":"C","text":"体现着鲜明的民族特色"},{"id":"D","text":"反映着特定的时代精神"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"是关于核心价值观的表述，而非价值观。","B":"是价值观的特征，是本题正确答案。","C":"是价值观的特征，是本题正确答案。","D":"是价值观的特征，是本题正确答案。"}}},{"id":"basic-sixiu-ch04-6","moduleId":"basic","subjectId":"sixiu","chapter":"第四章 明确价值要求 践行价值准则","chapterKey":"第四章","n":6,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第四章 第 6 题"},"stem":"社会主义核心价值体系主要包括马克思主义指导思想、中国特色社会主义共同理想、以爱国主义为核心的民族精神和以改革创新为核心的时代精神、社会主义荣辱观。它与社会主义核心价值观的关系是","choices":[{"id":"A","text":"社会主义核心价值观是社会主义核心价值体系的精神内核"},{"id":"B","text":"社会主义核心价值观就是社会主义核心价值体系"},{"id":"C","text":"二者具有内在的一致性"},{"id":"D","text":"社会主义核心价值体系是社会主义核心价值观历史底蕴的集中体现"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"是关于社会主义核心价值体系与社会主义核心价值观关系的正确表述，是本题正确答案。","B":"是错误说法，社会主义核心价值观与社会主义核心价值体系并不完全等同。","C":"是关于社会主义核心价值体系与社会主义核心价值观关系的正确表述，是本题正确答案。","D":"是错误说法，中华优秀传统文化是社会主义核心价值观历史底蕴的集中体现。"}}},{"id":"basic-sixiu-ch04-7","moduleId":"basic","subjectId":"sixiu","chapter":"第四章 明确价值要求 践行价值准则","chapterKey":"第四章","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第四章 第 7 题"},"stem":"爱国、敬业、诚信、友善，这一价值追求回答了我们要培育什么样的公民的重大问题，涵盖了社会公德、职业道德、家庭美德、个人品德等各个方面，是每个公民都应当遵守的价值规范。其中，爱国是","choices":[{"id":"A","text":"中华民族的优良传统"},{"id":"B","text":"最深沉、最持久的情感"},{"id":"C","text":"对待生产劳动和人类生存的一种根本价值态度"},{"id":"D","text":"每个公民应当遵循的最基本的价值准则"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是关于爱国的正确表述，是本题正确答案。","B":"是关于爱国的正确表述，是本题正确答案。","C":"对待生产劳动和人类生存的一种根本价值态度——是关于敬业的表述。","D":"是关于爱国的正确表述，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-1","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 1 题"},"stem":"动物的本能行为中不存在真正的道德，道德是人类社会发展到一定阶段的必然产物。道德起源的首要前提是","choices":[{"id":"A","text":"人的自我意识"},{"id":"B","text":"劳动"},{"id":"C","text":"社会关系"},{"id":"D","text":"风俗习惯"}],"answer":["B"],"analysis":{"point":"","options":{"A":"人的自我意识——是道德产生的主观条件。","B":"劳动——是道德起源的首要前提，是本题正确答案。","C":"社会关系——是道德赖以产生的客观条件。","D":"风俗习惯——非考点。"}}},{"id":"basic-sixiu-ch05-2","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 2 题"},"stem":"道德的功能集中表现为，它是处理个人与他人、个人与社会之间关系的行为规范及实现自我完善的一种重要精神力量。在道德的功能系统中，反映社会关系特别是反映社会经济关系的功效与能力的是","choices":[{"id":"A","text":"规范功能"},{"id":"B","text":"调节功能"},{"id":"C","text":"认识功能"},{"id":"D","text":"激励功能"}],"answer":["C"],"analysis":{"point":"","options":{"A":"规范功能——是指在正确善恶观的指引下，规范社会成员在社会公共领域、职业领域、家庭领域的行为，并规范个人品德的养成，引导并促进人们崇德向善。","B":"调节功能——是指道德通过评价等方式指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力。","C":"认识功能——是指道德反映社会关系特别是反映社会经济关系的功效与能力，是本题正确答案。","D":"激励功能——是道德的功能之一。"}}},{"id":"basic-sixiu-ch05-3","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 3 题"},"stem":"在社会生活中，道德调节并不是孤立进行的，而是和其他社会调节手段密切配合、共同发挥调节效用。道德调节的主要形式是","choices":[{"id":"A","text":"道德教育"},{"id":"B","text":"人们的内心信念"},{"id":"C","text":"道德评价"},{"id":"D","text":"社会舆论"}],"answer":["C"],"analysis":{"point":"","options":{"A":"道德教育——非考点。","B":"是道德调节所赖以发挥作用的力量，但不是道德调节的主要形式。","C":"道德评价——是道德调节的主要形式，是本题正确答案。","D":"是道德调节所赖以发挥作用的力量，但不是道德调节的主要形式。"}}},{"id":"basic-sixiu-ch05-4","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 4 题"},"stem":"在社会主义社会，每个劳动者和建设者都在为社会、为他人同时也是为自己而劳动和工作。社会主义道德的核心是","choices":[{"id":"A","text":"社会主义核心价值观"},{"id":"B","text":"为人民服务"},{"id":"C","text":"爱国主义"},{"id":"D","text":"集体主义"}],"answer":["B"],"analysis":{"point":"","options":{"A":"社会主义核心价值观——是当代中国精神的集中体现。","B":"为人民服务——是社会主义道德的核心，是本题正确答案。","C":"爱国主义——是中华民族精神的核心。","D":"集体主义——是社会主义道德的原则。基础题篇"}}},{"id":"basic-sixiu-ch05-5","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 5 题"},"stem":"在社会主义社会，国家利益、集体利益体现着个人根本的、长远的利益，是所有社会成员共同利益的统一。同时，每个人的正当利益，又都是集体利益不可分割的组成部分。调节国家利益、社会整体利益和个人利益关系的基本原则是","choices":[{"id":"A","text":"人道主义"},{"id":"B","text":"集体主义"},{"id":"C","text":"爱国主义"},{"id":"D","text":"个人主义"}],"answer":["B"],"analysis":{"point":"","options":{"A":"人道主义——非考点。","B":"集体主义——是调节国家利益、社会整体利益和个人利益关系的基本原则，是本题正确答案。","C":"爱国主义——是中华民族精神的核心。","D":"个人主义——是以个人利益为出发点和归宿的一种思想体系和道德原则，我们要反对极端个人主义。"}}},{"id":"basic-sixiu-ch05-6","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 6 题"},"stem":"集体主义离我们并不遥远，就存在和体现于具体的学习工作生活之中。人人都可以而且应当践行集体主义原则，沿着道德的阶梯循序渐进地向上攀登。在我国，集体主义的最高层次是","choices":[{"id":"A","text":"顾全大局、遵纪守法"},{"id":"B","text":"热爱祖国、诚实劳动"},{"id":"C","text":"先公后私、先人后己"},{"id":"D","text":"无私奉献、一心为公"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是对公民最基本的道德要求。","B":"是对公民最基本的道德要求。","C":"先公后私、先人后己——是已经具有较高社会主义道德觉悟的人能够达到的要求。","D":"无私奉献、一心为公——是集体主义的最高层次，是优秀共产党员、先进分子应努力达到的道德目标，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-7","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 7 题"},"stem":"中华传统美德内容丰富、博大精深，是人类文明发展的重要精神财富，是社会主义道德建设的源头活水。中华传统美德的根本要求是","choices":[{"id":"A","text":"“崇尚和谐”"},{"id":"B","text":"“推崇仁爱”"},{"id":"C","text":"“公义胜私欲”"},{"id":"D","text":"“提倡人伦价值”"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是中华民族的优良传统和高尚品德。","B":"是中华民族的优良传统和高尚品德。","C":"“公义胜私欲”——是中华传统美德的根本要求，是本题正确答案。","D":"“提倡人伦价值”——是中华传统美德的基本精神之一。"}}},{"id":"basic-sixiu-ch05-8","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 8 题"},"stem":"贯穿中国革命道德始终的一根红线是","choices":[{"id":"A","text":"始终把革命利益放在首位"},{"id":"B","text":"坚持社会主义和共产主义理想信念"},{"id":"C","text":"全心全意为人民服务"},{"id":"D","text":"推崇仁爱原则，注重以和为贵"}],"answer":["C"],"analysis":{"point":"","options":{"A":"始终把革命利益放在首位——是中国革命道德的重要内容。","B":"坚持社会主义和共产主义理想信念——是中国革命道德的灵魂。","C":"全心全意为人民服务——是贯穿中国革命道德始终的一根红线，是本题正确答案。","D":"推崇仁爱原则，注重以和为贵——是中华传统美德的重要内容。"}}},{"id":"basic-sixiu-ch05-9","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 9 题"},"stem":"中国革命道德具有丰富而独特的内涵，既包括革命道德的原则、要求、态度等方面，也包括革命理想、革命精神等方面。中国革命道德的灵魂是","choices":[{"id":"A","text":"始终把革命利益放在首位"},{"id":"B","text":"全心全意为人民服务"},{"id":"C","text":"树立社会新风，建立新型人际关系"},{"id":"D","text":"坚持社会主义和共产主义理想信念"}],"answer":["D"],"analysis":{"point":"","options":{"A":"始终把革命利益放在首位——是中国共产党人和革命者从事革命活动的目的，是中国革命道德的重要内容。","B":"全心全意为人民服务——是贯穿中国革命道德始终的一根红线。","C":"树立社会新风，建立新型人际关系——是中国革命道德的重要内容。","D":"坚持社会主义和共产主义理想信念——是中国革命道德的灵魂，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-10","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 10 题"},"stem":"社会公德是指人们在公共生活和社会交往中应该遵守的行为准则，是维护公共利益、公共秩序、社会和谐稳定的起码的道德要求。社会公德最基本的要求是","choices":[{"id":"A","text":"文明礼貌"},{"id":"B","text":"助人为乐"},{"id":"C","text":"爱护公物"},{"id":"D","text":"遵纪守法"}],"answer":["D"],"analysis":{"point":"","options":{"A":"是社会公德的内容，但不是最基本的要求。","B":"是社会公德的内容，但不是最基本的要求。","C":"是社会公德的内容，但不是最基本的要求。","D":"遵纪守法——是社会公德最基本的要求，是全体公民都必须遵循的基本行为准则，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-11","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 11 题"},"stem":"社会主义职业道德中，最高层次的要求是","choices":[{"id":"A","text":"办事公道"},{"id":"B","text":"奉献社会"},{"id":"C","text":"爱岗敬业"},{"id":"D","text":"诚实守信"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是社会主义职业道德的要求，但不是最高层次的要求。","B":"奉献社会——是社会主义职业道德中最高层次的要求，体现了社会主义职业道德的最高目标指向，是本题正确答案。","C":"是社会主义职业道德的要求，但不是最高层次的要求。","D":"诚实守信——是在行业中扎根立足的基础，是中华民族的传统美德，也是我国公民道德建设的重点，还是社会主义核心价值观的一条重要准则。"}}},{"id":"basic-sixiu-ch05-12","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 12 题"},"stem":"道德源于人的社会生活需要，又服务于人的社会生活需要，具有特殊的功能和作用。在道德的功能系统中，最基本的功能包括","choices":[{"id":"A","text":"调节功能"},{"id":"B","text":"激励功能"},{"id":"C","text":"规范功能"},{"id":"D","text":"认识功能"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是道德最基本的功能，是本题正确答案。","B":"激励功能——是道德的功能之一，但不是最基本的功能。","C":"是道德最基本的功能，是本题正确答案。","D":"是道德最基本的功能，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-13","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 13 题"},"stem":"中华民族生生不息绵延发展、饱受挫折又不断浴火重生，都离不开中华文化的有力支撑。今天，在新时代建设社会主义核心价值体系，应当从中汲取丰富的营养，使其成为人们修养道德、砥砺品格的精神来源。实现中华传统美德的创造性转化和创新性发展，需要我们","choices":[{"id":"A","text":"加强对中华传统美德的挖掘和阐发"},{"id":"B","text":"用中华传统美德滋养社会主义道德建设"},{"id":"C","text":"全盘保留和利用中华传统文化"},{"id":"D","text":"反对历史虚无主义和全盘复古论"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是实现中华传统美德的创造性转化和创新性发展的具体要求，是本题正确答案。","B":"是实现中华传统美德的创造性转化和创新性发展的具体要求，是本题正确答案。","C":"是错误说法，对于中华传统文化应当批判继承。","D":"是实现中华传统美德的创造性转化和创新性发展的具体要求，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-14","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 14 题"},"stem":"迄今为止，人类社会先后经历了五种基本社会形态，与此相适应，出现了原始社会的道德、奴隶社会的道德、封建社会的道德、资本主义社会的道德、社会主义社会的道德。与以往社会的道德形态相比，社会主义道德具有显著的先进性特征。这种先进性主要体现在","choices":[{"id":"A","text":"社会主义道德是对人类优秀道德资源的批判继承和创新发展"},{"id":"B","text":"社会主义道德克服了以往阶级社会道德的片面性和局限性"},{"id":"C","text":"社会主义道德是对人类道德传统的彻底否定"},{"id":"D","text":"社会主义道德是社会主义经济基础的反映"}],"answer":["A","B","D"],"analysis":{"point":"","options":{"A":"是社会主义道德先进性的体现，是本题正确答案。","B":"是社会主义道德先进性的体现，是本题正确答案。","C":"是错误说法，社会主义道德是对人类道德传统的批判与继承。","D":"是社会主义道德先进性的体现，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-15","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 15 题"},"stem":"“今天，中华民族要继续前进，就必须根据时代条件，继承和弘扬我们的民族精神、我们民族的优秀文化，特别是包含其中的传统美德。”中华传统美德是人类文明发展的重要精神财富，是社会主义道德建设的源头活水。下列诗句中反映推崇仁爱原则，注重以和为贵优良传统的有","choices":[{"id":"A","text":"“亲亲而仁民，仁民而爱物”"},{"id":"B","text":"“先天下之忧而忧，后天下之乐而乐”"},{"id":"C","text":"“兼相爱，交相利”"},{"id":"D","text":"“己欲立而立人，己欲达而达人”"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是推崇仁爱原则，注重以和为贵优良传统的体现，是本题正确答案。","B":"“先天下之忧而忧，后天下之乐而乐”——是追求精神境界，向往理想人格的体现。","C":"是推崇仁爱原则，注重以和为贵优良传统的体现，是本题正确答案。","D":"是推崇仁爱原则，注重以和为贵优良传统的体现，是本题正确答案。"}}},{"id":"basic-sixiu-ch05-16","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 16 题"},"stem":"中国革命道德是马克思主义与中国革命、建设、改革的伟大实践相结合的产物，它具有丰富而独特的内涵，包括","choices":[{"id":"A","text":"树立社会新风，建立新型人际关系"},{"id":"B","text":"修身自律，保持节操"},{"id":"C","text":"始终把革命利益放在首位"},{"id":"D","text":"为实现社会主义和共产主义理想而奋斗"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是中国革命道德的内涵，是本题正确答案。此外，中国革命道德还包括全心全意为人民服务。","B":"是中国革命道德的内涵，是本题正确答案。此外，中国革命道德还包括全心全意为人民服务。","C":"是中国革命道德的内涵，是本题正确答案。此外，中国革命道德还包括全心全意为人民服务。","D":"是中国革命道德的内涵，是本题正确答案。此外，中国革命道德还包括全心全意为人民服务。"}}},{"id":"basic-sixiu-ch05-17","moduleId":"basic","subjectId":"sixiu","chapter":"第五章 遵守道德规范锤炼道德品格","chapterKey":"第五章","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第五章 第 17 题"},"stem":"家庭生活中的男女平等表现为","choices":[{"id":"A","text":"夫妻权利和义务上的平等"},{"id":"B","text":"平等地对待自己的子女"},{"id":"C","text":"夫妻人格地位上的平等"},{"id":"D","text":"子女要孝敬、赡养父母及长辈，父母要抚育、爱护子女"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是家庭生活中男女平等的表现，是本题正确答案。第","B":"是家庭生活中男女平等的表现，是本题正确答案。第","C":"是家庭生活中男女平等的表现，是本题正确答案。第","D":"子女要孝敬、赡养父母及长辈，父母要抚育、爱护子女——是尊老爱幼的表现，不是男女平等五部的表现。"}}},{"id":"basic-sixiu-ch06-1","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 1 题"},"stem":"在漫长的文明演进中，法律发挥着特殊的社会规范作用。决定法律本质、内容和发展方向的根本因素是","choices":[{"id":"A","text":"法律文化"},{"id":"B","text":"物质资料生产方式"},{"id":"C","text":"人口因素"},{"id":"D","text":"自然环境"}],"answer":["B"],"analysis":{"point":"","options":{"A":"法律文化非考点。","B":"物质资料生产方式——是决定社会面貌、性质和发展的根本因素，也是决定法律本质、内容和发展方向的根本因素，是本题正确答案。","C":"人口因素——是社会物质生活条件的重要内容，是法律产生的基础之一。","D":"自然环境非考点。"}}},{"id":"basic-sixiu-ch06-2","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 2 题"},"stem":"法律遵守是法律运行过程中的一个环节，是指国家机关、社会组织和公民个人依照法律规定行使权力或权利以及履行职责或义务的活动。在法律运行过程中，法律实施和实现的基本途径是","choices":[{"id":"A","text":"立法"},{"id":"B","text":"执法"},{"id":"C","text":"司法"},{"id":"D","text":"守法"}],"answer":["D"],"analysis":{"point":"","options":{"A":"立法——是法律运行的起始性和关键性环节。","B":"执法是法律实施和实现的重要环节。","C":"司法——是国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。","D":"守法——是法律实施和实现的基本途径，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-3","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 3 题"},"stem":"法律适用是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。在我国，司法机关是指国家审判机关和检察机关。司法的基本要求是","choices":[{"id":"A","text":"公正、公平、公开"},{"id":"B","text":"科学立法、民主立法、依法立法"},{"id":"C","text":"合法性、合理性、信赖保护、效率"},{"id":"D","text":"正确、合法、合理、及时"}],"answer":["D"],"analysis":{"point":"","options":{"A":"公正、公平、公开——是立法的原则。","B":"科学立法、民主立法、依法立法——是立法中要贯彻执行的要求。","C":"合法性、合理性、信赖保护、效率——是行政执法的基本原则。","D":"正确、合法、合理、及时——是司法的基本要求，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-4","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 4 题"},"stem":"全面依法治国是坚持和发展中国特色社会主义的本质要求和重要保障，是国家治理的一场深刻变革。全面依法治国的根本遵循是","choices":[{"id":"A","text":"《中华人民共和国宪法》"},{"id":"B","text":"中国特色社会主义法治道路"},{"id":"C","text":"习近平法治思想"},{"id":"D","text":"社会主义核心价值观"}],"answer":["C"],"analysis":{"point":"","options":{"A":"《中华人民共和国宪法》——是国家各项制度和法律法规的总依据。","B":"中国特色社会主义法治道路——是社会主义法治建设成就和经验的集中体现，是建设社会主义法治国家的唯一正确道路。","C":"习近平法治思想——是全面依法治国的指导思想和根本遵循，是本题正确答案。","D":"社会主义核心价值观——是坚持和发展中国特色社会主义的价值遵循。"}}},{"id":"basic-sixiu-ch06-5","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 5 题"},"stem":"走什么样的法治道路，脱离不开一个国家的基本国情。我们是有14亿多人口的社会主义大国，有自己的历史文化传统，有长期积累的经验和优势，要在较短时间内建成法治国家，必须走中国特色社会主义法治道路。我国法治同西方资本主义国家的法治最大的区别是","choices":[{"id":"A","text":"坚持人民主体地位"},{"id":"B","text":"坚持法律面前人人平等"},{"id":"C","text":"党的领导"},{"id":"D","text":"物质资料生产方式"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是坚持中国特色社会主义法治道路必须遵循的原则。","B":"是坚持中国特色社会主义法治道路必须遵循的原则。","C":"党的领导——是中国特色社会主义法治之魂，是我们的法治同西方资本主义国家的法治最大的区别，是本题正确答案。","D":"物质资料生产方式是决定法律本质、内容和发展方向的根本因素。"}}},{"id":"basic-sixiu-ch06-6","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 6 题"},"stem":"既是社会主义法律的基本属性，又是社会主义法治的基本要求的是","choices":[{"id":"A","text":"诚信"},{"id":"B","text":"平等"},{"id":"C","text":"民主"},{"id":"D","text":"公正"}],"answer":["B"],"analysis":{"point":"","options":{"A":"诚信——是社会主义核心价值观的一条重要准则。","B":"平等是社会主义法律的基本属性，是社会主义法治的基本要求，是本题正确答案。","C":"民主——是人民当家作主，人民民主是社会主义的生命。","D":"公正——是法治的生命线，是司法活动最高的价值追求。"}}},{"id":"basic-sixiu-ch06-7","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 7 题"},"stem":"依法治国就是依照体现人民意志和社会发展规律的法律治理国家，而不是依照个人意志、主张治理国家；要求国家的政治、经济运作、社会各方面的活动通通依照法律进行，而不受任何个人意志的干预、阻碍或破坏。推进全面依法治国的根本目的是","choices":[{"id":"A","text":"依宪执政"},{"id":"B","text":"依法保障人民权益"},{"id":"C","text":"建设法治中国"},{"id":"D","text":"建设法治社会"}],"answer":["B"],"analysis":{"point":"","options":{"A":"依宪执政是对党执政的要求。","B":"依法保障人民权益——是推进全面依法治国的根本目的，是本题正确答案。","C":"建设法治中国是全面依法治国的宏伟目标。","D":"建设法治社会——是构筑法治国家的基础。"}}},{"id":"basic-sixiu-ch06-8","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 8 题"},"stem":"既是中国特色社会主义法治体系的前提，又是法治国家、法治政府、法治社会的制度基础的是","choices":[{"id":"A","text":"法律实施"},{"id":"B","text":"完备的法律规范体系"},{"id":"C","text":"公正司法"},{"id":"D","text":"《中华人民共和国宪法》"}],"answer":["B"],"analysis":{"point":"","options":{"A":"法律实施是法律的生命力所在，是法律的权威所在。","B":"完备的法律规范体系——是中国特色社会主义法治体系的前提，是法治国家、法治政府、法治社会的制度基础，是本题正确答案。","C":"公正司法——是维护社会公平正义的最后一道防线。","D":"《中华人民共和国宪法》——是国家的根本法，是党和人民意志的集中体现。"}}},{"id":"basic-sixiu-ch06-9","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 9 题"},"stem":"建设中国特色社会主义法治体系，就是要形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。其中，中国特色社会主义法治体系的本质要求和重要内容是","choices":[{"id":"A","text":"建设高效的法治实施体系"},{"id":"B","text":"建设完善的党内法规体系"},{"id":"C","text":"严密的法治监督体系"},{"id":"D","text":"有力的法治保障体系"}],"answer":["B"],"analysis":{"point":"","options":{"A":"建设高效的法治实施体系——是建设中国特色社会主义法治体系的重点。","B":"建设完善的党内法规体系——是中国特色社会主义法治体系的本质要求和重要内容，是本题正确答案。","C":"严密的法治监督体系——是宪法法律有效实施的重要保障，是加强对权力运行制约和监督的迫切要求。","D":"有力的法治保障体系——是全面依法治国的重要依托。"}}},{"id":"basic-sixiu-ch06-10","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 10 题"},"stem":"习近平总书记指出，法治国家、法治政府、法治社会三者各有侧重、相辅相成。构筑法治国家的基础是","choices":[{"id":"A","text":"法治政府"},{"id":"B","text":"依法治国"},{"id":"C","text":"法治社会"},{"id":"D","text":"科学立法"}],"answer":["C"],"analysis":{"point":"","options":{"A":"法治政府是建设法治国家的重点。","B":"依法治国——是党领导人民治理国家的基本方略。","C":"法治社会——是构筑法治国家的基础，是本题正确答案。","D":"科学立法是全面依法治国的前提。"}}},{"id":"basic-sixiu-ch06-11","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 11 题"},"stem":"推进全面依法治国的重点任务和主体工程是","choices":[{"id":"A","text":"法治社会建设"},{"id":"B","text":"法治思想建设"},{"id":"C","text":"法治道路建设"},{"id":"D","text":"法治政府建设"}],"answer":["D"],"analysis":{"point":"","options":{"A":"法治社会建设——是推进全面依法治国的基础工程。","B":"非考点。","C":"非考点。","D":"法治政府建设——是推进全面依法治国的重点任务和主体工程，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-12","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 12 题"},"stem":"全面依法治国，必须从立法、执法、司法、守法四个方面统筹推进。全面依法治国的关键是","choices":[{"id":"A","text":"科学立法"},{"id":"B","text":"严格执法"},{"id":"C","text":"公正司法"},{"id":"D","text":"全民守法"}],"answer":["B"],"analysis":{"point":"","options":{"A":"科学立法——是全面依法治国的前提，立法是法治的龙头环节。","B":"严格执法是全面依法治国的关键，是本题正确答案。","C":"公正司法——是全面依法治国的重点，是维护社会公平正义的最后一道防线。","D":"全民守法——是全面依法治国的基础，是法治社会的基础工程。"}}},{"id":"basic-sixiu-ch06-13","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 13 题"},"stem":"在中国，人民法院依照法律规定独立行使审判权，人民检察院依照法律规定独立行使检察权，公安机关负责刑事侦查，形成分工协作的司法体系。司法活动最高的价值追求是","choices":[{"id":"A","text":"公民在法律面前一律平等"},{"id":"B","text":"公正"},{"id":"C","text":"正确、合法、合理、及时"},{"id":"D","text":"信赖保护"}],"answer":["B"],"analysis":{"point":"","options":{"A":"公民在法律面前一律平等——是司法原则之一。","B":"公正——是法治的生命线，是司法活动最高的价值追求，是本题正确答案。","C":"正确、合法、合理、及时——是司法的基本要求。","D":"信赖保护——是行政执法的原则之一。"}}},{"id":"basic-sixiu-ch06-14","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 14 题"},"stem":"习近平强调：“宪法的生命在于实施，宪法的权威也在于实施。”加强宪法实施，党首先要","choices":[{"id":"A","text":"坚持依法治国"},{"id":"B","text":"坚持依法立法"},{"id":"C","text":"坚持严格执法"},{"id":"D","text":"坚持依宪执政"}],"answer":["D"],"analysis":{"point":"","options":{"A":"坚持依法治国——是以党领导下的广大人民群众为主体。","B":"坚持依法立法是以国家权力机关为主体，加强和改进立法工作。","C":"坚持严格执法——是以国家行政机关、监察机关、司法机关为主体（此处“执法”为广义上的执法)。","D":"加强宪法实施，党首先要坚持依宪执政，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-15","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 15 题"},"stem":"我国宪法将“国家尊重和保障人权”规定为一项基本原则。权利保障主要是指对公民权利的法律保障，具体包括公民权利的宪法保障、立法保障、行政保障和司法保障。其中，宪法保障是","choices":[{"id":"A","text":"权利保障的最后防线"},{"id":"B","text":"权利保障的重要条件"},{"id":"C","text":"权利保障的关键环节"},{"id":"D","text":"权利保障的前提和基础"}],"answer":["D"],"analysis":{"point":"","options":{"A":"权利保障的最后防线——是司法保障。","B":"权利保障的重要条件——是立法保障。","C":"权利保障的关键环节——是行政保障。","D":"权利保障的前提和基础——是宪法保障，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-16","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 16 题"},"stem":"法律程序是指法律主体实施法律行为时必须遵循的法定步骤、方式、时限和顺序，具有法定性与目的性的双重属性。程序的合法性是指","choices":[{"id":"A","text":"程序设计和运行应平等地对待双方当事人，不得偏向任何一方"},{"id":"B","text":"程序运行合乎法律的规定，有关机关或个人不得违反或变相违反"},{"id":"C","text":"程序运行的过程和结果应当向当事人和社会公开，以接受各方监督"},{"id":"D","text":"案件或纠纷的利害关系人都有机会进入办案程序，充分表达自己的利益诉求"}],"answer":["B"],"analysis":{"point":"","options":{"A":"是程序的中立性的体现。","B":"是程序的合法性的体现，是本题正确答案。","C":"是程序的公开性的体现。","D":"是程序的参与性的体现。"}}},{"id":"basic-sixiu-ch06-17","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 17 题"},"stem":"法律权利是指由一定的社会物质生活条件所制约的行为自由，是法律所允许的权利人为了满足自己的利益而采取的、由其他人的法律义务所保障的法律手段。权利的产生、发展和实现，都必须以一定的社会经济条件为基础。法律权利区别于其他权利的根本所在是","choices":[{"id":"A","text":"法律权利的内容、种类和实现程度受社会物质生活条件的制约"},{"id":"B","text":"法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异"},{"id":"C","text":"由国家强制力保障其实现"},{"id":"D","text":"法律权利必须依法行使"}],"answer":["C"],"analysis":{"point":"","options":{"A":"是法律权利的特征，并不是法律权利区别于其他权利的根本所在。","B":"是法律权利的特征，并不是法律权利区别于其他权利的根本所在。","C":"由国家强制力保障其实现——是法律权利区别于其他权利的根本所在，是本题正确答案。","D":"是法律权利的特征，并不是法律权利区别于其他权利的根本所在。"}}},{"id":"basic-sixiu-ch06-18","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":18,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 18 题"},"stem":"文化教育权利，是公民按照宪法的规定在文化和教育领域享有的权利，主要包括教育方面的权利和文化活动方面的权利。教育方面的权利主要表现为","choices":[{"id":"A","text":"科学研究的自由"},{"id":"B","text":"监督权"},{"id":"C","text":"文化权利"},{"id":"D","text":"受教育权"}],"answer":["D"],"analysis":{"point":"","options":{"A":"科学研究的自由——是公民的文化权利之一。","B":"监督权——是公民的政治权利之一。","C":"文化权利——是不同于教育方面的权利。","D":"受教育权——是公民在教育方面的权利的主要表现，是公民在教育领域享有的基本权利，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-19","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":19,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 19 题"},"stem":"法律义务的履行表现为两种形式，包括","choices":[{"id":"A","text":"作为和不作为"},{"id":"B","text":"履行和不履行"},{"id":"C","text":"执行和不执行"},{"id":"D","text":"积极和不积极"}],"answer":["A"],"analysis":{"point":"","options":{"A":"作为和不作为——是法律义务履行的两种表现形式，是本题正确答案。","B":"非考点。","C":"非考点。","D":"非考点。"}}},{"id":"basic-sixiu-ch06-20","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 20 题"},"stem":"我国社会主义法律，是在中国共产党领导新民主主义革命时期孕育、在中华人民共和国成立后不断形成和发展起来的。我国社会主义法律的特征包括","choices":[{"id":"A","text":"具有科学性和先进性"},{"id":"B","text":"由一定的物质生活条件所决定"},{"id":"C","text":"体现了党的主张和人民意志的统一"},{"id":"D","text":"是中国特色社会主义建设的重要保障"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是我国社会主义法律的特征，是本题正确答案。","B":"是法律的一般特征。","C":"是我国社会主义法律的特征，是本题正确答案。","D":"是我国社会主义法律的特征，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-21","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 21 题"},"stem":"司法机关是行使司法权的国家机关。在我国，司法机关是指","choices":[{"id":"A","text":"审判机关"},{"id":"B","text":"公安机关"},{"id":"C","text":"检察机关"},{"id":"D","text":"行政机关"}],"answer":["A","C"],"analysis":{"point":"","options":{"A":"审判机关和检察机关是我国的司法机关，是本题正确答案。","B":"公安机关——是国家行政机关的重要组成部分。","C":"审判机关和检察机关是我国的司法机关，是本题正确答案。","D":"行政机关——是指依法行使国家权力、执行国家行政职能的机关，与司法机关职能不同。"}}},{"id":"basic-sixiu-ch06-22","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 22 题"},"stem":"立法活动必须遵循法定程序。就全国人民代表大会的立法程序而言，大体包括","choices":[{"id":"A","text":"法律案的提出"},{"id":"B","text":"法律案的审议"},{"id":"C","text":"法律案的表决"},{"id":"D","text":"法律的实施"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是全国人民代表大会立法程序的环节，是本题正确答案。此外，全国人民代表大会的立法程序还包括法律的公布。","B":"是全国人民代表大会立法程序的环节，是本题正确答案。此外，全国人民代表大会的立法程序还包括法律的公布。","C":"是全国人民代表大会立法程序的环节，是本题正确答案。此外，全国人民代表大会的立法程序还包括法律的公布。","D":"法律的实施是立法之后的环节。"}}},{"id":"basic-sixiu-ch06-23","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 23 题"},"stem":"1954年9月20日，中华人民共和国第一届全国人民代表大会第一次会议通过了《中华人民共和国宪法》。我国宪法同党和人民进行的艰苦奋斗和创造的辉煌成就紧密相连，同党和人民开辟的前进道路和积累的宝贵经验紧密相连。在我国，宪法是","choices":[{"id":"A","text":"国家各项制度和法律法规的总依据"},{"id":"B","text":"维系一个国家、一个民族凝聚力的根本纽带"},{"id":"C","text":"党和人民意志的集中体现"},{"id":"D","text":"实现国家认同、凝聚社会共识、促进个人发展的基本准则"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是我国宪法的地位，是本题正确答案。","B":"是我国宪法的地位，是本题正确答案。","C":"是我国宪法的地位，是本题正确答案。","D":"是我国宪法的地位，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-24","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 24 题"},"stem":"宪法的基本原则是贯穿宪法规范始终，对宪法的制定、修改、实施、遵守等环节起指导作用的基本准则。我国宪法的基本原则包括","choices":[{"id":"A","text":"平等、自愿、公平原则"},{"id":"B","text":"人民当家作主原则"},{"id":"C","text":"党的领导原则"},{"id":"D","text":"尊重和保障人权原则"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"非考点。","B":"是我国宪法的基本原则，是本题正确答案。此外，我国宪法的基本原则还包括社会主义法治原则、民主集中制原则。","C":"是我国宪法的基本原则，是本题正确答案。此外，我国宪法的基本原则还包括社会主义法治原则、民主集中制原则。","D":"是我国宪法的基本原则，是本题正确答案。此外，我国宪法的基本原则还包括社会主义法治原则、民主集中制原则。"}}},{"id":"basic-sixiu-ch06-25","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 25 题"},"stem":"宪法的力量不仅因其地位崇高，更源于其有效的监督。在新的历史条件下，推进全面依法治国、加强宪法实施，对宪法监督提出了新的更高要求。完善宪法监督，应该","choices":[{"id":"A","text":"健全人大工作机制"},{"id":"B","text":"健全宪法解释机制"},{"id":"C","text":"健全备案审查机制"},{"id":"D","text":"健全合宪性审查机制"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是完善宪法监督的举措，是本题正确答案。","B":"是完善宪法监督的举措，是本题正确答案。","C":"是完善宪法监督的举措，是本题正确答案。","D":"是完善宪法监督的举措，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-26","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 26 题"},"stem":"法治思维是基于对法律的尊崇和对法治的信念判断是非、权衡利弊、解决问题的思维方式。法治思维是一种","choices":[{"id":"A","text":"蕴含着公正、平等、民主、人权等法治理念的正当性思维"},{"id":"B","text":"以法律原则和法律规则为依据指导人们社会行为的规范思维"},{"id":"C","text":"以法律手段和方法为依托分析问题、处理问题、解决纠纷的逻辑思维"},{"id":"D","text":"融法律的价值属性和工具理性于一体的特殊的高级法律意识"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是法治思维的含义，是本题正确答案。此外，法治思维还是一种符合规律、尊重事实的科学思维。","B":"是法治思维的含义，是本题正确答案。此外，法治思维还是一种符合规律、尊重事实的科学思维。","C":"是法治思维的含义，是本题正确答案。此外，法治思维还是一种符合规律、尊重事实的科学思维。","D":"是法治思维的含义，是本题正确答案。此外，法治思维还是一种符合规律、尊重事实的科学思维。"}}},{"id":"basic-sixiu-ch06-27","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 27 题"},"stem":"法律至上是指在国家或社会的所有规范中，法律是地位最高、效力最广、强制力最大的规范。法律至上具体表现为法律的","choices":[{"id":"A","text":"普遍适用"},{"id":"B","text":"优先适用"},{"id":"C","text":"不可违反"},{"id":"D","text":"公平普世"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是法律至上的具体表现，是本题正确答案。","B":"是法律至上的具体表现，是本题正确答案。","C":"是法律至上的具体表现，是本题正确答案。","D":"公平普世是错误说法。"}}},{"id":"basic-sixiu-ch06-28","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 28 题"},"stem":"公平正义是指社会的政治利益、经济利益和其他利益在全体社会成员之间合理、公平分配和占有。一般来讲，公平正义主要包括","choices":[{"id":"A","text":"权力公平"},{"id":"B","text":"机会公平"},{"id":"C","text":"规则公平"},{"id":"D","text":"救济公平"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"权力公平——是错误说法。","B":"是公平正义的内容，是本题正确答案。此外，公平正义还包括权利公平。","C":"是公平正义的内容，是本题正确答案。此外，公平正义还包括权利公平。","D":"是公平正义的内容，是本题正确答案。此外，公平正义还包括权利公平。"}}},{"id":"basic-sixiu-ch06-29","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 29 题"},"stem":"权利公平包括多重含义，分别是","choices":[{"id":"A","text":"权利主体平等"},{"id":"B","text":"享有的权利特别是基本权利平等"},{"id":"C","text":"权利保护和权利救济平等"},{"id":"D","text":"在法律内容面前人人平等"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是权利公平的三重含义，是本题正确答案。","B":"是权利公平的三重含义，是本题正确答案。","C":"是权利公平的三重含义，是本题正确答案。","D":"在法律内容面前人人平等——是规则公平的内容。"}}},{"id":"basic-sixiu-ch06-30","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 30 题"},"stem":"机会公平是指生活在同一社会中的成员拥有相同的发展机会和发展前景，反对任何形式的歧视。它包括","choices":[{"id":"A","text":"当代人和后代人的机会平等"},{"id":"B","text":"国家和社会要积极为社会成员的发展创造条件，并努力创造平等的起点"},{"id":"C","text":"社会成员的发展进步权要受到同等尊重"},{"id":"D","text":"为权利受到侵害或处于弱势地位的公民提供平等有效的救济"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是机会公平的内容，是本题正确答案。","B":"是机会公平的内容，是本题正确答案。","C":"是机会公平的内容，是本题正确答案。","D":"是救济公平的含义。"}}},{"id":"basic-sixiu-ch06-31","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":31,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 31 题"},"stem":"程序正当是法治思维的重要内容，只有按照程序做事情，才能防止主观任性、无序混乱。程序的正当，表现在程序的","choices":[{"id":"A","text":"时限性"},{"id":"B","text":"合法性"},{"id":"C","text":"中立性"},{"id":"D","text":"参与性"}],"answer":["A","B","C","D"],"analysis":{"point":"","options":{"A":"是程序正当的表现，是本题正确答案。此外，程序的正当还表现在程序的公开性。","B":"是程序正当的表现，是本题正确答案。此外，程序的正当还表现在程序的公开性。","C":"是程序正当的表现，是本题正确答案。此外，程序的正当还表现在程序的公开性。","D":"是程序正当的表现，是本题正确答案。此外，程序的正当还表现在程序的公开性。"}}},{"id":"basic-sixiu-ch06-32","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":32,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 32 题"},"stem":"法律权利是指由一定的社会物质生活条件所制约的行为自由，是法律所允许的权利人为了满足自己的利益而采取的、由其他人的法律义务所保障的法律手段。法律权利的特征包括","choices":[{"id":"A","text":"法律权利的内容、种类和实现程度受社会物质生活条件的制约"},{"id":"B","text":"法律权利的内容、分配和实现方式不因社会制度和国家法律的不同而存在差异"},{"id":"C","text":"法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性"},{"id":"D","text":"法律权利必须依法行使，不能不择手段地行使法律权利"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是关于法律权利特征的正确表述，是本题正确答案。","B":"是错误说法，法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异，同样一种权利，在不同的社会制度下和不同的国家法律中表现形式有所不同。","C":"是关于法律权利特征的正确表述，是本题正确答案。","D":"是关于法律权利特征的正确表述，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-33","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":33,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 33 题"},"stem":"法律义务是指由一定的社会物质生活条件所制约的社会责任，是保证法律所规定的义务人按照权利人要求从事一定行为或不从事一定行为以满足权利人利益的法律手段。法律义务的特点有","choices":[{"id":"A","text":"法律义务是历史的"},{"id":"B","text":"法律义务是固定的"},{"id":"C","text":"法律义务必须依法设定"},{"id":"D","text":"法律义务源于现实需要"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是关于法律义务特点的正确表述，是本题正确答案。","B":"是错误说法，法律义务可能发生变化，公民和社会组织承担的法律义务，在履行的过程中可能会基于法定情形而变更、消灭，或产生新的法律义务。","C":"是关于法律义务特点的正确表述，是本题正确答案。","D":"是关于法律义务特点的正确表述，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-34","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":34,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 34 题"},"stem":"古希腊有句谚语：“自由的第一个意义就是担负自己的责任。”从法律权利与法律义务关系的角度来看，这句谚语给我们带来的启示有","choices":[{"id":"A","text":"法律权利与法律义务就像一枚硬币的两面，不可分割、相互依存"},{"id":"B","text":"法律权利的实现必须以相应法律义务的履行为条件"},{"id":"C","text":"权利就是义务，义务就是权利"},{"id":"D","text":"在法律领域，权利和义务二者不可兼得"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是关于法律权利和法律义务关系的正确表述，是本题正确答案。","B":"是关于法律权利和法律义务关系的正确表述，是本题正确答案。","C":"是错误说法，权利和义务不能混淆。","D":"是错误说法，权利和义务是相互依存的。"}}},{"id":"basic-sixiu-ch06-35","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":35,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 35 题"},"stem":"我国宪法法律规定了公民享有的一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。其中政治权利包括","choices":[{"id":"A","text":"人身自由权"},{"id":"B","text":"民主管理权"},{"id":"C","text":"选举权与被选举权"},{"id":"D","text":"表达权"}],"answer":["B","C","D"],"analysis":{"point":"","options":{"A":"人身自由权是我国公民享有的人身权利之一。","B":"是我国公民享有的政治权利，是本题正确答案。此外，我国公民享有的政治权利还包括监督权。","C":"是我国公民享有的政治权利，是本题正确答案。此外，我国公民享有的政治权利还包括监督权。","D":"是我国公民享有的政治权利，是本题正确答案。此外，我国公民享有的政治权利还包括监督权。"}}},{"id":"basic-sixiu-ch06-36","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":36,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 36 题"},"stem":"我国宪法法律规定了公民享有的一系列权利。其中，人身权利是指公民的人身不受非法侵犯的权利。它是公民参加国家政治、经济与社会生活的基础，是公民权利的重要内容。人身权利主要包括","choices":[{"id":"A","text":"人格尊严权"},{"id":"B","text":"生命健康权"},{"id":"C","text":"通信自由权"},{"id":"D","text":"私有财产权"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是我国公民享有的人身权利，是本题正确答案。此外，我国公民享有的人身权利还包括人身自由权、住宅安全权。","B":"是我国公民享有的人身权利，是本题正确答案。此外，我国公民享有的人身权利还包括人身自由权、住宅安全权。","C":"是我国公民享有的人身权利，是本题正确答案。此外，我国公民享有的人身权利还包括人身自由权、住宅安全权。","D":"私有财产权是我国公民享有的财产权利之一。"}}},{"id":"basic-sixiu-ch06-37","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":37,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 37 题"},"stem":"人格尊严是人之为人所应当享有的地位、待遇或尊重的总和，集中表现为人的自尊心和自爱心。人格尊严权的基本内容有","choices":[{"id":"A","text":"肖像权"},{"id":"B","text":"住宅安全权"},{"id":"C","text":"姓名权"},{"id":"D","text":"隐私权"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是人格尊严权的基本内容，是本题正确答案。此外，人格尊严权还包括名誉权、荣誉权。","B":"住宅安全权——是同人格尊严权并列的权利，它们共同属于我国公民的人身权利。","C":"是人格尊严权的基本内容，是本题正确答案。此外，人格尊严权还包括名誉权、荣誉权。","D":"是人格尊严权的基本内容，是本题正确答案。此外，人格尊严权还包括名誉权、荣誉权。"}}},{"id":"basic-sixiu-ch06-38","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":38,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 38 题"},"stem":"社会经济权利，是指公民要求国家根据社会经济的发展状况，积极采取措施干预社会经济生活，加强社会建设，提供社会服务，以促进公民的自由和幸福，保障公民过上健康而有尊严的生活的权利。这一权利包括","choices":[{"id":"A","text":"劳动权"},{"id":"B","text":"休息权"},{"id":"C","text":"私有财产权"},{"id":"D","text":"继承权"}],"answer":["A","B"],"analysis":{"point":"","options":{"A":"是社会经济权利的内容，是本题正确答案。此外，社会经济权利还包括社会保障权、物质帮助权。","B":"是社会经济权利的内容，是本题正确答案。此外，社会经济权利还包括社会保障权、物质帮助权。","C":"是财产权利的内容。","D":"是财产权利的内容。"}}},{"id":"basic-sixiu-ch06-39","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":39,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 39 题"},"stem":"我国宪法规定了公民的宗教信仰自由，它是指公民依据内心的信念，自愿地信仰宗教的自由。具体内容包括","choices":[{"id":"A","text":"信仰宗教的自由"},{"id":"B","text":"传播宗教信仰的自由"},{"id":"C","text":"从事宗教活动的自由"},{"id":"D","text":"举行或参加宗教仪式的自由"}],"answer":["A","C","D"],"analysis":{"point":"","options":{"A":"是宗教信仰自由的具体内容，是本题正确答案。","B":"传播宗教信仰的自由——不是我国宪法规定的公民宗教信仰自由的具体内容。","C":"是宗教信仰自由的具体内容，是本题正确答案。","D":"是宗教信仰自由的具体内容，是本题正确答案。"}}},{"id":"basic-sixiu-ch06-40","moduleId":"basic","subjectId":"sixiu","chapter":"第六章 学习法治思维提升法治素养","chapterKey":"第六章","n":40,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·基础篇》","location":"思修 · 第六章 第 40 题"},"stem":"我国宪法第五十二条规定：中华人民共和国公民有维护国家统一和全国各民族团结的义务。可见，维护国家统一具有重大的意义，包括","choices":[{"id":"A","text":"国家统一是公民实现法律权利与自由的前提"},{"id":"B","text":"维护国家统一是以宪法为核心的整个法律制度存在的基础"},{"id":"C","text":"维护国家统一是整个社会共同体存在和发展的基础"},{"id":"D","text":"国家统一是国家政权稳定和公民依法行使权利与自由的根本保障"}],"answer":["A","B","C"],"analysis":{"point":"","options":{"A":"是维护国家统一的意义，是本题正确答案。","B":"是维护国家统一的意义，是本题正确答案。","C":"是维护国家统一的意义，是本题正确答案。","D":"是错误说法，国家安全是国家政权稳定和公民依法行使权利与自由的根本保障。"}}}]`);export{e as default};